-- English texts of the regional pack eastern_stormwind (#102). The rules are in AzerothUnspoken_EasternKingdoms/Stormwind.lua.
local AU = AzerothUnspoken

AU:RegisterRegionalTexts("elwynnforest", "enUS", "eastern_stormwind", [==[
	["sw.dawn"] = {
		"Dawn over Stormwind. The first bell, the first cart, the first argument of the day.",
		"The sun comes up behind the keep, the bells start, and every white wall turns gold for a moment.",
		"Dawn, and the city shakes itself awake like a big dog: slowly, then all at once.",
	},
	["sw.dusk.lamps"] = {
		"watches the lamplighters start their round as dusk settles over the rooftops of Stormwind.",
		"lingers on a bridge while the sunset paints the canals copper and the first lamps flicker on.",
		"notices the shops closing their shutters one by one as the light over the city goes amber at dusk.",
	},
	["sw.dusk.taverns"] = {
		"Lamps going on, shutters coming down. Somewhere a tavern just got louder.",
		"End of the day. The guards are changing and the taverns are filling. I know which line I'd rather join.",
		"Evening in Stormwind. Time for stew, a stool, and someone else's stories.",
	},
	["sw.farewell.01"] = {
		"Take care out there. The city will still be here.",
		"Off I go. If you see a gryphon wearing my hat, it's mine.",
		"Farewell. Don't let the merchants talk you into anything.",
	},
	["sw.farewell.02"] = {
		"Walk with care, and come back through these gates on your own feet. The bells will be waiting.",
		"Go with steady steps. Stormwind will keep a lamp lit.",
		"Until the bells bring us together again.",
	},
	["sw.greet.01"] = {
		"Well met, and welcome to Stormwind. Mind the carts.",
		"Hello there. Busy day in the city, isn't it?",
		"Good to see a face that isn't a guard's or a merchant's.",
	},
	["sw.greet.02"] = {
		"Peace on you, under the lion's banner.",
		"Greetings. May your road out of the city be as safe as your road in, under the same banner.",
		"Well met beneath these walls.",
	},
	["sw.jest.01"] = {
		"How many Stormwind masons does it take to fix a wall? Ask the nobles. They're still haggling over the price.",
		"The motto of Stormwind: if it isn't finished, add scaffolding.",
		"In Stormwind even the pigeons pay rent. Ask any merchant.",
	},
	["sw.journey.arrival.01"] = {
		"slides off the gryphon in the Trade District, legs unsteady, the noise of the city rushing back all at once.",
		"lands among the bustle of Stormwind and takes a moment to remember where the ground is.",
		"steps down from the gryphon, brushing off feathers and road dust, as the gryphon master takes the reins.",
	},
	["sw.journey.arrival.02"] = {
		"Stormwind. Solid ground, solid walls, and my stomach still somewhere over Elwynn.",
		"On stone again. Somebody take this gryphon before it decides it likes me.",
		"Down we come. Stormwind, your stone has never looked so steady.",
	},
	["sw.journey.start"] = {
		"The gryphon leaps into the sky, and Stormwind drops away: blue roofs, white walls, the canals like silver thread.",
		"Up and over the walls, into open sky. From here the whole city fits in my two hands.",
		"The gryphon master shouts something I don't catch, and then there's only wind and the city shrinking behind me.",
	},
	["sw.levelup"] = {
		"A little stronger today. The city doesn't notice. I do.",
		"Somewhere a bell is ringing the hour. I'll pretend it rings for me.",
		"Stone upon stone this city rose; so do I, one hard lesson at a time.",
	},
	["sw.lore.canal_song"] = {
		"A boatman sings under an Old Town bridge, slow as the pole he pushes:\nPush the pole and bend the knee,\nslide the boat beneath the stone;\nevery bridge will bow to me,\nevery lamp will walk me home.",
		"Another verse of the boatmen's song, from farther down the canal:\nWater low and water slow,\ncrates of apples, kegs of ale;\nnoble, beggar, friend or foe,\nall ride slower than a snail.",
	},
	["sw.lore.masons"] = {
		"A saying of the stonemasons, muttered over the chisel:\nLift the block and set it true,\nspread the mortar, tap it down;\nwalls remember hands they knew,\nnot the lords who own the town.",
		"Another the masons used to say, setting the last course of a wall:\nMortar dries and wages fly,\nstone will stand when we move on;\nlook it in the face and try\ncounting who it rests upon.",
	},
	["sw.meet.banker"] = {
		"The banker counts my coins one by one, as if each had given personal offense.",
		"Ledgers, scales, and a smile behind the counter that only lights up for coin.",
		"Somewhere behind that counter is a vault full of other people's treasures and coin. And my three spare boots.",
	},
	["sw.meet.flightmaster"] = {
		"Is that gryphon friendly, or just well fed?",
		"I need a gryphon and a strong stomach. You provide the first.",
		"Where can these beasts take me today? Somewhere with less stone, ideally.",
	},
	["sw.meet.guard"] = {
		"A Stormwind guard: blue tabard, gold lion, and eyes that have heard every excuse twice.",
		"The guard sizes me up in one glance, decides I'm not trouble, and goes back to watching the street.",
		"Polished helm, patient eyes. These guards look like they could stand there until the walls fell down.",
	},
	["sw.meet.guard.horde"] = {
		"meets the guard's eyes for one long heartbeat, and neither of them looks away first. The guard's hand drifts toward the hilt.",
		"goes still as a Stormwind guard turns, one hand already on the hilt.",
		"sees the gold lion on the guard's chest and the guard's hand moving, and both understand at once.",
	},
	["sw.meet.innkeeper"] = {
		"A room, a bowl of whatever's hot, and a corner where nobody will bother me. Please.",
		"Hello there. Is the stew today's, or is that yesterday's being brave?",
		"I've heard good things about this place. Mostly from people who wanted another round.",
	},
	["sw.meet.merchant"] = {
		"is greeted by a wide shopkeeper's smile, the kind that already knows how much coin a purse holds.",
		"looks over a stall crammed with goods while prices start raining from behind the counter, unasked.",
		"pauses at a counter of wares, where everything is a bargain and nothing costs less than a coin.",
	},
	["sw.meet.questgiver"] = {
		"Another troubled face in Stormwind, and another job that won't do itself.",
		"Here we go. Someone in this city always needs something carried, found or hit.",
		"The look of someone with a problem and a purse. I'll listen.",
	},
	["sw.meet.trainer"] = {
		"A trainer of Stormwind. Every scar on those hands is a lesson somebody paid for.",
		"Here's someone who's forgotten more than I know, with the scarred hands to prove it. Good. I'll take the leftovers.",
		"Steady eyes, plain words, no patience for excuses. The best teachers are always like that.",
	},
	["sw.muse.bells"] = {
		"The bells. You stop hearing them after a while, and then one day they're all you hear.",
		"Someone climbs that tower every hour to ring the bells. I hope they're paid better than the masons were.",
		"The cathedral bells count the hours for the whole city. Nobody asked them to; nobody would want them to stop.",
	},
	["sw.muse.boats"] = {
		"watches a flat-bottomed boat slide along the canal, the boatman humming and never once looking up from the water.",
		"leans on a bridge rail and watches the water carry an apple core off toward somewhere else.",
		"follows the slow progress of a boat under one bridge, then the next, then the next.",
	},
	["sw.muse.cathedral"] = {
		"The cathedral doors stand open. Whatever you believe, it's a good place to sit and be quiet.",
		"Pilgrims, beggars, paladins, children. The doors of the cathedral take everyone, and the steps outside take the rest.",
		"A priest hands out bread on the steps. The Light, it seems, also comes in loaves.",
	},
	["sw.muse.criers"] = {
		"Fresh bread! Warm from the oven, cheaper than yesterday, and yesterday was a bargain!",
		"Lamp oil, candles, flint and tinder! Don't go down into the dark without them!",
		"Apples from Elwynn, sweet as summer! Two for a copper, three for a smile! Bread to go with them, too!",
	},
	["sw.muse.forge"] = {
		"pauses by an open forge to watch a dwarf fold hot steel, sparks from the fire spitting across the stone floor.",
		"listens to the anvils of the district keep time with one another, like a slow argument.",
		"feels the heat of the forge fires on one side of the face and the cool of the stone on the other.",
	},
	["sw.muse.guards"] = {
		"Blue and gold, polished to a shine. These guards spend more on their tabards than I do on my supper.",
		"Ask a Stormwind guard for directions and you'll get them. Ask twice and you'll get a look.",
		"I've never seen a guard here with a crooked tabard. There must be a rule.",
	},
	["sw.muse.king"] = {
		"Ask about the king and the guards look at their boots. Ask about the regent and they look toward the keep.",
		"There's a boy on the throne and an empty place beside it. In the taverns, people lower their voices when they talk about the empty place.",
		"Whatever became of the boy's father, the city goes on: bread, bells, scaffolds. Cities are like that.",
	},
	["sw.muse.magequarter"] = {
		"Something in that tower just went bang. Nobody in the street even looks up anymore.",
		"The cobbles here are scorched in neat little circles. Practice, I hope.",
		"A mage hurries past, reading and walking at once. Neither is going well.",
	},
	["sw.muse.masons"] = {
		"They say the masons who raised these walls were never paid, and walked out with their tools and their grudge. Some say they wear red masks now, out west.",
		"A city built on unpaid labor. The walls don't mind. The men who raised them did, and some of them took to the masks.",
		"The nobles argue about the Defias over wine. The farmers in Westfall argue about them over burned barns.",
	},
	["sw.muse.morning"] = {
		"Early. The bakers are up, the guards are changing, and the city hasn't started lying to itself yet.",
		"Morning in Stormwind: damp cobbles, warm bread, and a guard yawning behind his halberd.",
		"First light on the white walls, and the smell of bread already. Even the scaffolds look noble at this hour.",
	},
	["sw.muse.night"] = {
		"At night the canals go quiet enough to hear the boats breathing against their ropes on the water.",
		"Footsteps echo under the bridges at this hour of the night, and every one of them sounds like someone following.",
		"Late now. A boatman sleeps under a tarp by the water, one hand still on the pole.",
	},
	["sw.muse.nobles"] = {
		"In the taverns they say the House of Nobles can argue for a week over who pays for a bridge, then name it after themselves.",
		"A noble's servant shoves through the crowd and doesn't say sorry. Some things a city never rebuilds.",
		"Gossip in this town runs faster than the canals: who owes whom, who dined with whom, who was seen leaving where.",
	},
	["sw.muse.oldtown"] = {
		"In Old Town nobody asks your business. They just remember your face.",
		"Smells like sweat, ale and old secrets. My kind of street.",
		"Watch the alleys here. The ones who don't want to be seen are very good at it.",
	},
	["sw.muse.park"] = {
		"A druid sits among the roots of the trees, as still as they are. I try being still too. It lasts about a breath.",
		"In the middle of all that stone, moss over old roots. The city pretends not to need it.",
		"Leaves on the path under the trees. Somewhere a gardener sighs; somewhere a druid smiles.",
	},
	["sw.muse.scaffold"] = {
		"More scaffolding, and more dust. I'm starting to think the scaffolds hold the city up.",
		"Every time I pass that tower, the scaffolds have moved one floor. Up or down, I can't tell.",
		"Somebody in this city is always building something. Somebody else is always complaining about the dust.",
	},
	["sw.muse.stockade"] = {
		"One more brawl in Old Town and somebody's sleeping in the Stockade.",
		"The guards talk about the Stockade the way mothers talk about the bogeyman.",
		"Behave, or it's the Stockade. Everyone in this city has heard that at least once.",
	},
	["sw.muse.stone"] = {
		"All this stone was quarried, carried and set by hands that went home tired. Nobody carves their name on the walls they build.",
		"Some days the walls look like fresh linen; some days, like old bone. Stone takes whatever you see in it, and keeps its own counsel.",
		"A city of stone is a promise: we are staying. Stormwind has made that promise twice, by the same kind of hands.",
	},
	["sw.muse.trade"] = {
		"Midday in the Trade District: a dozen voices bidding coin at once, and every one of them sure it's winning.",
		"The line at the auction house moves slower than a dwarf after supper.",
		"Someone just paid a fortune in coin for a hat. The hat looks very pleased with itself.",
	},
	["sw.npcd.flight.route.01"] = {
		"Westfall, Redridge, Duskwood, Ironforge: the gryphons know the way. Your job is to hold on.",
		"Lakeshire's a gentle ride over the hills. Darkshire, less so; the gryphons don't care for the trees out there.",
		"To Ironforge it's a long ride north over the mountains. Wrap up warm, and don't look down if you'd rather not.",
	},
	["sw.npcd.flight.route.02"] = {
		"Never ridden one? Hold the saddle, not the feathers. They bite when you pull the feathers.",
		"From up there the whole city looks like a toy someone built very carefully. You'll see.",
		"Westfall is a short hop. You'll barely have time to regret breakfast.",
	},
	["sw.npcd.guard.danger.01"] = {
		"Inside the walls, pickpockets. Outside, the Defias. West of the forest it only gets worse, from what the farmers say, and they're quick with a blade.",
		"Keep your purse close in Old Town and your blade close on the western roads. The Brotherhood's grown bold.",
		"They say the Defias have friends inside the walls. I say watch the man who's watching you, and keep a blade handy.",
	},
	["sw.npcd.guard.danger.02"] = {
		"The Stockade's full again. That tells you what the streets are like lately.",
		"Don't walk the canals alone after dark. Not everyone who falls in does it by accident.",
		"Trouble in the city? Shout. There's always one of us within earshot. Usually.",
	},
	["sw.npcd.guard.dir.01"] = {
		"The bank, the auction house, the Gilded Rose and the gryphon master? All in the Trade District. Follow the crowd and the noise.",
		"Anything to do with coin is in the Trade District. Anything to do with spending coin, too.",
		"Trade District, for the bank and the inn. You'll know it when someone tries to sell you something for a coin too many.",
	},
	["sw.npcd.guard.dir.02"] = {
		"Priests and paladins train around Cathedral Square. Mages keep to their own quarter, the one with the tall tower. Hard to miss either.",
		"Looking for the Light? Cathedral Square. Looking for trouble with a spellbook? The Mage Quarter.",
		"Holy business at the cathedral, arcane business in the Mage Quarter. Don't mix them up; they hate that.",
	},
	["sw.npcd.guard.dir.03"] = {
		"The tram to Ironforge leaves from the Dwarven District. Follow the sound of hammers.",
		"Warriors and rogues gather in Old Town. One lot trains in the open; the other, well, you'll find them if they want you to.",
		"Forges are in the Dwarven District, taverns with sawdust on the floor in Old Town. Pick your poison.",
	},
	["sw.npcd.guard.dir.04"] = {
		"The keep? Follow the banners, and the guards get taller. When they stop letting you through, you're there.",
		"If you need green instead of stone, The Park is your place. The night elves keep a glade there.",
		"Lost in the canals? Everyone is, once. Pick a bridge with a banner on it, cross it, and ask the next guard.",
	},
	["sw.npcd.guard.open.01"] = {
		"Welcome to Stormwind. Keep to the streets, keep your blade sheathed, and we'll get along fine.",
		"Move along, friend. Or stop, if you need something. Just don't block the bridge.",
		"Stormwind City Guard. Lost, looking, or just admiring the stonework?",
	},
	["sw.npcd.guard.open.02"] = {
		"In the name of the king, greetings. State your business if you have one, and enjoy the city if you don't.",
		"Good day. The lion keeps watch, and so do we.",
		"Peace within these walls, traveler. We keep it that way.",
	},
	["sw.npcd.inn.news.01"] = {
		"A mason was in last week, drinking alone. Said the nobles still owe his guild a fortune. Said it loudly, too.",
		"The talk at the tables? Same as always: the Defias, the nobles, and who's to blame for both.",
		"They say the nobles are arguing over taxes again. They also say the Defias are listening.",
	},
	["sw.npcd.inn.news.02"] = {
		"Folk at the bar whisper about the king, and then look over their shoulders. I just pour.",
		"A soldier swore the regent hasn't slept properly in months. Then he ordered another round, so take it as you like.",
		"Lady Prestor passed by again today. Everyone has an opinion about her. Nobody says it twice.",
	},
	["sw.npcd.inn.news.03"] = {
		"Business is good. The farmers from Elwynn come in for the market and leave with lighter purses and heavier heads.",
		"A gryphon got loose over the Trade District this morning. Took a whole fish off a cart and a hat off a noble. The hat's still missing.",
		"A dwarf came up from the tram covered in soot and singing. Said it was the best ride of his life. Then he slept on my floor.",
	},
	["sw.npcd.merch.news.01"] = {
		"Grain's dear this season. Westfall's farms aren't sending what they used to, and you know why.",
		"Wagons from the west come in late or not at all. Bandits. Prices go up, and somehow it's my fault.",
		"Lumber's cheap, stone's dear. The city never stops building, so the prices never stop climbing.",
	},
	["sw.npcd.merch.news.02"] = {
		"Somebody at the auction house paid triple for a sword last week. Rusty. Sentimental value, I suppose.",
		"The bank's been busy. When the bank's busy, I'm busy. When the bank's quiet, I start counting my candles.",
		"There's a rumor the dwarves want to charge for the tram. There's always a rumor the dwarves want to charge for something.",
	},
	["sw.npcd.merch.wares.01"] = {
		"Everything here came through the gate on a cart, and every cart paid a toll. Hence the prices.",
		"Good Stormwind goods: stitched, forged, and checked twice. Mostly.",
		"If it's not on the shelf, I can have it by tomorrow. If it's on the shelf, I can have it in your hands right now.",
	},
	["sw.npcd.merch.wares.02"] = {
		"Rope, rations, a good lantern for the road. You'd be amazed how many heroes leave the city without a lantern.",
		"Heading out past Elwynn? Take more bandages than you think the road will need. Then take a few more.",
		"Waterskins, flint, salt pork that will outlive us both. The road provides nothing; I provide the rest.",
	},
	["sw.npcd.trainer.adv.01"] = {
		"This city was rebuilt one stone at a time. Learn the same way.",
		"Out there, nobody waits for you to remember your lesson. Remember it here, between stone walls, where it's cheap.",
		"Train hard in Stormwind and the roads beyond will feel softer. Not soft. Softer.",
	},
	["sw.npcd.trainer.adv.02"] = {
		"Plenty of brave fools leave through that gate. Come back a careful one, and I'll call it a success.",
		"Your stance is sloppy and your eyes wander. Fix one today. The other tomorrow.",
		"Practice where the floor is flat, so you don't have to think about it when the ground is not.",
	},
	["sw.pray.01"] = {
		"Light, watch over this city: its bells, its bread, its tired guards, and the children in the orphanage.",
		"Holy Light, keep the walls standing and the hearths warm, and the bells ringing. I ask nothing more today.",
		"Light, give the hands that rebuilt this city their due, and give the rest of us the sense to remember them by every hearth.",
	},
	["sw.quest.01"] = {
		"Done. Another errand for the city. Somewhere a clerk is stamping something.",
		"That's handled. Stormwind runs on small favors, and I just did one.",
		"Finished. Now, where's the nearest bench?",
	},
	["sw.quest.02"] = {
		"pockets the reward coin with a nod, as the noise of Stormwind carries on regardless.",
		"hands over the last of the task and steps back into the stream of the street.",
		"counts the coins once, then again, under the eye of a passing guard.",
	},
	["sw.rest.inn"] = {
		"Boots off, back to the wall, a hearth I don't have to tend. This innkeeper knows the business.",
		"Warm room, low voices, a mug that refills when I'm not looking. Good.",
		"A city inn, a soft chair by the hearth, and no one here who wants anything from me but my coin.",
	},
	["sw.rest.safe"] = {
		"Safe walls, a full belly. I could sleep for a week.",
		"Nobody's chasing me, nothing's on fire. Stormwind, you're a marvel.",
		"One proper sleep in a real bed. Then the road can have me back.",
	},
	["sw.rest.serene"] = {
		"Bells somewhere, water under a bridge, someone laughing two streets away. I let all of it in.",
		"For once my hand isn't anywhere near a weapon. It rests on my knee, and that's all it does.",
		"The city hums like a hive at rest. I breathe slower without meaning to.",
	},
	["sw.rest.street"] = {
		"sits on the edge of a fountain and lets the city go by for a while, one hand trailing in the water.",
		"finds a bench in the shade of a wall and stretches out tired legs.",
		"settles on the steps above a canal, letting the bustle of Stormwind wash past like the water below.",
	},
	["sw.ret.01"] = {
		"{zone} again. The same bells, the same smell of bread and damp stone.",
		"Back among the white walls. The baker on the corner is still shouting the same prices for the same bread.",
		"Nothing here has moved since I left, except the scaffolding. The scaffolding always moves.",
	},
	["sw.ret.02"] = {
		"Back in {zone}. I'll pretend I missed the stairs.",
		"Stormwind again. Same guards, same scowls, same excellent pies.",
		"Here I am again. The canals haven't gotten any cleaner.",
	},
	["sw.ret.03"] = {
		"pauses at the gate of {zone}, as if checking that the walls are where they were left.",
		"slows on the bridge into {zone} after a long absence, taking in the new scaffolds and the old stones.",
		"walks into {zone} after many days away, glancing up at towers of stone that have not changed.",
	},
	["sw.ret.04"] = {
		"The road wears you down. {zone} puts you back together, a bowl of stew at a time.",
		"Wherever I came back from, these walls didn't ask. They just let me in.",
		"Under the lion's banners once more. I can sleep with both eyes closed here.",
	},
	["sw.ret.05"] = {
		"Same city, same faces. The guard at the gate almost smiled at me this time.",
		"I've walked these streets enough that the beggars know my name. Well, my purse.",
		"Five times through this gate, at least. The pigeons have stopped moving out of my way.",
	},
	["sw.ret.06"] = {
		"The cathedral bells ring the hour, and for a moment I am wherever I was the first time I heard them.",
		"The same lamp still leans over the same canal. Funny, what the mind keeps.",
		"I remember this corner. I remember being younger at it.",
	},
	["sw.sub.canal.01"] = {
		"follows the water through {subzone}, where it slaps against the stone and moored boats knock together gently.",
		"crosses a bridge over {subzone}, watching a boat loaded with crates drift under it on the green water.",
		"walks along {subzone}, the water low and slow, the bridges arching overhead one after another.",
	},
	["sw.sub.canal.02"] = {
		"The canals tie the districts together like stitches. Pull one out and the whole city might come apart at the seams.",
		"I wonder who fishes in this water, and what they catch. Better not to ask.",
		"This water remembers every boot, every barrel, every coin that ever fell off a bridge.",
	},
	["sw.sub.canal.03"] = {
		"Don't fall in. Don't fall in. Don't... right, I'm fine.",
		"If I had a boat, I'd never walk anywhere in this city again.",
		"Smells like a canal. Well, it is one.",
	},
	["sw.sub.cath.01"] = {
		"enters {subzone} as the cathedral bells begin, the sound rolling down over the stone like water.",
		"crosses {subzone}, where the Cathedral of Light lifts its spires and even the pigeons seem to lower their voices.",
		"slows in {subzone}, beneath the tall windows of the cathedral, where the light falls in colored bars across the paving.",
	},
	["sw.sub.cath.02"] = {
		"Priests in white, paladins in plate, and a line of orphans being marched to supper. The Light keeps busy hours.",
		"Children's voices from the orphanage, a hymn from the cathedral. Somehow they don't clash.",
		"A paladin kneels on the steps, armor and all. I wonder how long it takes to get up again.",
	},
	["sw.sub.cath.03"] = {
		"A candle for the road ahead. It can't hurt.",
		"If the cathedral is open, I'll light a candle. For whoever needs it more than me.",
		"So quiet here. Even my boots sound like they're apologizing.",
	},
	["sw.sub.dwarf.01"] = {
		"enters {subzone}, where the air goes hot with forge fire and the anvils ring like a second set of bells.",
		"walks into {subzone} and the smell changes at once: coal smoke, hot iron, quenching water.",
		"passes into {subzone}, past forges whose fire paints the walls orange through the smoke.",
	},
	["sw.sub.dwarf.02"] = {
		"The Deeprun Tram starts somewhere down here. A cart through the dark, all the way to Ironforge. Gnomes thought of it, naturally.",
		"Somewhere under my boots a tram runs through the rock to Ironforge. I try not to think about the water above it.",
		"Dwarves at one end, gnomes at the other, and the tram stitching them together like thread through a needle.",
	},
	["sw.sub.dwarf.03"] = {
		"If anyone can fix this buckle, it's someone down here with soot to the elbows and steady hands.",
		"Hot in here. Hot and honest. I like a district that sweats.",
		"Hear that? Somebody's hammering out a blade with a sure hand. Good rhythm.",
	},
	["sw.sub.keep.01"] = {
		"climbs toward {subzone}, where the guards stand straighter and the banners hang heavier against the stone.",
		"enters {subzone} beneath high arches and banners, boots ringing on polished stone.",
		"approaches {subzone}, and the noise of the streets falls away into the hush of the court.",
	},
	["sw.sub.keep.02"] = {
		"A boy under the crown, Highlord Bolvar Fordragon as his regent, and a court that whispers in every corridor.",
		"They say Lady Prestor has the regent's ear. They don't say it loudly, and never near the crown.",
		"Somewhere up there a boy king is learning to be one. I don't envy him the lessons.",
	},
	["sw.sub.keep.03"] = {
		"Straighten up. Even the floors here are watching.",
		"Quietly now. This is where the kingdom does its thinking.",
		"I'll mind my manners. The guards here look like they've been told to mind them for me.",
	},
	["sw.sub.mage.01"] = {
		"enters {subzone}, where the air tastes faintly of lightning and the cobbles hum underfoot.",
		"walks into {subzone}, past windows lit violet and a tower that seems taller from up close.",
		"crosses into {subzone}, where a passing apprentice mutters formulas and a cat watches with far too much interest.",
	},
	["sw.sub.mage.02"] = {
		"There's a tavern in this quarter with a cellar people don't talk about. I can guess why.",
		"Mages above, and below, if the rumors are right, something less respectable in a cellar.",
		"Every quarter has its secret. This one, they say, keeps it in a basement and feeds it candles.",
	},
	["sw.sub.mage.03"] = {
		"Touch nothing that glows. Touch nothing that hums. That rules out most of the street.",
		"If a book starts talking to me here, I'm not answering.",
		"Lovely quarter. Smells like burnt hair and ambition.",
	},
	["sw.sub.old.01"] = {
		"turns into {subzone}, where the streets narrow and the tavern doors open early.",
		"enters {subzone}: older stone, darker doorways, and a pair of soldiers arguing outside the barracks.",
		"steps into {subzone}, where somebody in a hood finds a sudden interest in a wall.",
	},
	["sw.sub.old.02"] = {
		"Old Town. They say SI:7 keeps its offices somewhere around here. They also say you'll never find the door, and their eyes are on you while you look.",
		"Half the eyes in this street are watching the other half. The other half know it.",
		"I keep my purse in front of me here. Not that it would help against anyone with the right eye for it.",
	},
	["sw.sub.old.03"] = {
		"Rough part of town. Good. Rough taverns pour honest ale.",
		"Anyone here looking for a fight, or just an ale? I can manage either.",
		"Mind the puddles. In this district, not all of them are water.",
	},
	["sw.sub.park.01"] = {
		"leaves the paving behind in {subzone}, where grass and old trees make a pocket of forest inside the walls.",
		"enters {subzone}, and the noise of the city drops away behind a screen of leaves.",
		"walks into {subzone}, where a night elf druid tends a quiet glade of trees and grass as if the walls were not there.",
	},
	["sw.sub.park.02"] = {
		"Birdsong. Real birdsong, not a merchant whistling. I'll sit a moment.",
		"Funny how a few trees and a few birds make a whole city breathe.",
		"The druids keep this corner of trees wild on purpose. I think the city needs them more than it knows.",
	},
	["sw.sub.park.03"] = {
		"Grass under my boots. I'd almost forgotten what that felt like inside these walls.",
		"Quiet here. Somebody tell the rest of the city.",
		"Shh. The trees are trying to think.",
	},
	["sw.sub.trade.01"] = {
		"steps into {subzone}, where every doorway seems to be shouting a price.",
		"is jostled at once by the crowd of {subzone}: porters, hawkers, a mage haggling over the price of ink.",
		"walks into {subzone}, all coin and clamor, where even the pigeons look like they're for sale.",
	},
	["sw.sub.trade.02"] = {
		"The bank, the auction house, the Gilded Rose. Everything a purse could want, and nothing it could keep.",
		"Somewhere in this district my coin goes to die. Usually at the auction house.",
		"Pastry from one door, ink and ledgers from the next. The bank never smells of pastry, and it never gives my coin back as quickly.",
	},
	["sw.sub.trade.03"] = {
		"First the bank, then the inn. In that order, or I'll have nothing left for the bank.",
		"Anyone selling something I need? No? Then I'll buy something I don't.",
		"Purse in one hand, list in the other. Let's see which runs out first.",
	},
	["sw.sub.valley.01"] = {
		"crosses {subzone}, the long road in from the gate, with the water of the moat glinting below the bridge.",
		"walks the length of {subzone} toward the city, past guards who watch every newcomer the same way.",
		"comes through {subzone}, where the road from the gate runs broad and straight over the water, built to impress.",
	},
	["sw.sub.valley.02"] = {
		"A valley named for heroes. I wonder which ones, and whether they'd recognize the place.",
		"Everyone who comes to the city walks this way. Kings, beggars, and now me.",
		"They built this entrance to make you feel small. It works, a little.",
	},
	["sw.sub.valley.03"] = {
		"Through the gate, over the bridge, into the city. The oldest road there is.",
		"Make way, make way. Or don't, I'm in no hurry on this road.",
		"Every hero walked in along this road once. Most of them on foot, I'd wager.",
	},
	["sw.thanks.01"] = {
		"Thank you. In a city this busy, a kind hand is worth more than gold.",
		"Much obliged. I'll remember that helping hand next time I'm lost in the canals.",
		"Thanks, truly. Stormwind could use more folk like you.",
	},
	["sw.toast.01"] = {
		"To Stormwind: white walls, warm bread, and ale that's almost dwarven!",
		"To the masons who built this place. May someone finally pay the bill, and the ale too.",
		"Drink up! To the city, the canals, and whoever's buying the next ale.",
	},
	["sw.toast.02"] = {
		"To the lion of Stormwind, and to all who stand beneath it.",
		"To the city that burned and rose again in stone. May it never have to rise again.",
		"Raise your cups: to stone that holds, and to friends who hold with it.",
	},
	["sw.travel.hearth"] = {
		"The hearthstone warms in my hand, and the bells of Stormwind blur into a hum.",
		"A breath, a lurch, and the white walls close like a book. The bells go on without me.",
		"I close my hand on the hearthstone. The city will keep.",
	},
	["sw.wx.fog"] = {
		"Fog rises off the water, and the towers of the keep fade into gray shapes.",
		"In this fog the canals vanish, and only the slap of water on the boats says they're still there.",
		"The fog swallows the far end of every street. Stormwind feels twice as large and half as friendly.",
	},
	["sw.wx.rain"] = {
		"stops under a stone arch as the rain arrives, and the gutters of the city begin to sing.",
		"watches every merchant in the square drag a tarp over the goods at the first drops of rain.",
		"hurries across the bridge as the rain turns the white stone gray.",
	},
	["sw.zone.ally.01"] = {
		"{zone}. Guards who nod instead of drawing steel. I could get used to that.",
		"Stone underfoot and a guard on every corner. {zone} has its comforts.",
		"Ah, {zone}. Somewhere the bread is warm and the blades stay in their sheaths.",
	},
	["sw.zone.ally.02"] = {
		"Every stone of this wall was set by hand after the burning. Lay a palm on it and you can almost feel the work.",
		"Once there was only ash here, they say. Now there are flower boxes under the windows.",
		"A city burned to the ground that decided, stone by stone, to stand up again.",
	},
	["sw.zone.ally.03"] = {
		"steps aside for a cart of barrels as {zone} rumbles on: hammers, hooves, someone haggling over onions.",
		"is swallowed by the noise of {zone}: wheels on stone, a smith's hammer, a child chasing a dog.",
		"weaves between carts and porters, the din of {zone} closing in on every side.",
	},
	["sw.zone.ally.04"] = {
		"The lion still flies over {zone}. Good. Let it.",
		"Blue and gold banners on every tower. Whatever comes, this city has not knelt.",
		"{zone} stands. As long as it does, so do we.",
	},
	["sw.zone.first.01"] = {
		"So this is {zone}. White walls, blue roofs, and more stone than I knew the world had.",
		"{zone}. The walls rise white from the edge of the forest, and the gate alone could swallow a village.",
		"Stone raised on the ashes of stone: {zone} stands where the orcs once left nothing, and it stands tall.",
	},
	["sw.zone.first.02"] = {
		"slows beneath the great gate of {zone}, head tilted back to take in the banners.",
		"stops on the bridge over the moat and looks up, as everyone does the first time.",
		"lets the crowd flow past at the gate of {zone}, eyes on the blue banners snapping overhead.",
	},
	["sw.zone.horde.01"] = {
		"Blue tabards everywhere. Every one of them would know me for an enemy at a glance.",
		"Enemy stone, enemy streets. I count the gates and keep my back to a wall.",
		"{zone}. The heart of the Alliance, and I walked in through the front. Quietly, now.",
	},
	["sw.zone.horde.02"] = {
		"Nice walls. Taller than I expected. Not tall enough.",
		"So this is where they keep their king. Smaller than the stories.",
		"Pretty city. Loud guards. Let's not stay for supper.",
	},
	["sw.zone.night"] = {
		"Night in {zone}: lamps on the bridges, their light shaking in the black water of the canals.",
		"The lamplighters have been through. Every canal carries a double row of small flames tonight.",
		"After dark the white stone turns blue, and the canals hold the lamplight like coins at the bottom of a well.",
	},
	["sw.zone.race.dwarf"] = {
		"Decent stonework, for folk who build under the open sky.",
		"Not bad, this masonry. A bit pale. Could use a mountain on top.",
		"The humans cut good stone. Shame they leave the roof off half the place.",
	},
	["sw.zone.race.gnome"] = {
		"Canals, sluices, a tram under the ground. Somebody in this city respects good plumbing.",
		"Stairs built for long legs, every last one of them. Still, the drainage is a small marvel.",
		"Open sky, wide streets, nothing ticking underfoot. A strange place for a tinkerer, and yet it will do.",
	},
	["sw.zone.race.human"] = {
		"Human-built, human-mended. Whatever else I am, this stone speaks my tongue.",
		"The cathedral bells carry all the way to the gate. I'd know them anywhere.",
		"My people burned here, and came back to build with the stone they had. That counts for something.",
	},
	["sw.zone.race.nightelf"] = {
		"So much cut stone, and the trees kept in tidy squares like polite guests.",
		"Walls on every side, and the sky sliced into narrow strips. Humans like a roof over their thoughts.",
		"They quarried a whole hillside of stone to raise this. My people would have asked the forest first.",
	},
	["sw.zone.rain"] = {
		"pulls up a collar as rain runs off the blue roofs of {zone} and down every gutter.",
		"hurries across a square gone slick with rain, the white stone shining like wet bone.",
		"ducks under an awning while the rain drums on the water of the canals.",
	},
	["sw.journey.arrival.w01.01"] = {
		"A long flight, and Stormwind at the end of it. The stones of the Trade District feel like an old friend's handshake.",
		"After all that sky, the city's racket is almost welcome. Almost.",
		"That was a long haul in the saddle. Nothing looks quite as solid as these white walls after it.",
	},
	["sw.journey.arrival.w01.02"] = {
		"climbs down from the gryphon as a dwarf of the roost takes the reins and mutters something kind to the animal.",
		"lands among the gryphon roosts, feathers drifting, and steps aside as another rider takes off overhead.",
		"stretches stiff legs at the gryphon roost, the smell of bread and horses drifting in from the Trade District.",
	},
	["sw.journey.start.w01.01"] = {
		"climbs above the Trade District on gryphon wings, the Cathedral's spires catching the light as the city tilts away below.",
		"wheels once over Stormwind as the gryphon finds the wind, the canals and the violet towers of the Mage Quarter sliding past.",
		"rises high over the white walls, the great statues at the gate shrinking to toy soldiers behind.",
	},
	["sw.journey.start.w01.02"] = {
		"Stormwind falls behind, bells and all. I always wonder what will have changed by the time I see these walls next.",
		"Below me the city's racket thins to a hum, then to nothing. The sky up here has no market days.",
		"Farewell for now, white walls. It's a long way ahead, and I'll carry the noise of your streets with me for a while yet.",
	},
	["sw.journey.start.w01.03"] = {
		"Up we go! Mind the rooftops, beast.",
		"Off again. Try not to drop me in the canal, friend.",
	},
	["sw.quest.w01.01"] = {
		"Done. A city this size runs on a thousand small loyalties, and today one of them was mine.",
		"One more thread in the weave that holds Stormwind together. The regent will never hear of it, and that's fine.",
		"Finished. The king is still missing, but the city keeps going, and so do its people.",
	},
	["sw.quest.w01.02"] = {
		"Done. I'd ask for a statue at the gate, but I hear the waiting list is long.",
		"Handled. Stormwind thanks you, says nobody, but I'll hear it anyway.",
	},
	["sw.quest.w01.03"] = {
		"is thanked warmly, and the smell of fresh bread drifting down the street seems, for a moment, part of the reward.",
		"shakes the hand offered in thanks while a child runs past chasing a hoop along the street.",
	},
	["sw.quest_complete.w02.01"] = {
		"Done. I'll be at the Pig and Whistle if anyone needs proof.",
		"Finished. One more little knot in this city untied; only ten thousand left.",
		"Sorted. Tell the next person with a problem I'm down by the canals, catching my breath.",
	},
	["sw.quest_complete.w02.02"] = {
		"Done. White stone, blue banners, and behind them people who needed a hand. I gave one.",
		"Finished. Even a great city still runs on small help, carried from door to door.",
	},
	["sw.dawn.w04.001"] = {
		"hears the watch change on the walls as dawn comes up: a muttered handover, a yawn, boots going home.",
		"watches the first boats push off along the canals at dawn, poles dipping quietly into the still water.",
	},
	["sw.farewell.w04.001"] = {
		"Off I go. Keep to the lit streets, and give my regards to the canals.",
		"Look after yourself. Never buy anything at the first stall you see; that's all the wisdom I have.",
	},
	["sw.farewell.w04.002"] = {
		"May your road lead you back to these walls.",
		"Go well, and come back without a scratch. The bridges need people to cross them.",
	},
	["sw.greet.w04.001"] = {
		"Hail. You look like someone who knows where the good bread is.",
		"Hello there! Looking for the way, or just admiring the canals like the rest of us?",
		"Greetings. Mind your purse around here; I say it to everyone.",
	},
	["sw.greet.w04.002"] = {
		"Light be with you, and with whatever brings you to the city.",
		"The Light keep you, on these streets and past them.",
	},
	["sw.greet.w04.003"] = {
		"Hello. If you're selling something, I already own two of it.",
		"Hey there. If this is about a debt, you have the wrong face.",
	},
	["sw.journey.w04.001"] = {
		"is lifted clear of the walls in three hard wingbeats, and the green of Elwynn spreads out past the moat as far as the hills.",
		"rises over the gate and the moat, the forest rolling away beyond them in every shade of green.",
		"climbs out above the city's edge, where white stone gives way at once to the dark green of Elwynn.",
	},
	["sw.journey.w04.002"] = {
		"holds on as the handler slaps the gryphon's flank and it launches, scattering every pigeon on the roost.",
		"is barely in the saddle before the gryphon bounds off the roost, and a cloud of startled pigeons breaks around them.",
		"grabs the harness as the beast leaps; below, the pigeons of the Trade District burst up and away in every direction.",
	},
	["sw.journey.w04.003"] = {
		"The walls drop away and something in my shoulders lets go. Stone keeps you safe; it also keeps you in.",
		"Leaving the city always loosens a knot I didn't know I'd tied. Walls are kind, and walls are heavy.",
		"Out past the walls, and I breathe differently. The city holds you close, sometimes too close.",
	},
	["sw.journey.w04.004"] = {
		"Onward! Out there, trouble is waiting for me to show up late.",
		"Up and away. Let's go find whatever needs finding.",
		"And off we go! Wherever it is, I bet it's lovely this time of year.",
	},
	["sw.journey.w04.005"] = {
		"From up here the auction house looks tiny. It never seemed tiny while I was losing money in it.",
		"The bank shrinks to a pebble below me. Everything I own fits in that pebble. Humbling.",
		"From this height the Trade District is a toy town, and nobody can sell me anything. Bliss.",
	},
	["sw.journey.w04.006"] = {
		"looks back at the towers of the keep as the gryphon climbs, the great banners on them streaming stiff in the wind.",
		"catches a last sight of the keep over one shoulder, its blue and gold standards straining on their poles.",
		"turns in the saddle to see the keep's high towers drop below, a banner snapping on every one.",
	},
	["sw.journey.w04.007"] = {
		"From above, the districts finally make sense: here the canals, there the forges, the green square of the Park. Down there it all felt like a maze.",
		"It took a gryphon to show me the plan of this city: the canals running between the quarters like the lines of a ledger.",
		"Up here Stormwind is a drawing in a master mason's book, every quarter in its place.",
	},
	["sw.journey.w04.008"] = {
		"Tell me when we're clear of the towers. I'm keeping my eyes shut until then.",
		"Is that the cathedral spire getting closer, or are we just very brave?",
		"Higher, please. Higher than the spires. Thank you.",
	},
	["sw.journey.w04.009"] = {
		"rises into the dark over Stormwind, the lamps of the city spread below like embers raked across a hearth.",
		"climbs away from the city by night, its lit windows and lanterns shrinking to a scatter of sparks.",
		"leaves the lights of Stormwind behind in the night, a glowing smudge on the black of the forest.",
	},
	["sw.journey.w04.010"] = {
		"Leaving at first light, the bakers' chimneys smoking under me. The city smells of bread all the way up here.",
		"Dawn flight. Stormwind's still yawning below, one chimney at a time.",
		"Early wings. The streets are empty but for carts and oven smoke, and the sky is all mine.",
	},
	["sw.journey.w04.011"] = {
		"Flying in the rain: wet harness, wet feathers, and the city below gone gray as slate.",
		"Rain in my eyes and the gryphon shaking its head at every gust. Landing will please us both.",
		"Up through the rain. Stormwind blurs under me like a wet painting.",
	},
	["sw.journey.w04.012"] = {
		"climbs out of the fog over Stormwind, and in a few wingbeats the whole city is gone beneath a gray sea under open sky.",
		"rises through the fog until only the tips of the highest towers show, like masts above the water, and then only sky.",
		"breaks out of the gray above the rooftops into clear sky, leaving the fogbound streets and their muffled bells below.",
	},
	["sw.journey.w04.013"] = {
		"The city has plenty of hands. Out there is a place that has too few. That's where I'm headed.",
		"Stormwind will manage without me. The roads beyond it might not.",
		"The walls stay; I go. Past the forest, someone's day is going worse than mine.",
	},
	["sw.journey.w04.014"] = {
		"Fly on. The city can spare me for a while.",
		"Go. Stormwind has guards enough; the road has fewer.",
	},
	["sw.journey.w04.015"] = {
		"glances down to see a child on a bridge waving up at the gryphon with both arms, and lifts a hand in answer.",
		"is waved off by a small boy on the canal bank, who keeps waving long after the gryphon has passed.",
		"catches sight of a few faces turned up from the street below, a child among them pointing and shouting.",
	},
	["sw.journey.w04.016"] = {
		"lands at the roost and is at once offered a porter, a hot pie and a map of the city, all before {g:his|her} boots have settled.",
		"steps down from the gryphon into a small crowd of errand-runners, each sure {g:he|she} needs exactly what they sell.",
		"has hardly touched the ground before a pie seller and a boy offering to carry bags start arguing over who saw {g:him|her} first.",
	},
	["sw.journey.w04.017"] = {
		"Feet down, list out: repairs, supplies, a hot meal, a bed. The city can have me in that order.",
		"Back on the cobbles with a list as long as my arm, and every item on it costs something.",
		"Down at last. Before anything else, a smith to look at these buckles.",
	},
	["sw.journey.w04.018"] = {
		"Feathers down my collar again. Every flight, without fail.",
		"Who keeps letting these birds molt on the passengers?",
		"There's a feather in my ear. I'm choosing not to ask how.",
	},
	["sw.journey.w04.019"] = {
		"The handler is already brushing the gryphon down and fetching it meat. Nobody's offered to brush me.",
		"The gryphon gets a rubdown and a bucket of fish. I get a sore back and a long walk to the inn.",
		"Look at that: a groom and a meal waiting for the beast. Whoever rode it gets directions, at best.",
	},
	["sw.journey.w04.020"] = {
		"tests the cobbles with one foot, as if they too might bank and dive, before walking on into the city.",
		"waits a moment after landing for the street to stop feeling like it is moving, then sets off.",
		"takes a few careful steps on the paving, like a sailor fresh off a boat, until the legs remember the ground.",
	},
	["sw.journey.w04.021"] = {
		"Half the kingdom passed under me today. My knees would like it known that they were not consulted.",
		"A long flight, and every mile of it settled in my back. The inn's beds had better be soft.",
		"That was the long way across the map. I'll be walking crooked until supper.",
	},
	["sw.journey.w04.022"] = {
		"Down in the dark. One lantern at the roost, a handler yawning, and the city asleep around us.",
		"Landing at night is an act of faith: you trust the beast knows where the ground is. It did.",
		"Night in Stormwind, and the roost keeps one lamp lit for whoever comes down out of the sky.",
	},
	["sw.journey.w04.023"] = {
		"lands as the first carts of the morning roll in from Elwynn, loaded with apples and cabbages for the market.",
		"comes down at dawn into a city just opening its shutters, the smell of the first bread rising from the ovens.",
		"touches down while the lamplighters go round putting out the last lamps, one by one.",
	},
	["sw.journey.w04.024"] = {
		"lands in a spray of puddle water as the rain comes down, and the handler hurries a blanket over the gryphon's back.",
		"slides down into the rain at the roost, the gryphon shaking itself like a wet dog the moment it lands.",
		"comes down through the rain onto slick stone, and ducks for the nearest roof with water running off every edge.",
	},
	["sw.journey.w04.025"] = {
		"Down through the fog on trust alone. The gryphon found the roost by smell, I think; I found it by the bells.",
		"Fog all the way down. One moment gray nothing, the next a rooftop and the bump of landing.",
		"I couldn't see the city until we were in it. The fog gave Stormwind back to me one wall at a time.",
	},
	["sw.journey.w04.026"] = {
		"Home ground, as near as I have one. The hearth I'm bound to and the city around me finally agree.",
		"Back where my hearth is bound. The road was long; these streets are the end of it, for a while.",
		"Here's the city that keeps my hearth. Whatever I carried out there, I can set it down here.",
	},
	["sw.journey.w04.027"] = {
		"Special delivery from the sky: me. Anyone want it? Not even the pigeons?",
		"Here I am, Stormwind! Hold your applause. No, really, you can stop holding it now.",
	},
	["sw.journey.w04.028"] = {
		"Coming in, the city looked like a white shield someone had set down in the middle of the forest.",
		"From the air, Stormwind is a shield lying on green cloth. From the ground, it's just home to a lot of noise.",
		"The walls looked like a shield from up there. Now that I'm inside them, I see they're also a crowd.",
	},
	["sw.journey.w04.029"] = {
		"scratches the gryphon under the beak before letting it go, and the beast bears it with great dignity.",
		"gives the gryphon a farewell pat on the neck, which it accepts the way a lord accepts a petition.",
		"offers the gryphon a scratch behind the feathered ear; it leans in, just slightly, then pretends it didn't.",
	},
	["sw.muse.w04.001"] = {
		"Every merchant in the Trade District swears their prices are the lowest in the city. Arithmetic says somebody is lying.",
		"Three stalls in a row, and by its own sign each one is the cheapest in Stormwind. The signs should meet and settle it.",
		"In the Trade District the cheapest shop in the kingdom changes hands every ten paces, and so does my coin.",
	},
	["sw.muse.w04.002"] = {
		"pauses to let a porter pass, a stack of crates on his back taller than he is, swaying through the crowd without touching anyone.",
		"steps aside for a porter bent under a tower of crates, who threads the crowd as if he had counted every elbow in it.",
		"flattens against a wall as a hand cart piled with bolts of cloth rattles past, its driver shouting apologies nobody hears.",
	},
	["sw.muse.w04.003"] = {
		"The bank keeps whatever people can neither carry nor bear to sell. Some of those boxes have been waiting a long time for owners who rode out the gate.",
		"Rows of strongboxes behind the bank counter, each one somebody's 'later'. Not every later comes.",
	},
	["sw.muse.w04.004"] = {
		"A sword, a meat pie and a new pair of boots, all on one street. Stormwind spoils a traveler.",
		"Pies on one corner, blades on the next, boots across the way. This city knows exactly what a traveler needs.",
		"Fresh bread, sharp steel and somebody to mend my cloak, all within shouting distance. I could get soft here.",
	},
	["sw.muse.w04.005"] = {
		"The auctioneers never look up from their ledgers. A fortune changes hands under their noses, and all they write down is the fee.",
		"A clerk at the auction house records a sale that would buy a farm in Westfall, blots the ink and calls the next lot.",
	},
	["sw.muse.w04.006"] = {
		"By the bank steps there's always some family from Westfall with everything they own in one sack. The coin walks past them all day long.",
		"Farmers' boots, farmers' hands, and no farm. There are more refugees from the west in these streets than the city cares to count.",
		"The people who used to grow Stormwind's grain now queue for Stormwind's charity. The bread comes back to them by a crueler road.",
	},
	["sw.muse.w04.007"] = {
		"counts what is left in {g:his|her} purse, glances at the shopfronts of the city, then counts again.",
		"weighs the purse in one hand, as if Stormwind's prices could be argued with by feel.",
	},
	["sw.muse.w04.008"] = {
		"Letters go into the mailbox outside the bank and come out anywhere in the world. Nobody here finds that strange, and I suppose neither do I.",
		"A whole kingdom's worth of letters must pass through that mailbox by the bank. Bills, mostly, I'd guess. And the odd love letter.",
	},
	["sw.muse.w04.009"] = {
		"Somewhere in the cathedral Archbishop Benedictus is praying for the whole city at once. That must be a long prayer.",
		"The archbishop prays for Stormwind every day, the priests say. Somebody ought to pray for the archbishop.",
		"One old man in white, holding up a whole city's worth of prayers. I hope the Light lets him sit down now and then.",
	},
	["sw.muse.w04.010"] = {
		"The orphanage near the cathedral is never empty. Every war fills a few more beds.",
		"Children from the orphanage, two by two behind the matron. Each of those small hands was let go by someone who never came back.",
	},
	["sw.muse.w04.011"] = {
		"Whatever the Light is, the cathedral is the best argument for it this city has. Even the doubters lower their voices on the steps.",
		"Some days I don't know what I believe. The cathedral doesn't ask; it just stays up there, very tall and very patient.",
		"Faith comes and goes in me like the tide. The cathedral stays where it is, which is more than I can say for my convictions.",
	},
	["sw.muse.w04.012"] = {
		"If the Light hears anything over the noise of this city, it hears the cathedral first.",
		"With bells like these, the Light can't claim it never heard from Stormwind.",
	},
	["sw.muse.w04.013"] = {
		"The fountains of this city all have coppers on the bottom. Wishes, mostly from people who couldn't spare the copper.",
		"Every fountain in Stormwind is a small treasury of wishes. Nobody fishes them out; even the pickpockets have that much decency.",
		"A copper in a fountain buys nothing at all, and the whole city keeps paying. That's hope, I suppose: a bad bargain everyone makes.",
	},
	["sw.muse.w04.014"] = {
		"SI:7 knows who I am. I'd bet on it. That's rather the point of SI:7.",
		"In some office in Old Town a clerk of SI:7 has a page with my name on it. I hope at least the handwriting is flattering.",
		"Nobody in this city is ever quite unwatched. SI:7 sees to that, and never lets you see it seeing.",
	},
	["sw.muse.w04.015"] = {
		"Old Town looks rough, but at least it's honest about it. The Trade District smiles while it picks your pocket.",
		"I trust Old Town more than the fine streets. In Old Town, at least, the knives are on show.",
	},
	["sw.muse.w04.016"] = {
		"The Champions' Hall hands out rank and title to those who fight the Horde in the field. The war is generous with ranks; with soldiers, less so.",
		"Banners and titles in the Champions' Hall, earned against the Horde. Every rank on the roll stands on a few who didn't come back to claim one.",
	},
	["sw.muse.w04.017"] = {
		"watches a pair of off-duty soldiers argue over a dice game on an upturned barrel, both of them losing.",
		"passes a doorway where two soldiers on leave play dice on a barrel lid, swearing in low, practiced voices.",
	},
	["sw.muse.w04.018"] = {
		"In Old Town a raised hood means nothing. A raised hood and good boots means SI:7.",
		"You learn to read Old Town by its boots. Worn ones are honest; soft new ones that make no sound are somebody's business.",
		"Old Town has two kinds of quiet: the quiet of folk minding their own, and the quiet of folk minding yours.",
	},
	["sw.muse.w04.019"] = {
		"The Pig and Whistle pours the kind of ale that starts arguments and serves the kind of stew that ends them.",
		"The Pig and Whistle: crooked sign, sticky floor, and nobody ever turned away for being too dusty.",
		"Half the soldiers of Old Town drink at the Pig and Whistle, and the other half are on their way there with a story.",
	},
	["sw.muse.w04.020"] = {
		"Rats ride the Deeprun Tram too, the dwarves say. Under the water and back, bold as nobles, and never a copper paid.",
		"The rats of the Deeprun Tram have the best bargain in the kingdom: free passage both ways, and nobody checks.",
		"Somewhere under the Dwarven District a rat is riding to Ironforge in more comfort than most dwarves.",
	},
	["sw.muse.w04.021"] = {
		"The dwarves of Stormwind complain about the open sky the way humans complain about the weather: daily, and with no intention of leaving.",
		"Every dwarf in the Dwarven District has the same complaint: fine walls, no cellars worth the name. They say it over the anvil and stay anyway.",
		"Dwarves in a human city grumble about the ceiling being too high. It's the sky. They know. They grumble anyway.",
	},
	["sw.muse.w04.022"] = {
		"You can always tell who just came up from the Ironforge tram: they squint at the open sky as if it might fall on them.",
		"Folk coming up from the tram stop at the top of the ramp and look up. Ironforge has a ceiling; Stormwind has weather.",
	},
	["sw.muse.w04.023"] = {
		"Gnomes in every corner of the Dwarven District, mending things that aren't theirs for coin they badly need. Gnomeregan is a long way down and a long way gone.",
		"The gnomes here talk about Gnomeregan the way sailors talk about a sunken ship: in the present tense, and quietly.",
		"Clever hands, borrowed workbenches, and a home lost under the snow of Dun Morogh. The gnomes of Stormwind fix everything except that.",
	},
	["sw.muse.w04.024"] = {
		"If it's broken, take it to the Dwarven District. If it's broken and smoking, take it to a gnome.",
		"Dwarves for whatever needs hammering, gnomes for whatever needs a lever and a long explanation.",
	},
	["sw.muse.w04.025"] = {
		"Whenever the city gets too loud I think of the tram rattling along far below. Under all this, two cities are holding hands in the dark.",
		"Stormwind and Ironforge, joined by a tunnel under the water. Most alliances are made of parchment; this one is made of rock.",
		"Treaties fade and kings go missing, but the tunnel to Ironforge is still down there, carrying dwarves and gnomes and gossip both ways.",
	},
	["sw.muse.w04.026"] = {
		"The tower of the Mage Quarter leans over the rooftops as if it were eavesdropping. Knowing mages, it probably is.",
		"That violet tower sees the whole city. I'd give a good deal to know what a mage writes down about the rest of us.",
		"The mages' tower watches Stormwind like a heron watches a pond: patiently, and with a very sharp beak somewhere.",
	},
	["sw.muse.w04.027"] = {
		"The Mage Quarter smells of ink, sulfur and dried herbs, depending on which way the wind decides to be clever.",
		"Every shop in the Mage Quarter has a smell you can't name and a shopkeeper who won't name it for you.",
	},
	["sw.muse.w04.028"] = {
		"Apprentice mages are like puppies: big feet, loud noises, and every so often something catches fire.",
		"Never stand downwind of an apprentice mage. Or upwind. Just stand somewhere else.",
		"Rule of the Mage Quarter: if an apprentice says 'stand back', you're already too close.",
	},
	["sw.muse.w04.029"] = {
		"Some robes in the Mage Quarter are too dark, and the smiles above them too careful. Stormwind lets them be, and keeps a guard on the corner.",
		"The city tolerates its warlocks the way a house tolerates a cellar door that won't quite shut.",
	},
	["sw.muse.w04.030"] = {
		"The mages of Stormwind still speak of Dalaran in lowered voices, the way you'd speak of a house still standing that is no longer yours.",
		"Half the books in the Mage Quarter came out of Dalaran before it fell, the booksellers like to say. Nobody says which half.",
		"Every library here has a shelf or two that smells of Dalaran. The mages handle those books like letters from the dead.",
	},
	["sw.muse.w04.031"] = {
		"The canals carry off everything the city wants to forget: peel, ash, letters torn in four. A day later it's all somewhere downstream.",
		"Whatever falls into a Stormwind canal is gone before the next bell. Useful, for certain people.",
	},
	["sw.muse.w04.032"] = {
		"A bridge every twenty paces. This city can't decide which side of the water it wants to be on.",
		"Six bridges to get somewhere a stone's throw away. Stormwind has a sense of humor.",
		"Whoever drew the canals of this city never had to walk to the bank in a hurry.",
	},
	["sw.muse.w04.033"] = {
		"stops at a canal rail, where the water is the color of old pewter, and lets the noise of the city go past overhead.",
		"rests both forearms on the stone rim of a canal and gazes down as the water slides patiently under the bridges.",
	},
	["sw.muse.w04.034"] = {
		"The boatmen say that if anyone ever drained the canals, half the city's secrets would be lying in the mud, and the other half standing on the bank, sweating.",
		"Drain the canals, the boatmen like to say, and you'd find enough daggers to arm a garrison and enough rings to marry it off.",
	},
	["sw.muse.w04.035"] = {
		"The canals give the city a second sky to look at, upside down and full of trembling roofs.",
		"Look down from any bridge and there's another Stormwind in the water: quieter, and a little crooked.",
		"Under every bridge the city goes on upside down, towers hanging into the green, and nobody in that one is in a hurry.",
	},
	["sw.muse.w04.036"] = {
		"The night elves tend the Park as if the city around them were only passing through. Given how long they live, perhaps it is.",
		"A grove of night elves inside a human city. A small embassy of trees, and a quiet one.",
		"In the Park the elves prune nothing, hurry nothing, and somehow the trees grow straighter than the streets.",
	},
	["sw.muse.w04.037"] = {
		"When Stormwind gets too loud, I go and stand under the trees in the Park for a while. Then I come back. I'm not a squirrel.",
		"A walk in the Park cures most things. Not the prices, but most things.",
	},
	["sw.muse.w04.038"] = {
		"Lovers in the Park, old men in the Park, druids in the Park. Everyone in this city goes there to be somewhere else for a while.",
		"The Park is where Stormwind keeps its quiet, the way a house keeps its good dishes: seldom used, but always there.",
		"Some days the only grass I want to see is in the Park, between walls, where nothing in it wants to bite me.",
	},
	["sw.muse.w04.039"] = {
		"The stone heroes at the gate are taller than any hero ever was. That's the point: you walk beneath them and find yourself straightening your back.",
		"Statues of the old heroes stand along the road in. Not one of them looks tired. Stone is kind that way.",
		"The heroes of the valley never age, never limp, never ask for their pay. Easy to honor, heroes made of stone.",
	},
	["sw.muse.w04.040"] = {
		"Old soldiers in the taverns still raise a cup to Lothar, the Lion of Azeroth, as if he might walk in late and sit down.",
		"Lothar led the people out when the first city burned. Every lion on these banners owes him something.",
		"Ask any veteran in Stormwind about the Lion of Azeroth and watch them stand a little straighter before they answer.",
	},
	["sw.muse.w04.041"] = {
		"All day the gate swallows Elwynn: carts of apples, pilgrims, recruits, farmers' sons with the dust still on them.",
		"The gate of Stormwind never shuts its mouth. Elwynn goes in by the cartload, and the world comes out armed.",
	},
	["sw.muse.w04.042"] = {
		"Walls this thick were built by people who had already lost a city once. You can tell.",
		"These walls aren't for show. They were raised by folk who remembered the last ones falling.",
		"Nobody builds this deep unless the ground has burned under them before.",
	},
	["sw.muse.w04.043"] = {
		"The moat before the gate is wide enough to make an army think twice. Stormwind learned the hard way that thinking twice is cheaper than rebuilding.",
		"Water before the gate, stone behind it, guards on both. The orcs found the old city easier. That was the idea.",
	},
	["sw.muse.w04.044"] = {
		"Bolvar Fordragon holds the kingdom the way a soldier holds a shield too long: steady, and paying for it in the shoulders.",
		"A paladin minding a throne that isn't his. Bolvar never asked to be regent, the guards say, and maybe that's why they trust him.",
		"The Highlord carries the crown's weight without the crown. I'm not sure which of the two is heavier.",
	},
	["sw.muse.w04.045"] = {
		"Lady Prestor is always at the regent's side, always smiling, always agreeing. Nobody is that agreeable for free.",
		"A noblewoman of Alterac, they say, whose family lands nobody has ever seen. And the whole court hangs on her every word.",
		"The way the court leans toward Lady Prestor when she speaks: like grass before a wind nobody else can feel.",
	},
	["sw.muse.w04.046"] = {
		"Lady Prestor? Charming, they say. Like a velvet glove. I'd like a look at the hand.",
		"Everyone at court adores Lady Prestor. That's what worries me.",
		"Lady Prestor smiles at everyone. Cats do that too, just before the bird.",
	},
	["sw.muse.w04.047"] = {
		"Every proclamation in the city goes out under the seal of a boy king. I wonder if anyone lets him read them first.",
		"Anduin Wrynn: a king by name, a child by every other measure, and a city that has to pretend the first is enough.",
		"Somewhere in the keep a boy is learning his letters and his kingdom at the same desk. I hope they give him time for the letters.",
	},
	["sw.muse.w04.048"] = {
		"The king went out to talk peace and never came back. Nobody in the keep will say where the road ended.",
		"King Varian is missing, not dead. The whole city leans on that one word, 'missing', like a crutch.",
		"The king will ride back through the gate any day now, people say. The bakers say it too, and they've stopped looking up when they do.",
	},
	["sw.muse.w04.049"] = {
		"Long live the king, wherever he is. And long live the boy keeping his chair warm.",
		"A missing king, a boy king, and a regent in between. Stormwind still stands; somebody's doing something right.",
		"The throne has a boy on it, a paladin beside it, and an empty space behind it. Still, the bread comes out of the ovens on time.",
	},
	["sw.muse.w04.050"] = {
		"pauses as a herald's voice carries over the rooftops from the direction of the keep, reading out a decree the street pointedly ignores.",
		"half-listens to a crier reading a proclamation in the name of the boy king, while a passing cart rolls over the end of it.",
	},
	["sw.muse.w04.051"] = {
		"The guards of the keep stand so still the pigeons have started to trust them.",
		"Try making a guard of the keep blink. People do. The guard always wins, without noticing there was a contest.",
	},
	["sw.muse.w04.052"] = {
		"The masons raised the cathedral too. Every hymn under that roof is sung on stone nobody paid for.",
		"Even the house of the Light was built on credit. The masons are still waiting; the Light, as far as I know, hasn't said.",
	},
	["sw.muse.w04.053"] = {
		"Real masons mark their blocks, the old builders say: a hook, a star, a little hammer. Somewhere in these walls are signatures on a bill that was never settled.",
		"Every block of these walls carries its mason's mark, the builders say, the way a letter carries its writer's hand. Nobody reads them now.",
	},
	["sw.muse.w04.054"] = {
		"Edwin VanCleef led the masons who rebuilt this city. Now the city says his name the way you'd spit.",
		"A master mason with a grievance and a gift for being followed. Stormwind made an outlaw of the one man who knew where all its walls were weakest.",
		"VanCleef put up these walls and then put on a mask. Somewhere between the two, a noble decided a debt was optional.",
	},
	["sw.muse.w04.055"] = {
		"Pay your masons. Somebody should carve that over every gate in the kingdom.",
		"Lesson of Stormwind, free of charge: pay the folk who build your walls, or they'll learn where the gaps are.",
		"Want to know what a bad debt costs? Ask Westfall. Then ask the nobles why they didn't.",
	},
	["sw.muse.w04.056"] = {
		"A red kerchief in a city crowd always turns a few heads. Usually it's only a farmer with poor taste. Usually.",
		"Since the Defias, nobody in Stormwind wears red around the face. Fashion follows fear.",
		"Show a scrap of red cloth near your chin in this city and the guards remember your face for a week.",
	},
	["sw.muse.w04.057"] = {
		"There are wives and children of masons in this city whose men went west and never came back. They still live under the walls those men built.",
		"The masons' families never left. Mothers, sons, a sister or two, living in rooms beneath stonework the missing men set.",
	},
	["sw.muse.w04.058"] = {
		"Not every mason took the mask. Some stayed, took whatever work the city offered, and keep their mouths shut over their ale.",
		"A few old masons never followed the Brotherhood. They still mend the city's walls, slowly, and never mention the bill.",
		"You can tell the masons who stayed by their hands and their silence. They patch the stone they were never paid for, and say nothing.",
	},
	["sw.muse.w04.059"] = {
		"Westfall burns because a ledger in this city didn't balance. Think about that next time you admire the stonework.",
		"Every barn the Defias set on fire out west was paid for by a bill left unpaid in this city.",
	},
	["sw.muse.w04.060"] = {
		"The nobles who wouldn't pay the masons still dine in their fine houses, a stone's throw from the walls they never paid for.",
		"The nobles' houses are the finest work the masons ever did. I wonder if the nobles ever think about that over supper.",
		"Marble stairs, carved lintels, a lion over every door: the nobles live inside the masons' best argument and never hear it.",
	},
	["sw.muse.w04.061"] = {
		"runs a hand along a block of the wall, where the mortar line is as straight as a ruled page, and lingers there a moment.",
		"traces the seam between two white stones with a fingertip, as though reading something written there.",
		"rests a palm flat against the cool stone of a wall for a breath, then lets it fall.",
	},
	["sw.muse.w04.062"] = {
		"The Defias don't need to come over the walls. They could have cut keys to half these doors while they were hanging them.",
		"Men who set every lintel in the city know which doors stick and which ones never lock. If I were a noble, I'd change the locks.",
	},
	["sw.muse.w04.063"] = {
		"Humans, dwarves, gnomes, night elves, all elbowing down one street. Stormwind is what the Alliance looks like before anyone tidies it up.",
		"Four peoples in one crowd, four ways of saying 'excuse me', and none of them used.",
		"Every tongue of the Alliance in one street, and the only word they all agree on is the price of bread.",
	},
	["sw.muse.w04.064"] = {
		"steps aside for a night elf who walks as if the cobbles might wake, followed by a gnome who walks as if they owed him money.",
		"is overtaken by a gnome at a near run, then by a dwarf at a steady stump, then by a human apologizing to both.",
	},
	["sw.muse.w04.065"] = {
		"On market days Elwynn comes to the city with apples, cheese and wool, and goes home with nails, gossip and a headache.",
		"The farmers of Elwynn stand out in the crowd: sunburned necks, slow steps, and a careful grip on their purses.",
	},
	["sw.muse.w04.066"] = {
		"You hear Darkshire in some voices here, and Lakeshire in others. People come to the capital asking for soldiers and go home with promises.",
		"Petitioners from Redridge and Duskwood wait on benches for an audience that comes late, if it comes. The kingdom is wide and the regent is one man.",
		"Every town that sends a rider to Stormwind sends the same message in different words: we're holding, but not for long.",
	},
	["sw.muse.w04.067"] = {
		"The children of Stormwind play guards and Defias in the alleys. The Defias always win; the guards always get the better sticks.",
		"Every child in this city owns a wooden sword and a list of who has to be the villain today.",
	},
	["sw.muse.w04.068"] = {
		"Soldiers on leave walk Stormwind as if the street were thin ice, waiting for the noise to turn into something else.",
		"You can spot the ones just back from the front: they flinch at the bells and sleep through the shouting.",
		"A soldier on leave sits with his back to every wall in the tavern. The city is safe. His shoulders haven't heard.",
	},
	["sw.muse.w04.069"] = {
		"Pilgrims come from all over the kingdom to see the cathedral, then spend half a day lost among the canals. The Light makes them work for it.",
		"Pilgrims always ask the way to the cathedral, always get three answers from three strangers, and always thank all three.",
	},
	["sw.muse.w04.070"] = {
		"A dwarf in a Stormwind tavern will tell you the stout here is weak. Then he'll order four more to be sure.",
		"Dwarves complain about human ale with real dedication. They've been doing it at the same tables for years.",
		"No dwarf has ever praised a Stormwind brew out loud. Plenty of them have finished the barrel to make their point.",
	},
	["sw.muse.w04.071"] = {
		"Gryphons come and go over the rooftops at all hours. The city stopped looking up long ago; I haven't, yet.",
		"Every gryphon overhead is someone leaving or someone coming home. Stormwind never notices; the gryphon masters always do.",
	},
	["sw.muse.w04.072"] = {
		"When the bells of the cathedral and the keep ring together, the whole city seems to stop for a heartbeat, like a held breath.",
		"There's a moment, when all the bells answer one another at once, that even the merchants stop shouting. It never lasts. It always comes back.",
		"One bell starts, a second takes it up, and then the whole sky over Stormwind is ringing like a struck shield.",
	},
	["sw.muse.w04.073"] = {
		"Nobody in Stormwind is ever late. They're just 'after the bell'. Which bell is a matter of opinion.",
		"'Meet me at the bell,' they say here. There are a dozen bells. Half the city is still waiting for the other half.",
	},
	["sw.muse.w04.074"] = {
		"The bells ring slow for the dead and quick for a wedding. Stormwind hears both most weeks, and buys its bread either way.",
		"Slow peals for a funeral, quick ones for a wedding. Live here long enough and you know the city's news without asking a soul.",
	},
	["sw.muse.w04.075"] = {
		"counts the strokes of a distant bell under {g:his|her} breath, and loses count somewhere after nine.",
		"tilts {g:his|her} head toward a bell ringing somewhere across the rooftops, as if it had said a name.",
	},
	["sw.muse.w04.076"] = {
		"The patrols keep the same rounds at every turn of the watch. A patient thief could time them; so could their sergeant, which is the point.",
		"Same streets, same rounds, same polished boots. The city guard has made routine into a kind of armor.",
		"A guard's day here is a thousand steps on the same stones. Nobody sings about it, and the city would fall apart without it.",
	},
	["sw.muse.w04.077"] = {
		"Lost your purse? A Stormwind guard will help you look. Lost your temper? That's a different service.",
		"The guards here will point you anywhere in the city. Just don't ask for the way into a noble's house after hours.",
	},
	["sw.muse.w04.078"] = {
		"I'd wager more eyes on the walls watch the western road than any other. Proclamations can say what they like; guards know where trouble walks in from.",
		"A guard's eyes are the best news in the city. Watch where they drift, and you'll know what the keep is afraid of this week.",
	},
	["sw.muse.w04.079"] = {
		"returns the nod of a passing guard, a small courtesy between two people who both have somewhere to be.",
		"watches a guard set a fallen shop sign upright without breaking stride, as if it were part of the patrol.",
		"falls into step beside a patrol for a few paces, then lets it draw ahead, the clink of mail fading down the street.",
	},
	["sw.muse.w04.080"] = {
		"At night the Trade District goes dark first and Old Town last. Coins sleep early; secrets keep late hours.",
		"When the shops shutter for the night, Stormwind's other trade begins: whispers in doorways, coins that don't jingle.",
	},
	["sw.muse.w04.081"] = {
		"walks beneath the dark windows of a sleeping street, boot heels loud on the stone, one window still lit high in some tower.",
		"passes a guard whose lantern swings in slow arcs, the only moving light in a street gone to sleep for the night.",
	},
	["sw.muse.w04.082"] = {
		"At dawn the first carts from Elwynn rumble in through the gate, loaded with milk and eggs, before the city has even dressed.",
		"The street sweepers have finished their round by dawn, before half of Stormwind opens an eye. Nobody ever thanks a sweeper.",
		"Dawn, and the city smells of wet stone and woodsmoke. In an hour it will smell of everything else.",
	},
	["sw.muse.w04.083"] = {
		"Rain in Stormwind. The canals are pleased; I am not.",
		"The masons built gutters for this rain, and nobody paid for those either. They work beautifully.",
	},
	["sw.muse.w04.084"] = {
		"Fog in Stormwind: bridges that begin and never end, towers with no tops, voices with no faces.",
		"In this fog every guard is a shape until the last step, and every shape a guard until it isn't.",
	},
	["sw.muse.w04.085"] = {
		"stops as the last of the dusk catches the cathedral spires and leaves the streets below already blue.",
		"watches the white walls of the city go pink at dusk, then gray, as the day lets go of them.",
	},
	["sw.muse.w04.086"] = {
		"A clear day, and the blue roofs of Stormwind match the sky so well you can't tell where the city stops.",
		"Under a clean sky the white stone is almost too bright to look at. Somebody should sell hats; somebody surely does.",
	},
	["sw.muse.w04.087"] = {
		"At midday the Trade District is at its loudest and the Park at its quietest. The city balances itself like a merchant's scale.",
		"Midday, and every shadow in the city has crawled under its own wall to wait out the sun.",
	},
	["sw.muse.w04.088"] = {
		"Thick walls keep the street out. Even the bells come through softened, as if someone had wrapped them in cloth.",
		"Indoors, Stormwind becomes a rumor: a cart on the cobbles, a shout, a bell, all of it one wall away.",
	},
	["sw.muse.w04.089"] = {
		"Strange, walking around with my weapon sheathed and my shoulders down. This city makes you forget the road.",
		"Blade sheathed, back unguarded. In Stormwind that's good manners. Anywhere past Elwynn it would be madness.",
	},
	["sw.muse.w04.090"] = {
		"A whole street, and nothing in it wants to kill me. My hands don't know what to do with themselves.",
		"My hand keeps drifting to the hilt out of habit. Easy. Nobody here is coming at me with anything worse than a sales pitch.",
		"Out there I listen for footsteps behind me. In here the footsteps behind me are a baker's boy with a tray. It takes some getting used to.",
	},
	["sw.muse.w04.091"] = {
		"watches a flock of pigeons lift from the rooftops all at once, startled by something nobody in the street can see.",
		"follows the pigeons wheeling over the blue roofs of Stormwind, a gray scarf thrown across the city and pulled back.",
	},
	["sw.muse.w04.092"] = {
		"Stormwind has a form for everything. There's a clerk somewhere whose whole life is stamping them, and a cellar full of the stamped.",
		"A kingdom without its king still runs on parchment. The clerks of Stormwind would keep stamping if the walls fell.",
		"Permits for the market, permits for the bridge, a permit to complain about the permits. The scribes of this city never go hungry.",
	},
	["sw.muse.w04.093"] = {
		"Whatever happens out there, this is where the Alliance comes to remember it's an alliance.",
		"Every banner in the Alliance has a cousin hanging somewhere in this city.",
		"Stormwind is the hearth the whole Alliance warms its hands at, quarrels and all.",
	},
	["sw.muse.w04.094"] = {
		"The gold lion is everywhere: tabards, banners, door knockers, the bottoms of tankards. A city reminding itself to be brave.",
		"Stormwind puts a lion on anything that stands still long enough. I'm surprised the pigeons don't wear one.",
	},
	["sw.muse.w04.095"] = {
		"A city is mostly its people's patience: bakers up before first light, guards on their feet, clerks bent over ledgers. Stone only keeps the shape.",
		"Walls are the part of a city you can see. The rest is people getting up every morning and doing it all again.",
		"Kings vanish, regents worry, the Defias plot. Meanwhile someone sweeps the steps and someone bakes the bread, and that is what keeps Stormwind standing.",
	},
	["sw.npc_meet.w04.001"] = {
		"passes a city guard whose halberd tips forward a finger's width: a greeting, or a warning, or both.",
		"draws a slow look from a guard in blue and gold, who shifts the weight of a halberd and says nothing.",
		"nods to a guard on the corner and gets back the smallest nod in the kingdom.",
	},
	["sw.npc_meet.w04.002"] = {
		"Quiet shift so far? Good. Long may it stay boring.",
		"Guard, anything in the streets I should steer clear of?",
		"You look like you've stood here since the walls went up. Need anything?",
	},
	["sw.npc_meet.w04.003"] = {
		"The merchant's eyes go from my boots to my belt to my purse in one practiced sweep. Weighed and priced.",
		"Before I've said a word, this one has guessed what I can spend. Probably to the copper.",
		"A counter polished smooth by a thousand elbows, and a seller who's heard every haggle twice.",
	},
	["sw.npc_meet.w04.004"] = {
		"Show me something that'll hold up past Goldshire. Not the shiny stuff. The ugly, useful stuff.",
		"What've you got that won't fall apart the first time it gets wet?",
		"I need things that work, not things that sparkle. You'll know the difference better than I do.",
	},
	["sw.npc_meet.w04.005"] = {
		"The innkeeper's glance goes to my boots, then my face, as if filing both away. In a city inn, that's how the peace is kept.",
		"Here's someone who knows every face that sleeps under this roof, and which ones snore.",
		"A keeper of keys and quarrels. City innkeepers must hear more secrets than SI:7.",
	},
	["sw.npc_meet.w04.006"] = {
		"is waved over by someone at the edge of the crowd, the way people wave at the one person who might help.",
		"catches the eye of someone who has clearly been watching the street for exactly this: a passerby with a weapon and some time.",
		"is beckoned aside by someone who glances around first, then lowers their voice to explain.",
	},
	["sw.npc_meet.w04.007"] = {
		"Before you begin, tell me it isn't rats. Anything but rats.",
		"Go on. What's gone missing, broken, or run off this time?",
		"I'm listening. Start with the part that's on fire, if there is one.",
	},
	["sw.npc_meet.w04.008"] = {
		"Teach me what I'm ready for. And maybe one thing I'm not.",
		"I've come to be told what I'm doing wrong. Don't be gentle.",
		"Show me something new. I'll pay in coin now and in bruises later.",
	},
	["sw.npc_meet.w04.009"] = {
		"hands a bundle across the counter while the clerk notes every item in a ledger, in handwriting too small to argue with.",
		"waits while a bank clerk weighs, counts and writes, the quill never once hesitating.",
		"watches a clerk lock the deposit away with a key from a ring that must weigh more than {g:his|her} pack.",
	},
	["sw.npc_meet.w04.010"] = {
		"The gryphon master talks to the birds in a soft voice, and to customers in a much shorter one. Fair enough.",
		"Few parents look as proud as this handler looks at those gryphons.",
		"This one checks the harness three times and my purse once. The right priorities, for a flight.",
	},
	["sw.npc_meet.w04.011"] = {
		"Highlord Bolvar Fordragon, holding a kingdom for a king who isn't here. It shows around the eyes.",
		"The regent stands straight under the weight. Whoever finds King Varian will be doing this man a kindness too.",
		"Bolvar Fordragon. A paladin who'd rather be in the field, I'd wager, keeping a throne warm for a boy.",
	},
	["sw.npcd_flightmaster_bye.w04.001"] = {
		"Up you get. Lean when the gryphon leans, and don't argue with it.",
		"Safe flying. Keep your mouth shut on the way down; the bugs over Elwynn are thick this season.",
	},
	["sw.npcd_flightmaster_open.w04.001"] = {
		"Need wings? Mind the beaks, sign the ledger, and pick a gryphon that likes the look of you.",
		"Welcome to the roost. They're fed, they're rested, and they're in a better mood than I am.",
		"Where are you headed? The birds know every road in the kingdom from above.",
	},
	["sw.npcd_guard_bye.w04.001"] = {
		"Move along, then. And keep out of the canals; we've fished out enough visitors this month.",
		"Go on. Stay on the lit streets after dark and you'll have no trouble from me or anyone else.",
		"Safe travels. Give our regards to the Westfall road; it could use a few more friendly faces.",
	},
	["sw.npcd_guard_thanks.w04.001"] = {
		"No thanks needed. Keeping the peace is the job, and you didn't break it. That helps.",
		"Just doing my duty. If you want to thank someone, thank whoever made these boots. I'm on my feet all day.",
	},
	["sw.npcd_innkeeper_bye.w04.001"] = {
		"Safe roads. And if anyone asks where you slept well, it was here.",
		"Off you go. The bed will miss you more than I will, but not by much.",
		"Mind the step on your way out. Half the city has tripped on it, and the other half is waiting its turn.",
	},
	["sw.npcd_innkeeper_more.w04.001"] = {
		"More? Buy a second mug and lean in. The best gossip never comes with the first one.",
		"That's all I'll say out loud. The walls in this city have ears, and some of them work for SI:7.",
	},
	["sw.npcd_innkeeper_open.w04.001"] = {
		"Come in, come in, and shut the door behind you. Bed, bowl or both?",
		"Welcome! Boots by the hearth, coin on the counter, troubles at the door.",
		"In you come. The kettle's on, the rooms are aired, and the cook is in a good mood. Rare day.",
	},
	["sw.npcd_innkeeper_open.w04.002"] = {
		"Another traveler with the whole road stuck to their boots. Wipe them, please, and then we'll talk.",
		"Ah, a new face. Or an old one I've forgotten. Either way, a room's a room.",
	},
	["sw.npcd_innkeeper_rest.w04.001"] = {
		"Upstairs, end of the hall. The window sticks, the bed doesn't creak, and the bells will wake you whether you like it or not.",
		"There's a room going on the quiet side, away from the canal smell. Take it before a dwarf off the tram does.",
	},
	["sw.npcd_innkeeper_sit.w04.001"] = {
		"Sit wherever there's a free stool. If it wobbles, that's the floor, not the ale.",
		"Good. Take the corner by the hearth; it's the warmest seat in Stormwind, and the quietest.",
	},
	["sw.npcd_innkeeper_thanks.w04.001"] = {
		"No need. Pay the tab and speak kindly of the stew, and we're square.",
		"Thank me by coming back. Half my trade is people who meant to stay a single evening.",
	},
	["sw.npcd_merchant_bye.w04.001"] = {
		"Come back when the road has chewed through those boots. It will.",
		"Off with you, and may your purse be heavier next time. For both our sakes.",
		"Goodbye, and watch your pockets on the bridges. I'd hate to lose a customer to a thief.",
	},
	["sw.npcd_merchant_haggle.w04.001"] = {
		"Discuss it? We can discuss it all day. The price will still be sitting there when we're done.",
		"Try discussing the nobles' taxes with them first. When they give way, so will I.",
	},
	["sw.npcd_merchant_open.w04.001"] = {
		"Step up, step up! Everything here came in on a wagon this week, and some of it still smells of the road.",
		"Good day! Have a look; touching is free, and buying is very reasonable.",
		"This is the finest counter between the bank and the canal. I'd know; I've measured.",
	},
	["sw.npcd_merchant_open.w04.002"] = {
		"What'll it be? I've got what you need, and a few things you'll need later.",
		"Come to look or come to buy? Either's welcome; one's a little more welcome.",
	},
	["sw.npcd_merchant_thanks.w04.001"] = {
		"My pleasure, truly. Tell your friends, and tell them I said so.",
		"Thank you for buying! It keeps the shutters up and the rats out.",
	},
	["sw.npcd_trainer_bye.w04.001"] = {
		"Go on. Practice until it's boring, then practice until it isn't.",
		"Off you go. Come back when you've broken something in a new way; I'll show you how to mend it.",
	},
	["sw.npcd_trainer_open.w04.001"] = {
		"Back straight, weight forward. There. Now we can talk about what you came to learn.",
		"You've come to learn? Good. Stormwind's full of people who think they already know.",
		"Show me your hands. Hm. Yes, there's work in them yet. What do you want to start with?",
	},
	["sw.quest_complete.w04.001"] = {
		"That's off my shoulders. Funny how a task weighs most just before it's finished.",
		"Accepted, thanked, settled. Whatever I owed that job, I don't owe it now.",
		"A weight off. I hadn't noticed how much I was carrying it until I put it down.",
	},
	["sw.quest_complete.w04.002"] = {
		"Anything else? Ask quickly, before my feet hear about it.",
		"Any more work, and you'll have to ask my boots. They've stopped taking orders from me.",
		"If there's more, I'll do it. Just let me sit for as long as it takes to complain.",
	},
	["sw.quest_complete.w04.003"] = {
		"has barely put the reward away before a street hawker appears at {g:his|her} elbow with something shiny to sell.",
		"tucks the reward out of sight, too late: two peddlers have already noticed and are drifting closer.",
		"stows the reward just as a vendor three stalls away starts calling out bargains a little louder.",
	},
	["sw.quest_complete.w04.004"] = {
		"The thanks was three words long. The face behind it said the rest.",
		"Not much of a speech, that thank-you. The relief in those eyes made up for it.",
		"They didn't say much. They didn't need to; I watched their shoulders come down.",
	},
	["sw.quest_complete.w04.005"] = {
		"Glad to help. Now, which of these streets smells most of fresh pie?",
		"Happy to do it. Point me toward something hot to eat and we're even.",
		"My pleasure. And now my pleasure would like a bowl of stew.",
	},
	["sw.quest_complete.w04.006"] = {
		"A flock of pigeons bursts up off the street just as I finish. I'll take that as applause.",
		"The pigeons take off all at once, wings clapping. Stormwind's idea of an ovation.",
		"Nearby, a whole roof of pigeons lifts off in a clatter. Applause, of a sort.",
	},
	["sw.quest_complete.w04.007"] = {
		"receives a short, formal nod of thanks, the kind the city's officers give, and returns it in kind.",
		"is thanked with a stiff little bow, the courtesy of a capital, and answers it with one of {g:his|her} own.",
		"accepts a curt nod that seems to carry a whole kingdom's worth of formality, and nods back.",
	},
	["sw.quest_complete.w04.008"] = {
		"By tomorrow nobody will remember there was ever a problem. That's how you know it was fixed.",
		"Good work in a city is the kind that disappears. Tomorrow this will simply be how things are.",
		"No one will notice what changed today. That's the best a job like this can hope for.",
	},
	["sw.quest_complete.w04.009"] = {
		"Pleasure. Tell your friends: I work fair and I walk fast.",
		"Any time. If your neighbors need something done, you know where I'll be. Roughly.",
		"Glad it's settled. Spread the word: there's a pair of hands in town that doesn't mind work.",
	},
	["sw.quest_complete.w04.010"] = {
		"Solved, for now. In a city this size the same trouble will knock on another door next week.",
		"Over. And past the canals the next one is already starting. Cities never run short.",
		"It's handled. Tomorrow some other street will need the same help. That isn't failure; it's Stormwind.",
	},
	["sw.quest_complete.w04.011"] = {
		"stretches until {g:his|her} back gives a loud crack, then steps aside to let a cart through.",
		"rolls both shoulders, the work behind {g:him|her}, and gets out of the way of a porter with a barrel on his back.",
		"lets out a long breath and steps aside as a wagon rattles past, already bound somewhere else.",
	},
	["sw.quest_complete.w04.012"] = {
		"Half of this goes to the armorer before it ever gets warm in my purse.",
		"The reward is nice. The repair bill waiting in the Dwarven District is nicer, for the smith.",
		"I can already hear an anvil in the Dwarven District calling for its share.",
	},
	["sw.quest_complete.w04.013"] = {
		"If anyone asks, it was terribly dangerous and I was terribly brave.",
		"Remember to tell people I was heroic about it. Use the word 'dashing' if you can.",
		"When you tell this story, make it bigger. I won't correct you.",
	},
	["sw.quest_complete.w04.014"] = {
		"People in a capital have no time for long thanks. A quick one from a busy stranger counts double.",
		"In a city in such a hurry, someone stopped to say thank you. I'll keep that.",
		"Everyone here is late for something. They stopped anyway, long enough to thank me.",
	},
	["sw.quest_complete.w04.015"] = {
		"turns the reward over once in {g:his|her} palm, as if to make sure it is real, then puts it away.",
		"weighs what was given in one hand for a moment before stowing it with care.",
		"glances down at the reward, then up at the busy street, and slips it into the pack without a word.",
	},
	["sw.quest_complete.w04.016"] = {
		"They're already looking past me at the next problem. Fair. So am I.",
		"A thanks, a nod, and their eyes go straight back to whatever comes next. I know the feeling.",
		"A quick thank-you and then that distant look again. Whatever follows this, it's already on their mind.",
	},
	["sw.quest_complete.w04.017"] = {
		"There. It's done. No speeches, please.",
		"That's it. Keep the thanks short; I've got places to be.",
		"Finished, settled, paid. Spare me the ceremony.",
	},
	["sw.quest_complete.w04.018"] = {
		"Even at this hour of the night someone was still waiting up for this. The lamps are lit; the work's done.",
		"Late, and the streets have gone quiet. A job finished by lamplight still counts.",
		"Night over the rooftops, and one more thing settled before bed.",
	},
	["sw.quest_complete.w04.019"] = {
		"Settled before the city has properly woken up. The bakers and I, the only ones at work.",
		"Early still. The first carts are only now rolling in, and my task is already behind me.",
		"Wrapped up at first light. Whatever else the day brings, it starts with one thing off the list.",
	},
	["sw.quest_complete.w04.020"] = {
		"Settled, and only half soaked. The rain can have the rest of me.",
		"Finished with rain dripping off the end of my nose. Nobody in Stormwind seems to notice the rain anymore.",
		"Water down my collar, the task behind me. The rain and I both did our part.",
	},
	["sw.quest_complete.w04.021"] = {
		"They paid me. A real reward, for real work, in the capital. I could get used to this.",
		"A whole capital, and it trusted me with a piece of its business. Me.",
		"The reward's modest. The feeling of being useful to Stormwind is not.",
	},
	["sw.quest_complete.w04.022"] = {
		"After everything out there, a plain thank-you on a city street still lands. Good.",
		"The roads I walk now are grim. A safe street and a grateful face are fair pay for the walk back.",
		"Strange: big battles leave less of a mark than a stranger's thanks in the city.",
	},
	["sw.quest_complete.w04.023"] = {
		"Back into the crowd. Not one face here knows what I just finished, and I find I like that.",
		"The street swallows me again. No one turns their head, no one knows. A comfortable kind of quiet.",
		"Over, and invisible again among the carts and shoppers. Some rewards are just being left alone.",
	},
	["sw.quest_complete.w04.024"] = {
		"One more person in this city who'll wave when I pass. I'm collecting them.",
		"That's another friendly face for my next walk through town.",
		"Good. Now there's someone else in Stormwind who'll say hello to me.",
	},
	["sw.quest_complete.w04.025"] = {
		"perches on a low wall to sort through {g:his|her} pack, putting what is left in order after the job.",
		"sits on the edge of a low wall and takes stock of the supplies that survived the work.",
		"finds a ledge out of the traffic and repacks everything, a little more tidily than before.",
	},
	["sw.quest_complete.w04.026"] = {
		"My feet would like a word about this job. I've told them to wait their turn.",
		"Every step of that job has gone into my calves, and they're keeping count.",
		"My legs have opinions about all that. I'll hear them out once I find a chair.",
	},
	["sw.quest_complete.w04.027"] = {
		"For Stormwind, then. It was no trouble.",
		"Whatever helps the city. Call on me again.",
		"Glad to serve, in a small way. The lion's work is never finished.",
	},
	["sw.quest_complete.w04.028"] = {
		"Every task I bring back here adds another name to the list of people I know in this city.",
		"One more face, one more door, one more name. Bit by bit this city is becoming a map I carry in my head.",
		"The more work I hand in here, the less Stormwind feels like a maze.",
	},
	["sw.quest_complete.w04.029"] = {
		"lets the reward rest in an open palm a moment, while above the rooftops a bell strikes the hour.",
		"pauses as a bell over the city tolls the hour, as if the whole of Stormwind were marking the moment.",
		"hears the hour ring out from a tower as the business is concluded, and stays listening until the last stroke fades.",
	},
	["sw.quest_complete.w04.030"] = {
		"Part of the reward was the look of relief on that face. Shame no merchant takes it.",
		"The best bit of payment was that sigh of relief. Can't spend it, can't bank it, can't stop thinking about it.",
	},
	["sw.quest_complete.w04.031"] = {
		"In this city every favor gets written down somewhere. Some noble's ledger just gained a line with my name on it.",
		"In some fine house, someone is keeping count of who helped whom. Today they can add me.",
		"Stormwind never forgets a favor. It just files it, in some noble's study, for later use.",
	},
	["sw.quest_complete.w04.032"] = {
		"One down. The day isn't over, and neither am I.",
		"That's one. Next.",
		"Settled. I've got more in me than one job.",
	},
	["sw.quest_complete.w04.033"] = {
		"Two tries, but it's done. The city doesn't need to hear about the first one.",
		"Second attempt, and this time it stuck. Let's never speak of the other.",
	},
	["sw.quest_complete.w04.034"] = {
		"High walls, and still the kingdom's troubles walk in through the gate like anyone else. Today I walked one back out.",
		"The capital likes to think it's safe behind stone. Then someone needs help, and the stone is no use at all.",
		"Walls keep out armies, not problems. Problems need hands, and today they got mine.",
	},
	["sw.reputation_change.w04.001"] = {
		"A ledger of goodwill just tipped a little my way. In this city, that counts for more than coin.",
		"A little more trust, earned the slow way. In a capital it's worth more than gold, and harder to spend.",
		"They'll say my name a bit more kindly now. I'll try to give them no reason to forget why.",
	},
	["sw.rest_enter.w04.001"] = {
		"A room with a window on the street. The city's noise comes up muffled, like a river heard through a wall.",
		"Shutters half closed, a bed that doesn't move, the street murmuring somewhere below. I could stay a week.",
		"Indoors at last. The city goes on without me out there, which is exactly how I want it right now.",
	},
	["sw.rest_enter.w04.002"] = {
		"hangs {g:his|her} cloak on a peg by the door and unbuckles everything that has been pinching for hours.",
		"sets down the pack, loosens a belt a notch, and lowers {g:himself|herself} onto the nearest bench with a sigh.",
		"knocks the road dust off {g:his|her} boots at the threshold and lets the warmth of the room do the rest.",
	},
	["sw.rest_enter.w04.003"] = {
		"City walls, city guards. For once the watch is someone else's job.",
		"Nobody here needs me to stand guard. I may forget how to sleep lightly.",
		"I'm sitting down, and I'm not getting up until someone brings food.",
	},
	["sw.rest_enter.w04.004"] = {
		"Inside these walls my shoulders come down on their own. I didn't tell them to.",
		"I catch myself listening for footsteps behind me, then remember where I am and stop.",
		"Deep in me, a sentry goes off duty. I hadn't noticed it was standing there.",
	},
	["sw.rest_enter.w04.005"] = {
		"leans back against a wall in a quiet corner of the street and lets the pack slide down to the cobbles.",
		"finds a doorstep out of the crowd's way and sits, elbows on knees, watching Stormwind go about its business.",
		"settles on the low rim of a planter box under someone's window, legs stretched out across the paving.",
	},
	["sw.rest_enter.w04.006"] = {
		"Safe walls, and still my thoughts are out on the road. They'll come in when they're ready.",
		"The city is calm. I'm the one who isn't, yet. Give it a cup of something hot.",
		"Rest, they call it. My mind hasn't heard; it's still counting everything that could go wrong.",
	},
	["sw.rest_enter.w04.007"] = {
		"A whole night in a real bed, with a lock on the door and a city guard outside. Luxury.",
		"Night, and nothing to do but sleep. I'd almost forgotten that was allowed.",
		"The lamps are lit downstairs and the night is someone else's problem. Pillow, here I come.",
	},
	["sw.thanks.w04.001"] = {
		"Thanks. That's one more good turn I owe this city.",
		"My thanks. Remind me which tavern you drink in; the next round's mine.",
		"Thank you kindly. Stormwind's manners are better than its reputation.",
	},
	["sw.thanks.w04.002"] = {
		"You have my gratitude, and my word that I'll pass the kindness on.",
		"I'm in your debt. I won't forget it on my way out of the city.",
	},
	["sw.travel.w04.001"] = {
		"closes a hand around the hearthstone in the middle of the crowd, and a pigeon is the only one who notices {g:him|her} go.",
		"lets the hearthstone's warmth climb up {g:his|her} arm while the people of Stormwind flow around, unaware.",
	},
	["sw.weather_change.w04.001"] = {
		"watches the rain pock the green water of the canals, while the boatmen drag oiled tarps over their cargo.",
		"stops on a bridge as the rain begins, the canal below breaking out in a thousand small rings.",
		"sees the rain reach the canals first, a hiss running along the water from bridge to bridge.",
	},
	["sw.weather_change.w04.002"] = {
		"Rain on the slate roofs, and the whole city smells of wet stone and chimney smoke.",
		"The rain brings out the smell of the city: damp stone, coal smoke, something baking under it all.",
		"Rain, and Stormwind goes the color of pewter. The stone smells older when it's wet, and the smoke hangs low.",
	},
	["sw.weather_change.w04.003"] = {
		"Every awning in Stormwind just became the most popular spot in town.",
		"Rain! Watch the doorways fill up with people who suddenly need to look at hats.",
		"There it goes. Half the market under one awning, and the other half pretending it doesn't mind getting wet.",
	},
	["sw.weather_change.w04.004"] = {
		"watches the fog fill the canals first, as if poured from a jug, then spill over the banks into the streets.",
		"sees the far end of the bridge vanish as the fog comes in off the water, and a lantern on it become a smudge of yellow.",
		"notices the fog thicken until the guards on the next corner are only shapes with halberds.",
	},
	["sw.weather_change.w04.005"] = {
		"In the fog the city becomes all voices: a cart I can't see, a laugh with no face, a door closing somewhere.",
		"Fog. I can hear the whole street and see almost none of it, voices drifting past with no one attached.",
		"The fog takes the towers first, then the rooftops, then the far side of the street. Only the voices keep their place.",
	},
	["sw.weather_change.w04.006"] = {
		"watches the clouds tear open over Stormwind and the white walls flare almost too bright to look at under the sun.",
		"squints as the sky clears and the sunlight lands all at once on the blue roofs and the white stone.",
		"sees the gray break up in the sky overhead, and the sun pick out the gold on every banner along the street.",
	},
	["sw.weather_change.w04.007"] = {
		"The weather lifts, and the street fills again as if someone had thrown open a gate.",
		"Clear again. The merchants roll their awnings back up and the shouting resumes, louder to make up for lost time.",
		"The gray goes, and everyone in the square seems to straighten up at the same moment.",
	},
	["sw.weather_change.w04.008"] = {
		"Weather's turned. Good. I'd started to forget what color this city is.",
		"There, clear skies. Now the canals can go back to looking pretty.",
	},
	["sw.weather_change.w04.009"] = {
		"Night rain on Stormwind. The lamps hiss, the canals rise a finger's width, and the streets belong to the guards.",
		"Rain in the dark: every lamp wears a halo, and the cobbles shine like the canal itself.",
		"A wet night setting in. The taverns will be full and the bridges empty.",
	},
	["sw.jest.w05.001"] = {
		"Stormwind's canals are a great convenience. Anything you drop off a bridge, they keep for you forever.",
		"You can always find the canals in Stormwind. Usually by stepping into one.",
	},
	["sw.pray.w05.001"] = {
		"Whoever listens above the bells: bring every soldier who marched out through the Valley of Heroes home the same way, on their own feet.",
		"May all who walked out past the statues at the gate walk back in beneath them, whole.",
	},
	["sw.muse.w19.acolyte.001"] = {
		"makes way for an acolyte in white running an errand across the city, robe hitched to the knee and the hem gone brown from the gutters.",
		"watches a young acolyte dodge a cart, a porter and a sleeping dog in one long stride, white robes bunched in a fist and a sealed letter clamped in the teeth.",
	},
	["sw.muse.w19.acolyte.002"] = {
		"The priests of the cathedral will mend anything you bring them: the cut, the fever, the cracked rib. The lecture about how you got it comes free, and so does the second one.",
		"A cathedral priest heals with one hand and wags a finger with the other. You leave whole and slightly ashamed, which is probably the full treatment.",
		"Get patched up at the cathedral and you'll leave with a clean bandage, a sermon on caution and the distinct feeling of having been told off by someone very kind.",
	},
	["sw.muse.w19.acolyte.003"] = {
		"Priests' hands all smell the same: beeswax, crushed herbs and the yellow soap they scrub with between patients. You notice it when one of them tips your chin up to look at a cut.",
		"A cathedral priest turned my face to the lamp to look at a graze. Her fingers smelled of wax and bitter herbs, and didn't tremble at all.",
	},
	["sw.muse.w19.acolyte.004"] = {
		"pauses by a row of young paladins sitting on the cathedral steps, each with a breastplate across the knees and a rag going in slow circles.",
		"passes a line of squires polishing plate on the steps of the cathedral, none of them talking, all of them checking their reflections when they think nobody sees.",
	},
	["sw.muse.w19.acolyte.005"] = {
		"There's an old priest in the cathedral who can't keep a single name in his head and remembers every wound he ever closed. He greets people by their scars.",
		"One elderly priest at the cathedral forgets your name before you've finished saying it. Show him a scar, though, and he'll tell you the year he stitched it.",
		"The oldest healer at the cathedral can't tell you who you are, but show him a scar and he'll tell you whose work it was, and whether they rushed it.",
	},
	["sw.muse.w19.acolyte.006"] = {
		"Saw a paladin buy a honey bun and eat it in two bites behind a pillar. Even the Light's champions have a weakness.",
		"A paladin in full plate, sneaking a pastry outside the cathedral. I won't tell. Mostly.",
	},
	["sw.muse.w19.acolyte.007"] = {
		"The acolytes gossip about who will be raised to priest next the way stable boys gossip about horses: fiercely, wrongly, and in whispers behind the hymnals.",
		"Behind the cathedral's calm there's a whole court of whispers. Which acolyte the elder priests favor, who fumbled a blessing, whose robe had to be let out again.",
	},
	["sw.muse.w19.acolyte.008"] = {
		"When Archbishop Benedictus crosses Cathedral Square, people step back before they know they've done it. He never asks. The crowd simply opens, like a book to a marked page.",
		"I've watched a market crowd part for the archbishop without a word from anyone. Benedictus nods to each side as he goes, as if thanking every stone.",
	},
	["sw.muse.w19.acolyte.009"] = {
		"Overheard: a priest of the cathedral haggling with a chandler over the price of tallow, and winning. Serenity has its uses at the counter.",
		"A cathedral priestess bargains like an old quartermaster. Calm voice, folded hands, and she doesn't move a copper until the chandler gives up.",
	},
	["sw.muse.w19.acolyte.010"] = {
		"slows to watch a priest kneel in the street to clean a child's skinned knee, talking all the while about something else entirely so the child forgets to cry.",
		"notices an acolyte crouched beside a sobbing boy, dabbing a scraped knee and solemnly promising that the cobblestone has been punished.",
	},
	["sw.muse.w19.acolyte.011"] = {
		"A night elf stood in the cathedral door a long while, reading the windows the way you'd read a letter in a language you half know. Then she bowed to them, politely, and left.",
		"Some night elves visit the cathedral the way you'd visit a neighbor's shrine: courteous, curious, and careful not to touch anything.",
	},
	["sw.muse.w19.acolyte.012"] = {
		"One priest in the cathedral choir sings loudly and badly, and the others have arranged themselves around him like masons around a crooked stone. The hymn comes out straight anyway.",
		"The cathedral's singers have one voice among them that wanders off the note. They've stopped trying to fix it and simply sing a little louder on either side.",
		"Nobody corrects the priest who bellows a hair off the note in the cathedral choir. They lean in and carry him, the way soldiers carry a friend with a bad leg.",
	},
	["sw.muse.w19.acolyte.013"] = {
		"Ever heard a row of paladins kneel at once? Like a cutlery drawer falling down a well.",
		"Paladins kneeling together in the cathedral sound like somebody dropped a smithy. Then: perfect silence. They're very proud of the silence.",
		"A dozen paladins going down on one knee together: a crash, then a hush you could stand a spoon in.",
	},
	["sw.muse.w19.acolyte.014"] = {
		"Some of the older paladins at the cathedral pray with their eyes open. They picked that up in Lordaeron, one of them said, where the dead didn't always stay where they were laid.",
		"You can tell the paladins who served in the north: they kneel facing the doors, not the altar. Old habit, one told me. Up there the dead walked in uninvited.",
	},
	["sw.muse.w19.acolyte.015"] = {
		"I've lost faith in plenty: nobles, prices, the post. Not in the cathedral's priests. They turn up where it's worst and stay till it's better. In a kingdom that keeps losing its kings, that's no small thing.",
		"Kings go missing and nobles squabble, but the priests of the cathedral are always where it hurts most, sleeves rolled. That's the Light I believe in: the one that turns up.",
	},
	["sw.muse.w19.acolyte.016"] = {
		"watches a paladin in polished plate put a shoulder to a stuck cart wheel, heave it free of the gutter and walk on, the carter's thanks trailing after.",
		"pauses as a paladin stops to lift the back of a mired handcart alone, sets it down on the cobbles and nods the owner on as if this too were part of the oath.",
	},
	["sw.muse.w19.acolyte.017"] = {
		"The Alliance keeps its priests in that great cathedral of theirs. If they knew what I was, I think they'd heal me first and call the guards second. That's what unsettles me.",
		"Every priest in this city would bind my wounds, I'm told, before handing me to the guards. I don't know what to do with an enemy like that.",
	},
	["sw.muse.w19.acolyte.018"] = {
		"receives a small bow from a priest passing the other way, the same bow the cathedral's people give a beggar or a lord.",
		"is given a brief nod and a murmured greeting by a priest in white bent on some errand, who is gone before it can be returned.",
		"meets the eye of a passing acolyte, who smiles as if they had known each other for years and hurries on.",
	},
	["sw.muse.w19.acolyte.019"] = {
		"Never argue doctrine with a paladin. They're trained to hold a position for hours.",
		"Debate the Light with a paladin if you like. Bring a chair. They won't need one.",
		"I asked a paladin a simple question about the Light. That was a while back. I think he's still answering.",
	},
	["sw.muse.w19.ale.001"] = {
		"Whichever forge had the best week gets the keg on its doorstep, the dwarves of the Dwarven District say. It moves around. Following it is a pastime for some.",
		"A keg travels from forge to forge in the Dwarven District, a smith told me, stopping wherever the work went best. This week it's sitting with the nail-maker, which nobody expected.",
	},
	["sw.muse.w19.ale.002"] = {
		"Ask a dwarf in the Dwarven District the way and you get the way, a story and a mug. In that order, if you're lucky.",
		"I asked a dwarf for directions and got half a mug of ale with them. I've thought of more questions.",
		"A dwarf gives directions the way he pours ale: generously, and with a head on it.",
	},
	["sw.muse.w19.ale.003"] = {
		"A dwarf at a doorstep table raised his mug to Gnomeregan, and the gnome beside him said nothing, only lifted his own. That was the whole toast.",
		"The dwarves of the Dwarven District leave the last swallow in the mug for whoever didn't make it back, a smith told me. Every round there ends with full bottoms.",
		"There's a toast the dwarves here give without words: the mug raised, held a moment toward the tram, and set down untouched. Nobody explains it to strangers.",
	},
	["sw.muse.w19.ale.004"] = {
		"sits for a while on the edge of a stone trough beside a dwarf drinking alone on a doorstep; neither says a word, and neither seems to mind.",
		"shares a quiet stretch of wall with a dwarf nursing a mug, the two of them watching the street go by as if it were a play neither had paid for.",
	},
	["sw.muse.w19.ale.005"] = {
		"The kegs that come in on the tram are all marked 'tools'. The dwarves of the Dwarven District are very well equipped.",
		"A crate off the tram marked 'gears, fragile' sloshes when it's set down. Nobody in the Dwarven District says a word, and somebody fetches mugs.",
	},
	["sw.muse.w19.ale.006"] = {
		"In the Dwarven District there's nearly always some doorway with dwarves singing in a tongue the city doesn't speak. I can't understand a word, and I know exactly what it means.",
		"Dwarven voices from a doorway, deep and a little off key, singing in their own language. The words are lost on me. The missing of a mountain isn't.",
	},
	["sw.muse.w19.ale.007"] = {
		"To Ironforge, then, from this end of the tunnel.",
		"One for Ironforge, and one for the poor fools who dug the way there.",
		"Here's to the tunnel: the only thing between two capitals that never argues.",
	},
	["sw.muse.w19.ale.008"] = {
		"Somebody in the Dwarven District is always brewing. The smell of malt drifts between the coal smoke like a better thought interrupting a bad one.",
		"Coal smoke, hot iron, and then, without warning, a warm wave of malt from some dwarf's back room. The Dwarven District has its priorities in order.",
	},
	["sw.muse.w19.ale.009"] = {
		"watches a dwarf smith drain a tankard in one long pull, set it on the anvil and go straight back to hammering, as if it had been a sip of water.",
		"notices that every anvil along the forge row has a tankard parked on its heel, a safe distance from the hammer, placed as carefully as the tongs.",
	},
	["sw.muse.w19.ale.010"] = {
		"Gnomes drink in the Dwarven District too, from mugs that come up to their chins, and they hold their ale far better than anyone expects. The dwarves stopped betting against them long ago.",
		"Never challenge a gnome to a drinking match in the Dwarven District. They're small, yes, and they've spent their whole lives being underestimated, and they keep score.",
	},
	["sw.muse.w19.ale.011"] = {
		"In the Dwarven District the ale is passed over doorsteps rather than across a bar, the way we drink at home. Ironforge, for a moment, with a sea in between.",
		"A mug from a stranger's doorstep, a nod, a few words of Dwarvish. That's all it takes for Stormwind to stop feeling like a human city for a while.",
	},
	["sw.muse.w19.ale.012"] = {
		"King Magni gets the first mug in the Dwarven District, and then, after a pause, the boy in Stormwind Keep gets the second. The pause says more than the toast.",
		"First mug to Magni Bronzebeard, second to the young king in Stormwind Keep. The dwarves never skip the second, but they always look at the table before they drink it.",
	},
	["sw.muse.w19.ale.013"] = {
		"Smoke, iron and beer. If the Dwarven District had a coat of arms, that would be it.",
		"Hammer in one hand, mug in the other. The dwarves of the Dwarven District have a gift for doing two things well at once.",
	},
	["sw.muse.w19.ale.014"] = {
		"watches the forge row go quiet at dusk, the hammers set down one by one and kegs rolled out onto the doorsteps in their place.",
		"lingers as the light goes and the forges are banked, while the smiths drag stools into the street and the first mugs come out.",
	},
	["sw.muse.w19.ale.015"] = {
		"A dwarven stout poured in Stormwind tastes of the tram ride, the dwarves claim: a little shaken, a little proud of it. They drink it anyway, and slowly.",
		"The dwarves say stout doesn't travel well and then ship it a whole tunnel's length to prove the point, one keg after another.",
	},
	["sw.muse.w19.ale.016"] = {
		"A dwarf just pushed a mug across to a gnome without a word, and the gnome nodded without looking. Some friendships don't need talking.",
		"Dwarves and gnomes drink side by side in the Dwarven District and hardly speak. They don't have to. They lost a city's worth of things together.",
	},
	["sw.muse.w19.alms.001"] = {
		"Emptying the cathedral's alms box takes two priests counting together, each one watching the other's hands. Faith is faith, and arithmetic is arithmetic.",
		"The alms box gets counted by a pair of priests, coin by coin, one reading the tally and the other checking it. Even the Light likes a second signature.",
		"Coins from the alms box are counted twice, by two different priests, at two different tables. The Light trusts everyone; the ledger trusts no one.",
	},
	["sw.muse.w19.alms.002"] = {
		"The soup the priests ladle out at the cathedral's side door is thin and always hot. The line for it is long and always quiet.",
		"Nobody in the cathedral's soup line talks. They hold their bowls with both hands and look at the bowl, not at each other.",
		"Thin soup, hot, and a queue of people who've learned not to be seen waiting for it. The priests ladle without looking up, which is its own kindness.",
	},
	["sw.muse.w19.alms.003"] = {
		"Acolytes sort the cathedral's donated clothes on the steps: coats in one heap, cloaks in another, and a hill of single boots waiting for partners that never come.",
		"The cathedral keeps a crate of odd boots, every one given in good faith and none of them matching. The poor of Stormwind walk lopsided and grateful.",
	},
	["sw.muse.w19.alms.004"] = {
		"The beggars on the cathedral steps know every priest by stride. This one gives copper, that one gives advice, and the tall one gives both and takes forever.",
		"Ask a beggar at the cathedral which priest to approach and you'll get a full report: who's generous, who's busy, who preaches before he pays.",
	},
	["sw.muse.w19.alms.005"] = {
		"A priest on the cathedral steps teaches a knot of orphans their sums with the coppers from the alms box. Every coin gets counted twice, then goes back in.",
		"The orphans learn arithmetic from the alms box: a priest tips out the coppers, they count, they argue, and every copper goes home to the box.",
		"Copper by copper, the orphans count the cathedral's alms out loud. It's the only money they'll handle for years, and they handle it like glass.",
	},
	["sw.muse.w19.alms.006"] = {
		"steps aside for two acolytes carrying a soup cauldron slung from a pole between them, both keeping careful step so as not to spill a drop.",
		"makes way for a pair of acolytes bearing a steaming pot on a pole toward the cathedral, matching their steps like a well-drilled patrol.",
	},
	["sw.muse.w19.alms.007"] = {
		"Free healing on the cathedral steps. Look at the queue: two porters, a guard and a cutpurse with a sprained wrist. The Light doesn't ask.",
		"Anyone who sits on those steps gets patched up by the priests: bruised porters, a scalded laundress, a pickpocket who won't say how.",
	},
	["sw.muse.w19.alms.008"] = {
		"The priests at the cathedral door ask the Westfall families which farm they came from. Out west a farm is a family's name, and most of those names are ash now.",
		"Westfall farmers queue for the cathedral's soup with their hats in their hands, the way they once queued at harvest to sell their grain to this same city.",
	},
	["sw.muse.w19.alms.009"] = {
		"A noble's footman drops a heavy purse into the alms box from a height, so it rings, and waits to be seen. The acolyte thanks him in a whisper. That seems to sting.",
		"Some gifts to the cathedral are made to be heard. A fat purse dropped from shoulder height, a pause for applause, and a priest who only murmurs and moves on.",
	},
	["sw.muse.w19.alms.010"] = {
		"A copper for the cathedral's box. The Light can sort out its own accounts; the soup pot can't.",
		"I'll leave something in the alms box. Whatever the priests believe, they buy onions with it.",
		"Coin in the box. Whatever the Light does with it, the soup gets salt.",
	},
	["sw.muse.w19.alms.011"] = {
		"The orphans of Cathedral Square watch the paladins the way other children watch sweets in a window. Some of them will be paladins one day. Most will be something quieter.",
		"Every orphan near the cathedral has picked a paladin to follow with their eyes. The paladins pretend not to notice, and walk a little straighter.",
	},
	["sw.muse.w19.alms.012"] = {
		"watches an old woman press a coin into a priest's hand and the priest fold her fingers back over it, the two of them arguing without a word.",
		"notices a priest and a gray-haired woman locked in a silent tussle over a single copper, each trying to make the other keep it.",
	},
	["sw.muse.w19.alms.013"] = {
		"The beggars of the cathedral steps have their places, and they hold them like nobles hold land. The spot by the door passes from hand to hand; a stranger starts at the bottom, in the draft.",
		"On the cathedral steps every beggar has a place, and the places have a rank. The top step by the door is inherited, the bottom one is where you begin, and nobody jumps the line.",
	},
	["sw.muse.w19.alms.014"] = {
		"Every war the Alliance wins sends a few more widows to the cathedral's side door. Victories have a bill too, and the priests pay part of it in soup.",
		"The soldiers get the banners. Their widows get the priests' soup line. Both belong to the Alliance, and only one of them is in the songs.",
	},
	["sw.muse.w19.alms.015"] = {
		"Humans give alms in coppers dropped through a slot. At home we'd give a hot plate and a seat at the table. Still, I fed the slot. When in Stormwind.",
		"A slot in a box: that's how this city gives. In Ironforge you'd get a stool by the fire and an earful. I dropped a copper in and found I missed the earful.",
	},
	["sw.muse.w19.alms.016"] = {
		"Got a coat you never wear? Take it to the cathedral. The acolytes will find it a back within the hour.",
		"Old cloaks, odd boots, spare blankets: the cathedral takes them all. They're not fussy about fit, only about warmth.",
		"Before you sell that old cloak for two coppers, think of the cathedral. Someone on those steps needs it more than a rag dealer does.",
	},
	["sw.muse.w19.apprentice.001"] = {
		"That apprentice has one eyebrow. One. And he walks as if it were the plan.",
		"Missing an eyebrow and proud of it. The tower teaches confidence, at least.",
	},
	["sw.muse.w19.apprentice.002"] = {
		"holds a door for an apprentice carrying a stack of books taller than she is, and gets a muffled thanks from somewhere behind the bindings.",
		"steps aside for an apprentice who comes down the street behind a tower of books, steering by the sound of the crowd.",
		"catches the top volume as it slides off an apprentice's armful, sets it back on the pile, and is thanked by a pair of eyes peering round the side.",
	},
	["sw.muse.w19.apprentice.003"] = {
		"watches an apprentice in the bakery queue rehearse a gesture with both hands, very small, until the woman behind her takes one careful step back.",
		"notices an apprentice waiting for bread who keeps practicing a tiny movement of the fingers, and the space around her in the queue growing a little wider each time.",
		"catches an apprentice in the bread queue practicing a gesture under her cloak, and the baker serving her first, quickly, to send her on her way.",
	},
	["sw.muse.w19.apprentice.004"] = {
		"The mages send their apprentices on every errand in the city. Half the shopkeepers of Stormwind know them by sight, and the other half by the burn holes in their sleeves.",
		"Apprentices run the mages' errands: wax, thread, cheese, a particular kind of salt. Follow one across the city and you'll learn more about the tower than by standing at its door.",
		"An apprentice's day, as far as I can see, is nine parts errands and one part terror, and the errands are what they complain about.",
	},
	["sw.muse.w19.apprentice.005"] = {
		"An apprentice sits on a step with her face in her hands. Whatever went wrong in that lesson, the street walks past and lets her keep it.",
		"On a doorstep, an apprentice in scorched robes, not crying, only staring at her own hands as if they belonged to someone careless. Nobody stops. In a city, that can be a kindness.",
	},
	["sw.muse.w19.apprentice.006"] = {
		"Some apprentice turned a whole barrel of water to ice last month, the fishmonger says, and sold it to him at a fair price. He's been praying for another accident ever since.",
		"The fishmonger swears his best season came from an apprentice who couldn't stop freezing things. He speaks of the boy the way farmers speak of a good harvest.",
	},
	["sw.muse.w19.apprentice.007"] = {
		"steps aside for a stray sheep ambling down the street with a puzzled air, while the passers-by give it a wide and very polite berth.",
		"smiles at a sheep that nobody owns as it wanders past a mage's door, and at the passing guard who touches his helmet to it, just in case.",
		"stops to let a lost-looking sheep cross in front of {g:him|her}, and notices that not one person in the street laughs at it.",
	},
	["sw.muse.w19.apprentice.008"] = {
		"steps out of the way of a pointed hat drifting down the street at head height, with nothing at all to carry it and its owner sprinting after it.",
		"watches an apprentice's hat sail past at the height of a face, sedate as a barge, the apprentice two strides behind and losing ground.",
		"ducks as a scroll goes past {g:his|her} ear at a brisk walking pace, all on its own, an apprentice in pursuit and apologizing to everyone.",
	},
	["sw.muse.w19.apprentice.009"] = {
		"Mind where you point that, will you? Point it at the canal. The canal has seen worse.",
		"Careful with that! If it has to go off, aim it at the water.",
		"Not at the bakery. Anywhere but the bakery.",
	},
	["sw.muse.w19.apprentice.010"] = {
		"watches a baker chase her son out of the shop with a brush, his brand-new apprentice robe white with flour from collar to hem.",
		"steps around a boy in a brand-new apprentice robe delivering loaves, flour up to the elbows and beaming like a lamp.",
	},
	["sw.muse.w19.apprentice.011"] = {
		"watches an apprentice, cornered by a pack of children demanding magic, sigh and pull a copper from behind the smallest one's ear the ordinary way.",
		"smiles as a gaggle of children chase an apprentice down the street for a trick, until the apprentice gives in and makes a coin vanish up a sleeve to wild applause.",
		"sees an apprentice refuse a crowd of children their magic, then relent just enough to make a pebble disappear, using nothing but quick fingers.",
	},
	["sw.muse.w19.apprentice.012"] = {
		"One apprentice in the quarter has gray in his beard. Some lessons take longer, he says, and besides, the robe still fits.",
		"Not every apprentice is a youngster. There's one with a gray beard and a patient way of sweeping up after the others, and the masters speak to him in a different voice.",
		"There's a gray-bearded apprentice who sweeps the tower steps and takes his lessons beside the children. The trick, he says, is not minding.",
	},
	["sw.muse.w19.apprentice.013"] = {
		"The chandlers of this city should raise the apprentices a statue. Out of wax, naturally.",
		"No one in Stormwind burns more candles than an apprentice, or falls asleep next to more of them.",
	},
	["sw.muse.w19.apprentice.014"] = {
		"Smoke from the second floor and a voice saying 'that's fine, that's fine'. It is never fine.",
		"Every window on that street is propped open. Nobody up there trusts the air for long.",
		"Hear that pop? Give it a moment. Yes, there's the shouting.",
	},
	["sw.muse.w19.apprentice.015"] = {
		"In the Mage Quarter, the neighbors say, nobody speaks of the apprentices who reached too far. A bed is cleared, the books go back on the shelf, and the lessons go on.",
		"Every quarter has its losses. Here they're quieter: a name no longer called at the tower door, a seat at the long table that somebody else has taken by the end of the week.",
	},
	["sw.muse.w19.apprentice.016"] = {
		"notices a row of full buckets lined up along a wall of the Mage Quarter, the way other streets keep pots of flowers.",
		"passes a doorway where a bucket of water and a damp folded blanket wait by the step, the way other houses keep a boot scraper.",
		"counts five buckets of water on five doorsteps in a row, and not one of them, by the look of the dust, has ever been carried in for washing.",
	},
	["sw.muse.w19.arcane.001"] = {
		"The lamps of the Mage Quarter light themselves. A lamplighter from Old Town told me he takes it personally.",
		"Nobody climbs a ladder for the violet lamps of the Mage Quarter. The lamplighters of the rest of the city call that cheating, and they mean it.",
		"Every lamp in Stormwind needs a pole, a flame and a tired man, except the violet ones by the tower. The tired men have opinions about those.",
	},
	["sw.muse.w19.arcane.002"] = {
		"stops under a violet lamp that hums half a note below its neighbors, and tilts {g:his|her} head at it like a fiddler hearing a sour string.",
		"lingers beneath one lamp of the quarter whose hum sits a shade flat against all the others, frowning up at it as at an off-key singer.",
		"listens to the lamps along the street hum together, and then to the one that doesn't quite, and stays there longer than the matter deserves.",
	},
	["sw.muse.w19.arcane.003"] = {
		"The glaziers must love the mages. Every few weeks a window goes, and always outward.",
		"Ask a glazier about the Mage Quarter and he'll smile. Glass that breaks from the inside is very steady work.",
		"A window just blew out on the mages' street. Somewhere a glazier is smiling.",
	},
	["sw.muse.w19.arcane.004"] = {
		"In the taverns the old soldiers lower their voices for one story only: a great mage in a tower to the southeast, a friend of King Llane, who opened the door the orcs came through.",
		"Ask a veteran why Stormwind watches its mages so closely and you may get a name he won't say and a tower he won't point at. A king's friend, he'll tell you, opened the way for the orcs.",
		"Some veterans spit as they pass the Mage Quarter. Not at the mages, they explain: at a memory. A tower far to the southeast, and a friend of the king who let the orcs in.",
	},
	["sw.muse.w19.arcane.005"] = {
		"A city that keeps mages pays twice: once in coin, and once in nerves.",
		"In a war every city wants mages on its walls. In peace it has to live next door to them.",
		"Mages are a fine thing to have in a siege. The rest of the year you're buying them buckets.",
	},
	["sw.muse.w19.arcane.006"] = {
		"There's a doorstep near the tower with frost on it in every season. The baker next door keeps her butter there.",
		"One house by the mages has a step that never thaws. The neighbors salt it, sigh, and have stopped asking.",
		"That step by the tower is frosted over whatever the season. Watch your feet there.",
	},
	["sw.muse.w19.arcane.007"] = {
		"pauses in a doorway where the small hairs on {g:his|her} forearms rise for no reason at all, then steps back into the street and waits for them to settle.",
		"crosses a threshold with every hair on {g:his|her} arms suddenly standing on end, and backs out the way {g:he|she} came.",
	},
	["sw.muse.w19.arcane.008"] = {
		"watches the violet behind a mage's window hold perfectly still, without any of the restless flicker of a candle.",
		"looks for a flicker in the light behind a mage's shutters and finds none at all, only a steady violet that no flame ever made.",
		"notices that the glow in the mages' windows never wavers when a door bangs or a cart shakes the street, and keeps watching it for a while.",
	},
	["sw.muse.w19.arcane.009"] = {
		"In the stories magic roars. In real life it turns pages and swears very softly.",
		"All that power in one street, and the loudest thing is a kettle.",
		"Everyone expects a mage to crackle and boom. Mostly you get sighing over a book.",
	},
	["sw.muse.w19.arcane.010"] = {
		"The guards call the Mage Quarter the quietest beat in the city. The ones who have walked it after dark don't call it anything.",
		"Ask the Watch and the Mage Quarter is an easy round. Ask a guard who drew it after dark, and he'll only ask you for a drink.",
		"A guard told me the Mage Quarter never gives the Watch any trouble. Then he looked at his boots for a while, as if he'd remembered one exception.",
	},
	["sw.muse.w19.arcane.011"] = {
		"That pigeon has a violet feather in its tail. No. I'm not asking.",
		"Even the pigeons round the tower look odd. One of them just stared at me for far too long.",
		"The pigeons by the tower don't startle. Not at a shout, not at a bang. They've heard worse.",
	},
	["sw.muse.w19.arcane.012"] = {
		"Now and then a traveler in violet comes down from the north, and the mages of the tower gather round like farmers around someone who has seen the next valley's harvest.",
		"When a mage arrives from the north with news, the whole quarter seems to lean in. Whatever is being rebuilt up there, they want to hear every stone of it.",
		"News from the north reaches the tower before it reaches the keep, the clerks grumble, and comes out of it, if at all, a week later and a good deal shorter.",
	},
	["sw.muse.w19.arcane.013"] = {
		"No moneylender in Stormwind will lend against a house in the Mage Quarter, they say at the bank. Next week it may still be standing, or it may be interesting.",
		"Houses in the Mage Quarter sell cheap and never stand empty. The buyers are always mages, and they always ask about the cellar first.",
		"A clerk at the bank once explained to me that a house near the tower is worth exactly what the house next door survived last year.",
	},
	["sw.muse.w19.arcane.014"] = {
		"The guards of the enemy's capital worry me least. A guard sees a face. A mage might look straight through it.",
		"Past the mages' tower with the hood low and the stride easy. Of all the eyes in this city, theirs are the ones that see past a disguise.",
	},
	["sw.muse.w19.arcane.015"] = {
		"Two wars taught the Alliance what a tower of mages is worth when the walls are tested. Stormwind may grumble at its mages, but it would never let them go.",
		"Every time a window blows out in the quarter, someone grumbles. Nobody grumbles when the Alliance marches and the mages march with it.",
		"The tower costs Stormwind glass, sleep and patience. In the field, a single mage standing with the line has paid all of it back before the fighting is done.",
	},
	["sw.muse.w19.arcane.016"] = {
		"My people remember what the arcane cost them once: half a continent sunk under the sea. Passing the mages' tower, I keep to the far side of the street, and I'm not ashamed of it.",
		"The humans study the arcane as if it were new. The kaldorei could tell them how that study ends. Most of us choose to say nothing, and walk a little faster past the tower.",
		"The violet of that tower is a color my people once wore with pride, before the sea closed over our cities. I look at it the way one looks at an old wound.",
	},
	["sw.muse.w19.banner.001"] = {
		"The great banners of the keep are taken down to be mended, a seamstress in the Trade District says, and hung back before anyone notices. A kingdom's pride, darned by lamplight in a back room.",
		"Somebody in this city spends her days patching royal banners with gold thread, and nobody has ever thanked her by name. She seems to prefer it that way.",
	},
	["sw.muse.w19.banner.002"] = {
		"Not one banner in the city has been lowered for the king. He is missing, not dead, and the banners have been told.",
		"When a king dies the banners come down to half their height. Stormwind's stay at the top of the poles, out of stubbornness or hope; nobody will say which.",
		"The banners over the keep still fly for a living king. Nobody has had the heart, or the authority, to say otherwise.",
	},
	["sw.muse.w19.banner.003"] = {
		"The dyers must love this city. Every flag fades a shade a season, and every season somebody pays to bring the blue back.",
		"Keeping a city this blue must cost a fortune in dye. I'd love to see that line in the treasury ledger.",
	},
	["sw.muse.w19.banner.004"] = {
		"At feasts the noble houses hang their own pennants beneath the royal banner, the servants say, and argue for weeks over whose hangs nearest.",
		"A feast in the keep means a war of little flags: every house wants its colors a hand's width closer to the crown's, and the stewards measure.",
	},
	["sw.muse.w19.banner.005"] = {
		"looks on as a man on a tall ladder untangles a banner cord from a lamp bracket, while a guard holds the ladder below and offers advice nobody asked for.",
		"stops to watch two workers wrestle a fresh banner up a pole, one hauling the rope and the other shouting that it's upside down, which it is.",
	},
	["sw.muse.w19.banner.006"] = {
		"The old royal banners went north with the exodus, the veterans say, rolled in oilcloth aboard the refugee ships, and came home to hang over new stone.",
		"Some of the oldest banners in the keep crossed the sea and back, to hear the old soldiers tell it. You can see it in the color: not faded, exactly. Traveled.",
	},
	["sw.muse.w19.banner.007"] = {
		"A banner on the keep says one thing: someone is in charge. With the throne as it is, the banners have to say it twice as loudly.",
		"So many banners on the keep these days. A house with its master away lights every lamp in the windows.",
	},
	["sw.muse.w19.banner.008"] = {
		"A banner-bearer of the Royal Guard holds the staff upright through a whole ceremony without a dip. The trick, one of them told a tavern, is to pick a stone on the far wall and stare it down.",
		"The guards who carry the standards say the hard part isn't the weight. It's the itch on your nose in the middle of the regent's speech.",
	},
	["sw.muse.w19.banner.009"] = {
		"notices that one of the keep's banners hangs a hand's width lower than the rest, and that the guards beneath it have very carefully decided not to see.",
		"picks out, high on the keep, one banner newer than its neighbors, its blue still too bright, like a new tooth in an old smile.",
	},
	["sw.muse.w19.banner.010"] = {
		"Wherever the regent goes, a herald goes first and a banner goes after. From a distance he looks like a man trying to walk out from under them.",
		"The regent can't cross a courtyard without someone announcing it. I'd go mad. He just nods at the herald, the way you'd nod at a neighbor.",
	},
	["sw.muse.w19.banner.011"] = {
		"The banners of the keep hang dark and heavy in the rain, too sodden to stir. Somebody will have to dry every one of them, and somebody will grumble.",
		"Rain has turned the royal blue nearly black. The lion on the nearest banner looks as if it would like to come in.",
	},
	["sw.muse.w19.banner.012"] = {
		"looks up at the keep in the dark, where the torches along the walls catch the edges of the banners and leave their middles to the night.",
		"watches the guards on the steps of the keep at night stand just outside the torchlight, so that only their gold shows.",
	},
	["sw.muse.w19.banner.013"] = {
		"Give a soldier a banner to follow and he'll walk into anything. Give him one to hold still in a courtyard and he'll complain about his feet.",
		"Banners are for battlefields. In a courtyard they're just very expensive curtains.",
		"Nobody ever asks the banner what it thinks of all this standing still.",
	},
	["sw.muse.w19.banner.014"] = {
		"Our banners fly from Menethil to Darkshire, but this keep is where they're sewn. Every scrap of blue and gold in the Alliance can trace its thread back here.",
		"I've followed these colors farther than I can count. Seeing them over the keep is like seeing the root of a tree I'd only ever known by its branches.",
	},
	["sw.muse.w19.banner.015"] = {
		"looks up at the tall banners hanging down the walls of the throne room, so long and still that they seem less like cloth than like part of the stone.",
		"stands beneath the great hangings of the throne room and notices how they deaden every sound, as if the hall were wrapped in its own colors.",
	},
	["sw.muse.w19.beggar.001"] = {
		"The old beggar by the bridge thanks you the same for a copper as for nothing at all. It's the most dignified thing I've seen in this city, and it costs him everything he has.",
		"A beggar near the canal says 'thank you kindly' whether you give or not. After a while you understand the thanks was never for the coin.",
	},
	["sw.muse.w19.beggar.002"] = {
		"Begging has its own guild here, unwritten: the best corners belong to whoever has sat there longest, and a stranger to the trade who tries the corner by the Gilded Rose is moved on by the other beggars before any guard bothers.",
		"The beggars of Stormwind keep stricter rules than the auction house. Every good corner has an owner, and the owner has a deputy.",
	},
	["sw.muse.w19.beggar.003"] = {
		"A beggar on the corner reads the same battered book every day, moving his lips. He's been on the last page for a week. I think he's afraid to finish it.",
		"That beggar with the book has been on its final page for days. Each time I pass he's reading it over. Some endings you put off as long as you can.",
	},
	["sw.muse.w19.beggar.004"] = {
		"That beggar's dog earns more than he does. Smart dog. Probably keeps the books, too.",
		"Everyone walks past the beggar and stops to pet his dog. The dog's doing fine. Somebody feed the man.",
		"The dog has the bowl, the beggar has the patience. Between them they're doing better than some shops.",
	},
	["sw.muse.w19.beggar.005"] = {
		"A few of the beggars wear coats that were once very fine. The buttons go first, one by one, then the lining, and the manners last of all.",
		"A man asks for coppers in a coat cut by a good tailor, long ago. He says 'if you would be so good' like someone who used to say it to servants.",
		"One beggar near the water still ties his cravat every day, badly, with no mirror. Whatever he lost, he hasn't agreed to lose that.",
	},
	["sw.muse.w19.beggar.006"] = {
		"Here in the Trade District the beggars sit right where the coin changes hands, between the bank and the auction house, in the river of purses. Clever. Cruel, too, to watch it all day.",
		"The beggars of the Trade District choose their spot by the sound of coin. They spend the whole day within earshot of other people's fortunes.",
	},
	["sw.muse.w19.beggar.007"] = {
		"overhears a beggar repay a passerby's copper with a solemn piece of news: the name of the one cook in the city who doesn't water the soup.",
		"hears a beggar pay for a passing stranger's coin in advice: which guard looks the other way, and which one never does.",
		"listens as a beggar, given one copper by a hurrying clerk, hands him in return the exact hour the next patrol will pass.",
	},
	["sw.muse.w19.beggar.008"] = {
		"Late, and the doorways of the city have filled: one sleeper folded into each, like letters waiting for someone to call for them.",
		"By this hour every deep doorway in the street has its sleeper. The guards walk past them softly, which is its own kind of kindness.",
	},
	["sw.muse.w19.beggar.009"] = {
		"Rain, and the beggars of the street gather under the one deep arch, shoulder to shoulder. For as long as it lasts, they're a neighborhood.",
		"The rain drives every beggar on this street under the same archway. They pass a crust and a rumor down the row and wait it out like old neighbors.",
	},
	["sw.muse.w19.beggar.010"] = {
		"A lady stopped to give a beggar a coin, and kept her glove on to do it. Charity at arm's length, through kidskin.",
		"Fine folk often give alms the way you'd feed a horse you don't trust: quickly, palm flat, and gloved.",
	},
	["sw.muse.w19.beggar.011"] = {
		"One beggar near the canal never asks for anything. He just sits with a sign saying that he's waiting for someone. Nobody knows who. People leave him bread anyway.",
		"By the water sits a man whose sign doesn't ask for coin. It says only that he's waiting. The bakers' boys bring him the broken loaves, and nobody asks for whom he waits.",
	},
	["sw.muse.w19.beggar.012"] = {
		"steps over a beggar's outstretched legs and earns, for the courtesy of not treading on them, a solemn 'much obliged'.",
		"steps carefully around a beggar asleep across half the lane, and one of his eyes opens just long enough to approve.",
	},
	["sw.muse.w19.beggar.013"] = {
		"No coin on me. Half an apple do you?",
		"Here, take the end of this loaf. It's the good end.",
		"Sorry, purse is empty. There's cheese in the pack, though, if you're not proud.",
	},
	["sw.muse.w19.beggar.014"] = {
		"The beggars of Cathedral Square don't ask the faithful for coin on the way in, only on the way out. Somebody worked out long ago that people leave more generous than they arrive.",
		"Every beggar near the Cathedral knows the trick: wait for the doors, not the steps. Whatever goes on in there, folk come out of it with their purses looser.",
	},
	["sw.muse.w19.bell.001"] = {
		"The cathedral's bell ringers all talk to you from the same side, head tilted. The acolytes say the other ear went long since, rope by rope.",
		"You can spot a bell ringer of the cathedral in any tavern: the one who leans in with the left ear and nods at everything said to the right.",
		"Ring the cathedral bells long enough and you hear the city from one side only. The ringers don't seem to mind; it halves the gossip.",
	},
	["sw.muse.w19.bell.002"] = {
		"No two acolytes agree on how many stairs climb the bell tower. Every one of them has counted, and every one got a different number by the top.",
		"Ask the cathedral's acolytes how many stairs go up to the bells and you'll start an argument. Each swears by a different count, and each has the aching calves to prove it.",
	},
	["sw.muse.w19.bell.003"] = {
		"notices the surface of the square's fountain shiver into fine rings as the cathedral bells begin, a moment before the ear has quite caught up.",
		"watches the water in the fountain tremble with the first stroke of the bells overhead, as though the square itself had flinched.",
	},
	["sw.muse.w19.bell.004"] = {
		"One of those cathedral bells is flat. Just a hair. Once you hear it, you'll never stop hearing it, so, sorry.",
		"The third bell in that peal is a little off. The whole city knows and nobody will fix it. I think they're fond of it.",
		"Listen to the next peal. The one that sounds a bit tired? That's the city's favorite.",
	},
	["sw.muse.w19.bell.005"] = {
		"The youngest acolyte at the bell ropes keeps his palms wrapped in linen. Rope, he says, teaches slowly and always leaves a receipt.",
		"Bell rope chews the hands raw before it makes them hard. You can tell how long an acolyte has been ringing by how much linen he wears.",
	},
	["sw.muse.w19.bell.006"] = {
		"There's a dog near Cathedral Square that sings along with every peal. The priests have decided to take it as devotion.",
		"When the cathedral bells start, one dog in the neighborhood always joins in, off-key and wholehearted. Nobody has the courage to tell it.",
		"Each time the bells start, a dog by the cathedral lifts its nose and joins the hymn. The acolytes have started calling it the cantor.",
	},
	["sw.muse.w19.bench.001"] = {
		"There's a bench by the water with a hollow worn into one end, exactly one person wide. Somebody has been sitting in that same spot for a very long time, or a great many somebodies, one after another.",
		"Some benches in this city have a favorite end, rubbed smooth and dipped like a saddle. The other end looks almost new. People, it seems, prefer to sit where someone already has.",
	},
	["sw.muse.w19.bench.002"] = {
		"listens to two old men on a bench argue about something that happened before most of the street was born, both of them wrong and neither willing to stop.",
		"overhears a pair of old men on a bench settling the affairs of the kingdom between them, in loud voices, with great authority and no information.",
	},
	["sw.muse.w19.bench.003"] = {
		"Every bench in Stormwind is taken. I'm starting to think people are born on them.",
		"One free bench in the whole city, and a pigeon is sitting on it. Proudly.",
		"Is anyone ever getting up off that bench? I've been circling it like a vulture.",
	},
	["sw.muse.w19.bench.004"] = {
		"Sit on a bench long enough and the whole city walks past: a priest, a pickpocket, a dwarf with a ladder, a mage reading, and the same pickpocket going the other way.",
		"From a bench by the canal the city performs for free: a quarrel, a reconciliation, an upset basket, three runaway onions and one very fast boy.",
		"A bench is the best seat in the theater of Stormwind. The plays are short, the actors don't know they're in them, and nobody charges for the ticket.",
	},
	["sw.muse.w19.bench.005"] = {
		"Stone benches in this city hold the cold like nobles hold a grudge: long after everything else has warmed up.",
		"Sit on a Stormwind bench and it reminds you, right through your trousers, that it came out of a quarry.",
	},
	["sw.muse.w19.bench.006"] = {
		"Sharing a bench with a stranger is the most Stormwind thing there is: shoulder to shoulder, eyes front, not a word, and somehow both of you a little less alone.",
		"Two strangers on one bench make a small treaty: you keep to your half, I keep to mine, and nobody mentions how pleasant it is to sit.",
		"The quietest friendships in Stormwind are made on benches, and most of them never get as far as names.",
	},
	["sw.muse.w19.bench.007"] = {
		"There's a woman who sits on the bench by the bridge and looks up at every set of footsteps. Whoever she waits for is very late, or not coming, and from the way she folds her hands again each time, she knows which.",
		"Every city has a bench where someone waits. In Stormwind it's by the water, and the one waiting never takes her eyes off the far end of the bridge.",
	},
	["sw.muse.w19.bench.008"] = {
		"Mind if I sit? My knees have lodged a formal complaint.",
		"Room on that bench? I'll be no trouble. I'll barely even sigh.",
		"Shove up a little? I'll take the cold end.",
	},
	["sw.muse.w19.bench.009"] = {
		"notices an old man asleep on a bench, who shifts over a little in his sleep to make room for nobody at all.",
		"passes a bench where an old man dozes with his chin on his chest and a hand resting on the empty seat beside him, as if keeping it for someone.",
	},
	["sw.muse.w19.bench.010"] = {
		"lingers to watch a woman on a bench tear bread for the sparrows, crumb by crumb, scolding the greedy ones by name.",
		"pauses near a bench where an old woman feeds the birds from a paper twist of breadcrumbs, holding back the biggest for a scruffy sparrow with one bad leg.",
	},
	["sw.muse.w19.bench.011"] = {
		"slows to look at a board game laid out on a bench between two players who have plainly been at it for hours, and earns a glare from both for standing too close.",
		"glances at two players hunched over a scratched board on a bench; the quieter one, without looking up, moves a piece that makes the other groan aloud.",
	},
	["sw.muse.w19.bench.012"] = {
		"There's always someone on a bench with a book, and they always look up at exactly the wrong moment: the moment you happen to be looking at them.",
		"Readers on benches have a sixth sense. Glance at the cover of the book and up come their eyes, and now you're both embarrassed and it's your fault.",
	},
	["sw.muse.w19.bench.013"] = {
		"Best benches face the water, next best face the street. The ones facing a wall? Those are for couples, apparently.",
		"A bench by the canal is for thinking, a bench by the street is for gossip, and a bench facing a wall is for kissing. Don't ask me why.",
	},
	["sw.muse.w19.bench.014"] = {
		"Benches, trees, ducks on a canal. The front is a long way off, and somebody has to remember what all of it is for. It's easiest to remember sitting down.",
		"Out there we fight in mud and smoke. In here an old couple shares a bench and argues about ducks. That's the whole cause, as far as I can tell, and it's enough.",
	},
	["sw.muse.w19.bench.015"] = {
		"You can tell how long someone has lived in Stormwind by which bench is theirs. The passing ones sit anywhere. The old ones have a bench, and a side of it, and the city knows to leave it free.",
		"Some benches belong to people the way houses do. Sit on the wrong one and an old man will stand nearby, saying nothing, until you understand.",
	},
	["sw.muse.w19.bid.001"] = {
		"There's always someone at the auction house raising a bid by a single copper, over and over, on something nobody else wants. That isn't commerce. That's a feud with a fee.",
		"Watch the auction house long enough and you'll see two strangers fight over a pair of plain gloves one copper at a time. Neither of them needs gloves.",
		"The fiercest wars in Stormwind are fought over secondhand gloves at the auction house, one copper per volley.",
	},
	["sw.muse.w19.bid.002"] = {
		"The auction house takes a deposit just to let you hope. If nothing sells, it keeps the deposit and hands your hope back, slightly used.",
		"Post a thing for sale and the house wants a coin up front. If it goes unsold, the thing comes home by post; the coin does not.",
	},
	["sw.muse.w19.bid.003"] = {
		"unfolds a scrap of parchment covered in crossed-out prices, frowns at the last one, and folds it away a little smaller than before.",
		"studies a much-folded list of prices, licks a thumb, rubs one figure out and writes in a worse one.",
	},
	["sw.muse.w19.bid.004"] = {
		"Some of what's sold at the auction house comes from people who won't be back for it. Nobody says so. The prices are a little lower, that's all.",
		"A good cloak with a mended tear at the shoulder, going cheap at auction. Somebody sold it, or somebody's friends did. The listing doesn't say which.",
		"Nobody posts a dead friend's boots under their own name. The auction house lists them anyway, and the buyer gets a bargain and never the story.",
	},
	["sw.muse.w19.bid.005"] = {
		"Half the buyout prices at the auction house aren't prices at all. They're the seller's opinion of their own taste.",
		"Bid, outbid, bid again. The auction house ought to sell benches to the people who just come to watch.",
		"I'd post my old boots at auction, but somebody would buy them, and then I'd have to know who.",
	},
	["sw.muse.w19.bid.006"] = {
		"The auctioneers know their regulars by the way they lean on the counter. The hopeful lean forward. The ones who've been at it for years lean back.",
		"You can tell the old hands at the auction house: never surprised, never pleased, and never once letting a price see them flinch.",
	},
	["sw.muse.w19.bid.007"] = {
		"Sooner or later the whole world passes through the auction house: a lace collar beside a bundle of wolf pelts beside a sack of gnomish bolts. The house doesn't judge. It just takes its cut.",
		"Linen from Elwynn, iron from the hills, a strange green stone from who knows where, all on the same list. The auction house is the one place in Stormwind where everything is equal, briefly.",
		"Mithril bars, a sack of wool and a hat with a feather the size of a cat: the auction house lists them all in the same patient hand.",
	},
	["sw.muse.w19.bid.008"] = {
		"makes room for a runner hurrying from the direction of the auction house, a stack of string-tied parcels under the chin and a tag fluttering from every one.",
		"edges aside for a clerk's boy balancing a tower of wrapped parcels, each one labeled in a cramped, impatient hand.",
	},
	["sw.muse.w19.bid.009"] = {
		"Every so often a farmer's wife comes to the auction house with something wrapped in a cloth, and leaves with coin and an empty cloth. That's how Westfall does its banking now.",
		"A silver brooch somebody's grandmother wore at her wedding, sold at auction for the price of a winter's flour. The buyer will never know. The seller will never forget.",
	},
	["sw.muse.w19.bid.010"] = {
		"Want to know what your treasure's worth? Post it at auction. You'll learn it's worth less.",
		"Nothing humbles a hoard like the auction house. Everything I thought was rare, three other people are selling.",
	},
	["sw.muse.w19.bid.011"] = {
		"The auction house sells while you sleep. You go to bed with a hope and wake to a letter: sold or unsold, and either way a little less than you wanted.",
		"Leave a thing at auction and go about your business. A day later the post brings the verdict, with all the warmth of a tax collector.",
		"Auction house letters always open the same way and end in one of two moods. I've learned to read the last line first.",
	},
	["sw.muse.w19.bid.012"] = {
		"slows to listen as two people on a corner argue over who outbid whom, both stabbing a finger at the same crumpled receipt.",
		"passes a pair of disappointed bidders comparing their losses outside a doorway, like soldiers comparing scars.",
	},
	["sw.muse.w19.bid.013"] = {
		"Some people go to the auction house the way others go to the Cathedral: daily, quietly, and with great faith that this time it'll be different.",
		"There are regulars at the auction house who never buy and never sell. They come to read the lists, the way an old farmer reads the clouds over his field.",
	},
	["sw.muse.w19.bid.014"] = {
		"Off to the auction house. If I come out smiling, someone made a mistake. If I come out frowning, it was me.",
		"Auction house, then. Hold my purse. No, wait. Hold me back from my purse.",
	},
	["sw.muse.w19.bid.015"] = {
		"The auction house is the one battlefield in Stormwind where nobody bleeds and everybody loses something.",
		"Bids thrown, bids answered, a hush before the last one. If anyone sang of the auction house, it would be the longest war song ever written.",
	},
	["sw.muse.w19.bid.016"] = {
		"Even at night the auction house keeps its lamps lit. Somewhere a stranger is outbidding someone who's fast asleep.",
		"The shops have shuttered for the night, but the auction house never quite stops. Bids go on in the dark like crickets.",
	},
	["sw.muse.w19.boat.001"] = {
		"follows a boatman as he leans his whole weight into the pole, walks it down the length of the boat, pulls it free with a twist and starts over, never once looking at his feet.",
		"studies the rhythm of a boatman at work: plant, lean, walk, twist, lift. The boat goes on as if the water were helping.",
	},
	["sw.muse.w19.boat.002"] = {
		"Every boatman has one bridge he won't pole under after the last bell, and no two of them pick the same one. Ask why and you get a shrug, or a story you'd rather not have.",
		"The boatmen keep a private map of the canals: which stretch is lucky, which bridge to avoid, where to spit for luck. Each man's map is different, and each is sure of his own.",
		"Ask three boatmen for the luckiest stretch of the canals and you get two different stretches, one insult and a long silence.",
	},
	["sw.muse.w19.boat.003"] = {
		"Barrels of salt fish, sacks of flour, a crate of hens complaining the whole way: the canal boats carry the city's dull necessities so the streets don't have to.",
		"Nobody admires a canal boat. They carry coal, flour and lamp oil, and if they stopped for a week the bakers would be the first to notice and the nobles the last.",
		"Watch the boats for a while and you learn what the city eats: flour going in, barrels going in, and empty barrels coming back out, lighter and louder.",
	},
	["sw.muse.w19.boat.004"] = {
		"The boatmen call out before every blind bend, one short word thrown at the water, and wait for an answer. They have never collided, they claim. Their hulls tell it otherwise, in scrapes.",
		"Listen near any corner of the canals and you'll hear it: a boatman's hoarse call, an answer from around the bend, then two boats squeezing past each other with a great deal of muttering.",
	},
	["sw.muse.w19.boat.005"] = {
		"takes in a boatman bailing his boat with a dented cooking pot, steady as a clock, while the water seeps back in just as steadily.",
		"pauses by a moored boat where a man scoops water out over the side with a pot, scoop after scoop, and makes no comment on the fact that the leak is winning.",
	},
	["sw.muse.w19.boat.006"] = {
		"Nearly every canal boat has a name painted on the bow, and most of them are women's names. The boatmen won't say whose. One of them changed the subject very fast.",
		"Boats on the canals carry names in fading paint: a woman's name, mostly, and once a word I took for a curse until the boatman explained it was his mother-in-law.",
	},
	["sw.muse.w19.boat.007"] = {
		"notices a cat asleep on a coil of rope in a moored boat, rising and settling with the water and entirely unconcerned by any of it.",
		"glances down at a moored boat where a cat lies stretched along the bench seat, one ear turning to every footstep on the bank and the rest of it not bothering.",
	},
	["sw.muse.w19.boat.008"] = {
		"Asked a boatman how long to the far end of the canal. He said 'depends', and spat. I'm walking.",
		"A ride by boat? I've seen how fast they go. I'll get there sooner on foot, and I'll get there dry.",
		"I'd hire a boat, but the last one I watched was overtaken by a duck.",
	},
	["sw.muse.w19.boat.009"] = {
		"One boat on the canals has sat half sunk at its ring for as long as anyone can remember. Nobody claims it, nobody moves it, and the boatmen steer around it without a word, the way you'd step around a grave.",
		"By one of the bridges a sunken boat sits with its bow still above water and its rope still tied. The boatmen say its owner tied that knot and never came back for it, and nobody has had the heart to cut it.",
	},
	["sw.muse.w19.boat.010"] = {
		"Somewhere along the canals someone is always tarring a boat. The smell clings to your clothes for a day, a reminder that wood stays afloat only as long as somebody keeps after it.",
		"Hot tar and wet wood: the canals' working smell. Every boat on the water is a promise somebody keeps with a brush and a bucket.",
	},
	["sw.muse.w19.boat.011"] = {
		"Want the city's gossip? Skip the tavern. Find a boatman. Nobody minds what they say in front of a man with his back turned.",
		"Boatmen hear everything. Half of Stormwind leans over a bridge to talk and never looks at who's floating underneath.",
	},
	["sw.muse.w19.boat.012"] = {
		"tracks a single lantern drifting along the black canal at night, the boat beneath it invisible, known only by the soft knock of the pole.",
		"stands still to let a lantern go by on the canal below, a small yellow light afloat in the night, and behind it a low voice telling the water something.",
	},
	["sw.muse.w19.boat.013"] = {
		"sees a flour boat go by low in the water, a small boy perched on top of the sacks, dusted white to the eyebrows and enormously pleased with his view.",
		"catches the eye of a boy riding a load of flour sacks down the canal like a king on a pale throne, white handprints on everything he has touched.",
	},
	["sw.muse.w19.boat.014"] = {
		"A few of the boatmen live aboard, by the look of it: a pot on a brazier, a shirt drying on the pole, a door made of an old tarp. No rent, no neighbors upstairs, and a new view whenever they like.",
		"Some canal boats are plainly somebody's whole house. Washing on a line from bow to stern, a pot of herbs by the tiller. The cheapest lodgings in Stormwind, and the only ones that move.",
	},
	["sw.muse.w19.boat.015"] = {
		"A boatman's pole is the one tool he won't lend. Each is cut to its owner's height and worn to his grip, and a borrowed one, they say, steers like a stranger's horse.",
		"The boatmen notch their poles, one notch for every year on the water, the oldest of them say. Some of those poles look gnawed by a very patient beaver.",
	},
	["sw.muse.w19.brawl.001"] = {
		"watches a scuffle at a street corner end the instant a guard's helmet shows round the bend, both men suddenly the best of friends, dusting each other off.",
		"sees two men rolling on the cobbles spring apart at the clink of an approaching patrol and stroll off arm in arm, whistling.",
	},
	["sw.muse.w19.brawl.002"] = {
		"Two porters just knocked each other into a stack of crates over who had right of way. Now they're restacking the crates together, still arguing, with real teamwork.",
		"A fistfight over right of way, a toppled stack of crates, and then both brawlers picking up apples side by side. In Stormwind even a quarrel ends in tidying.",
		"One bumped, one shoved, and now there are cabbages all over the street and two porters rolling among them. A passing dog is having the best hour of its life.",
	},
	["sw.muse.w19.brawl.003"] = {
		"steps smartly aside as a tangle of brawlers tumbles out of the Pig and Whistle into the lane, followed by a stool, followed by the barkeep's opinion.",
		"flattens against a wall while a knot of shoving, shouting regulars spills out of the tavern door, goes three rounds in the lane and shuffles back in for the next cup.",
	},
	["sw.muse.w19.brawl.004"] = {
		"Look at that: a ring formed, bets taken, and nobody's even thrown a punch yet.",
		"Old Town turns a quarrel into a sport faster than anywhere I know.",
		"The fight hasn't started and there's already a bookmaker. I admire the efficiency.",
	},
	["sw.muse.w19.brawl.005"] = {
		"sees an old woman wade into a scuffle with a broom, deal out two smart cracks across two thick skulls, and go back to sweeping as if nothing had happened.",
		"stops to see a fistfight end abruptly when a grandmother leans out of a window and empties a bucket over both parties.",
	},
	["sw.muse.w19.brawl.006"] = {
		"The two soldiers brawling by the canal aren't really angry at each other. You can tell by how they hold on afterward, foreheads together, saying a name.",
		"Some fights in Old Town are grief that ran out of words. Two veterans, a scuffle, and then the one who threw the first punch weeping into the other's collar.",
	},
	["sw.muse.w19.brawl.007"] = {
		"Nobody's winning that fight. They're just taking turns being sorry.",
		"Five copper on the one with the bigger hat. No, wait, he's lost the hat.",
		"That's not a brawl. That's two men hugging angrily.",
	},
	["sw.muse.w19.brawl.008"] = {
		"A gnome has climbed onto a barrel to break up a fight between two men twice his height. He isn't stopping it, exactly, but he's explaining to them in detail why they should.",
		"Two big men squaring up, and between them, on an upturned crate, a gnome lecturing both on leverage. The fight seems to have lost its nerve.",
	},
	["sw.muse.w19.brawl.009"] = {
		"From behind a wall somewhere: a crash, a sudden silence, then a great roar of laughter. A chair, I'd guess, has lost an argument.",
		"Close by, the unmistakable sound of a table going over, a pause, and twenty voices cheering it. Somebody's having a lively hour.",
	},
	["sw.muse.w19.brawl.010"] = {
		"lingers in the dark of a lane while two shadows under a lamp shove each other, slip, and end up sitting side by side on the cobbles, laughing.",
		"hears scuffling feet and slurred threats from the far end of a dark street, then a splash, then a long, offended silence.",
	},
	["sw.muse.w19.brawl.011"] = {
		"Two men brawling in a lane stopped mid-punch to let a little girl with a jug go by, then went back to it. Old Town has its manners.",
		"Even a street fight in this city pauses for a child carrying milk. They waited, nodded to her, and resumed hitting each other.",
	},
	["sw.muse.w19.brawl.012"] = {
		"Humans brawl much like anyone else, it turns out, only with more apologizing afterward. I watch from under my hood and keep very still.",
		"Their street fights are shorter than ours and end in handshakes. I'd find it charming if a single one of them knew what I was.",
	},
	["sw.muse.w19.brawl.013"] = {
		"On the tavern step sits a man with a split lip, being dabbed clean by the fellow who split it. Whatever started it has been forgiven, or forgotten, which in Old Town is the same.",
		"Brawl's over. The loser holds a wet rag to his eye, the winner holds the loser's cup, and both of them look faintly embarrassed.",
	},
	["sw.muse.w19.brawl.014"] = {
		"The guards of Old Town have a gift for arriving at a fight just as it runs out of steam. I'm almost sure it's on purpose.",
		"A brawl two streets off, and the patrol takes the long way round, unhurried, chatting. By the time they get there it'll be a hug.",
		"A patrol walks toward a scuffle the way a cook walks toward a pot that's nearly done: unhurried, knowing it will keep.",
	},
	["sw.muse.w19.brawl.015"] = {
		"glances toward a scuffle between two pupils from the training hall, which ends when a trainer arrives, takes each by an ear and walks them back inside without a word.",
		"sees a pair of trainees squaring off in the lane to impress nobody in particular, and a gray-haired trainer appear behind them, quiet as a debt falling due.",
	},
	["sw.muse.w19.brawl.016"] = {
		"Somebody fetch a bucket of water for those two. Over their heads, preferably.",
		"Look at them go. Neither has landed a punch yet, and both are winning.",
		"Should someone stop them? No? Then somebody pass the bread.",
	},
	["sw.muse.w19.bridge.001"] = {
		"rests a hand on a bridge parapet where the stone has been rubbed glassy by a whole city's worth of passing palms.",
		"slides a hand along the top of a bridge's low wall, the stone polished smooth at exactly the height where everyone else's hand goes too.",
		"lays a palm on the worn crown of a bridge's parapet, where the stone dips slightly, shaped by all the elbows that have leaned there before.",
	},
	["sw.muse.w19.bridge.002"] = {
		"Somebody has scratched two sets of initials into the parapet of nearly every bridge in the city. Some have been scratched out since. A few have been scratched back in.",
		"Bridges collect initials the way benches collect sleepers: two letters, a cross between them, and sometimes, in a later hand, a single furious line.",
		"Initials on the bridges, initials on the benches, initials on a tree in the Park. The lovers of this city are short on paper and long on knives.",
	},
	["sw.muse.w19.bridge.003"] = {
		"watches two children drop twigs off one side of a bridge and race across to see whose comes out first, then argue the result with tremendous heat.",
		"pauses as a pair of children lean over a bridge, eyes on the water, waiting for their racing sticks to appear from under the arch. One cheers. The other demands a rematch.",
	},
	["sw.muse.w19.bridge.004"] = {
		"Nobody stops at the end of a bridge. Everyone stops in the middle, leans, and looks down, as if the water could only be seen properly from there.",
		"The middle of a bridge is the city's favorite place to stand still. Nobody decides to; the feet slow at the top of the hump and the head goes over the edge on its own.",
		"Put a bridge over water and people will stop on it to stare down. It doesn't matter what's below. Something about a parapet makes everyone a philosopher.",
	},
	["sw.muse.w19.bridge.005"] = {
		"watches a porter take a running start at the hump of a bridge with a laden handcart, crest it by a hair, and roll down the far side as if that had been the plan all along.",
		"steps aside as a handcart comes rattling down off a humped bridge, its owner trotting behind and holding on more out of hope than control.",
	},
	["sw.muse.w19.bridge.006"] = {
		"I've crossed this bridge before. Or its twin. This city builds bridges in litters.",
		"Same arch, same rail, same chipped stone. Either I'm walking in circles or the masons only had the one drawing.",
		"Third time over this bridge. That, or Stormwind owns a great many identical ones.",
	},
	["sw.muse.w19.bridge.007"] = {
		"Halfway across certain bridges the city changes its mind: forge smoke behind, ink and baking ahead. The water in between belongs to nobody.",
		"In Stormwind a bridge is a border with no guard. One end smells of one district, the other of the next, and the middle smells of canal and belongs to nobody at all.",
	},
	["sw.muse.w19.bridge.008"] = {
		"Every arch hangs on one stone at the top, the masons say, and the rest of the bridge leans on it the way a household leans on its one reliable child.",
		"The keystone of a bridge does the least work and carries the most weight, an old mason told me once. He seemed to think that explained a great deal about kings.",
	},
	["sw.muse.w19.bridge.009"] = {
		"Under the widest bridges there's a dry ledge just above the water, and it is rarely empty: a blanket, a pot, a pair of boots set neatly side by side.",
		"Some people in this city have no roof but an arch. They keep the ledge beneath it swept, which is more than some nobles do with their stairs.",
		"Under one of the bridges someone has hung a scrap of curtain across the dry ledge. A curtain. Somebody down there still insists on a door.",
	},
	["sw.muse.w19.bridge.010"] = {
		"lingers on a bridge where a fiddler plays more for the water than for the passers-by, the hat at his feet holding two coppers and a leaf.",
		"slows on a bridge to hear a fiddler working through a sad tune for nobody in particular, eyes closed, a single copper keeping his hat company.",
	},
	["sw.muse.w19.bridge.011"] = {
		"At night every bridge lamp burns twice, once above the water and once below it, and the lower one never holds still.",
		"The lamps along the bridges hang their light down into the canal, long and shaking, like ropes someone is trying to climb in the dark.",
		"Night on the bridges: lamp, reflection, lamp, reflection, all the way down the canal, like a sentence written twice.",
	},
	["sw.muse.w19.bridge.012"] = {
		"A bridge in the middle of Stormwind, hood up, staring at the water like any other idler. The best disguise in an enemy city is to look bored.",
		"Lean on the rail, watch the canal, yawn now and then. Nobody looks twice at someone wasting time, not even in Stormwind, not even at a face like mine.",
	},
	["sw.muse.w19.bridge.013"] = {
		"People here part on bridges, I've noticed. Halfway across, one goes on and the other turns back, and the bridge holds them apart at exactly the right distance.",
		"A bridge is a good place for a goodbye. There's a middle to stop at and two ends to walk away to, and the water says nothing either way.",
	},
	["sw.muse.w19.bridge.014"] = {
		"Up, over, down. Up, over, down. Whoever built these bridges had excellent knees.",
		"I could draw a map of this city's bridges from the aches in my calves alone.",
		"Stormwind is a city of stairs pretending to be bridges.",
	},
	["sw.muse.w19.bridge.015"] = {
		"Humans build a bridge for every ditch of water. In Ironforge we'd have tunneled under the lot and been home in time for supper.",
		"A bridge is just a tunnel that lost its nerve, the miners say. The humans have built a great many of them here, and very prettily too.",
	},
	["sw.muse.w19.canal.001"] = {
		"Every few dozen paces a flight of steps runs down into a canal and simply stops in the water, worn hollow in the middle. Somebody needed to get very close to this water, very often.",
		"Steps down to the water all along the canals, and not one of them leads anywhere but in. Washing, fetching, fishing, falling: the stone keeps no record of which.",
		"Of all the stairs in Stormwind, the canal steps lead nowhere you'd want to go, and they're the most worn of the lot.",
	},
	["sw.muse.w19.canal.002"] = {
		"A dark band runs along the canal walls a hand above the water, where the level stood for a long time. The water has dropped since. The stone kept the line.",
		"Look closely at a canal wall and the water's old heights are written on it in stripes of moss and stain, like the rings of a felled tree.",
		"In moss, the canal walls keep a diary: green at the waterline, black above it, and a pale old stripe higher up where the water stood once and has never reached since.",
	},
	["sw.muse.w19.canal.003"] = {
		"Follow a canal in this city long enough and it brings you back to the bridge you started from. The water doesn't mind going in circles. I do.",
		"The canals here don't end, they just come round again. Like gossip at a wedding.",
		"Who designed these canals? I'd like a word. And a map.",
	},
	["sw.muse.w19.canal.004"] = {
		"There are people who fish the canals and eat what they catch. They swear it's good. I'll take their word for it, from a safe distance.",
		"Somebody is always fishing off a canal wall, line slack, eyes half shut. Whether anything ever bites seems entirely beside the point.",
		"Fishermen on the canals never talk about what they caught. They talk about what they nearly caught, which is always bigger and always got away under a bridge.",
	},
	["sw.muse.w19.canal.005"] = {
		"watches an old fisherman on the canal steps haul up an empty hook, inspect it as though it had insulted him, and drop it back in.",
		"stops beside a child fishing from the canal edge with a bent nail on a string, and is told, very gravely, to step back because the fish can see.",
		"lingers by a fisherman on the canal steps just long enough to see him land an old boot, regard it fondly, and put it in his basket anyway.",
	},
	["sw.muse.w19.canal.006"] = {
		"You learn the canals by nose before you learn them by name. Tar there, wet bread here, and past the bend something nobody's gone to look at.",
		"On a good day the canals smell green. On a bad day, like an argument.",
	},
	["sw.muse.w19.canal.007"] = {
		"notices the iron rings set into the canal wall at knee height, each one rubbed bright along its inner curve by a great many ropes.",
		"runs a thumb over a mooring ring in the canal wall, its iron worn into a smooth groove where ropes have pulled at it for longer than anyone can say.",
	},
	["sw.muse.w19.canal.008"] = {
		"Somebody has to dredge these canals. I've seen the crew at it: long rakes, high boots, and the faces of people who have already found everything there is to find.",
		"Dredgers never look surprised. Whatever comes up on the rake, a boot, a chair, a noble's wig, they've pulled out two of it before.",
		"Whatever the canals swallow, a dredging crew sooner or later coughs back up onto the bank, dripping, to be sorted by men who have stopped asking questions.",
	},
	["sw.muse.w19.canal.009"] = {
		"Swim in the canals? On a dare, maybe. Once.",
		"Two kinds of people have swum a canal in this city: the ones who lost a bet and the ones who lost their footing.",
		"I'd go a long way round rather than swim one of these canals. Having smelled them, a very long way.",
	},
	["sw.muse.w19.canal.010"] = {
		"When a thought won't sit still, I walk it along a canal. The water goes at the right pace for thinking: slow, but never stopped.",
		"The streets are quicker across the city. For untangling a knot in your head, nothing beats the long way round, beside the water.",
		"Walking beside the water slows me down without my noticing. By the third bridge I've usually forgotten what I was in such a hurry about.",
	},
	["sw.muse.w19.canal.011"] = {
		"Ask anyone raised in Stormwind about the canals and you get the story of the day they fell in. Everyone has one. It's practically a birth certificate.",
		"Every child in this city falls into a canal once, their parents say. The second time is carelessness.",
		"Stormwind folk can tell you which canal they fell into as children, how deep it was, and who laughed. They remember the one who laughed longest of all.",
	},
	["sw.muse.w19.canal.012"] = {
		"watches the canal swell under the storm, the water climbing one step and reaching for the next, the moored boats tugging at their ropes like dogs at a gate.",
		"keeps clear of the canal edge as the storm drives the water up the stone steps, brown and quick, carrying leaves from somewhere far off.",
	},
	["sw.muse.w19.canal.013"] = {
		"The canals have a small music of their own if you stop to hear it: water lapping at stone, a pole knocking a hull, a shutter opening somewhere above and a basin emptied without warning.",
		"Under the noise of the streets the canals keep their own time: a lap, a gurgle, the hollow knock of wood on wood.",
		"Even with the street roaring, the canal underneath goes on with its small business: a gurgle at a drain, a slap at a step, a rope creaking against a ring.",
	},
	["sw.muse.w19.canal.014"] = {
		"Two houses facing each other across a canal can go a lifetime within shouting distance and never once visit. The nearest bridge is three streets off, and pride is much closer.",
		"In this city a canal makes a better wall than stone. Neighbors across the water wave, shout, gossip, and never cross: the bridge is always just too far.",
		"Two neighbors across a canal can share every quarrel and never share a doorstep. The water carries the shouting over; nobody has ever asked it to carry an apology.",
	},
	["sw.muse.w19.canal.015"] = {
		"Whoever laid out these canals did it with gravity, patience and not a single valve. No gauges, no sluice wheels, no pressure readings. Charming. Primitive, but charming.",
		"Every gnome who walks these canals ends up sketching improvements on the back of something. Locks, pumps, a little paddle wheel. The humans thank us politely and change nothing.",
		"I timed the flow of a canal with a leaf and a pocket watch. Disappointing. I'm told nobody here has ever wanted it to go faster.",
	},
	["sw.muse.w19.cart.001"] = {
		"lends a shoulder when a handcart's wheel drops into a gap in the paving, and the cart's owner thanks everyone and no one in particular.",
		"watches three strangers heave a cart wheel out of a rut in the street, then part without a word, each back to their own errand.",
	},
	["sw.muse.w19.cart.002"] = {
		"There's a cart in this city with an axle that squeals like a trodden cat. I've never seen it, but I'd know it anywhere, and so would every dog in Stormwind.",
		"Somewhere an axle is begging for grease, loudly, at the top of every rise. The carter has clearly decided it's company.",
	},
	["sw.muse.w19.cart.003"] = {
		"steps aside for a cart whose driver is fast asleep on the bench, reins slack, while the old horse in the traces takes every turn without being asked.",
		"lets a dozing carter go by, chin on his chest, his horse picking its way through the crowd as if it had walked this route since it was a foal.",
	},
	["sw.muse.w19.cart.004"] = {
		"Everyone watches what the carts bring into Stormwind. Nobody watches what they take out: ash from the ovens, broken crates, the swept-up straw of a whole district. A city has to empty its pockets too.",
		"The carts that leave the city at the end of the day carry the parts nobody admires: ash, rubble, old straw, the sweepings of the market. They go out quietly, and nobody waves.",
		"Somebody has to cart the city's ash out of the gate every week. A city this size must burn a forest a year just keeping its ovens hot.",
	},
	["sw.muse.w19.cart.005"] = {
		"Mind the cart! Says every porter in Stormwind, about three paces too late.",
		"Every handcart in this city comes with a warning shout, and every shout arrives just after the wheel.",
		"Cart coming through! Which, in this city, means you're already standing in the wrong place.",
	},
	["sw.muse.w19.cart.006"] = {
		"A plain cart came through the gate with a long shape under a blanket and two soldiers walking beside it, not talking. The crowd made room without being asked.",
		"Sometimes a cart rolls in slowly with a soldier on each side and something long under a cloak in the back. People stop talking as it passes and start again a little later than they should.",
	},
	["sw.muse.w19.cart.007"] = {
		"steps out of the way of a hen that has escaped from a market cart and is crossing the street with the confidence of a noble.",
		"watches a carter chase a runaway goose twice around a stalled cart while the crowd offers advice and nobody offers help.",
		"trades a glance with a carter whose crate of piglets has just discovered the latch, then retreats to a doorstep.",
	},
	["sw.muse.w19.cart.008"] = {
		"The paving near the gate has two long grooves worn into it, exactly a wheel-span apart. Stone gives way to carts in the end; it only takes a few hundred thousand of them.",
		"Look down near the gate and you'll see where the city's carts have been: twin grooves polished into the stones, the road's own record of every load.",
		"Wheels have polished a path into the stones by the gate, two pale lines that shine whenever the street is wet.",
	},
	["sw.muse.w19.cart.009"] = {
		"Want it cheap? Catch the cart before it reaches the stalls. Same onions, half the price, and no awning to pay for.",
		"Never buy from a stall what you can buy off the back of a cart at the gate. The onion doesn't know the difference; your purse does.",
	},
	["sw.muse.w19.cart.010"] = {
		"Humans cannot move anything without a wheel and a great deal of noise. In the groves we carried what we needed, and needed less. Still, I admit their carts are very well painted.",
		"Wheels everywhere, grinding on stone. I find myself stepping more softly to make up the difference, as if a city could be balanced.",
	},
	["sw.muse.w19.cart.011"] = {
		"A hay cart went through and left a trail of straw from the gate halfway across the city. You could follow it like a story, right to wherever Stormwind's horses eat.",
		"You can tell where a hay wagon has been by the straw it sheds on every corner. The sweepers follow it like crows behind a plow.",
	},
	["sw.muse.w19.cart.012"] = {
		"trades a long look with a small child riding on the tailboard of a cart, legs dangling, who is plainly taking in the whole city at once and finding it acceptable.",
		"is waved at by a farm child perched on a sack at the back of a passing wagon, solemn as a herald, until the crowd closes in between them.",
	},
	["sw.muse.w19.cart.013"] = {
		"Every steep little bridge in Stormwind is a battle between a carter and the slope. The carter usually wins, though you'd never guess it from the language.",
		"Watch a loaded cart take one of the city's arched bridges: a run-up, a hope, a lot of shouting, and at the top a horse giving its driver a look.",
		"The arched bridges of this city were drawn by someone who never pushed a barrow in his life.",
	},
	["sw.muse.w19.cart.014"] = {
		"Timber comes in through the gate and leaves as chairs, beams and coffins. Iron comes up from the forges and leaves as nails, hinges and horseshoes. The carts don't care which way the city is changing things.",
		"Logs in, furniture out. Ore in, nails out. Stand by the gate for an hour and you can watch the city make things without ever setting foot in a workshop.",
	},
	["sw.muse.w19.causeway.001"] = {
		"watches an old man lower a fishing line over the parapet into the moat, settle his elbows on the stone and wait with the patience of the statues behind him.",
		"leans beside a fisherman at the bridge rail who has caught nothing and seems entirely content about it, his line hanging still in the green water below.",
		"spends a moment beside a boy dangling a bent pin on a string over the parapet, who explains with great seriousness that the big one is down there somewhere.",
	},
	["sw.muse.w19.causeway.002"] = {
		"Judging by what floats in the moat, the bridge is the best place in Stormwind to lose a hat. One careless lean over the parapet, a curse, and off it goes to join the others.",
		"There's always a hat in the moat. Never the same hat. I think the bridge collects them.",
		"The moat must hold the finest hat collection in the kingdom. Not one owner has ever come to claim a piece.",
	},
	["sw.muse.w19.causeway.003"] = {
		"The dust of the Elwynn road stops at the gate. Past it, everything is dressed stone, and you can hear the change under every boot and wheel: soft, then loud.",
		"Dust on one side of the gate, cut stone on the other, and a line between them as clear as a signature. The forest ends there, and every cart wheel says so with a clatter.",
	},
	["sw.muse.w19.causeway.004"] = {
		"Long bridge, that one. I think they built it that way so visitors have time to rehearse what they'll say at the gate.",
		"The bridge by the gate is just long enough to change your mind on, and just short enough that you won't.",
		"That bridge is long enough to have a proper middle. Most bridges don't bother.",
	},
	["sw.muse.w19.causeway.005"] = {
		"drops a pebble over the parapet and listens; the moat takes it with a small, deep sound, as if it had been waiting.",
		"lets a crust of bread fall from the bridge into the moat and watches a slow shape rise from the green to take it, then sink again without hurry.",
	},
	["sw.muse.w19.causeway.006"] = {
		"Armies leave the city over the long bridge in columns and come back over it in clusters. The paving doesn't know the difference; the people lining it always do.",
		"The long bridge has carried every army out of Stormwind in good order, and carried what was left of them back in no order at all.",
		"That bridge has heard every kind of marching: proud, tired, and the kind with gaps in it.",
	},
	["sw.muse.w19.causeway.007"] = {
		"Want to know who's in town? Don't ask at the inn. Sit on the bridge parapet with an apple and watch. Sooner or later everybody comes that way.",
		"The idlers on the parapet by the gate know more than SI:7, and they work for apples.",
	},
	["sw.muse.w19.causeway.008"] = {
		"waits at the edge of the bridge while a hay cart, a column of soldiers and a flock of sheep try to pass one another, and everyone shouts directions at everyone else.",
		"steps up onto the curb of the bridge as a drover's sheep pour around a stalled wagon like water round a stone, bleating their opinion of the city.",
	},
	["sw.muse.w19.causeway.009"] = {
		"The moat smells green: pondweed, wet stone, and something underneath that nobody has ever wanted to investigate.",
		"Lean over the bridge parapet and the moat sends up its smell, weed and cold stone and a faint hint of whatever fell in last.",
	},
	["sw.muse.w19.causeway.010"] = {
		"In this fog the long bridge has no far end. Carts roll out of the white with their lanterns lit, as if Elwynn were sending them one by one.",
		"Fog sits on the moat like wool on a pond. The bridge goes out into it and simply stops being a bridge, and every cart that comes back out of it is a small surprise.",
	},
	["sw.muse.w19.causeway.011"] = {
		"Rule of the bridge: wagons in the middle, walkers on the edges, and sheep wherever the sheep decide.",
		"Stay to the side on the bridge. The carters won't stop, and their horses have never heard of manners.",
		"On the bridge, give way to anything with wheels or horns. Pride heals; feet take longer.",
	},
	["sw.muse.w19.causeway.012"] = {
		"Down where the wall meets the moat there's a dark band on the stone, a hand tall, marking where the water has stood for years. The wall keeps the moat's diary.",
		"The stones at the moat's waterline are darker and softer at the edges than the rest, worn by water that has been patient a very long time.",
	},
	["sw.muse.w19.causeway.013"] = {
		"Every time I cross the long bridge on my way out, I straighten up without meaning to. The Alliance put its best face on its front door, and some of it rubs off.",
		"There's something about walking out over that bridge toward the gate. Whatever waits beyond it, the Alliance sent me out through its finest door.",
	},
	["sw.muse.w19.causeway.014"] = {
		"stops halfway across the bridge, where the gate and the city are equally far, and stands a moment belonging to neither.",
		"lingers at the middle of the long bridge, the gate at one end and the noise of the streets at the other, as if waiting to be claimed by one of them.",
	},
	["sw.muse.w19.causeway.015"] = {
		"There's a woman who stands at the bridge parapet most days, facing the gate. The guards greet her by name and never ask who she's waiting for. I think they know.",
		"Not everyone leaning on the bridge is watching the water. Some are watching the gate, the way you watch a door someone promised to come back through.",
		"An old man brings a stool to the parapet and sits facing the gate. He tells anyone who asks that he likes the view. The view is a road.",
	},
	["sw.muse.w19.causeway.016"] = {
		"Don't lean over the parapet with a full purse. The moat is a very patient thief.",
		"Keep your purse tied when you lean over that bridge. The moat never gives change.",
	},
	["sw.muse.w19.champion.001"] = {
		"At the Champions' Hall they hand out titles by the rung: sergeant, knight, marshal, each one shinier than the last. The climb is long, and paved with bruises.",
		"Knight-Lieutenant, Knight-Captain, Knight-Champion: the Champions' Hall has more ranks than a bakery has loaves, and every one of them costs more.",
	},
	["sw.muse.w19.champion.002"] = {
		"steps aside for an officer striding out of the Champions' Hall, a fresh insignia on her collar that she keeps touching as though it might fall off.",
		"makes room on the steps of the Champions' Hall for a soldier coming out with a new tabard folded over one arm, held like something that might bruise.",
	},
	["sw.muse.w19.champion.003"] = {
		"Not everyone at the Champions' Hall is there for a rank. Some come to ask a quiet question at the desk about a name, and leave without the answer they wanted.",
		"Among the soldiers waiting at the Champions' Hall there's always one who isn't collecting anything, only asking after somebody, a cap held in both hands.",
	},
	["sw.muse.w19.champion.004"] = {
		"Two soldiers outside the Champions' Hall compare their insignia with the solemn care of boys comparing marbles. Neither will admit the other's is shinier.",
		"Old soldiers can't help it: meet one with a new rank and the other leans in to inspect the stitching, finds a loose thread, and is very happy.",
	},
	["sw.muse.w19.champion.005"] = {
		"Whatever the nobles argue about, the Champions' Hall keeps faith with the soldiers who hold our lines. It's the one hall in the city whose floor is worn by boots and not by slippers.",
		"Our soldiers come back from the fronts to the Champions' Hall to be counted. It matters, being counted. Out there it's easy to feel the city has forgotten you.",
	},
	["sw.muse.w19.champion.006"] = {
		"The warrior trainers of Old Town have one lesson: hit it once more. The advanced course is: hit it once more, harder.",
		"Ask a warrior trainer for a secret and you'll get a shrug and a shove toward whatever needs hitting.",
		"Warrior trainers never say 'well done'. They say 'once more', and you learn to hear the difference.",
	},
	["sw.muse.w19.champion.007"] = {
		"hears a trainer's voice from an open doorway counting slowly to ten, and a dozen pupils groaning on every number.",
		"catches, through an open door, the dull rhythm of wooden weapons on padded posts and a trainer barking one word over and over, which sounds a lot like 'elbow'.",
	},
	["sw.muse.w19.champion.008"] = {
		"Old Town trains both kinds: the warriors, who learn to stand where everyone can see them, and the rogues, who learn the exact opposite two doors down.",
		"One quarter, two schools: in one they teach you to be the loudest thing in a fight, in the other the quietest. They drink at the same tavern and pretend not to know each other.",
	},
	["sw.muse.w19.champion.009"] = {
		"Inside the Champions' Hall, they say, hang the colors of companies that no longer exist. Nobody takes them down. A banner is cheaper than a memorial and says the same.",
		"Old companies' colors hang faded in the hall where the champions gather, the soldiers say: units broken up, merged, or simply ended. They're dusted, never replaced.",
	},
	["sw.muse.w19.champion.010"] = {
		"Every rank handed out in that hall in Old Town was earned against someone like me. I walk past it the way you'd walk past a butcher who knows your measurements.",
		"The Champions' Hall: where Stormwind counts what it took from the Horde. I don't stop to read the tally.",
	},
	["sw.muse.w19.champion.011"] = {
		"passes a rack of dented practice helmets set out to air, each one bearing the same dent in the same spot, a trainer's favorite blow.",
		"notices a basket of padded helmets by a doorway, every one dented over the left ear, as if they had all met the same opinion.",
	},
	["sw.muse.w19.champion.012"] = {
		"The soldiers at the Champions' Hall talk about Alterac, Warsong Gulch and the Arathi Basin the way farmers talk about three stubborn fields: endlessly, and with mud in every sentence.",
		"Listen to the talk outside the Champions' Hall and the whole war shrinks to three names, a gulch, a basin and a valley, argued over like pieces on a board.",
	},
	["sw.muse.w19.champion.013"] = {
		"Titles are fine things. You can't eat one, though, and you can't sleep under it.",
		"A rank and a pat on the back. I've had worse pay, but never lighter.",
		"Medals are lovely. Boots that don't leak are lovelier.",
	},
	["sw.muse.w19.champion.014"] = {
		"One of the old trainers in Old Town keeps a list of the pupils who came back to say thank you, the guards say. It's a short list. He carries it in his breast pocket.",
		"Trainers seldom learn what becomes of most of their pupils. The lucky ones get a visit, years on, from someone who stands a little straighter in the doorway.",
	},
	["sw.muse.w19.champion.015"] = {
		"The Champions' Hall: where they pin a title on you and send you straight back out.",
		"That hall has a rank for everything except 'tired'.",
		"Every title in that hall is a polite way of saying 'go back out there'.",
	},
	["sw.muse.w19.chimney.001"] = {
		"looks up as a sweep's boy pops out of a chimney pot two roofs over, black from cap to boots, and waves his brush at the street like a flag.",
		"spots a chimney sweep sitting astride a roof ridge with a heel of bread, sooty legs dangling, as much at ease up there as a pigeon.",
	},
	["sw.muse.w19.chimney.002"] = {
		"A fine black dust settles on everything in this city if you stand still long enough: sills, collars, the back of your hand. The chimneys share what they have.",
		"There's always a little soot in the air here, the gift of a few thousand chimneys. Wipe a windowsill with a finger and the city writes its name on you.",
	},
	["sw.muse.w19.chimney.003"] = {
		"Look up and there's a second crowd over Stormwind: chimney pots, hundreds of them, tall and squat and crooked, some wearing little tin hats. Nobody planned them, and they get along fine.",
		"The chimneys of this city never agree on anything: one leans east, one leans west, one has a tin cap like a nervous soldier. Together they make a skyline nobody drew.",
		"Seen from any height, the roofs of Stormwind bristle with chimney pots like the stubble on a carter's chin, no two the same length.",
	},
	["sw.muse.w19.chimney.004"] = {
		"watches the smoke rise from a hundred chimneys in straight gray threads, not one of them bending, as if the city had been tied to the sky for safekeeping.",
		"follows the smoke climbing straight up from the rooftops into a cloudless sky, every column so still it might have been painted there.",
	},
	["sw.muse.w19.chimney.005"] = {
		"You can read a street by its smoke. Sweet and pale means good oak; thick and yellow means cheap coal; thin and sour means somebody is burning whatever will burn.",
		"The nobles' chimneys smell of apple wood. Old Town's smell of coal and old boots. Even the smoke in Stormwind knows its station.",
		"Follow your nose down any street and the smoke tells you who lives there: resin for the joiners, coal for the smiths, and dried dung where nobody can afford better.",
	},
	["sw.muse.w19.chimney.006"] = {
		"Through a low window: a table, a fire, a dog asleep under the bench, someone laughing with a full mouth. The city keeps its warmest rooms just out of reach of the street.",
		"A half-open door, a glimpse of a kitchen fire and a kettle starting to sing, and then the street carries me past. Stormwind is full of small rooms like that, lit and private.",
	},
	["sw.muse.w19.chimney.007"] = {
		"Folk in Stormwind brush a sweep's sleeve for luck, or so a sweep told me with a perfectly straight face, before admitting he had started the custom himself.",
		"A chimney sweep swore to me that touching his sooty sleeve brings a month of good fortune. He charged a copper for the privilege, which seemed to be where the fortune went.",
	},
	["sw.muse.w19.chimney.008"] = {
		"flicks a speck of soot from one sleeve, finds two more, and gives up, letting the city mark {g:him|her} as it marks everyone.",
		"rubs at a smudge of soot on the back of one hand and only spreads it into a small gray cloud the shape of somewhere far away.",
	},
	["sw.muse.w19.chimney.009"] = {
		"My cloak picks up the city's smoke the way a dog picks up burrs. For days after I leave, I'll smell of other people's suppers.",
		"Woodsmoke, coal smoke, somebody's frying: it all ends up in the folds of my cloak. Stormwind sends me off with a keepsake whether I want one or not.",
		"I'll be picking Stormwind's smoke out of my hood for a week.",
	},
	["sw.muse.w19.chimney.010"] = {
		"The storm keeps shoving the smoke back down the chimney, and every few minutes the whole room coughs at once, then goes back to its conversations as if nothing had happened.",
		"Each gust outside sends a puff of smoke back into the room from the hearth. Nobody comments. In Stormwind, apparently, storms come indoors to warm up.",
	},
	["sw.muse.w19.chimney.011"] = {
		"A thousand chimneys in this city, and not one fire you can sit by without buying a drink first.",
		"All that smoke means all those hearths, and every single one of them behind a door that's shut.",
		"So many hearths, and every one of them somebody else's.",
	},
	["sw.muse.w19.chimney.012"] = {
		"Every chimney that smokes means someone inside who expects to be there tomorrow. A whole city of them is a kind of quiet bravery.",
		"Out on the roads a column of smoke can mean trouble. Here, a thousand of them mean supper. It takes a moment to remember which world I'm in.",
		"Chimney smoke over a city means it expects to wake up. I find that more comforting than the walls.",
	},
	["sw.muse.w19.chimney.013"] = {
		"lifts {g:his|her} head at a thread of cherrywood smoke drifting from somewhere nearby, sweet enough to stop a conversation.",
		"turns toward a whiff of pine smoke, resinous and sharp, curling in from some hearth out of sight.",
	},
	["sw.muse.w19.chimney.014"] = {
		"Humans build a chimney for every room, little and crooked. Back in Ironforge one good flue carries the smoke of a whole hall, and nobody coughs.",
		"So many chimneys, and every one of them drawing badly. Give me a week and a dwarven mason and this skyline would draw like a forge.",
	},
	["sw.muse.w19.chimney.015"] = {
		"Coal smoke and baking bread and wet slate. Wherever else I go, this is what my people mean when they say 'home'.",
		"The smell of Stormwind's chimneys gets into human bones early and never leaves. I'd know it blindfolded, anywhere in the world.",
	},
	["sw.muse.w19.chimney.016"] = {
		"Look at these cuffs. A few streets of Stormwind and they're the color of a chimney sweep.",
		"Everything in this city leaves a mark. Mostly soot.",
	},
	["sw.muse.w19.court.001"] = {
		"Every boot in the kingdom crosses this carpet sooner or later, and not one of them is ever wiped. Somewhere in the keep there's a servant who knows that better than the regent.",
		"Farmers, envoys, soldiers, mud: the long carpet of the throne room has taken them all, and somebody has to brush it before the next lot arrives.",
	},
	["sw.muse.w19.court.002"] = {
		"watches a page come down from the keep at a fast walk that never quite becomes a run, a folded letter pressed flat to his chest.",
		"steps aside for a page in royal colors hurrying down from the keep, all elbows and seriousness, both hands guarding a sealed letter.",
		"follows with {g:his|her} eyes a page boy who takes the steps below the keep two by two and then, remembering where he is, one by one.",
	},
	["sw.muse.w19.court.003"] = {
		"Folk coming down from the keep talk too softly for the street for the first twenty paces. Then a cart nearly runs them over and they remember where they are.",
		"Anyone who has just left the court is easy to pick out: low voice, folded hands, right up to the first fishmonger's shout.",
		"Courtiers come down from the keep blinking at the noise of the streets, like folk stepping out of a temple into a fair.",
	},
	["sw.muse.w19.court.004"] = {
		"Nobody at court ever says no. They say 'it will be considered'. Anyone in this city can tell you what that means.",
		"At court, 'the matter is under consideration' is the polite way of shutting a door very slowly.",
	},
	["sw.muse.w19.court.005"] = {
		"Court news reaches the cheese stalls before it reaches the court's own clerks. The sellers had the new tariff by heart while the herald was still clearing his throat.",
		"Whatever is decided in the keep, the market hears of it first. I'd wager the regent learns half his own decisions from a fruit seller.",
	},
	["sw.muse.w19.court.006"] = {
		"A servant from the keep told the whole inn: they still set King Varian's cup at the high table, and still carry it away full.",
		"At the keep's table there's a place laid for the king at every meal, so the servants say. Nobody sits there, and nobody has dared to stop laying it.",
		"The servants still polish the king's place at table, it's said. A knife, a spoon, a cup, all bright, all waiting.",
	},
	["sw.muse.w19.court.007"] = {
		"pauses as a courtier in velvet stops at the edge of the street to scrape something off a soft shoe, glaring at the cobbles as if they had done it on purpose.",
		"notices a man in court silks picking his way across the cobbles on his toes, as though the street were a rumor he didn't want to be seen near.",
	},
	["sw.muse.w19.court.008"] = {
		"Nobody here tells you to lower your voice. The height of the ceiling tells you, and the echo of your own boots agrees with it.",
		"The throne room never asks for silence out loud. It simply makes every sound you bring in seem a little too large.",
		"In this hall a dropped glove would sound like a verdict.",
	},
	["sw.muse.w19.court.009"] = {
		"stands among the onlookers at the edge of the throne room, close enough to see the hush and too far away to hear the words that made it.",
		"lingers by a pillar at the side of the hall, where the courtiers' murmur is a low tide that rises whenever the regent turns his head.",
	},
	["sw.muse.w19.court.010"] = {
		"If the court ever ran out of whispers, the keep would go so quiet you could hear the boy king yawn.",
		"Whispers are the court's real currency. And the mint never closes.",
		"In the keep they don't gossip. They 'share concerns'. Same thing, better shoes.",
	},
	["sw.muse.w19.court.011"] = {
		"Court dress calls for white gloves, the tailors say, and a courtier seen opening a door with his own hand has lost the afternoon.",
		"The glovers of Stormwind live off the court. Nobody who matters ever touches anything with a bare hand, least of all a door.",
	},
	["sw.muse.w19.court.012"] = {
		"turns to see a courier in royal colors hurry up toward the keep with a sealed tube on his back, while another comes down the other way, slower, both hands empty.",
		"sees two messengers pass each other on the way to and from the keep, one fresh and one spent, and neither so much as glance at the other.",
	},
	["sw.muse.w19.court.013"] = {
		"Watch a courtier at rest: weight on one foot, chin half turned, ready to step toward whoever matters next. They never quite stand still; they hover.",
		"Courtiers don't walk so much as drift, always a little toward the most important person in the room. You could find the regent in a crowd by watching their shoulders.",
	},
	["sw.muse.w19.court.014"] = {
		"The keep's kitchens buy more bread than any inn in the city, the bakers boast. A court runs on talk, and talk runs on bread.",
		"Ask a baker who his best customer is and he'll point at the keep. Councils, it seems, are hungry work, even the ones that decide nothing.",
	},
	["sw.muse.w19.court.015"] = {
		"notices that the Royal Guard on the steps of the keep wear their gold a little brighter than the City Watch, and stand as if the extra shine weighed nothing at all.",
		"compares the guards of the keep with the watchmen of the streets: the same colors, polished harder, and a stillness that makes the street patrols look restless.",
	},
	["sw.muse.w19.court.016"] = {
		"A smith in the Dwarven District swears the Royal Guard's breastplates weigh half again what a watchman wears, and that the extra is all polish and pride.",
		"The Royal Guard practice standing still, a watchman grumbled in a tavern, the way other soldiers practice with the pike. Nobody laughed, because it shows.",
	},
	["sw.muse.w19.court.017"] = {
		"In this fog the keep has vanished altogether. For a while the city has no head, only shoulders, and it goes about its business just the same.",
		"The keep is gone in the fog, towers and all. Odd how quickly you stop looking up for it.",
	},
	["sw.muse.w19.court.018"] = {
		"Thunder rolls over the keep and not one guard on the walls so much as shifts. Nobody gave the storm permission.",
		"Lightning shows the keep for an instant, white against the dark, every banner snapping. Then it's gone, and only the guards' lanterns remember where it stood.",
	},
	["sw.muse.w19.court.019"] = {
		"Give High Tinker Mekkatorque a week in that throne room and the petitioners would arrive by lift and leave by chute. The regent would hate every minute of it.",
		"A whole kingdom run by hand, with quills and runners and shouting. If my people still had Gnomeregan, we'd have sent the keep a proper speaking tube by now.",
	},
	["sw.muse.w19.crier.001"] = {
		"Some of the criers in the Trade District have voices that could halt a cavalry charge. They use them on turnips.",
		"Half the hawkers in Stormwind could have made sergeant on voice alone. The army's loss is the onion trade's gain.",
		"A good crier could make a battle horn sound shy, and spends it all on the virtues of dried figs.",
	},
	["sw.muse.w19.crier.002"] = {
		"winces as a hawker a step away fills the street with the price of smoked eels, every word aimed squarely at {g:his|her} left ear.",
		"flinches from a peddler who chooses that very moment, at that very distance, to announce the virtues of his pickled onions.",
	},
	["sw.muse.w19.crier.003"] = {
		"After a while the cries of the sellers stop being words and become a sort of tide. You only notice it when one voice drops out.",
		"Spend an hour among the hawkers and their calls run together like water over pebbles. It's the silence of a missing one that makes you look up.",
	},
	["sw.muse.w19.crier.004"] = {
		"Shout it loud enough and even yesterday's fish sounds fresh.",
		"Volume isn't quality. That fish makes the point from three streets away.",
		"Bellowing doesn't make a cabbage any greener.",
	},
	["sw.muse.w19.crier.005"] = {
		"Between the price of bread and the price of rope, a crier calls a reward for news of a wagon that left for Westfall and never reached it. Then back to the rope.",
		"The hawkers fold the bad news in among the bargains: a missing cart, a farm gone quiet, and then candles, three for a copper.",
	},
	["sw.muse.w19.crier.006"] = {
		"stops to hear a crier rattle off forty goods and their prices in one unbroken run, and very nearly applauds at the end.",
		"listens with one eyebrow raised as a hawker recites every kind of rope ever twisted without stopping once.",
	},
	["sw.muse.w19.crier.007"] = {
		"There's always a child somewhere in the Trade District calling out a parent's wares, very serious, very loud, and mispronouncing half of them.",
		"The smallest criers are the most earnest: some shopkeeper's child chanting the prices with total faith and two of the numbers wrong.",
	},
	["sw.muse.w19.crier.008"] = {
		"Stormwind's hawkers don't need repeating. The first time, you hear them. The second time, so does Ironforge.",
		"You never miss a crier in this city. You may try. They take it as a challenge.",
	},
	["sw.muse.w19.crier.009"] = {
		"The hawkers' calls must be older than the walls. The city burned and was rebuilt, and someone went on singing 'fresh fish' on the same three notes.",
		"I'd wager the cries of the market haven't changed in a hundred years: the same lilt on 'onions', the same drop on 'cheap'. Stone gets rebuilt. Tunes get handed down.",
		"Listen to how the onion sellers draw the word out. Their grandparents called it just that way before the First War, I'd bet, and in the same street.",
	},
	["sw.muse.w19.crier.010"] = {
		"finds a handbill pressed into {g:his|her} hand by a boy who has vanished into the crowd before it can be handed back.",
		"looks down at a hand-copied notice of a tailor's sale that someone has just tucked, unasked, under {g:his|her} arm.",
	},
	["sw.muse.w19.crier.011"] = {
		"Human hawkers sing their prices. At home in Ironforge we chalk the price on a slate and glare at anyone who reads it twice. Saves the voice.",
		"All this hollering over cabbages. A dwarf writes the price down, folds his arms and waits. The same cabbages get sold.",
	},
	["sw.muse.w19.crier.012"] = {
		"hears the last calls of the day thin out along the street as dusk comes down, one hawker after another dropping to a hoarse, half-hearted murmur.",
		"listens as the market cries dwindle with the dusk, the final bargains offered to the street in tired, cracked voices.",
	},
	["sw.muse.w19.crier.013"] = {
		"Some old hawker in this city has shouted his voice down to a rasp, and he goes on calling anyway. People buy from him the way you'd tip a hat.",
		"A crier with no voice left, still calling his wares in a croak nobody can make out. Half the street buys from him. Nobody could say exactly why.",
	},
	["sw.muse.w19.crown.001"] = {
		"Stormwind has lost a king twice in one lifetime. The first died in his own keep; the second simply never arrived. I don't know which is harder to mourn.",
		"Llane fell inside these walls, Varian vanished outside them. The city has had its king taken both ways now, and still the throne has never stood empty.",
		"One king killed in his own hall, the next lost somewhere between the city and a peace. Stormwind has bad luck with its kings, and none of it is the city's fault.",
	},
	["sw.muse.w19.crown.002"] = {
		"pauses at a toy seller's tray, where a row of painted wooden soldiers stands around a small wooden king whose face has been left blank.",
		"picks up a carved toy king from a stall, finds its face unpainted, and sets it back down gently among the soldiers.",
	},
	["sw.muse.w19.crown.003"] = {
		"Children in the alleys play at being King Anduin. As far as I can tell, the game is mostly sitting very straight while the others tell you what to do.",
		"On a doorstep a small girl sits enthroned on an upturned bucket, and her brother, the regent, explains to her very sternly what she has decided.",
		"The alley game of king and regent always ends the same way: the regent does all the work and the king gets called home for supper.",
	},
	["sw.muse.w19.crown.004"] = {
		"The proclamations all open with 'by order of the King' and close, in smaller letters, with the regent's name. The smaller letters do the work.",
		"The big letters on a decree belong to a boy; the small ones at the bottom belong to the man who wrote it. Read the bottom first.",
	},
	["sw.muse.w19.crown.005"] = {
		"The boy's father set out to make a peace and never arrived. If I were Anduin, I'd either hate the word or want it more than anything.",
		"In a manner of speaking, it was peace that took the king away. I wonder what the boy on the throne thinks of the word now.",
	},
	["sw.muse.w19.crown.006"] = {
		"A crown belongs to the kingdom, not to the head beneath it. A city that has had to rebuild everything else knows the difference better than most.",
		"Heads change, the crown stays. Stormwind has learned to bow to the circle of gold and to hope for whoever happens to be inside it.",
	},
	["sw.muse.w19.crown.007"] = {
		"A boy on the throne. I hope somebody in the keep remembers to send up a honey cake now and then.",
		"Ten thousand subjects, and not one of them allowed to tell the king it's past his bedtime.",
	},
	["sw.muse.w19.crown.008"] = {
		"notices a small painted likeness of King Varian tacked inside a shop doorway, its corners curling, a dried sprig tucked behind the frame.",
		"glances at a faded portrait of the missing king hung behind a counter, where the shopkeeper has set a stub of candle that nobody seems to light.",
	},
	["sw.muse.w19.crown.009"] = {
		"Varian grew up far from this keep after his father fell in it, the old soldiers say, and came back a grown man to sit where Llane had sat. Now his son waits on the same seat.",
		"Three Wrynns, one seat: a grandfather slain in that hall, a father raised in exile to reclaim it, a boy sitting in it, waiting. Some families inherit land. This one inherits absence.",
	},
	["sw.muse.w19.crown.010"] = {
		"'Missing' is a word with a door left open in it. The whole city keeps a hand on that door.",
		"Every week without news, 'missing' gets a little heavier to say. People carry it more carefully, the way you carry a full bowl.",
	},
	["sw.muse.w19.crown.011"] = {
		"Our king is a child and our other king is a question. I bow to the first and pray for the second, and I'm not sure which of them is listening.",
		"My kingdom has a boy for a king and a regent for a father. We've lived through worse. I just can't think when.",
	},
	["sw.muse.w19.crown.012"] = {
		"The boy king reads everything put in front of him, the clerks say. So the clerks have started putting less in front of him.",
		"Word is the young king asks a question about every paper he's handed. The council has learned to hand him fewer papers and longer answers.",
		"The clerks say the boy signs slowly, sounding out each word. Nobody dares hurry him; it's the one part of the day that's entirely his.",
	},
	["sw.muse.w19.crown.013"] = {
		"Hood up, eyes down, in the capital of the people my side fights. Their king is a child. I hadn't pictured that, and I'd rather not have learned it.",
		"Where I come from they talk about Stormwind's throne as if a warlord sat on it. It's a boy, and a tired knight standing beside him. Harder to hate than I'd like.",
	},
	["sw.muse.w19.crown.014"] = {
		"Old men in the taverns still say 'King Llane' the way you'd name a street you grew up on and can't find anymore.",
		"Mention Llane to anyone old enough and they go quiet first and fond after. A king killed in his own hall leaves that kind of silence.",
	},
	["sw.muse.w19.crown.015"] = {
		"A throne built for a grown man, and in the middle of it a boy with his feet set very carefully side by side.",
		"So many grown people in this hall, all of them watching one child try not to fidget. In his place I'd fidget.",
	},
	["sw.muse.w19.crown.016"] = {
		"A good king can be raised as well as born. Stormwind's trying both at once.",
		"They're bringing up a king in that keep the way you'd build a wall: slowly, true, and hoping nothing hits it before the mortar sets.",
	},
	["sw.muse.w19.crown.017"] = {
		"hears a cheer go up somewhere toward the keep, thin and brief, the kind a crowd gives a child it loves and is a little afraid for.",
		"turns at a ripple of cheering from the direction of the keep, short and warm, the sort of sound that ends with people telling each other he looked well.",
	},
	["sw.muse.w19.crown.018"] = {
		"In Ironforge you can tell how long a king has ruled by his beard. This one hasn't got a beard. Give the lad time.",
		"Magni's been ruling since before this boy was born. A king who can't grow a beard yet. Humans do everything in a hurry.",
	},
	["sw.muse.w19.crown.019"] = {
		"Tyrande has led my people since before the first stone of this city was cut. Here they hand a kingdom to a boy and call it the natural order. Short lives make brave arrangements.",
		"Humans crown their children because they cannot wait for them to grow. I find it frightening, and a little beautiful.",
	},
	["sw.muse.w19.cutpurse.001"] = {
		"The bump is nothing. The apology is the theft: a hand on your arm, a 'so sorry, friend', and while you're being gracious about it, your purse is crossing the canal.",
		"In a Stormwind crowd, be wary of anyone who apologizes too well. A real accident mumbles. A rehearsed one bows.",
		"The best cutpurses in Stormwind are wonderfully polite. They bump, they beg pardon, they ask after your health, and they leave with your coin in the most courteous way imaginable.",
	},
	["sw.muse.w19.cutpurse.002"] = {
		"thanks a stranger who helped gather up a few dropped coins, takes two steps, and pats {g:his|her} belt all the same.",
		"accepts a helping hand up a crowded bridge from someone very charming, then counts the purse at the top, just to be fair to everyone.",
	},
	["sw.muse.w19.cutpurse.003"] = {
		"Every bridge in Stormwind narrows the crowd to a single throat, and the cutpurses know every one of them. Over water, the guards say, hold your purse in front of you like a lantern.",
		"Crowds bunch on the bridges, and thieves love a bunch. The guards' advice is plain: purse forward, elbows in, and no admiring the water until you're across.",
		"Cutpurses love a bridge: one way on, one way off, and everybody looking at the water.",
	},
	["sw.muse.w19.cutpurse.004"] = {
		"notices a boy loitering by a stall with nothing to sell and the cleanest hands in the street, and keeps one palm resting on {g:his|her} belt until he wanders off.",
		"marks a lad idling near the crowd with spotless fingers and no errand at all, and shifts {g:his|her} purse to the other hip without making a show of it.",
	},
	["sw.muse.w19.cutpurse.005"] = {
		"Somebody shouts 'Thief!' and the whole street does the same thing at once: a hand to its own purse. Nobody looks for the thief until they've found their coin.",
		"Cry 'thief' in Stormwind and you'll see a hundred people pat their belts in perfect time. The thief, meanwhile, pats his too, to blend in.",
		"'Stop, thief!' Every head turns, every hand drops to a belt, and the only person in the street who doesn't flinch is the one walking calmly away.",
	},
	["sw.muse.w19.cutpurse.006"] = {
		"Every cutpurse in the guards' reports is the same man: middling height, brown hood, ran. Either one thief is very busy or the guards need more adjectives.",
		"'Brown hood, average build, went that way.' I've heard that description three times now. Stormwind's most wanted is apparently anyone.",
		"There's a description of the city's cutpurses in the guards' books that would fit me, the guard who wrote it, and most of the crowd. They call it thorough.",
	},
	["sw.muse.w19.cutpurse.007"] = {
		"Old Town swears no cutpurse works the Cathedral steps. Whether it's respect for the Light or fear of a paladin with a long reach, nobody in Old Town will say.",
		"The cutpurses leave the Cathedral alone, so the gossip goes. Some say it's honor. Others point at the paladins on the steps and say it's arithmetic.",
	},
	["sw.muse.w19.cutpurse.008"] = {
		"turns sharply at a light touch at {g:his|her} belt and finds only a small girl holding up a button that fell off somewhere, very proud of having caught it.",
		"spins round at a tug on {g:his|her} pack and finds a child offering back a dropped glove, solemn as a guard handing over a prisoner.",
	},
	["sw.muse.w19.cutpurse.009"] = {
		"The longest line in the Trade District isn't for the auction house. It's for the cutpurses, who work their way along it from the back, very patiently, like everyone else.",
		"Here in the Trade District the busiest trade is the one with no stall. It works the auction house queue, purse by purse.",
	},
	["sw.muse.w19.cutpurse.010"] = {
		"The city teaches its thieves their trade officially, in Old Town, and then arrests them unofficially everywhere else. There's a lesson in that, but I'd hate to say whose.",
		"In some back room of Old Town a trainer is showing someone how to lift a purse without a sound. Three streets away, a guard is showing someone else the inside of a cell. Stormwind likes to keep both trades busy.",
	},
	["sw.muse.w19.cutpurse.011"] = {
		"watches an old market woman tuck her purse away and catches the glint of a fishhook sewn just inside its mouth. Whoever reaches in there uninvited will be leaving with a souvenir.",
		"spies a fishhook stitched inside the lip of a vegetable seller's purse, barb outward, and keeps a respectful distance from it.",
	},
	["sw.muse.w19.cutpurse.012"] = {
		"Hands where I can see them, friend. Yes, both. I can count to two.",
		"That's close enough. I like my purse where it is, and so does my purse.",
		"Nice crowd for a stroll, isn't it? Stroll that way, please. Away from my belt.",
	},
	["sw.muse.w19.cutpurse.013"] = {
		"The cutpurses call fog their wages, the guards say. In this murk a hand can reach a purse and be gone before its owner has finished turning round.",
		"Fog over the city, and every purse in Stormwind is a little more anyone's. I keep a hand on mine and the other free for apologizing to lampposts.",
	},
	["sw.muse.w19.cutpurse.014"] = {
		"Some of the quickest hands in the city belong to children whose families came up from Westfall with nothing. The guards catch them, feed them, and catch them over and over. Nobody has found a better answer.",
		"A thin girl with Westfall dust still in her hems was caught with a purse that wasn't hers. The guard holding her by the collar looked as tired of it as she did.",
		"The guards have a name for the Westfall children who work the crowds: strays. They say it the way you'd say it of kittens, and arrest them anyway.",
	},
	["sw.muse.w19.cutpurse.015"] = {
		"A gnome near the tram swears by his purse: it snaps shut on any hand but his, with a sound like a mousetrap. He has the bandaged fingers to prove it works.",
		"One gnome's answer to the cutpurses of Stormwind is a purse with a spring in it. It works beautifully. He shows you his own two bruised thumbs as evidence.",
	},
	["sw.muse.w19.cutpurse.016"] = {
		"Whoever just brushed past me: I'd already counted it. All of it. Twice.",
		"Nice try, whoever that was. The purse is on the other side. It's always on the other side.",
	},
	["sw.muse.w19.decree.001"] = {
		"stops at a notice post thick with layers of nailed paper, new decrees over old, and finds at the bottom a corner still bearing a king's seal from before he went missing.",
		"lifts the edge of a notice nailed over a notice nailed over a notice, until an older seal shows underneath, faded, from when the king was still in the keep.",
	},
	["sw.muse.w19.decree.002"] = {
		"Every face on the wanted notices looks like the same unlucky cousin, drawn in charcoal by someone in a hurry. I'd hate to be that cousin.",
		"The wanted posters in this city all show the same scowl under a different name. Either the artist has one face in him, or crime runs in a single family.",
		"Someone has drawn a mustache on one of the wanted notices. The guards haven't taken it down. I suspect it's a better likeness now.",
	},
	["sw.muse.w19.decree.003"] = {
		"'Breaking the king's peace,' the guards still call it, when they haul someone off. The king is missing and his peace goes on being broken in his name. Somebody has to keep it for him meanwhile.",
		"The charge is still 'disturbing the king's peace'. Nobody has thought of a better word, and nobody wants to be the one to suggest the regent's.",
	},
	["sw.muse.w19.decree.004"] = {
		"The nobles write the laws of Stormwind, and the guards wear them out on the cobbles. I've yet to see a noble walk one.",
		"Laws in this city are drafted in fine rooms and enforced in rough boots. The two ends have never been introduced.",
		"A decree is a noble's idea that a guard has to carry around the streets all day.",
	},
	["sw.muse.w19.decree.005"] = {
		"People at the notice posts say the decrees have grown longer since Lady Prestor began to take an interest at court, and the reasons given in them shorter. Nobody says it loudly.",
		"A clerk muttered that the new decrees read differently lately: smoother, longer, and somehow always to the nobles' advantage. Then he looked over his shoulder and found something else to do.",
	},
	["sw.muse.w19.decree.006"] = {
		"The farmers from Westfall tell it bitterly: they asked the crown for soldiers and got a proclamation. So they raised a militia themselves, and nailed the proclamation up in a barn.",
		"Westfall asked Stormwind for guards and received a letter with a seal, the refugees say. A seal is very handsome. It doesn't keep the Defias out of a barn.",
	},
	["sw.muse.w19.decree.007"] = {
		"There's no decree in Stormwind about orcs walking the streets. There doesn't need to be. Every guard already knows exactly what the law would say.",
		"Nobody ever had to write down what happens to an orc found inside these walls. Some laws are kept so well they never need ink.",
	},
	["sw.muse.w19.decree.008"] = {
		"lingers by a notice post where a girl is reading a decree aloud to an old man, skipping every long word with great confidence, while he nods as though she had read them all.",
		"overhears a boy reading a fresh notice to his grandfather, turning 'whereas' into 'and then' and the regent's titles into a mumble, to the old man's evident satisfaction.",
	},
	["sw.muse.w19.decree.009"] = {
		"The rain has got at the decrees on the notice posts. The ink runs, the seals bleed, and for once the whole city agrees on what the law says: nothing legible.",
		"Wet notices hang off every post, their ink sliding toward the bottom of the page. The regent's latest word, softened by the rain into a gentle suggestion.",
	},
	["sw.muse.w19.decree.010"] = {
		"A thief sentenced in Stormwind is sentenced in the king's name. Which king, he might fairly ask: the one who's missing, or the one who's learning to read? The clerk writes it down either way.",
		"Justice here still wears the crown's name like a borrowed coat. It fits nobody quite right, and everybody keeps it buttoned.",
	},
	["sw.muse.w19.decree.011"] = {
		"Get caught brawling in Stormwind and you pay a fine to a clerk, who gives you a receipt. Keep the receipt, the guards advise. Next time it proves you're a regular.",
		"Fines here come with a receipt, signed and sealed. A city that loses its king and keeps its receipts has its priorities in some kind of order.",
	},
	["sw.muse.w19.decree.012"] = {
		"Long may the law hold, king or no king. Somebody has to keep the streets honest while the crown sorts itself out.",
		"The regent's law is good enough for me. It keeps the gates shut on the right people.",
	},
	["sw.muse.w19.decree.013"] = {
		"Our laws were written for a king who sat in the keep and heard the petitions himself. They still work without him, the way a mill still turns after the miller has stepped out. I'd rather the miller came back.",
		"Stormwind's law outlived one king already, and the city with him. It can outlive a missing one. I just don't want it to have to.",
	},
	["sw.muse.w19.decree.014"] = {
		"waits while the guards at the gate turn over a carter's load of chisels and mallets twice, the carter reciting from memory the paper that says he's allowed.",
		"observes a mason's apprentice at the gate unroll every tool in his kit for a guard, one by one, like a peddler showing silks, under a notice nailed above them both.",
	},
	["sw.muse.w19.decree.015"] = {
		"There's still a law against driving goats over the bridges, a guard swears, older than the walls. He has never once enforced it, and he spends every round hoping for a goat.",
		"According to an old sergeant, the city never repealed a single law after the rebuilding. In some ledger it's still forbidden to whistle near the keep. He whistles very quietly whenever he passes it.",
	},
	["sw.muse.w19.decree.016"] = {
		"'By order of the regent.' Well, that settles it. Whatever it is.",
		"A fresh notice. Let me guess: something is forbidden, someone is to blame, and the regent is very sorry about all of it.",
		"Can anyone read the small print on this one? I'd like to know what I'm not allowed to do before I do it.",
	},
	["sw.muse.w19.elf.001"] = {
		"Every doorway in this city is a little short for a night elf. They duck through without complaint, the way you bow to a host who means well.",
		"A night elf stoops under the lintel of one shop, then the next, then the next. By the end of the street it looks almost like a courtesy.",
		"Some shopkeepers in the city have taken to hanging a rag from the lintel at night-elf height, so their visitors duck before they're reminded the hard way.",
	},
	["sw.muse.w19.elf.002"] = {
		"I heard a night elf ask a girl how old she was. 'Nine,' she said, and the elf repeated it softly, as if it were the name of a very small, very precious coin.",
		"A night elf asked a child her age and was told 'nine and a half'. She thanked the girl gravely, like someone who has been handed something fragile.",
	},
	["sw.muse.w19.elf.003"] = {
		"notices that the night elf ahead makes no sound at all on the cobbles, and for a few paces walks a little more softly too.",
		"falls in behind a night elf whose feet make no sound on the stone, and for a stretch of street tries, without much luck, to match the silence.",
		"hears the crowd's boots clatter on the stone on every side, and in the middle of it one pair of night elf feet that make no sound whatsoever.",
	},
	["sw.muse.w19.elf.004"] = {
		"I saw a night elf lay a palm on the bark of the only tree in some little courtyard, the way you'd greet an old acquaintance met far from home.",
		"There's a lone tree in a yard just off the street. The night elves who pass all touch it. None of them says why, and the tree isn't telling either.",
	},
	["sw.muse.w19.elf.005"] = {
		"By the patience on her, that night elf has been waiting at the counter longer than I've been alive.",
		"Never queue behind a night elf. She'll wait a century without a sigh and make you feel rude for tapping your foot.",
	},
	["sw.muse.w19.elf.006"] = {
		"The humans here live their whole lives at a run, and still they stop to show a stranger the way. The running I understand from a distance. The stopping I am still learning.",
		"Their lives are short and their city is loud, and somehow the two fit: they shout so that someone will remember. I find I listen more carefully here than in Darnassus.",
	},
	["sw.muse.w19.elf.007"] = {
		"A night elf at a pie stall asked what was in the pie, listened to the entire answer, and bought one anyway. That's either courage or excellent manners.",
		"I watched a night elf take a first bite of a Stormwind meat pie with the face of a scholar opening a doubtful book. The verdict was a slow nod.",
		"The pie-man explained his recipe to a night elf for a good while. She heard it all with perfect courtesy, bought two, and ate neither in front of him.",
	},
	["sw.muse.w19.elf.008"] = {
		"watches a string of children trail a night elf down the street at a careful distance, halting whenever she halts, like goslings that have heard stories.",
		"notices a knot of children following a tall night elf through the crowd, freezing each time she glances back, then creeping on.",
	},
	["sw.muse.w19.elf.009"] = {
		"Every night elf in this city came by two ships and a long road. You can see the distance on them: they stand like guests who haven't decided whether to take off their cloaks.",
		"Two crossings of the sea and half a continent lie between this street and the forests of Teldrassil. The night elves here carry that distance quietly, like a pack never set down.",
	},
	["sw.muse.w19.elf.010"] = {
		"Can't find anyone in this crowd? Find a night elf. She'll be the tallest thing in the street that isn't a lamppost.",
		"Easiest way to meet up here: stand next to a night elf and let everyone else find you.",
		"Don't know where you are? Look up. That's a night elf. Walk toward her and you'll be somewhere.",
	},
	["sw.muse.w19.elf.011"] = {
		"The night elves keep their own hours, even here. While the city shouts they doze in some quiet corner; when the shutters come down they wake, and the streets seem to be theirs.",
		"You see night elves half asleep in quiet corners while Stormwind does its business, then wide awake once the shops close. They are the city's other shift.",
	},
	["sw.muse.w19.elf.012"] = {
		"glances at a corner table where a night elf bends nearly double to hear a dwarf, and the dwarf rises on the rung of his stool to be heard.",
		"notices two strangers at one small table, a night elf and a dwarf, meeting halfway: one stooping, one stretching, both laughing at the effort.",
	},
	["sw.muse.w19.elf.013"] = {
		"Humans keep asking the night elves how old they are, and the elves keep answering with a smile and no number. It's the most polite refusal in the city.",
		"Ask a night elf her age and you get a gentle look, the kind you'd give a child who asked how deep the sea is. Then she changes the subject to your boots.",
	},
	["sw.muse.w19.elf.014"] = {
		"Here in the Park the night elves walk slower than anywhere else in the city, and the humans who come to sit there start, without noticing, to walk slower too.",
		"The visitors from Darnassus seem to gather in the Park the way travelers gather near a hearth. They don't say they miss the forest. They pick up fallen leaves and keep them.",
	},
	["sw.muse.w19.exodus.001"] = {
		"The ones who were children on the boats north don't remember the burning, an old baker says. They remember the cold of the deck, the smell of tar, and somebody's mother singing the same three lines over and over.",
		"Ask an old woman of Stormwind about the flight north and she won't talk about orcs. She'll talk about wet blankets, a crust of bread passed hand to hand, and a sailor who let the children hold the rope.",
	},
	["sw.muse.w19.exodus.002"] = {
		"Stormwind has elders who still have a northern turn in their vowels, from growing up in Lordaeron during the exile. They don't talk about the friends they left up there. Everyone knows what came to Lordaeron since.",
		"You can hear Lordaeron in certain old voices in this city: a flattened word, a northern way of saying thank you. The people who taught them those words are under the plague now, or worse.",
		"An old chandler says 'aye' where the rest of Stormwind says 'yes', a habit from the exile years. Every time he hears himself, he goes quiet a moment. Whoever he learned it from is gone with the north.",
	},
	["sw.muse.w19.exodus.003"] = {
		"overhears an elderly woman give a stranger directions by a turning that only exists in Lordaeron, catch herself, laugh, and begin again.",
		"listens as an old man explains the way to the bank by a square he must have known in the north, then stops, frowns, and simply points.",
	},
	["sw.muse.w19.exodus.004"] = {
		"Varian went north as a boy with the refugees and came back a grown man to be crowned in the rebuilt keep. Now he's gone again. Stormwind has a king the roads keep carrying off.",
		"The city lost a king to the orcs, sent his son away to be raised among strangers, crowned him on his return, and lost him too. Some kingdoms have bad luck. This one has a habit.",
		"The father fell in his own keep; the son was sent north to be safe, came back to be crowned, and vanished on the way to a peace talk. Stormwind builds a fine throne room. It has trouble keeping kings in it.",
	},
	["sw.muse.w19.exodus.005"] = {
		"Lothar walked a whole kingdom out of its own ruins. I've seen people take longer to leave a tavern.",
		"Lothar got an entire city out the door with orcs on the doorstep. I've watched a dwarf take longer leaving an inn.",
		"Lothar got a kingdom onto boats with orcs at its back. I can barely close a satchel.",
	},
	["sw.muse.w19.exodus.006"] = {
		"Not everyone went north. Some hid in the woods of Elwynn and lived rough until the war moved on, the old farmers say. There's still a small coolness between those families and the ones who took the boats, and nobody will tell you who's owed the apology.",
		"Those who stayed behind in the forest tell the exile one way; those who sailed tell it another. Seat an old one of each at the same table and you'll hear two wars.",
	},
	["sw.muse.w19.exodus.007"] = {
		"listens to two old men at the next table argue whether the crossing to Lordaeron took nine days or twelve, each of them very sure and neither willing to count.",
		"half-hears a pair of elders bicker over the length of the voyage north, nine days, twelve, a fortnight, the number rising with each cup.",
	},
	["sw.muse.w19.exodus.008"] = {
		"Lothar was Llane's champion and his oldest friend, the veterans say, and the last thing he did for him was take his people away. They call it the hardest order anyone ever gave in this kingdom.",
		"Leaving was the brave choice, the old soldiers insist: Lothar could have died on the walls for his king's memory. He chose to walk the living north instead, and to carry the shame of it.",
	},
	["sw.muse.w19.exodus.009"] = {
		"watches an old cobbler pause in his work to drink from a dented tin cup, holding it the way one holds a thing carried a very long way.",
		"notices a shoemaker set down his awl and lift a battered tin cup, turning it in his fingers a moment before drinking, as if it had a story he never tells.",
	},
	["sw.muse.w19.exodus.010"] = {
		"The exiles came back along this road, the old folk say, and stopped where the gate had been, because there was nothing left to walk through. Some knelt. Some just set their bundles down and started picking up stones.",
		"Here, an old man told me, the returning column halted at the edge of a field of rubble. Nobody gave an order. People simply put down what they carried and began sorting the stones into piles.",
	},
	["sw.muse.w19.exodus.011"] = {
		"Lordaeron took my people in when Stormwind was ash. Now Lordaeron is a grave, and its survivors sleep in our doorways. I'd like to think we're repaying the debt. Mostly we're stepping around them.",
		"The north gave Stormwind shelter once, and it was generous. Its people come south now with nothing, and we humans of this city don't always remember who fed us.",
	},
	["sw.muse.w19.exodus.012"] = {
		"Half the old folk in this city were born in one kingdom, grew up in another, and grew old in a third that wears the first one's name.",
		"Leave your city as a child, come back to find a different one built on the spot. That's every gray head on this street.",
		"Born in Stormwind, raised in Lordaeron, buried in Stormwind. Same name, twice. Not the same place.",
	},
	["sw.muse.w19.exodus.013"] = {
		"When the exiles returned, the old farmers say, Elwynn had swallowed its own farms, and the only way to find a homestead was to look for the stones of its hearth in the grass.",
		"Coming back from the north meant hunting for your own doorstep in the brambles, by the old ones' account. Most found it by the fireplace stones. Some never found it at all.",
	},
	["sw.muse.w19.exodus.014"] = {
		"passes a low window where an old woman sits up with a single candle, the way the exiles are said to have kept watch on the ships north, one light for the whole night.",
		"notices one lamp still burning in a ground-floor window this late, an old man behind it, awake and looking north, or at nothing at all.",
	},
	["sw.muse.w19.exodus.015"] = {
		"Northern black bread, sour as an old debt. The elders here swear by it. I swear at it.",
		"That dark sour loaf? Lordaeron bread, from the exile years. Nobody under forty eats it. Nobody over sixty does without.",
		"The bakers still make the bread the exiles brought back from the north. One bite and you understand why they were so glad to come home.",
	},
	["sw.muse.w19.folk.001"] = {
		"A lady in a fur-trimmed cloak and a ragpicker with his sack wait for the same cart to pass, side by side, and for the length of that wait they are exactly equal.",
		"The cart doesn't care who you are. A noblewoman and a ragpicker stood shoulder to shoulder at the corner until it had gone by, and neither of them enjoyed it.",
	},
	["sw.muse.w19.folk.002"] = {
		"A woman in a green shawl stands at the same corner every time I pass, and a man with a limp always crosses on the same stone. I don't know their names. I'd notice if they were gone.",
		"I've started to know faces here without a single name to go with them: the shawl at the corner, the limp at the crossing, the whistler. Strangers, every one, and somehow mine.",
		"Nobody in this crowd knows me, and still a few faces have become landmarks: the shawl, the limp, the man who whistles off-key. If one went missing, the street would look wrong.",
	},
	["sw.muse.w19.folk.003"] = {
		"stops beside a letter-writer's folding table, where a laborer dictates slowly and the scribe, kindly, leaves out every third word.",
		"lingers near a scribe who writes letters for coppers and reads each one back aloud, while the customer nods along to words he never quite said.",
		"waits while a scribe at a folding table reads a laborer's letter back to him, the man mouthing along, pleased to hear himself sound so educated.",
	},
	["sw.muse.w19.folk.004"] = {
		"Somebody just trod on my foot and apologized, and I apologized back. I think that's how this city works.",
		"Bump into anyone here and you both say sorry. Nobody's ever sure who started it.",
		"Four apologies to cross one street. I've never been shoved so politely.",
	},
	["sw.muse.w19.folk.005"] = {
		"An old couple from Lordaeron sit by the canal most days. He wears a house key on a string around his neck. The house is in Andorhal, he says, and doesn't say the rest.",
		"Some of the northerners here still carry keys to doors in Lordaeron. Nobody asks what stands behind those doors now. The keys are kept polished anyway.",
	},
	["sw.muse.w19.folk.006"] = {
		"Some voices in this city still carry Lordaeron: flatter vowels, shorter thanks. Those folk came south ahead of the plague and never quite unpacked.",
		"The northerners in Stormwind still say 'the kingdom' and mean the one up north. Nobody corrects them. It's kinder than asking which kingdom they have left.",
	},
	["sw.muse.w19.folk.007"] = {
		"steps aside for a woman with a basket of turnips balanced on her head and both hands free for scolding the boy who trots behind her.",
		"makes room for a market woman carrying a laden basket on her head as if it weighed nothing, her hands busy counting change for somebody else.",
		"yields the path to a market woman with a basket on her head, who never once looks up and never once loses a turnip.",
	},
	["sw.muse.w19.folk.008"] = {
		"There's a blind man in this city who gives better directions than the guards. He counts the bridges by the change in the echo and knows every street by its smell.",
		"Lost, I asked a blind man the way. Left at the smell of tar, he said, and right at the second echo. He was perfectly right.",
		"The blind man on the corner hears a stranger coming three steps before anyone sees one. Strangers, he says, walk as if the street might move under them.",
	},
	["sw.muse.w19.folk.009"] = {
		"Half this city is in a hurry and the other half is in its way. I keep switching sides.",
		"Everyone here is either late or blocking someone who is. At the moment I'm managing both.",
		"Stormwind walks at two speeds: too fast and in the way. I've tried both.",
	},
	["sw.muse.w19.folk.010"] = {
		"In a crowd this size I've taken to reading hands: ink on a clerk's fingers, flour in a baker's knuckles, small burns on a smith's thumbs. Mine, I suppose, just say 'road'.",
		"Every hand in the street tells its trade: ink, flour, tar, the shine of a moneylender's rings. Mine would only say 'traveler', and not a tidy one.",
		"The trades of this city are written on its hands. The clerks have the cleanest, the laborers the widest, and the pickpockets, I'm told, the softest.",
	},
	["sw.muse.w19.folk.011"] = {
		"Humans build in a hurry and then live inside the hurry they built. I've watched a man here eat his supper walking. A dwarf would sooner skip it.",
		"The folk of this city fit a whole life into the time it takes a dwarf to settle on how to braid a beard. I'm learning not to say so out loud.",
	},
	["sw.muse.w19.folk.012"] = {
		"Half the gnomes I know in Stormwind rent a room over someone else's workshop and fill it with plans. We lost a city; we did not lose the habit of building one.",
		"Every gnome lodging here owns the same furniture: a cot, a lamp, and a stack of drawings for a city that isn't there yet. I know that furniture well.",
	},
	["sw.muse.w19.folk.013"] = {
		"passes two old men on a low wall who have plainly been arguing the same argument for years, and nods to both, which settles nothing.",
		"slows beside a pair of graybeards on a doorstep, deep in a quarrel about a winter neither of them can date, and moves on before either asks for a witness.",
	},
	["sw.muse.w19.folk.014"] = {
		"listens a moment to a fiddler on a crate who has only three strings and plays as if the fourth were merely resting.",
		"pauses for a street fiddler whose bow has more hair missing than left, and finds the tune none the worse for it.",
	},
	["sw.muse.w19.folk.015"] = {
		"A footman in livery stands by a noble's door all day, guarding it from nobody in particular. He and I have traded so many nods that I count him a friend.",
		"The doorman of some fine house nods to everyone who passes and opens the door for no one. A whole career spent nearly being polite.",
	},
	["sw.muse.w19.folk.016"] = {
		"Directions in this city are all ghosts: turn where the old bakery was, go past the house that burned, stop where the well used to be.",
		"Nobody here gives directions by what's standing. It's always 'past where the tannery was'. I get lost in a city that isn't there anymore.",
		"Ask the way and you get a history lesson: left at a shop that closed, right at a wall they pulled down. The old folk navigate by what's missing.",
	},
	["sw.muse.w19.folk.017"] = {
		"catches sight of a dwarf hoisting a stranger's small daughter onto his shoulder so she can see over the crowd, then handing her back to her mother with a little bow.",
		"sees a dwarf lift somebody's little girl above the press of the street to see what everyone is staring at, and set her down again, gravely, like a borrowed tool returned.",
	},
	["sw.muse.w19.folk.018"] = {
		"Stormwind folk will complain about their city all day long, the prices, the dust, the nobles, until a stranger agrees. Then they defend every stone of it.",
		"Complain about this city to someone born here and you'll hear a list longer than yours. Agree with them, and the list turns around and bites you.",
	},
	["sw.muse.w19.folk.019"] = {
		"The enemy's capital is mostly people buying turnips. Old women, children, a cobbler with nails in his mouth. Hate is easier from far away.",
		"Nobody here looks twice at one more hood. They're too busy: rent, bread, a sick child at home. I keep my head down and my opinions further down.",
	},
	["sw.muse.w19.folk.020"] = {
		"A few dwarvish oaths have crept into the speech of this city. Human carters use them when a wheel sticks, with no idea what they're asking for.",
		"Stormwind curses in dwarvish now and then, mostly at stuck wheels. The dwarves who overhear keep perfectly straight faces, which tells you it's a rude one.",
	},
	["sw.muse.w19.folk.021"] = {
		"watches a gnome and her grown son carry one very long plank through the district between them, arguing in perfect time with their steps.",
		"steps around two gnomes, a mother and a son nearly her height, bearing a single plank down the street and disagreeing about which end is the front.",
	},
	["sw.muse.w19.folk.022"] = {
		"Humans don't get many years, so we built a city to do our remembering: the bank keeps the coin, the stone keeps the shape, the Cathedral keeps the names.",
		"A human life is short. Stormwind is how we cheat: the stone outlasts the mason, the street outlasts the child who learned to walk on it.",
	},
	["sw.muse.w19.folk.023"] = {
		"Everybody here has a cousin at court. Nobody has a cousin who can mend a boot.",
		"Half this city claims a friend in the keep. I'd trade the lot of them for one honest cobbler.",
	},
	["sw.muse.w19.folk.024"] = {
		"What's the crowd for? Oh. A man trying to lead a goat across a bridge. Fair, I'd watch that too.",
		"Everyone's stopped to stare at something. A goat, apparently, winning an argument with its owner.",
		"Twenty people, one goat, one very red-faced man. Stormwind knows a good show when it sees one.",
	},
	["sw.muse.w19.folk.025"] = {
		"Lordaeron's people came south for shelter and got it. Whatever the Alliance is, this much of it is real: a door that opened when the north fell.",
		"When the north fell, Stormwind took in whoever reached its gate. The Alliance has its quarrels, but I've seen what it looks like on a bad day, and it looks like an open door.",
	},
	["sw.muse.w19.folk.026"] = {
		"passes through a fog that turns every passerby into a voice first and a face only at arm's length, and hears three greetings meant for someone else.",
		"is greeted twice in the fog by people who, at the last step, turn out to have mistaken {g:him|her} for a neighbor, and apologize, and vanish again.",
	},
	["sw.muse.w19.forge.001"] = {
		"A smith in the Dwarven District keeps a kettle on the lip of his forge. The hottest tea in Stormwind, he says, and the worst.",
		"One forge in the Dwarven District has a stew pot hung at its edge, and the dwarf working it stirs between hammer blows without missing either.",
		"Dwarven smiths waste no heat. There's always a kettle, a pot or a pair of wet boots somewhere along the edge of the coals.",
	},
	["sw.muse.w19.forge.002"] = {
		"watches a human apprentice work the bellows for a dwarf smith, too fast and then too slow, until the dwarf lays a hand on the handle and shows the rhythm without a word.",
		"stops beside a forge where a young human leans on the bellows and a dwarf counts the strokes for him into his beard.",
	},
	["sw.muse.w19.forge.003"] = {
		"The smiths of the Dwarven District never let a forge die, a dwarf told me. They bank the coals under ash and wake them with a puff of the bellows, the way you'd wake someone you're fond of.",
		"A dwarven forge is banked, never put out, the smiths say. Iron gone cold is dead weight; a covered fire is only asleep.",
		"Every forge in the Dwarven District sleeps under a blanket of ash and wakes at the first pump of the bellows. Putting one out for good, a smith said, is something you do for a funeral.",
	},
	["sw.muse.w19.forge.004"] = {
		"Every anvil in the Dwarven District has a name. I asked one smith what his was called. None of my business, he said, and patted it.",
		"Dwarves name their anvils. I asked to be introduced to one and got a look that could temper steel.",
	},
	["sw.muse.w19.forge.005"] = {
		"Half-closed shutters on every smithy, and not for privacy: in dim light the smiths read the color of hot iron, cherry, orange, straw, the way a clerk reads a ledger.",
		"Dwarven smiths hate a bright doorway. They need the shade to see the colors in the iron, and they'll shoo a gawker out of their light quicker than a thief.",
		"How hot is the iron? A dwarf smith won't answer with a number. He'll say a color, and look at you as if you should have seen it yourself.",
	},
	["sw.muse.w19.forge.006"] = {
		"realizes the dwarf squinting down a freshly straightened iron bar is lining it up on {g:him|her}, nods politely, and steps out of the inspection.",
		"finds {g:himself|herself} at the far end of a smith's newly trued rod, serving for a moment as the mark the dwarf sights along with one eye shut.",
	},
	["sw.muse.w19.forge.007"] = {
		"An old dwarf at a forge hammers a dent out of a helm and says he knows that dent: an orc axe makes it, and he beat out his first one in the Second War.",
		"There's a smith near the tram who can tell what dented a helm just by running his thumb over it. He learned in the Second War, he says, and wishes he hadn't.",
		"Some of the dwarven armorers here mended plate for the Alliance in the Second War. They still go quiet over a certain kind of split, and work on it very carefully.",
	},
	["sw.muse.w19.forge.008"] = {
		"Ask a dwarf smith a question and the answer comes in pieces, one word between each hammer blow.",
		"Never ask a smith anything mid-strike. You'll get your answer, but the iron gets told first.",
	},
	["sw.muse.w19.forge.009"] = {
		"lingers too close to a forge and ends up holding the far end of a hot bar while the smith works the near one, thanked at the finish with a grunt.",
		"is handed a pair of tongs by a dwarf who says only 'hold that, steady', and goes back to the hammer as if help had been ordered and delivered.",
		"drifts near an open forge and is promptly put to use: a bucket to fetch, a bar to steady, and a nod by way of wages.",
	},
	["sw.muse.w19.forge.010"] = {
		"There's always someone sitting with their back to the outside wall of a forge, where the stone stays warm. The smiths let them, and those fires never seem to drop.",
		"The warm wall behind the big forge in the Dwarven District has its regulars: an old beggar, two cats, a boy with nowhere better. Nobody owns that stone, and the smith keeps it heated anyway.",
	},
	["sw.muse.w19.forge.011"] = {
		"Do the forges in the Dwarven District ever go quiet, or do the dwarves just pass the hammer along?",
		"Clang, clang, clang. I'd count the strokes, but I'd still be counting at the next war.",
		"The Dwarven District doesn't have a quiet hour. It has a slightly less loud one.",
	},
	["sw.muse.w19.forge.012"] = {
		"When a piece comes out right, a dwarf told me, every smith in earshot gives the anvil a single knock. I've been listening for it ever since.",
		"One ring of hammer on anvil from every forge at once, then work again. Somebody finished something good, the dwarves say, and that's all the ceremony it gets.",
		"The smiths don't cheer a fine piece of work. They knock once on the anvil, all together, and go back to their own. Higher praise doesn't exist in the Dwarven District.",
	},
	["sw.muse.w19.forge.013"] = {
		"Honest work, these forges of Stormwind. Not the Great Forge, but the hammers sound like kin, and that's enough to slow my boots.",
		"Human iron, human coal, and a dwarf at every anvil worth the name. Ironforge turns up wherever the work is serious, and I'm glad of it.",
	},
	["sw.muse.w19.forge.014"] = {
		"At first light the forges of the Dwarven District wake one by one: a hammer, then two, then the whole street, like roosters that took up smithing.",
		"The first hammer of the dawn in the Dwarven District is always the same one, the smiths say, and the rest start when they hear it, out of pride or spite.",
	},
	["sw.muse.w19.forge.015"] = {
		"In a storm the dwarves at the forges don't look up from the anvil. Anything that loud, one of them told me, ought to pay rent on a forge.",
		"Thunder over the roofs, and somewhere in the Dwarven District a smith answers it with a hammer blow, perfectly timed. The dwarves laugh. The sky doesn't.",
	},
	["sw.muse.w19.haggle.001"] = {
		"Three coppers? You can say it louder, but it won't turn into two.",
		"Four silver, and you're smiling. That's how I know it's three.",
		"I'll give you two. No, don't look at me like that. The look costs extra and I'm not paying it.",
	},
	["sw.muse.w19.haggle.002"] = {
		"Haggling in Stormwind has steps, like a dance: the shocked face, the slow turn to leave, the call back, the handshake. Skip one and both sides feel cheated.",
		"A Stormwind bargain isn't struck, it's performed: outrage, retreat, a voice calling you back, then a grip across the counter. Nobody enjoys a deal that skips the middle.",
	},
	["sw.muse.w19.haggle.003"] = {
		"practices a look of weary disappointment, the one every good haggler owns, on nobody in particular.",
		"rehearses a slow, pained shake of the head, the kind that knocks a copper off any price.",
	},
	["sw.muse.w19.haggle.004"] = {
		"Every seller in Stormwind has six hungry children when the haggling starts. By the handshake it's down to two, and one of them is a nephew.",
		"Start bargaining and the stallkeeper's family grows: a sick mother, a roof that leaks, a son at the front. Agree a price and they all recover at once.",
		"Haggle long enough and you'll hear a seller's whole family history. It always ends with them losing money on you personally.",
	},
	["sw.muse.w19.haggle.005"] = {
		"Some sellers you don't haggle with: the old ones with a single basket and careful hands. A copper off their price is a copper off their supper.",
		"Bargain hard with the big shops; they can take it. The old man with three skeins of thread on a blanket gets his price, and a little more.",
	},
	["sw.muse.w19.haggle.006"] = {
		"Meet me halfway. No, not your halfway. Mine.",
		"Let's split the difference. I'll take the bigger half.",
		"Fine, halfway. Halfway to my price, from where you're standing.",
	},
	["sw.muse.w19.haggle.007"] = {
		"'It's the last one,' say the sellers of the Trade District, and in every back room there's a crate full of last ones.",
		"In Stormwind every bargain is the last of its kind. The shops must keep warehouses of lasts.",
		"'Only one left,' says the seller, and turns to a shelf of identical ones to fetch it.",
	},
	["sw.muse.w19.haggle.008"] = {
		"rubs thumb and two fingers together in the old merchant's sign, then notices and stops.",
		"catches {g:his|her} own hand making the money gesture of the market, thumb over fingertips, and lowers it with a faint grin.",
	},
	["sw.muse.w19.haggle.009"] = {
		"Watch a good haggler work and you learn something for every quarrel: never hurry, never shout, and always be ready to leave.",
		"The best bargainers in Stormwind never raise their voices. They lower them, and the seller leans in to hear, and is lost.",
	},
	["sw.muse.w19.haggle.010"] = {
		"I step out in this city for a loaf of bread and come back with a lantern, a hat and a grudge against a cheesemonger.",
		"One errand in Stormwind is never one errand. I went out for thread and came back owning a stool.",
	},
	["sw.muse.w19.haggle.011"] = {
		"Sometimes the haggling turns ugly without a raised voice: a Westfall farmer selling the harness off his last horse, and a buyer knocking him down coin by coin while both pretend it's only business.",
		"There's a kind of bargain nobody brags about. A family from the west with everything on one cart, and buyers who know exactly how little choice they have.",
	},
	["sw.muse.w19.haggle.012"] = {
		"The silk is from Darnassus, the seller swears, spun by elves under ancient trees. The hem says Goldshire, and a hurried Goldshire at that.",
		"'Dwarven steel, straight from Ironforge.' It bears a maker's mark of a little apple. I'm no smith, but I know an Elwynn joke when I see one.",
	},
	["sw.muse.w19.haggle.013"] = {
		"Listen to any two people passing in the Trade District, and within ten paces one of them says a number.",
		"Every conversation here in the Trade District ends in a figure. Even two old friends embracing at a door are asking what the other paid for the coat.",
	},
	["sw.muse.w19.haggle.014"] = {
		"Every counter in this city is built at human height. I haggle better standing on a crate. The shopkeepers have noticed, and the crates keep disappearing.",
		"Hard to drive a bargain when the seller is talking to the top of my hat. I've started carrying a stool. Prices have improved.",
	},
	["sw.muse.w19.haggle.015"] = {
		"A fair price is the one both sides grumble about all the way home.",
		"If we're both a little unhappy, it's a deal.",
	},
	["sw.muse.w19.haggle.016"] = {
		"watches two neighboring stallholders undercut each other a copper per round, louder each time, until both are selling below cost and neither will be the first to quit.",
		"pauses to follow a price war between two rival carts, the figures dropping with every shout until a passing cook buys out both of them.",
	},
	["sw.muse.w19.hours.001"] = {
		"The city wakes up by its shutters: one bangs open, then a dozen more along the street, like somebody shuffling an enormous deck of cards.",
		"First the shutters, banging back against the stone one after another. Then the first price shouted. Then Stormwind is open for business.",
	},
	["sw.muse.w19.hours.002"] = {
		"ducks under a washing line strung across a narrow lane, a row of shirts dripping onto the cobbles with their arms spread like a welcoming committee.",
		"glances up at the laundry hung between two upper windows, sheets and stockings swaying over the street like the flags of some small, very clean country.",
	},
	["sw.muse.w19.hours.003"] = {
		"The washers on the canal steps slap wet linen against the stone and pass the city's news along in the same rhythm. If you want to know who quarreled with whom, go and stand near the soap.",
		"Nobody hears the gossip sooner than the people doing Stormwind's washing. They beat it out of the shirts along with everything else.",
		"Laundry on the canal steps: arms red to the elbow, linen slapped on stone, and every scandal in Stormwind wrung out and hung up to dry.",
	},
	["sw.muse.w19.hours.004"] = {
		"The cats of this city have carved it up between them: one has the cooper's step, one the sill above the bakery, a third the lid of a water barrel. Nobody ever disputes a cat's deed.",
		"Every doorstep in Stormwind belongs to a cat. The people behind the door are only tenants, and they know it.",
		"You can map Stormwind by its cats, a carter told me: the fat one by the chandler's, the one-eared one on the smithy steps, the white one who sits on a bridge rail and judges everyone. He wasn't joking.",
	},
	["sw.muse.w19.hours.005"] = {
		"watches a cat on a sill follow a fly with its whole head, tail twitching, never quite deciding the matter is worth getting up for.",
		"is studied, at length and without approval, by a fat gray cat on a barrel, which then closes its eyes as if the question had been settled.",
	},
	["sw.muse.w19.hours.006"] = {
		"stops near a knife grinder working his wheel with one foot, a thin spray of sparks hissing off a kitchen knife while a cook waits with her arms folded.",
		"lingers by a grinder's barrow, the stone singing against a cleaver, sparks skittering away toward the boots of a passing guard.",
	},
	["sw.muse.w19.hours.007"] = {
		"A rag-and-bone man pushes his barrow through the streets calling for bones, bottles and old cloth, and the city hands him its leftovers out of windows. Nothing in Stormwind gets thrown away twice.",
		"One man in this city buys what nobody wants: rags, bones, broken crockery. He calls it out on one long, sad note, and doors open for him all along the street.",
	},
	["sw.muse.w19.hours.008"] = {
		"Hammers, wheels, a crying baby, two dogs and a man selling onions. How does anyone in this city hear themselves think?",
		"Does Stormwind ever stop talking? Even the cobbles clatter.",
		"In all that noise there's a bird singing somewhere. I'll take its word for it.",
	},
	["sw.muse.w19.hours.009"] = {
		"Somewhere in the middle of the afternoon the city slows down. The criers rest their voices, the cats find a doorstep, and even the canals seem to move more lazily.",
		"The early rush is over and the late one hasn't started. For an hour or so Stormwind dozes on its feet, like a horse in harness.",
	},
	["sw.muse.w19.hours.010"] = {
		"Every trade in this city keeps its own clock. The bakers finish when the smiths begin, the clerks shut their ledgers just as the taverns open their doors, and the guards change shifts grumbling about all of them.",
		"Stormwind never quite sleeps; it hands itself from one trade to the next: bakers to smiths, smiths to clerks, clerks to tavern keepers, and tavern keepers back to the bakers.",
		"The city works in shifts nobody ever wrote down: ovens, anvils, ledgers, taps, and round to the ovens. Someone is always on duty.",
	},
	["sw.muse.w19.hours.011"] = {
		"steps back just in time as a shutter bangs open overhead and a bucket of gray washing water lands where {g:he|she} was about to put a foot.",
		"hears a cry of 'mind below!' from an upper window and flattens against the wall a moment before a basin of suds splashes across the cobbles.",
	},
	["sw.muse.w19.hours.012"] = {
		"After the taverns empty, Stormwind belongs to its night trades: the watch, the bakers, the carters who clear the gutters, and one singer somewhere who knows only the first verse.",
		"The city at this hour is all small sounds: a watchman's cough, the slow turn of a cart wheel, a door eased shut so as not to wake a house.",
	},
	["sw.muse.w19.hours.013"] = {
		"I could cross Stormwind with my eyes shut and still know where I was by the smell: yeast, then horse, then hot iron, then old paper and something faintly scorched.",
		"Every quarter of the city has its own air. Walk long enough and your nose draws the map before your eyes do.",
		"Bread on one corner, horse and leather on the next, coal smoke, then ink and singed cloth. Stormwind is easier to smell than to read.",
	},
	["sw.muse.w19.hours.014"] = {
		"The water carriers of this city walk with the careful pride of people who have never spilled a drop in public, and glare at anyone who looks likely to jostle.",
		"A yoke, two brimming buckets and an expression that dares you to bump into them: the water carriers own whatever street they're walking down.",
	},
	["sw.muse.w19.hours.015"] = {
		"In this city, anything with a railing ends up wearing somebody's shirt.",
		"Washing on the railings, washing in the windows, washing on a handcart. Stormwind dries its laundry wherever it can reach.",
	},
	["sw.muse.w19.hours.016"] = {
		"Up with the bakers. I don't know how they do this every day and still smile at customers.",
		"This early, the only people awake are bakers, guards and fools. I'm not carrying bread or a halberd.",
	},
	["sw.muse.w19.hours.017"] = {
		"Bread, chimney smoke, lamp oil, a dog barking at a cart. The enemy's capital smells like any other city, and that is the hardest thing about standing in it.",
		"I expected something else from the heart of the Alliance. Instead: washing on lines, a baker shouting, a child dragging a stick along the railings. It would be easier if they were monsters.",
	},
	["sw.muse.w19.ink.001"] = {
		"notices the fingers of a mage beside {g:him|her} in the crowd: ink to the second knuckle, and not a callus anywhere.",
		"brushes past a mage in the crush and glimpses a hand stained blue-black to the knuckles, soft as a clerk's.",
	},
	["sw.muse.w19.ink.002"] = {
		"The ink sellers keep a blue that is nearly black and a black that is nearly violet. The mages argue over the difference as if lives hung on it. Perhaps some do.",
		"Two mages at an ink seller's, holding bottles up to the window and disagreeing about a shade I can't tell apart. The seller waits like a man who has heard it all before.",
		"There are eleven kinds of black ink for sale in the Mage Quarter. I asked what the twelfth was for, and the seller said it wasn't for sale.",
	},
	["sw.muse.w19.ink.003"] = {
		"Paper comes into the Mage Quarter by the cartload and leaves it as smoke, ash and now and then a book.",
		"Carts of blank paper roll into the quarter every week. What comes back out is mostly ash, and once in a while a slim book that cost a hundred cartloads.",
		"The rag-and-paper men of the city all end up in the Mage Quarter sooner or later. Whatever they bring, the tower buys, and burns.",
	},
	["sw.muse.w19.ink.004"] = {
		"catches a loose page skittering over the cobbles, covered in a cramped hand and careful circles, and holds it out to the apprentice running up behind it.",
		"stoops for a sheet of diagrams that has drifted against {g:his|her} boot and hands it back to its flustered owner without a glance at what it says.",
	},
	["sw.muse.w19.ink.005"] = {
		"A spilled bottle of ink has dried on the cobbles into a shape that looks a little too deliberate. The apprentices step around it, and so, I notice, do I.",
		"Ink spilled on a doorstep, dried into curls and angles. Probably nothing. Still, nobody in the street has set a foot on it all day.",
		"A blot of ink on a wall by the tower, flung there in some long-forgotten temper. Nobody has painted over it. Nobody has wanted to touch it with a brush.",
	},
	["sw.muse.w19.ink.006"] = {
		"Somewhere in this kingdom there's a goose who is very tired of mages.",
		"All those quills. Spare a thought for the geese, will you?",
		"Somewhere a goose is honking about mages, and it's right.",
	},
	["sw.muse.w19.ink.007"] = {
		"To borrow a book from a mage, they say in the quarter, you leave something of equal weight: coin, a ring, or a promise written in your own hand. The promise is the expensive one.",
		"Mages lend books the way moneylenders lend gold, the booksellers grumble: with a pledge, a date, and a look that follows you down the street.",
		"A mage will lend you a book, a scribe told me, the way a cat lends you a mouse: you will hear about it, and you will be watched until it comes back.",
	},
	["sw.muse.w19.ink.008"] = {
		"Some letters leave the Mage Quarter in an ink that fades once it's read, the couriers complain. They never know whether to hurry or dawdle.",
		"A courier told me he once delivered a letter from the tower and watched the words go pale in the reader's hands. He still hasn't decided whether that was rude.",
	},
	["sw.muse.w19.ink.009"] = {
		"listens to the scroll cases on a passing mage's belt knock together with every step, like a peddler's pans.",
		"steps aside for a scholar hung all over with leather scroll tubes, who clatters gently down the street like a walking library.",
		"hears a mage coming before seeing her: a soft wooden knocking of scroll cases, a rustle of paper, and a voice reading half aloud to nobody.",
	},
	["sw.muse.w19.ink.010"] = {
		"The clerks of the keep buy their ink in the Mage Quarter, the plain kind. They swear even the plain kind dries faster there, and none of them can say why.",
		"Ordinary ink, sold on a street of extraordinary things. The scriveners of Stormwind insist it's better than any other, and look faintly embarrassed saying so.",
	},
	["sw.muse.w19.ink.011"] = {
		"pauses at an open workshop to watch a bookbinder sew a spine, slow and exact, like someone setting a bone.",
		"stops by a binder's bench where a new book is being pressed flat under a stack of old ones, and the smell of glue and leather reaches the street.",
		"lingers over a binder's hands as they fold, crease and stitch a quire of pages without a single wasted movement, until the needle is set down.",
	},
	["sw.muse.w19.ink.012"] = {
		"Here the lines strung between windows carry pages instead of shirts: wet sheets of vellum pegged out to dry, every one of them covered in writing.",
		"Pages pegged on a line between two windows, drying, a whole chapter stirring over the street. Someone below is reading it upside down and frowning.",
	},
	["sw.muse.w19.ink.013"] = {
		"Need something written that nobody else can read? I know just the street.",
		"If you want a letter nobody can read, ask a mage to write it. If you want one somebody can, ask a clerk.",
		"A mage's handwriting is a ward all by itself. Nobody gets through it.",
	},
	["sw.muse.w19.ink.014"] = {
		"Every library in the quarter has gaps on its shelves, the binders say: books that went to war in a mage's pack and never came back. They leave the gaps. Filling them would be forgetting.",
		"A shelf with one book missing, kept empty on purpose. In the Mage Quarter, that is how they remember a reader.",
	},
	["sw.muse.w19.laborer.001"] = {
		"Before the shops unbar, the day laborers already line a wall near the gate road, caps in hand, waiting for a foreman to point. The ones he passes over stay a while anyway.",
		"First light, and the hiring corner is full: men and a few women with their tools wrapped in sacking, each trying to look strong and cheap at once.",
	},
	["sw.muse.w19.laborer.002"] = {
		"You can pick out the stone-carriers in a crowd: one shoulder higher than the other, from years of the same load on the same side.",
		"The hod carriers of this city walk lopsided even with empty hands. The stone has had them long enough to leave its shape.",
	},
	["sw.muse.w19.laborer.003"] = {
		"passes a row of laborers eating on a curb, bread in one hand and an onion in the other, chewing in silence with the concentration of people who have exactly this long.",
		"steps around a knot of workmen sharing a loaf and a jug on an upturned barrow, the rest of the city flowing around their brief island.",
		"comes upon a row of laborers sitting with their backs to a wall and their boots off, eating in a silence nobody in the street would dare to break.",
	},
	["sw.muse.w19.laborer.004"] = {
		"A gnome stands on a crate unrolling a drawing for six human laborers. They nod at every line. Then they lift the beam exactly as they always have, and the gnome sighs and corrects the drawing.",
		"On any work site in this city you'll find one gnome with a diagram and a dozen humans with a better idea. The gnome is usually right. The humans are usually finished first.",
	},
	["sw.muse.w19.laborer.005"] = {
		"Along the Canals, men in leather waders rake the bottom clean of whatever the city drops. A boot for every coin, they say, and now and then a letter that was never sent.",
		"Here by the Canals the dredgers work chest-deep in the cold water, pulling up silt and cabbage leaves and the occasional chair. Nobody on the bridges ever looks down at them.",
	},
	["sw.muse.w19.laborer.006"] = {
		"Want a hand with that end? No? Fair. You look like you've carried worse.",
		"I'd offer to help, but you've plainly been doing that since before I could walk.",
	},
	["sw.muse.w19.laborer.007"] = {
		"When pay comes late on a work site here, the laborers don't shout. They set down their tools, all at once, and sit. Every foreman in Stormwind knows what that silence remembers.",
		"No foreman in this city likes the sound of tools being laid down together. The laborers don't need to say why. The whole city knows how the last unpaid bill ended.",
	},
	["sw.muse.w19.laborer.008"] = {
		"watches a roofer go on laying slates through the rain, water pouring off his hat brim, as if the weather were somebody else's business.",
		"looks up at two workmen on a half-finished roof who keep at it in the rain, calling measurements to each other over the drumming.",
	},
	["sw.muse.w19.laborer.009"] = {
		"The water-girls who haul buckets up from the canals to the high houses carry two pails and all the latest news, and they spill neither.",
		"Every bucket of water in the fine houses was carried up by a woman with a yoke on her shoulders and a story for every door. The nobles get the water. The stories go elsewhere.",
	},
	["sw.muse.w19.laborer.010"] = {
		"On one scaffold a dwarf and a human have argued about every joint since the first plank, and the building is coming along beautifully.",
		"Two carpenters up on the scaffold, a dwarf and a human, bicker in two accents about every peg. The frame beneath them stands as straight as a plumb line.",
		"The dwarf says the beam goes here, the human says there, and they settle it by putting it where neither said. Best work on the street, apparently.",
	},
	["sw.muse.w19.laborer.011"] = {
		"The men who empty the city's cesspits work while everyone else sleeps, and are gone before anyone wakes. Stormwind smells as well as it does because of people it never meets.",
		"Somebody carries away what a whole city leaves behind, every day, unseen. Nobody in Stormwind knows their names. Everybody would know if they stopped.",
	},
	["sw.muse.w19.laborer.012"] = {
		"nods to a laborer who has stopped to press both fists into the small of his back, and gets back the tired grin of someone asked nothing who answers anyway.",
		"passes a workman leaning on his shovel with his eyes shut, upright and perfectly asleep, while the foreman's back is turned.",
	},
	["sw.muse.w19.laborer.013"] = {
		"Every stone in this city went up a ladder on somebody's back. And I complain about stairs.",
		"Look at that one, carrying a hod up three ladders. And I thought my day was hard.",
		"Somebody carried every one of these stones. I've hauled a pack up one hill and I want a medal.",
	},
	["sw.muse.w19.laborer.014"] = {
		"On the work sites you can pick out the men from Westfall: before they lift anything they glance up at the sky, out of a farmer's habit. Nothing here depends on the weather, and they still check.",
		"Former farmers, most of the new hands on the scaffolds. They still squint at the clouds every hour, though the only harvest left to them is a day's wage.",
	},
	["sw.muse.w19.laborer.015"] = {
		"Those workmen up on the scaffold whistle the same four notes, over and over. It's in my head for good now.",
		"Somebody on that scaffold has whistled one tune for an hour. If I hear it again I'm climbing up to learn the rest of it.",
	},
	["sw.muse.w19.lamb.001"] = {
		"Somebody named a tavern the Slaughtered Lamb and opened it in the Mage Quarter. Either a joke or a warning, and the regulars won't say which.",
		"The Slaughtered Lamb: a cheerful name for a tavern, if you don't think about it. Most of the regulars seem to have stopped thinking about it on purpose.",
		"A tavern called the Slaughtered Lamb, not far from the Cathedral. Somebody in this city has a dark sense of humor, or a very honest one.",
	},
	["sw.muse.w19.lamb.002"] = {
		"People go down the Lamb's back stairs with their hoods up and come back with their hoods pulled even lower.",
		"Hoods go down the cellar stairs of the Slaughtered Lamb, and later the same hoods come up, drawn tighter. Nobody at the bar ever turns to look.",
		"Whoever goes down to the Lamb's cellar comes back up quieter. Not changed, exactly. Just quieter, the way people are after a long letter.",
	},
	["sw.muse.w19.lamb.003"] = {
		"Decent ale at the Lamb. Warm floor. I'd rather not know why.",
		"The Lamb's floorboards are always warm, and the kitchen is on the other side. Pass the jug.",
	},
	["sw.muse.w19.lamb.004"] = {
		"A warlock strolls by with an imp trotting at heel, and the street parts for it without a word, the way it parts for a manure cart.",
		"Nobody screams at an imp anymore. They lift their hems and step aside, as they would for a muddy dog belonging to someone important.",
		"An imp waits outside a shop, picking at the doorframe and muttering. The shopkeeper sweeps around its feet and pointedly says nothing.",
	},
	["sw.muse.w19.lamb.005"] = {
		"glances at the low cellar window of the Slaughtered Lamb, where a glow the color of a bruise comes and goes behind the grime.",
		"slows beside the Slaughtered Lamb, where something down at the level of the cobbles pulses green behind a cellar grate, then walks on.",
		"stops short as a cold draft rises from the cellar steps of the Slaughtered Lamb, smelling of candle smoke and hot pennies.",
	},
	["sw.muse.w19.lamb.006"] = {
		"watches a warlock haggle over a bunch of turnips, lose, and pay up with perfect good grace.",
		"notices that the warlock ahead in the bread queue says please and thank you, counts out the exact coins, and wishes the baker a good day.",
		"holds back to let a hooded warlock help an old woman lift her basket over a puddle; the warlock nods politely and goes on toward the Mage Quarter without a word.",
	},
	["sw.muse.w19.lamb.007"] = {
		"Every warlock started out wanting something badly enough to go down those stairs. Sit long enough upstairs at the Lamb and you start to wonder what you'd want that much.",
		"Nobody goes down to the Lamb's cellar on a whim. Behind every hood there's a want, a grief or a grudge, and the ale upstairs is poured for all three.",
	},
	["sw.muse.w19.lamb.008"] = {
		"Stormwind would rather know where its warlocks study than wonder. A cellar under a tavern is easy to watch. A cave in the hills is not.",
		"Close the Lamb's cellar, a guard once told me, and they'd only dig a worse one somewhere out of sight. Better the cellar you can find.",
		"The Watch knows every face that goes down to the Lamb's cellar, a guard told me, and would rather know them there than meet them in a ditch outside the walls.",
	},
	["sw.muse.w19.lamb.009"] = {
		"Upstairs at the Lamb everyone talks very loudly about the weather. Nobody wants to hear what's said underneath.",
		"Drinks at the Slaughtered Lamb come with a free rule: what's under the floor stays under the floor.",
		"At the Lamb you don't ask what's in the cellar. You ask what's in the stew, and that's brave enough.",
	},
	["sw.muse.w19.lamb.010"] = {
		"lets a pair of perfectly respectable merchants pass as they come out of the Slaughtered Lamb, blink at the street, and part ways without a goodbye.",
		"sees a scholar in good boots step out of the Slaughtered Lamb, glance both ways, and straighten a collar that needed no straightening.",
	},
	["sw.muse.w19.lamb.011"] = {
		"The orcs came with warlocks at their head, the veterans say. Now Stormwind has warlocks of its own, a few streets from the keep, and the veterans go quiet whenever the Lamb comes up.",
		"A city once burned by demon magic now lets that magic be taught under a tavern. Some call it folly, some call it knowing your enemy. The old soldiers simply change the subject.",
	},
	["sw.muse.w19.lamb.012"] = {
		"Upstairs at the Lamb the tables are scarred with rings and initials, like any tavern's. Only the quiet is different: everyone here listens a little toward the floor.",
		"A tavern like any other, the Lamb, until you notice how the drinkers sit: backs to the wall, feet flat, half an ear on the boards beneath them.",
	},
	["sw.muse.w19.lamb.013"] = {
		"Whoever cleans the Slaughtered Lamb deserves a medal and a very long holiday.",
		"I'd like to meet whoever sweeps the Lamb. I'd like even more to know which floor they won't do.",
	},
	["sw.muse.w19.lamb.014"] = {
		"The Lamb's barkeep never asks what's downstairs. He asks whether you're eating, and he asks it of everyone, hood or no hood.",
		"Behind the bar of the Lamb they pour, wipe, and, when asked, point to the cellar door exactly as they'd point to the privy.",
		"Every tavern keeper in Stormwind has seen everything. The one at the Lamb has seen it come up the stairs and order soup.",
	},
	["sw.muse.w19.lamp.001"] = {
		"watches a lamplighter work along the street, raising a long pole with a small flame at its tip to each lamp in turn and never once missing on the first try.",
		"pauses as a lamplighter goes by with pole and ladder, and the street brightens behind him in small, patient steps.",
		"follows the lamplighter's progress by the lamps alone, each one blooming yellow a little farther down the street, the man himself only a shadow between them.",
	},
	["sw.muse.w19.lamp.002"] = {
		"Every street in this city seems to have one lamp that never lights. The locals give directions by it: left at the dead lamp, then down the steps.",
		"A broken lamp on a corner becomes a landmark faster than any statue. 'Past the dark one, by the cooper's' will get you anywhere in Stormwind.",
		"Ask the way in Stormwind and you'll be steered by the lamps that don't work: 'turn at the broken one, the one with the cracked glass, not the other broken one.'",
	},
	["sw.muse.w19.lamp.003"] = {
		"I can count the windows still lit along the street. Every so often one goes dark, and the city gets a room smaller.",
		"The lit windows go out one after another, never in order: somebody's last candle, somebody's last page. Stormwind puts itself to bed without a plan.",
	},
	["sw.muse.w19.lamp.004"] = {
		"listens as, somewhere close, a lantern is set down on stone, a door is barred, and a voice says goodnight to someone who doesn't answer.",
		"hears a shutter close nearby, then the small chink of a lamp's glass being lifted and the hush of a flame put out.",
	},
	["sw.muse.w19.lamp.005"] = {
		"A few windows in this city keep a candle lit at all hours. Ask a neighbor and the answer comes low: someone from that house went to the war and hasn't come back yet. The 'yet' does a lot of work.",
		"Candles in windows, burning when no one needs the light. In Stormwind, a woman on a doorstep told me, that means a house still waiting for someone. Nobody ever says for how long.",
		"Somewhere nearby a candle burns for someone who went to the war. The neighbors keep an eye on it, and if it ever gutters, one of them knocks.",
	},
	["sw.muse.w19.lamp.006"] = {
		"I passed a chandler's back room where rows of wicks hung from a rack, dipped and dipped into a vat of tallow until they fattened into candles. Every light in this city starts as a string and a great deal of waiting.",
		"Candles don't come from nowhere. Somewhere in Stormwind a chandler is dipping wicks into hot tallow for the hundredth time, and somewhere else a guard is grumbling about the price.",
	},
	["sw.muse.w19.lamp.007"] = {
		"The glass on the street lamps here is always clean, and I have never once seen anyone cleaning it. Stormwind has servants nobody sees, and they are very good.",
		"Somebody polishes the soot off every lamp in Stormwind, at some hour when nobody is looking. I'd like to meet them. I suspect I never will.",
		"Clean lamp glass, street after street. Either an army of polishers works while the city sleeps, or the lamps have more self-respect than most nobles.",
	},
	["sw.muse.w19.lamp.008"] = {
		"watches the candle on the nearest table lean every time the door opens, as though it too wanted to see who had come in.",
		"notices the candle flames along the wall all bow together when the door swings, then straighten one by one, like a row of clerks.",
	},
	["sw.muse.w19.lamp.009"] = {
		"In this fog a lamp doesn't light the street. It lights a small round room of fog around itself, and you walk from one room to the next with nothing in between.",
		"Every lamp in the fog is its own little island. Between them you go by memory and by the sound of your own boots.",
	},
	["sw.muse.w19.lamp.010"] = {
		"A flask of lamp oil costs nearly what a mug of ale does here. I know which of the two I'd rather sit in the dark with.",
		"Lamp oil or ale, same price. Easy choice. I'll find the door by feel.",
		"I priced lamp oil, then I priced ale. I'll be sitting in the dark, but I won't mind.",
	},
	["sw.muse.w19.lamp.011"] = {
		"A lamplighter told me, with real bitterness, that some lamps in the Mage Quarter light themselves. He considers it a kind of theft.",
		"The lamplighters of Stormwind have one enemy, and it isn't the dark. It's the mages, whose lamps come on without anybody's pole, and who have never once tipped a lamplighter.",
	},
	["sw.muse.w19.lamp.012"] = {
		"There's a short stretch at dusk when the daylight is gone and the lamps aren't lit yet, and the whole city turns the soft blue-gray of a pigeon's back.",
		"Between the last of the day and the first lamp, Stormwind has a few minutes when nothing has an edge. Even the guards look gentle.",
		"Dusk, and for a little while the stone forgets to be white. Everything goes the same mild gray-blue, roofs and walls and faces alike.",
	},
	["sw.muse.w19.lamp.013"] = {
		"I saw a gnome fix a sputtering street lamp with a hairpin and one sharp tap, then walk off before the guard nearby could decide whether to thank her or be offended.",
		"A spluttering lamp, a passing gnome, two twists of a hairpin, and the flame stood up straight. The guard who'd watched it all stared at the lamp for a long time afterward, as if it had betrayed him.",
	},
	["sw.muse.w19.lamp.014"] = {
		"stands aside to watch a lamplighter in a dripping oilskin climb back up his ladder to a lamp the rain has put out, muttering the same words he used on the last one.",
		"sees a lamplighter shelter a flame inside his coat all the way up the ladder, coax a drowned lamp back to life, and move on without a glance at the sky.",
	},
	["sw.muse.w19.lamp.015"] = {
		"The lamp on this table has a chipped glass and a crooked wick, and it still makes the best circle of light in the room. I've settled into it like a cat on a warm step.",
		"There's one good lamp in here, and I've claimed the table under it. Whatever comes next can wait until it starts to smoke.",
	},
	["sw.muse.w19.lamp.016"] = {
		"Half this city is asleep and the other half is in a tavern. I know which half I'm in.",
		"At this hour Stormwind divides neatly into the snoring and the singing.",
		"Everyone sensible is in bed. Everyone else is having a much better time.",
	},
	["sw.muse.w19.lane.001"] = {
		"The lanes of Old Town are just wide enough for two people, provided one of them is willing to become a wall for a moment.",
		"Two people meet in an Old Town lane and one of them turns sideways. Which one is a whole question of rank, debt and temper.",
		"Old Town's narrowest lanes have rules nobody wrote: whoever carries more goes first, whoever owes money flattens against the stone.",
	},
	["sw.muse.w19.lane.002"] = {
		"turns sideways to let a woman with a basket of turnips squeeze past, in a lane barely wider than the basket.",
		"presses {g:his|her} back to the wall of a narrow lane while a boy rolls a barrel by, apologizing to the barrel.",
	},
	["sw.muse.w19.lane.003"] = {
		"In the narrow lanes your own footsteps come back off the walls a moment late, as if somebody were keeping pace and politely not catching up.",
		"Old Town's lanes give every footstep back twice. It takes a while to stop turning round for the second one.",
		"Walk an Old Town lane alone and the walls walk it with you, a step behind. Only an echo. Usually I believe that.",
	},
	["sw.muse.w19.lane.004"] = {
		"Everyone in Old Town knows a shortcut. No two of them agree, and at least one ends in somebody's kitchen.",
		"Ask for a shortcut in this city and you'll get three, all different, all ending at a wall.",
		"There's a quick way through Old Town. There are also twenty slow ways that everybody swears are quick.",
	},
	["sw.muse.w19.lane.005"] = {
		"A door in one of the back lanes has been painted so many times the chips show five colors at once, each one somebody's idea of starting over.",
		"Green over red over blue: an old door in a side lane wears every color its tenants ever chose. Nobody ever scraped it back to the wood.",
	},
	["sw.muse.w19.lane.006"] = {
		"Someone has chalked arrows on the corners of the lanes, pointing the way out. Someone else has chalked them pointing back. Old Town humor, I think. Or a war.",
		"Two hands have been at the chalk on the corners of Old Town: one drawing arrows toward the canal, one turning every arrow round. I hope they never meet in a narrow lane.",
		"Chalk arrows on the lane corners point every which way, corrected and corrected again. The only certain thing is that somebody in Old Town is very stubborn.",
	},
	["sw.muse.w19.lane.007"] = {
		"ducks under a shop sign hung so low in the lane that its iron bracket has been polished bright by passing foreheads.",
		"stoops beneath a sign jutting into the lane at exactly the height of a tall person's eyes, its lower edge rubbed smooth.",
	},
	["sw.muse.w19.lane.008"] = {
		"No lane in Old Town runs straight for more than twenty paces. The old guardsmen say it was built that way, so that nothing could ever charge down one again.",
		"The lanes bend and bend once more, and you never see far ahead. A crooked street is hard to charge down, the guards like to say, and hard to flee along.",
	},
	["sw.muse.w19.lane.009"] = {
		"One doorstep in the lanes is crowded with cracked pots, each growing a single stubborn herb in the shade. Old Town gardens wherever it can.",
		"A row of chipped crocks on a windowsill over a lane, and in every one a sprig of something green that refuses to give up. The stone hasn't won yet.",
	},
	["sw.muse.w19.lane.010"] = {
		"Three locks on one door in a back lane, and the window beside it propped open with a shoe. Old Town has its own ideas about security.",
		"One door in the lanes behind the tavern carries four locks and a bar. Whatever is inside is either very precious or very angry.",
	},
	["sw.muse.w19.lane.011"] = {
		"Keep to the middle of the lane here. Things drop from windows in Old Town, and not every one by accident.",
		"Watch above as well as ahead in these lanes. Old Town empties its basins without much warning.",
	},
	["sw.muse.w19.lane.012"] = {
		"The lanes are so narrow that neighbors talk from window to window across them. Walk through and you pass under a whole conversation about the price of onions.",
		"Two windows face each other across a lane, an old man leaning out of each, settling some argument older than either of them over the heads of everyone below.",
	},
	["sw.muse.w19.lane.013"] = {
		"Old Town's lanes keep the dark longer than the wide streets. At this hour the only light is what leaks under the doors, a bright line on the cobbles every few paces.",
		"By night a back lane is a row of thin gold threads, the light from under each door, and the dark between them.",
	},
	["sw.muse.w19.lane.014"] = {
		"steps over the runnel of rainwater racing down the middle of the lane, carrying a cork, a feather and somebody's lost button toward the canal.",
		"keeps to the edge of a steep lane while the rain turns its gutter into a small, busy river.",
	},
	["sw.muse.w19.lane.015"] = {
		"The cobbles of the lanes are patched with whatever stone was to hand: a gray one, a pink one, half of a broken step. The street is a quilt somebody keeps mending.",
		"Here and there a lane's paving is mended with odd stones, none of them matching, each laid by someone who didn't wait for the city to send a mason.",
	},
	["sw.muse.w19.lane.016"] = {
		"Dead end, locked door, somebody laughing behind it. Old Town's favorite joke.",
		"Every lane in Old Town ends at a locked door. I'm starting to take it personally.",
		"If this lane goes anywhere, it's keeping it a secret.",
	},
	["sw.muse.w19.lane.017"] = {
		"Left at the onions, right at the shouting, straight past the man who isn't watching you. Old Town directions.",
		"Directions in this quarter come in smells and noises, never in street names.",
	},
	["sw.muse.w19.lane.018"] = {
		"Fog fills the lanes of Old Town the way water fills a jug. Voices come round the corners before the people do, and sometimes instead of them.",
		"In this fog a lane is ten paces long in every direction. Someone coughs close by and is never seen at all.",
	},
	["sw.muse.w19.mason.001"] = {
		"An old mason in a tavern pointed through the window at a wall and read it to me like a ledger: careful courses at the bottom, then a hurried stretch with wedges in the joints. 'That's when the money stopped,' he said, and went back to his cup.",
		"Masons read a wall's history in its joints, one told me: tight and even while the crews were fed, then thicker mortar and shims, then a course laid by men who'd stopped caring. He didn't say which wall. He didn't have to.",
	},
	["sw.muse.w19.mason.002"] = {
		"sees an old man with a mason's knuckles pass a doorway and rap its stone jamb twice, lightly, the way one greets an acquaintance in a crowd.",
		"catches a stooped old laborer tapping the corner of a building as he goes by, two quick knocks with one knuckle, as though checking that it is still sound.",
	},
	["sw.muse.w19.mason.003"] = {
		"Over one doorway a carved lion stops at the shoulders; the rest is still rough block, chisel marks and all. The neighbors say the carver walked out with the guild, and nobody since has dared to finish another man's lion.",
		"There's a frieze on one house that runs smooth for half its length and then turns to raw stone, mid-leaf. Its carver left with the rest of the masons, people say. The owner kept it as it is, out of spite or out of shame.",
		"Look up along the cornices and you find them: a garland that stops, a crest only half cut. The masons left their unfinished work up there like a sentence nobody wants to complete.",
	},
	["sw.muse.w19.mason.004"] = {
		"Ask a mason what he thinks of the cathedral. You'll hear a great deal about its gutters.",
		"Show a mason the finest building in Stormwind and he'll find the one joint he'd have done differently.",
		"Never take a walk with a mason. Every hundred paces he stops to frown at a lintel.",
	},
	["sw.muse.w19.mason.005"] = {
		"The guild had apprentices when the work stopped, boys halfway through learning the trade. Some went west with their masters. The ones who stayed haul crates in the Trade District now, with hands that know half of something.",
		"Somewhere in this city are men who were mason's apprentices when the guild walked out. They never finished learning. You see them hauling sacks, and now and then running a thumb along a joint as they pass.",
	},
	["sw.muse.w19.mason.006"] = {
		"Masons trust a plumb line and the weight of stone, an old one told me. The nobles, he said, had neither.",
		"'Stone never lies about where it wants to fall,' an old mason told me. 'Can't say the same for a signed contract.'",
	},
	["sw.muse.w19.mason.007"] = {
		"glances at a mason's mallet hanging on a nail behind the bar, its handle worn pale, and catches the barkeep telling a stranger that its owner will be back for it.",
		"spots a dusty mallet over the shelves of bottles, plainly a mason's, and hears a regular explain that the nail stays its owner's until he comes back from the west.",
	},
	["sw.muse.w19.mason.008"] = {
		"The boatmen claim the masons built these canal walls leaning ever so slightly outward, so the city could never quite close its fist on the water. Joke or wisdom, the masons who'd know aren't saying.",
		"Run an eye along the canal wall and it isn't quite plumb, the boatmen say, and on purpose: the masons wanted the water to feel welcome. They tell it with a straight face. The wall agrees with them.",
	},
	["sw.muse.w19.mason.009"] = {
		"You can tell an old mason by the knuckles and the cough. Stone dust never quite leaves.",
		"Knuckles like walnuts and a dry cough. Thirty years of stone dust, that old fellow. He's earned the bench.",
		"Watch that old man's thumb. It keeps feeling for a chisel edge that isn't there.",
	},
	["sw.muse.w19.mason.010"] = {
		"watches a young mason fit a replacement block into a wall while an old man on a bench twenty paces off corrects him without once getting up, and is right every time.",
		"pauses by a repair crew whose youngest is setting a stone, while a retired mason across the street calls out 'Left! Your other left!' until the block sits true.",
		"stops to watch an old man on a stool supervise a wall repair with nothing but his chin, a jut to the left, a jut down, until the new stone settles where he wants it.",
	},
	["sw.muse.w19.mason.011"] = {
		"The human masons cut a fair joint, I'll give them that. A dwarf would've cut it the same, and then sat on the last stone until the purse came out.",
		"Decent work on these walls. In Ironforge, mind, a mason doesn't hand over the keys to anything until the coin's been counted twice. Humans learn slowly, but they do learn.",
	},
	["sw.muse.w19.mason.012"] = {
		"A mason once explained to me that every block remembers how it lay in the quarry, and a good mason sets it the same way up. Turn it on its side and it weathers in a generation. I look at walls differently now, wondering which were laid by tired men.",
		"Stone has a grain, an old mason said, and set wrong it flakes away in thirty winters. Here and there in Stormwind a wall has already started peeling. He knew which crews had laid those, and named none of them.",
	},
	["sw.muse.w19.mason.013"] = {
		"One old baker says he fed the masons' crews on credit all through the rebuilding. The day they walked out, he wiped their slate clean himself. Somebody in Stormwind had to settle with them, he says.",
		"The masons ran a tab at a bakery while they built, the baker's old customers say, and the baker forgave it the day the guild left town. It's told as a small thing. It isn't.",
		"Of everyone the masons left behind, a baker is the only one I've heard speak of them without a grudge or a sneer. He lost the most bread to them, too.",
	},
	["sw.muse.w19.mason.014"] = {
		"finds a block near the base of a wall cut a hair too short, the gap packed with a wedge of slate: somebody's hurry, set in stone for good.",
		"spots a course of stone where one block sits proud of its neighbors by a finger's width, the kind of slip a careful crew would never have let stand.",
	},
	["sw.muse.w19.mason.015"] = {
		"Men in red masks out west laid some of the stone I'm standing on. I'll fight them if I have to. I'd still like the nobles to explain to me first how it came to this.",
		"The Defias are the Alliance's trouble now, and so mine. Still, every mask out there has a mason's hands under it, and somebody in this city put them there.",
	},
	["sw.muse.w19.mason.016"] = {
		"Half this city's sayings come off a building site: an honest man is 'square', a liar is 'out of plumb'. The masons left. The words stayed.",
		"People here call a fair dealer 'level' without a thought for where it comes from. A mason could tell them. Not many left to ask.",
	},
	["sw.muse.w19.nave.001"] = {
		"Somebody dropped a hymnal at the far end of the cathedral's nave. I saw it hit the floor, and only then heard it, like news arriving late.",
		"The nave is long enough that sound arrives late. A book falls by the altar, and a moment later the slap of it reaches the door.",
		"In the cathedral even a dropped book takes its time. You see it land, then the nave decides when you hear it.",
	},
	["sw.muse.w19.nave.002"] = {
		"The kneelers in the cathedral are worn into two shallow dips apiece. Years of knees, all finding the same place.",
		"Somebody should count the knees that wore those hollows into the cathedral's kneeling boards. Thousands, and every one of them asking for something.",
		"Look closely at the cathedral's kneeling boards: each has two smooth hollows, set a little too far apart for any one person. The wood has averaged everyone.",
	},
	["sw.muse.w19.nave.003"] = {
		"pauses near an acolyte on hands and knees, scraping old candle wax off the floor of the nave with a little knife and a great deal of patience.",
		"steps around a sacristan who is prising drips of wax from the flagstones, one pale coin of it after another.",
	},
	["sw.muse.w19.nave.004"] = {
		"Everyone whispers in the cathedral. Except dwarves. A dwarf's whisper reaches the back pews.",
		"Two gnomes whispering in the cathedral sound exactly like a kettle coming to the boil.",
		"Inside the cathedral, a dwarf at a whisper is a human at a polite shout.",
	},
	["sw.muse.w19.nave.005"] = {
		"I've never met anyone who has seen the great doors of the cathedral closed. An acolyte told me they oil the hinges every year regardless. Just in case.",
		"Nobody remembers the cathedral's doors shut, they've stood open so long. Still, someone oils the hinges, an acolyte swears, so they'll swing on the day they must.",
		"An acolyte's job, he told me: oiling hinges on doors that never close. He said it like a vow, and maybe it is one.",
	},
	["sw.muse.w19.nave.006"] = {
		"High in the cathedral's colored windows there's one pane of plain glass, a repair nobody paid to color. It's the one I always end up looking at.",
		"Among all that colored glass in the cathedral, one pane is clear, patched after some old crack. Through it the city looks exactly like itself.",
		"One window of the cathedral was mended with clear glass and never painted. The priests call it a temporary repair. It has been temporary longer than the regent has been regent.",
	},
	["sw.muse.w19.nave.007"] = {
		"Those cathedral benches are built to keep you awake. Hard oak, straight backs. The Light expects attention.",
		"Whoever carved the pews in that cathedral wanted prayers short and nobody nodding off.",
		"Hard oak and a straight back. That cathedral bench has heard more complaints from my spine than prayers from my mouth.",
	},
	["sw.muse.w19.nave.008"] = {
		"settles at the end of a back pew, where the murmur of the nave closes over the noise of the street like water over a stone.",
		"sits a while in the last row of benches, hands loose in {g:his|her} lap, while somewhere far ahead a priest turns a page.",
	},
	["sw.muse.w19.nave.009"] = {
		"A path is worn into the cathedral floor from the doors to the altar, a shade paler than the rest. Nobody laid it. Feet did.",
		"Down the middle of the nave the flagstones are a little brighter, polished by everyone who ever walked straight up to ask for something.",
		"Feet have drawn a line down the cathedral floor, door to altar. The masons built the room; the faithful drew the map.",
	},
	["sw.muse.w19.nave.010"] = {
		"The candles up in the cathedral's high sconces are lit with a brass pole as long as a boat. The acolyte who holds it has the steadiest arms in Stormwind and the sorest neck.",
		"Somebody has to light the high candles in the cathedral. There's a pole for it, taller than three men, and an acolyte who has clearly lost every argument about whose turn it is.",
	},
	["sw.muse.w19.nave.011"] = {
		"Wax, old stone and damp wool. That's what the Light smells like, if you ask the cathedral.",
		"Whenever I leave the cathedral I carry its smell out with me: candle wax and cool stone. It lasts about two streets.",
	},
	["sw.muse.w19.nave.012"] = {
		"When I sit in the cathedral I don't ask the Light for much. Mostly I let it see me as I am, dust and all, and that's enough.",
		"The priests say the Light listens everywhere. Under that vaulted roof I find it easier to believe them, and I'm not ashamed of it.",
		"Under that roof I don't need to understand the Light to be welcomed by it. I sit, and something larger than the city sits with me.",
	},
	["sw.muse.w19.nave.013"] = {
		"Inside the cathedral nobody calls a price. The candles by the door cost whatever you have, and the acolyte doesn't look to see what that was.",
		"The only stall in the cathedral is a tray of candles by the door, and its keeper looks the other way while you pay. Stormwind has no other shop like it.",
	},
	["sw.muse.w19.nave.014"] = {
		"turns at the sound of a paladin crossing the nave in full plate, every step rung back twice by the vaulting overhead.",
		"listens to a pair of armored boots cross the cathedral floor, the echo running ahead of them toward the altar.",
	},
	["sw.muse.w19.nave.015"] = {
		"From the street the cathedral looks big. From inside it looks bigger, which shouldn't be possible. An acolyte told me everyone says so, and the masons only laughed.",
		"Somehow the cathedral is larger inside than out. It isn't, of course. But step through the doors and your eyes refuse to believe the arithmetic.",
		"The cathedral cheats on its size. From the steps it's a big building; from the middle of the nave it's a small sky made of stone.",
	},
	["sw.muse.w19.nave.016"] = {
		"Helmets off in the cathedral. Not for the Light; for everyone else. One dropped helm in there sounds like a cart falling down a stair.",
		"Take your helm off before you go in there. Drop it on that floor and the whole nave will tell you about it for a week.",
		"Helm off at the cathedral door. It's not piety, it's acoustics.",
	},
	["sw.muse.w19.noble.001"] = {
		"A noble's manservant walks two steps behind and carries everything: the parcels, the cloak, and his master's opinions, which he's paid to hold without spilling.",
		"Behind every lord in the street, a servant with full arms and an empty face. The face is the harder part of the job.",
		"The servants of the great houses keep their own court down in the kitchens, the gossip goes, and it's better informed than the one upstairs.",
	},
	["sw.muse.w19.noble.002"] = {
		"steps aside for a noblewoman whose hem never touches the street; a maid walks behind her, holding it clear of the cobbles with both hands.",
		"gives way to a lady in heavy brocade and the girl behind her, who carries the train of the gown over every gutter like a priest carrying a relic.",
	},
	["sw.muse.w19.noble.003"] = {
		"The House of Nobles can spend a season on the wording of a single law. The guards on the bridge enforce it in three words.",
		"Laws come out of the House of Nobles long, ornate and late, and reach the street as a guard saying 'not there, friend'.",
	},
	["sw.muse.w19.noble.004"] = {
		"Some noble houses lost every heir in the wars and kept the title anyway. A name with no one under it, polished every week by servants who remember the faces.",
		"There are fine houses in this city where the crest over the door has outlived everyone with a right to it. The servants still dust it.",
	},
	["sw.muse.w19.noble.005"] = {
		"A noble just thanked a guard. The guard looked so startled I thought he'd salute the wrong way round.",
		"Did that lord just say 'please' to a porter? Somebody mark the date.",
	},
	["sw.muse.w19.noble.006"] = {
		"I've heard three people describe Lady Prestor and get three different women. Only the smile was the same each time.",
		"Ask after Lady Prestor and you'll hear she's tall, or slight, or striking, or plain. Nobody forgets her. Nobody seems quite able to remember her either.",
	},
	["sw.muse.w19.noble.007"] = {
		"Every time Lady Prestor's name comes up in a tavern, somebody changes the subject. Nobody can ever say why.",
		"Say 'Prestor' in a crowded room and watch it get a little less crowded.",
	},
	["sw.muse.w19.noble.008"] = {
		"notices two well-dressed men lower their voices when a third mentions the regent's adviser, and walk on with their talk left unfinished.",
		"passes a knot of courtiers just as one of them says 'Lady Prestor', and hears the rest of the sentence swallowed whole.",
	},
	["sw.muse.w19.noble.009"] = {
		"One of those rings on a noble's hand would feed a street for a season. He wears four.",
		"There's more gold on one courtier's fingers than in a whole Westfall village, and none of it ever gets dirty.",
	},
	["sw.muse.w19.noble.010"] = {
		"glances at a shop window just as a young lord rehearses a bow in its dark glass, then a second, deeper one, before hurrying off toward the keep.",
		"catches a well-dressed youth practicing a courtly bow against his own reflection in a window, frowning at the result and trying it lower.",
	},
	["sw.muse.w19.noble.011"] = {
		"The nobles' gardens are behind high walls. You only know they're there because the roses lean over the top to see who's passing.",
		"Behind those tall garden walls are fountains no commoner has ever seen. The ivy gets a look over; a passerby gets only the smell of cut grass.",
	},
	["sw.muse.w19.noble.012"] = {
		"Old names, new stone. Half the noble houses in this city are younger than the grudges living in them.",
		"The houses were rebuilt; the family feuds came back from the north intact. Stone's easier to replace than a grudge.",
		"Every house on the nobles' side of town went up after the burning, and every family in them talks as if it never left.",
	},
	["sw.muse.w19.noble.013"] = {
		"The nobles of Stormwind count their ancestors the way merchants count stock, and both keep a few back they'd rather not show.",
		"Every noble family has a gallery of portraits and at least one face turned to the wall. Ask a servant which. Never ask the family.",
	},
	["sw.muse.w19.noble.014"] = {
		"Every noble at court has a firm opinion about the war, and every one of them holds it from a very comfortable distance.",
		"The fiercest talk of war I've heard in this city came from a man in silk slippers who had never been past Goldshire.",
	},
	["sw.muse.w19.noble.015"] = {
		"watches a noble's son in a velvet cap stare longingly at street children playing by a gutter, until a governess steers him on by the shoulder.",
		"sees a small boy in fine clothes hang back from his tutor to watch a game of knucklebones on the cobbles, as if it were a foreign country.",
	},
	["sw.muse.w19.noble.016"] = {
		"Here every noble finds a reason to stand a little closer to the throne than the noble beside them. By the end of an audience the whole crowd has crept forward a pace.",
		"Watch the nobles at an audience: nobody moves, and yet somehow the front of the crowd is nearer the throne than it was.",
	},
	["sw.muse.w19.noble.017"] = {
		"You can smell a courtier before you see one. Rosewater, mostly, and a little fear of the regent.",
		"Lavender, rosewater and money. That'll be a noble coming round the corner.",
	},
	["sw.muse.w19.oven.001"] = {
		"A baker told me every bakehouse in the city cuts its own mark into the dough before it goes in: a cross, a ladder, three short slashes. Bread in Stormwind comes signed.",
		"Three short slashes on one loaf, a cross on the next, a little ladder on the third. The bakers sign their work with a knife, they say, so nobody can pass off a rival's crust as their own.",
	},
	["sw.muse.w19.oven.002"] = {
		"makes room for a baker's boy with a board of loaves balanced on one shoulder, who calls 'mind your backs' to nobody in particular and to everybody.",
		"steps aside for a lad carrying a plank of fresh loaves at head height, steering it through the crowd with the calm of a canal boatman.",
		"gives way to a baker's boy with a tray of rolls on his head, one hand up to steady it, and gets a crumb-dusted nod of thanks.",
	},
	["sw.muse.w19.oven.003"] = {
		"Not every house in Stormwind has an oven worth the name. Folk carry their dough to the baker's under a cloth, pay a copper for a place by his fire, and come back later for it, hot.",
		"Half the loaves in a baker's oven aren't his. The neighbors bring their dough in covered bowls, pay a coin for the heat, and collect their bread at the next bell.",
	},
	["sw.muse.w19.oven.004"] = {
		"The pies in this city are hot enough to burn your tongue and cheap enough that you buy a second one to finish the job.",
		"Burned my tongue on a pie, so naturally I bought another. That's how Stormwind gets you.",
		"Stormwind pie rule: wait for it to cool, give up waiting, burn yourself anyway.",
	},
	["sw.muse.w19.oven.005"] = {
		"The price of a loaf is chalked on a slate by the bakery door. It has been rubbed out and written higher so many times that the slate has worn pale in that one spot.",
		"Every baker's slate in the city carries the same ghost: an old price wiped away and still faintly showing under the new one. Westfall grain doesn't come in the way it used to.",
		"Bread's dearer than it was. Nobody says so loudly. They just buy the smaller loaf and look at the bigger one on the way out.",
	},
	["sw.muse.w19.oven.006"] = {
		"Break a crust anywhere in this city and a pigeon arrives within the minute, with the bearing of a tax collector and roughly the same manners.",
		"The pigeons of Stormwind can hear bread being torn from three streets away. They don't beg. They simply attend.",
		"Nobody in this city eats bread alone. There's always a pigeon on the next step, waiting with the patience of a creditor.",
	},
	["sw.muse.w19.oven.007"] = {
		"Somebody nearby has burned a whole batch. The smell is already round every corner, and somewhere a baker is telling an apprentice it was done on purpose.",
		"Burned bread, close by. The whole quarter can smell the mistake; only one apprentice is going to hear about it.",
		"That's the smell of a ruined oven-load and a very long lecture, both going on a street or two away.",
	},
	["sw.muse.w19.oven.008"] = {
		"There's a stew pot in the Trade District that never seems to empty or taste the same twice. Ask the cook what's in it and he says 'whatever was cheap', which at least is honest.",
		"One cookshop keeps a kettle on the fire from the first bell to the last and feeds it whatever the market didn't sell. The stew has no name. It doesn't need one.",
	},
	["sw.muse.w19.oven.009"] = {
		"Half a loaf, a wedge of cheese and a wall to lean on. Whoever says Stormwind is expensive is shopping wrong.",
		"A heel of bread and an apple from Elwynn: best meal in the city, and it cost less than the bootlace I broke.",
		"Bread, cheese, a bench out of the way of the carts. Kings eat worse, and with more people watching.",
	},
	["sw.muse.w19.oven.010"] = {
		"lays a palm against a wall that is warm to the touch, some oven working away on the other side of the stone.",
		"leans for a moment on a stretch of wall gone warm from a bakery behind it, as if the city kept a hearth between its ribs.",
	},
	["sw.muse.w19.oven.011"] = {
		"A dwarf at a bakery counter asked for bread 'with something in it'. The baker offered raisins. It took them a while to establish that he had meant ale.",
		"Overheard at a bakery: a dwarf asking whether the loaves came 'with anything in them', and a baker slowly realizing the answer he wanted was not raisins.",
	},
	["sw.muse.w19.oven.012"] = {
		"Ask a gray-haired baker when the ovens of this city last went cold and you get the year it burned, and nothing more. A baker measures a disaster in loaves not made.",
		"The bakers have a saying, an apprentice told me: as long as one oven in Stormwind is lit, the city hasn't fallen. It's only half a joke. They don't say the other half.",
	},
	["sw.muse.w19.oven.013"] = {
		"passes a bakery with its shutters still down and its door propped open for the heat, a floured forearm working dough in the half-dark within.",
		"slows beside a bakery door left ajar in the early chill, where someone unseen is slapping dough onto a board in a steady, sleepy rhythm.",
		"goes by a bakehouse whose open door spills a gust of heat and yeast into the cold street, and, from somewhere inside, a yawn.",
	},
	["sw.muse.w19.oven.014"] = {
		"Most of the city is asleep. Somewhere a baker is already up to the elbows in dough, and tomorrow is going to start from that one lit kitchen.",
		"Bakers keep their own hours. They're kneading while the last drinkers are still finding their way home, and they'll be asleep by the time anyone eats what they made.",
	},
	["sw.muse.w19.oven.015"] = {
		"Smell that? Cinnamon, somewhere close. Somebody in this city is doing better than I am.",
		"Somebody's baking with honey nearby. I'm not hungry. I'm going to go and look anyway.",
	},
	["sw.muse.w19.oven.016"] = {
		"That smell has followed me down three streets. Fine. I surrender. Somebody sell me the pie.",
		"I've gone past that bakery twice pretending not to notice it. It noticed me.",
	},
	["sw.muse.w19.park.001"] = {
		"watches a gardener rake fallen leaves into a tidy heap, step back to admire it, and then watch a child walk straight through the middle.",
		"pauses as a gardener leans on his rake to contemplate a heap of leaves that two small boys are already circling like wolves.",
	},
	["sw.muse.w19.park.002"] = {
		"The gardeners lay out the Park's paths; the city walks wherever it likes. You can read the argument in the grass: a straight bare line from one end to the other, cutting through every graceful curve.",
		"Somebody designed lovely winding paths for the Park. Somebody else, in a hurry, wore a brown stripe straight across the lawn. The second somebody has more followers.",
		"Every lawn in the Park has a path across it that nobody planned. The city votes with its boots.",
	},
	["sw.muse.w19.park.003"] = {
		"Couples in the Park walk slower than anyone else in Stormwind. It's the one place in the city where being in nobody's way is the whole point.",
		"The Park is where this city sends its lovers, it seems: two by two, arm in arm, at a pace that would get them trampled in the Trade District.",
	},
	["sw.muse.w19.park.004"] = {
		"The Park has its regulars who come alone and mean to stay that way: a man who reads the same thin book, a woman who talks to one particular tree, an old soldier who keeps his back to a trunk and his eyes on the path.",
		"Some people go to the Park for company. Others go because it is the only place in Stormwind where sitting alone doesn't look like a misfortune.",
		"Not everyone in the Park is at peace. Some come to sit beside whatever they can't carry through the streets, and set it down on a bench for an hour.",
	},
	["sw.muse.w19.park.005"] = {
		"The humans keep a little forest in a box of stone and call it a park. It is kindly meant, and the trees, I think, have forgiven them.",
		"Our druids tend these trees as a courtesy, and the humans thank us as if it were a gift. Perhaps it is. A tree in a city needs a friend more than one in a wood.",
	},
	["sw.muse.w19.park.006"] = {
		"steps aside as a cloth ball comes bouncing across the grass, chased by four children and one very small, very determined dog.",
		"stops a rolling ball with the side of a boot, out of pure reflex, and finds five small faces on the lawn waiting to see what happens next.",
	},
	["sw.muse.w19.park.007"] = {
		"Stone doesn't change with the seasons. The Park does, and that's how the whole city keeps count: by the color of a few dozen trees between walls.",
		"Anywhere else in Stormwind you'd have to ask a baker what season it is. In the Park the trees tell you, without being asked.",
	},
	["sw.muse.w19.park.008"] = {
		"The Park smells of cut grass and damp bark, which in a city of forge smoke and canal water comes close to a luxury.",
		"Bark, moss, turned earth. After so much tar and coal and other people's cooking, the Park smells like a window opened in a stuffy room.",
	},
	["sw.muse.w19.park.009"] = {
		"Somebody ought to charge admission to the Park. No, don't. Somebody would.",
		"Trees, grass, quiet, and all of it free. Don't tell the nobles; they'd find a way to tax it.",
		"Best thing in Stormwind, the Park, and it doesn't sell a thing.",
	},
	["sw.muse.w19.park.010"] = {
		"Quiet, now. Someone's asleep under that tree, and by the state of his boots he's earned it.",
		"Let him sleep. Anyone who can nap on roots like those has walked farther than most.",
	},
	["sw.muse.w19.park.011"] = {
		"At dusk the Park empties from the edges inward. The couples go first, then the children called in for supper, and last of all the old men on the far benches, who have nowhere they need to be.",
		"Dusk in the Park: the gardeners shoulder their rakes, the paths go blue, and one old woman stays on her bench as if waiting to be the last thing the light lets go of.",
	},
	["sw.muse.w19.park.012"] = {
		"follows a path deeper into the Park as the fog thickens, the trees going pale, then faint, then nothing more than a smell of bark on either side.",
		"stops on a Park path where the fog has swallowed both ends, leaving one bench, one tree and a lamp glowing with nothing to shine on.",
	},
	["sw.muse.w19.park.013"] = {
		"Rain in the Park doesn't sound like rain on the roofs. It's softer, a whole crowd whispering in the leaves, and the paths smell of earth instead of stone.",
		"Under the big trees of the Park the rain arrives late, a drop here and a drop there, long after it has soaked the streets.",
	},
	["sw.muse.w19.park.014"] = {
		"Someone has tied a ribbon round one of the trees in the Park, faded nearly white. Nobody unties it. The gardeners prune around it, carefully, as if it might still be listening.",
		"There's a tree in the Park with a strip of cloth knotted round its trunk, the color long since washed out of it. Whoever tied it hasn't come back. The tree has kept it anyway.",
	},
	["sw.muse.w19.park.015"] = {
		"The sparrows in the Park know the sound of a parcel of food being unwrapped from twenty paces. By the time the string is off, there's a committee.",
		"Unwrap so much as a crust in the Park and the sparrows arrive in a hurry, hopping closer by inches and pretending each time that they just happened to be passing.",
		"Every bird in the Park is a beggar with excellent manners. They never ask; they just stand close and look reasonable.",
	},
	["sw.muse.w19.park.016"] = {
		"passes a young couple on the grass pretending to share a book, neither of whom has turned a page in some time.",
		"notices two people under a tree sitting a carefully measured hand's width apart, both studying the leaves with enormous interest.",
	},
	["sw.muse.w19.patrol.001"] = {
		"A patrol crossing a bridge always breaks step. The guards say it's an old soldiers' rule: march in time over a stone arch long enough and the stone starts to hum along.",
		"Halfway over the bridge the patrol falls out of step on purpose, boots scattering into ordinary walking. An old habit, a sergeant told me: never let a bridge learn your rhythm.",
		"Watch a patrol on any bridge: the step breaks at the first stone of the arch and comes back together at the last. Nobody gives the order; the boots just know.",
	},
	["sw.muse.w19.patrol.002"] = {
		"watches a patrol fish a floating hat out of the canal with the butt of a halberd and hang it, dripping, on a lamp hook for whoever lost it.",
		"pauses to see a guard on patrol lean over the water, hook a drifting hat on the end of his halberd and set it on a railing, then walk on without looking back.",
	},
	["sw.muse.w19.patrol.003"] = {
		"stands aside as a small funeral goes by and sees the passing patrol halt, set their halberds upright and wait, heads bowed, until the last mourner is past.",
		"notices two guards on their round stop dead for a coffin carried down the street, heels together, and fall back into their walk only when it has turned the corner.",
		"pauses as a patrol meets a funeral on a bridge and gives way to it, the guards pressed to the parapet with their halberds held upright like candles.",
	},
	["sw.muse.w19.patrol.004"] = {
		"Dice vanish into sleeves, the cart on the corner suddenly remembers an errand, a dozen people discover a shop window. Somewhere behind me, a patrol has turned into the street.",
		"When a patrol turns into a street, the street tidies itself: cards away, voices down, a cart moved off the corner where carts are not supposed to stand.",
		"A patrol rounds the corner and the whole lane rearranges its face: the loud voice drops, the stray barrel finds its wall, and somebody's dog is suddenly on a leash.",
	},
	["sw.muse.w19.patrol.005"] = {
		"News crosses Stormwind fastest along the patrols. Two of them meet at a corner, trade three words and part, and by the next change of the watch everyone in blue knows which bridge has a loose stone.",
		"Patrols meet at the corners like ants on a path: a pause, a word, gone. Whatever they passed along, the far side of the city will know it before the criers do.",
		"A patrol from the Trade District meets one from Old Town on a bridge, and in three words the description of a stolen ring has crossed the city.",
	},
	["sw.muse.w19.patrol.006"] = {
		"steps aside to let a patrol pass two abreast, and notices a few others in the crowd step aside rather faster, and rather farther.",
		"makes room for a passing patrol and sees, out of the corner of an eye, a lean figure in a doorway make a great deal more room, all the way round the corner.",
	},
	["sw.muse.w19.patrol.007"] = {
		"Someone should tell that patrol the left boot squeaks. Every thief in the street can hear them three corners off.",
		"Lovely polish on those boots, guards. Pity about the squeak. You're announcing yourselves to the whole quarter.",
	},
	["sw.muse.w19.patrol.008"] = {
		"follows a patrol on its round through the rain, walking at exactly the pace it keeps in the dry, capes gone dark, water running off the rims of their helmets.",
		"keeps under an eave as two guards go by in the rain without hurrying, as though hurrying were something the watch had decided against long ago.",
		"lingers in a doorway while a patrol tramps past through the downpour, one guard tipping his helmet forward so the water runs off the front instead of down his neck.",
	},
	["sw.muse.w19.patrol.009"] = {
		"spots a guard on the night round stopping at a bridge lamp that has gone out, lighting it again from a tinderbox at his belt, and standing a moment to be sure it holds.",
		"follows with {g:his|her} eyes a guard who pauses on the night round to coax a dead lamp back to life, shielding the little flame with one gloved hand.",
	},
	["sw.muse.w19.patrol.010"] = {
		"Patrols here pair an old guard with a young one. The old one talks to the street; the young one watches the rooftops, the windows, the hands. Neither seems to know the other is the clever half.",
		"Look at any patrol: one talks, one looks. The talker is always gray at the temples, and the looker never says a word all round.",
	},
	["sw.muse.w19.patrol.011"] = {
		"There's a woman who walks one patrol's round every day, a few paces behind, never speaking. Her husband walked it once, the guards say. They slow down a little at the corners, so she can keep up.",
		"A guard's widow follows the same round her husband used to walk, a little behind the patrol, every day. Nobody has ever asked her to stop. They wait for her at the bridges.",
		"Nobody on that patrol ever tells the widow to go home. When she stops at the end of the round, they stop too, and wait until she turns back alone.",
	},
	["sw.muse.w19.patrol.012"] = {
		"Same route as before? Good. I'd hate for this city to start surprising me.",
		"You two again. Either the city is very small or you walk very fast.",
		"Don't mind me, I'm only admiring the formation. Very straight. Very blue.",
	},
	["sw.muse.w19.patrol.013"] = {
		"The patrol's eyes pass over me, stop, and go on. I don't know which part of that I'll be turning over for a long while yet.",
		"Every patrol that goes by is a coin tossed in the air. So far it keeps landing on the side where they walk on.",
		"Walk like you belong. Don't hurry, don't stop, don't look at the halberds. The patrol is three paces off, and they've been trained to notice exactly the things I'm trying not to do.",
	},
	["sw.muse.w19.patrol.014"] = {
		"Here in the Park the patrols keep strictly to the paths. The night elves asked them once, a guard told me, very politely, and nobody in the watch wants to be asked twice.",
		"Guards on the Park round never set foot on the grass. Something about a quiet word from the elves who tend it, and the look that went with the word.",
	},
	["sw.muse.w19.patrol.015"] = {
		"A king can vanish on his way to a peace talk and a court can lose its head over who rules, and the patrols still go round. Order in this city isn't kept in the keep. It's kept on foot, corner by corner.",
		"The king's gone missing, but the rounds are walked. If Stormwind holds, it holds at street level, in boots.",
		"The guards on patrol don't know where the king is either. They just keep walking, as if somebody ought to.",
	},
	["sw.muse.w19.patrol.016"] = {
		"Going my way? Good. I'll walk on this side of you and look extremely law-abiding.",
		"Mind if I trail you two for a street or so? Nobody bothers anyone near a patrol.",
	},
	["sw.muse.w19.petition.001"] = {
		"Petitioners rehearse on the way up to the keep: lips moving, hands making small shapes in the air. By the time they reach the steps, most of them have cut the speech in half.",
		"You can spot someone with a petition by the way they walk and mutter at once, polishing a speech they'll forget the moment the doors open.",
		"Most petitions are composed on the walk up to the keep. Most are revised on the walk back down.",
	},
	["sw.muse.w19.petition.002"] = {
		"watches a farmer on his way up to the keep turn his hat round and round in his hands, the brim long since worn soft by it.",
		"notices a man in his best coat waiting near the keep, kneading the brim of a hat that has clearly been through this before.",
	},
	["sw.muse.w19.petition.003"] = {
		"The scribes who take down petitions write fast and seldom look up. A whole village's trouble becomes three lines and a number.",
		"A clerk can turn a widow's long story into a single line of ink and blot it dry before she has finished. Efficient. Terrible, but efficient.",
	},
	["sw.muse.w19.petition.004"] = {
		"Want something from the keep? Bring it in writing, bring it twice, and bring patience to spare.",
		"The secret of a good petition: a clear hand, a short page, and a great deal of sitting on benches.",
		"Petitions? Keep them short. The regent reads every one, they say, and even the regent has to sleep sometime.",
	},
	["sw.muse.w19.petition.005"] = {
		"There's a letter-writer who sets up near the keep and writes petitions for those who can't. For a copper more he makes them sound angry; for two, humble.",
		"The public scribe on the way to the keep sells three tones of voice: respectful, desperate and wounded. Desperate costs extra, and sells best.",
	},
	["sw.muse.w19.petition.006"] = {
		"sees an old man come down from the keep with a folded paper bearing a seal, and stop to read it again at every turn of the stairs.",
		"watches an elderly woman leave the keep clutching a sealed letter to her coat, walking very carefully, as though it might spill.",
	},
	["sw.muse.w19.petition.007"] = {
		"A petition is a strange act of trust: you write your worst trouble down, hand it to strangers, and believe it will climb all the way to the throne.",
		"Every petition starts somewhere small, a farm, a mill, a burned barn, and is carried to the capital on the hope that a boy and a tired knight will read it.",
	},
	["sw.muse.w19.petition.008"] = {
		"Nobody petitions the boy, not really. They petition the regent through the boy's name, and the boy sits there and hears every word of it.",
		"The petitions are all addressed to the king and all answered by the regent. In between sits a child who hears both halves.",
	},
	["sw.muse.w19.petition.009"] = {
		"Look at the queue for an audience. Half the kingdom's troubles, standing in a line and shifting from foot to foot.",
		"The line to see the regent is longer than the line at the bank. And nobody in it is getting paid.",
	},
	["sw.muse.w19.petition.010"] = {
		"The keep answers petitions in batches, the clerks say, like a baker drawing loaves from the oven. Some come out underdone, and a few come out burnt.",
		"A petition goes in, and some weeks later an answer comes out, warm and stamped. Nobody outside the keep knows what happens in the oven.",
	},
	["sw.muse.w19.petition.011"] = {
		"Petitioners from the countryside all come in their best, and their best is always a size wrong: borrowed from a brother, or last worn at a wedding.",
		"Feast-day coats and wedding shoes on the road to the keep. People dress up to ask for help, as if trouble could be made to look respectable.",
	},
	["sw.muse.w19.petition.012"] = {
		"waits at the edge of the hall while a petitioner's name is read aloud, mangled, and corrected from the back in a small, stubborn voice.",
		"hears a herald stumble over a farmer's name, and the farmer say it again, clearly, the only loud thing he does all audience.",
	},
	["sw.muse.w19.petition.013"] = {
		"Petitions Lady Prestor takes an interest in move quickly, the clerks whisper. The ones she frowns at stop moving at all. Nobody has ever seen a reason written down.",
		"Pleas that cross Lady Prestor's desk come back very polite and very empty, the copyists say, as if the ink itself had been told to behave.",
	},
	["sw.muse.w19.petition.014"] = {
		"Westfall sends a petition every week, the clerks say, and every week it goes into the same tall cabinet. The cabinet is nearly full.",
		"There's a drawer in the keep with nothing in it but pleas from Westfall. Someone must open it now and then. Someone must close it again.",
	},
	["sw.muse.w19.petition.015"] = {
		"notices the first petitioners already on the steps of the keep at dawn, before any door has opened, sitting on folded coats against the cold of the stone.",
		"sees a handful of country folk waiting by the keep in the gray of dawn, sharing a loaf, their papers tucked inside their shirts.",
	},
	["sw.muse.w19.petition.016"] = {
		"The keep goes through so much sealing wax that somewhere in Elwynn there must be a bee who thinks it works for the crown.",
		"Red wax, blue ribbon, a stamp with a lion on it: answers from the keep come dressed better than most of the people who receive them.",
	},
	["sw.muse.w19.post.001"] = {
		"Couriers in Stormwind never walk. One went by me at a trot with his satchel slapping his hip, reading the next address as he ran, and touched nobody. I'd have flattened four people.",
		"A courier's lad cuts through the crowd at a jog, bag bouncing, eyes on the letter in his hand. Nobody steps aside for him, and nobody needs to.",
	},
	["sw.muse.w19.post.002"] = {
		"notices a woman nearby read a letter, laugh out loud, look around in embarrassment, and then read it once more from the top.",
		"passes a dwarf standing quite still in the middle of the crowd with a letter in both hands, people parting around him like water round a post, his lips moving as he reads.",
		"sees a young man fold a letter very small, tuck it inside his shirt, and walk off with a hand pressed flat over the place.",
	},
	["sw.muse.w19.post.003"] = {
		"Most letters come by courier. The worst ones are carried by a soldier in clean gloves, and the whole street goes quiet while he looks for the right door.",
		"You can tell the letters that matter by who brings them. A boy with a satchel means news. An officer with a sealed fold and his helmet under his arm means the other kind.",
	},
	["sw.muse.w19.post.004"] = {
		"I keep meaning to write letters. Then I reach the mailbox and remember the writing was the hard part.",
		"A letter would take five minutes. I've been 'about to write it' for longer than some wars.",
		"I'll write that letter tomorrow. Tomorrow has a lot of letters waiting for it.",
	},
	["sw.muse.w19.post.005"] = {
		"There are scribes in this city who write letters for those who can't. I watched one take down a farmer's slow, careful sentences and read them back to him twice, until he nodded.",
		"For two coppers a page a public scribe will write whatever you need sent: a proposal, a complaint, an apology. He hears the whole city's business and looks as if he has heard none of it.",
		"The letter-writers at their little folding desks know more about Stormwind than any spy. They just charge less and keep it to themselves.",
	},
	["sw.muse.w19.post.006"] = {
		"stops at a crowded notice board, where new papers are nailed over old ones so thickly that the board has become a book nobody can open.",
		"reads the edge of a notice half buried under three newer ones: a lost dog, a room to let, and something about a reward torn off at the most interesting word.",
	},
	["sw.muse.w19.post.007"] = {
		"The couriers say letters still come in addressed to towns in Lordaeron that aren't there anymore. Nobody has the heart to burn them. There's a sack somewhere, getting heavier.",
		"Somebody in Stormwind still writes to an aunt in Andorhal every month, a courier told me, and every month the letter comes back. He's stopped explaining why.",
	},
	["sw.muse.w19.post.008"] = {
		"When the mailbox has nothing for me, either nobody owes me anything or nobody knows where I am. I'll take either.",
		"An empty mailbox is underrated. It's just peace and quiet, delivered.",
		"No letters means no bills. I'm choosing to see the bright side.",
	},
	["sw.muse.w19.post.009"] = {
		"I've seen a dwarf post a whole wheel of cheese to someone in Ironforge. The mailbox took it without a fuss. I've stopped asking how the post works and started envying it.",
		"Somebody once mailed a full suit of plate in front of me, piece by piece, as calmly as a love letter. The mailbox swallowed the lot. I'd like to hire whatever lives in there to carry my pack.",
	},
	["sw.muse.w19.post.010"] = {
		"Someone in front of me dropped a letter that smelled of lavender. I handed it back, and we both pretended I hadn't noticed.",
		"A scented letter slipped out of a stranger's sleeve. Returning it took one second and a great deal of tact.",
	},
	["sw.muse.w19.post.011"] = {
		"Saw a letter go into the box with 'URGENT' written on it three times. Nothing truly urgent ever needs saying twice.",
		"Three 'urgents' on one envelope. Whoever wrote that has never met a courier.",
	},
	["sw.muse.w19.post.012"] = {
		"Soldiers' letters, a courier told me, all say the same three things in different hands: still alive, very tired, please send socks.",
		"Letters from the front are short. 'Alive. Cold. Food bad. Send socks.' The families of Stormwind read them like poetry anyway.",
		"The letters that come from the war are read until the folds wear through. Most of them say almost nothing, and that nothing is all a family wants.",
	},
	["sw.muse.w19.post.013"] = {
		"watches a courier hunch over his satchel in the rain like a hen over her eggs: letters first, himself a distant second.",
		"catches sight of a messenger dashing between doorways in the downpour with his bag held under his coat and his own head left to the weather.",
	},
	["sw.muse.w19.post.014"] = {
		"Half the post in this city, a scribe swore to me, goes from one street to the next street over. Stormwind would rather pay a courier than knock on a neighbor's door.",
		"People here write letters to people they could shout to from the window. It isn't laziness, a scribe told me. It's that a letter can't be interrupted.",
		"Two houses facing each other across one lane, and a courier running between them all day. In Stormwind even a quarrel goes by post.",
	},
	["sw.muse.w19.post.015"] = {
		"I once watched a gnome stretch on tiptoe toward a mailbox slot, fail, fetch a crate, climb it, and post the letter with tremendous dignity. Nobody applauded. Somebody should have.",
		"A gnome hopped twice at a mailbox slot, then handed the letter up to a passing guard, who posted it for her without a word. The whole exchange had the gravity of a treaty between kingdoms.",
	},
	["sw.muse.w19.post.016"] = {
		"If anyone needs me, write. I'll be impossible to find, but the letter will manage somehow.",
		"Send word if something comes up. The post always finds me, which is more than I can say for my own feet.",
	},
	["sw.muse.w19.quarrel.001"] = {
		"On a narrow bridge the heavier load goes first. That's the guards' rule, and they recite it every time two carts meet in the middle, to two drivers who each insist theirs is the heavier.",
		"Two carters nose to nose on a bridge, each swearing his load is heavier. The guard who arrives asks each of them to name his cargo, and the one hauling empty baskets backs up without another word.",
	},
	["sw.muse.w19.quarrel.002"] = {
		"looks on as a guard arrives at a shouting match between two dwarves, listens for a moment, and decides, wisely, to go and stand somewhere else until they start laughing.",
		"sees two dwarves bellow at each other over an anvil until one thumps the other on the shoulder and calls for ale, while a guard nearby, who never moved, eases his grip on the halberd.",
	},
	["sw.muse.w19.quarrel.003"] = {
		"Two men were shouting about a debt outside the bank. Then they went in together, still shouting, and came out together, still shouting, but about something else. That's a quarrel settled, Stormwind fashion.",
		"A debt quarrel in this city rarely ends in blows. It ends at the bank counter, both parties glaring at the clerk instead of at each other.",
		"Money quarrels here end in front of a clerk. The clerk never takes a side; he takes a fee.",
	},
	["sw.muse.w19.quarrel.004"] = {
		"lingers as a priest and a hawker argue, with great courtesy on both sides, about which step of the Cathedral is the last one that counts as holy ground.",
		"stops to hear a young priest explain to a peddler, very gently and for the third time, that the steps are not for selling, while the peddler explains, just as gently, that he is only standing on them.",
	},
	["sw.muse.w19.quarrel.005"] = {
		"Two men at the next table argue about the Defias: bandits, says one; wronged, says the other. Neither of them has ever been to Westfall. The farmer at the end of the bench, who has, keeps his eyes on his bowl.",
		"Everyone in this room has an opinion on the Defias. The loudest belong to people who've never lost a barn. The quietest belong to the ones who did.",
		"Somebody at the bar calls the Defias murderers, somebody else calls them masons, and the Westfall man in the corner says, quietly, that they were both, and asks for his bill.",
	},
	["sw.muse.w19.quarrel.006"] = {
		"watches a guard listen to a quarrel in three languages at once, nodding gravely to each in turn as if he understood a word, then point one party east and the other west.",
		"catches a guard hearing out a dwarf, a gnome and a human all talking over one another, his face perfectly solemn, before he sends them off in three different directions.",
	},
	["sw.muse.w19.quarrel.007"] = {
		"Don't look at me. I saw nothing, and I saw it very clearly.",
		"I'm not a witness. I'm a passerby. There's a difference, and I'd like to keep it.",
		"Shout a little louder, both of you. The guard on the next bridge hasn't quite heard yet.",
	},
	["sw.muse.w19.quarrel.008"] = {
		"Two noble houses aren't speaking this season, so their servants do the fighting: elbows at the fishmonger's, a basket knocked into the canal, very polite glares.",
		"When nobles quarrel in Stormwind, nobody draws steel. Their cooks just stop letting each other through the market first.",
		"Two noble families are feuding, and the fishmonger knows it before anyone at court: the footmen have started shoving in the queue.",
	},
	["sw.muse.w19.quarrel.009"] = {
		"Two drinkers came close to blows over whether the regent should be running the kingdom at all. The guard who parted them had one opinion only: not in his street.",
		"Politics, in Stormwind, is a quarrel about Bolvar and the boy king that the guards break up without ever taking a side. One told me his side is the cobbles.",
		"Ask a tavern who should hold the throne and you'll get a quarrel. Ask the guard by the door and you'll get a look that says the throne is somebody else's business and the tavern is his.",
	},
	["sw.muse.w19.quarrel.010"] = {
		"watches an old cobbler step into a squabble between two apprentices, say one quiet word nobody else can hear, and leave them both apologizing to the pavement.",
		"notices a stooped old woman break up a quarrel between two hulking porters with nothing but a raised finger, faster than any guard could have reached them.",
	},
	["sw.muse.w19.quarrel.011"] = {
		"A quarrel was warming up nicely in here until a man at the bar, out of uniform, simply stood up. Nobody knew him. Everybody sat down.",
		"Two hotheads by the hearth were about to say something regrettable when a quiet drinker set down his mug and stretched. The way he stood said guard, and both hotheads remembered their manners.",
	},
	["sw.muse.w19.quarrel.012"] = {
		"In the fine streets people quarrel in whispers, behind shutters. In Old Town they quarrel at the top of their voices in the middle of the lane. As far as I can tell it's the same quarrel: money, mostly, and who said what to whose sister.",
		"Old Town shouts its grudges and the noble streets murmur theirs. The subjects don't change with the address.",
	},
	["sw.muse.w19.quarrel.013"] = {
		"A dwarf and a night elf were quarreling by the fountain about whose people kept their word better. Both raised their voices; neither reached for anything. That's our Alliance on a good day: loud, rude, and on the same side.",
		"Allies quarrel. I watched a gnome and a human tear into each other over a broken contract until a guard got bored of them, and I thought: good. Enemies don't bother arguing.",
	},
	["sw.muse.w19.quarrel.014"] = {
		"Whatever it is, it isn't worth the Stockade. Nothing is worth the Stockade.",
		"Lower your voices, friends. Half the watch is within earshot and the other half is on its way.",
		"Keep shouting and you'll both be explaining yourselves to a sergeant. He's worse at listening than I am.",
	},
	["sw.muse.w19.quarrel.015"] = {
		"Excuse me, coming through. Carry on, you were both doing very well.",
		"Don't stop on my account. I'm just squeezing past the argument.",
	},
	["sw.muse.w19.rampart.001"] = {
		"notices a tuft of grass growing from a joint high in the city wall, green and stubborn, well out of reach of whoever is paid to pull it.",
		"spots a small yellow flower clinging to a crack halfway up the wall, the only thing in Stormwind that ever climbed it without a ladder.",
		"picks out a sprig of green rooted in the mortar high on the wall, the one untidy thing on the whole face of it.",
	},
	["sw.muse.w19.rampart.002"] = {
		"Swifts nest in the little square holes high on the walls, where the scaffold beams once sat. The builders moved on, the birds moved in, and nobody asks them for rent.",
		"The holes the builders' scaffolds left in the walls have tenants now: small dark birds that shoot in and out like thrown pebbles.",
	},
	["sw.muse.w19.rampart.003"] = {
		"I asked a guard if I could walk the top of the wall. He looked at me as if I'd asked to borrow his pension.",
		"No visitors on the ramparts, apparently. Shame. Best view in the city, wasted on people paid to look at it.",
		"Some cat has the run of the ramparts and I don't. I've been insulted by worse, but not lately.",
	},
	["sw.muse.w19.rampart.004"] = {
		"Call out anywhere near the great wall and it answers a moment later, in a voice a little deeper than yours. Children here spend whole afternoons arguing with it.",
		"The wall by the gate keeps an echo the way an old dog keeps a bone. Clap once and it claps back, slower, as if it had to think about it.",
	},
	["sw.muse.w19.rampart.005"] = {
		"Walk along the foot of the great wall and the city goes quiet on one side. Stone that thick swallows a lot: carts, quarrels, even a little of the bells.",
		"There's a strip of quiet that runs along the inside of the walls, a pace or two wide, where the noise of the streets seems to lose interest. I keep finding myself in it.",
		"Along the inner face of the wall the street is always a shade dimmer and a shade calmer, as if the stone kept some of the silence for itself.",
	},
	["sw.muse.w19.rampart.006"] = {
		"pauses below a rope cradle hanging against the wall, where a worker scrapes out old mortar a finger's width per stroke and presses in new.",
		"looks up at a cradle of planks creaking down the face of the wall on two ropes, the worker in it whistling and tapping the stones as if listening for a bad one.",
		"notices fresh mortar, still pale, in a ragged patch high on the wall, like a dressing on the side of the city.",
	},
	["sw.muse.w19.rampart.007"] = {
		"Every tower along the wall hides a spiral stair. You can tell the guards posted up there: they come down at the end of the watch walking as if the street were tilted.",
		"Whoever stands guard on the towers earns the pay twice, once watching and once climbing. You can pick them out in a tavern by the way they lower themselves onto a bench.",
	},
	["sw.muse.w19.rampart.008"] = {
		"All that wall and not a single counterweight, gear or alarm bell wired to anything. The humans just stacked rocks very high and trusted them. Bold. Old-fashioned, but bold.",
		"I sized up one of the wall stones by eye and nearly fell over doing the sums. Ramps and ropes, all of it. Not one lifting engine. I'm torn between horror and admiration.",
	},
	["sw.muse.w19.rampart.009"] = {
		"A clerk once tried to count the stones in the outer wall, the guards swear. He got as far as the second tower and asked for a transfer.",
		"Somebody tried counting the stones in that wall, the guards say. Lost track at the gate, started over, and was never quite the same.",
		"Count the stones in that wall? I'd rather count the guards' jokes. There are fewer, and they repeat.",
	},
	["sw.muse.w19.rampart.010"] = {
		"follows the line of the great wall upward, block by block, until the neck protests and the eyes come back down to the street.",
		"cranes to see the top of the wall, loses it against the sky, and finds it again a little further along than expected.",
	},
	["sw.muse.w19.rampart.011"] = {
		"Every wall is a sentence in two halves: in here, out there. Stormwind wrote its own in letters three stories tall, and Westfall reads it from the wrong side.",
		"A wall decides who's inside before anyone has to say it aloud. This one decides very firmly, and very politely, with a guard at every door.",
	},
	["sw.muse.w19.rampart.012"] = {
		"tracks a lantern moving slowly along the top of the dark wall as it stops, dips once and moves on: the night round making its way.",
		"picks out a single bobbing lantern high on the black line of the wall, a sentry walking the round while the city below goes to sleep.",
	},
	["sw.muse.w19.rampart.013"] = {
		"Huge towers on the walls, and the doors into them barely wide enough for a guard and his lunch. Easy to hold, I suppose. Hard to get a bed through.",
		"The doors in the wall towers are narrow and low, set deep, with iron on them. Somebody planned for a bad day and hoped it would never come.",
		"Every tower door I've seen in this city is narrower than the people it was built for. Defense, the guards say. Spite, says anyone who has tried to carry a crate through one.",
	},
	["sw.muse.w19.rampart.014"] = {
		"Whatever goes wrong in the kingdom, the walls are still up. It's a low bar for comfort, and I take it every time I pass under them.",
		"Humans built these walls twice. Some days that feels like stubbornness, some days like the best thing about us.",
	},
	["sw.muse.w19.rampart.015"] = {
		"I've seen whole castles with less wall than this city keeps around for spare.",
		"That's not a wall. That's a mountain somebody squared off and put a door in.",
	},
	["sw.muse.w19.rebuild.001"] = {
		"The rebuilding went in an order, the old builders say: walls first, then the cathedral, then the keep, then everyone else. You can still tell who came last by how much they argue about it.",
		"Walls, cathedral, keep, houses: that's how Stormwind went back up, by the builders' account. The folk whose houses came last have never quite forgiven the order.",
	},
	["sw.muse.w19.rebuild.002"] = {
		"When the exiles came back from the north there was nothing left to come back to but property lines, and everyone remembered theirs a little wider. A clerk told me some of those quarrels are still before the magistrates.",
		"Returning families found ash, stakes and a hundred neighbors who remembered the boundaries differently. Some of those disputes are older than the new walls, a magistrate's clerk says, and still open.",
		"Rebuilding a city is mostly arguing, an old surveyor told me. The stone went up in a few years. The fences are still being fought over.",
	},
	["sw.muse.w19.rebuild.003"] = {
		"notices where the paving of a street changes mid-stride, herringbone giving way to plain courses, as though two crews had built toward each other without once speaking.",
		"crosses a seam in the street where one pattern of cobbles stops dead and another begins, a quarrel between two work gangs still visible underfoot.",
	},
	["sw.muse.w19.rebuild.004"] = {
		"Everything in Stormwind is a second try. Wiser than the first, I'd guess, and a good deal more expensive.",
		"This is the fair copy. The first Stormwind was the draft, and the orcs tore it up.",
		"Bridges, fountains, shop signs: all second editions. The first printing burned.",
	},
	["sw.muse.w19.rebuild.005"] = {
		"An old woman told me the rebuilt city was laid out by people who'd lived in the first one, so the doors are where their hands expected them, even if the streets aren't.",
		"The folk who rebuilt Stormwind had the old city in their legs, an old woman says: they put the steps where their feet went looking for them. Only strangers trip.",
	},
	["sw.muse.w19.rebuild.006"] = {
		"The old woodcutters of Elwynn say the beams of the new Stormwind came out of their forest, and you can still find the wide clearings where whole hillsides of oak went off to the city on ox carts.",
		"Somewhere in Elwynn there are stumps as wide as tables, a carter told me, left by the rebuilding. Half the rafters in this city grew there.",
	},
	["sw.muse.w19.rebuild.007"] = {
		"Wide streets in the new city, so an army can march through. The guards never say in which direction.",
		"They built the streets wide enough for soldiers this time. And for carts, crowds and every parade the nobles can dream up.",
		"Streets broad enough for a column of soldiers. Somebody remembered the narrow ones, and what got stuck in them.",
	},
	["sw.muse.w19.rebuild.008"] = {
		"studies a wall where the lowest courses have gone the yellow of old teeth and the ones above are still pale, a line straight across it like the mark a flood leaves.",
		"looks along a wall built in two seasons, darker stone below and fresher above, the seam between them running level from corner to corner.",
	},
	["sw.muse.w19.rebuild.009"] = {
		"The dwarves of the Dwarven District will tell you, unasked, that the humans could never have rebuilt Stormwind without dwarven help. The human masons, back when there were some to ask, told it the other way round.",
		"Ask a dwarven smith about the rebuilding and you'll hear about every arch a dwarf ever set in this city. Ask how many arches, and the number grows with the ale.",
	},
	["sw.muse.w19.rebuild.010"] = {
		"The rebuilding took long years. Some of the people who started it were old by the end, and some never saw a finished street. They built it for whoever would walk it after them. Right now that's me, and the carter cursing behind me.",
		"Some of the laborers who cleared the first rubble were buried before the last roof went on. Every finished street in Stormwind is a gift from someone who never walked it.",
	},
	["sw.muse.w19.rebuild.011"] = {
		"The priests say the first services in the rebuilt city were held out here in the open, among stacked stone, before there was a roof to gather them under. A few of the oldest worshippers still prefer the steps to the pews.",
		"Before the cathedral had walls again, an old acolyte says, the clergy kept the Light in this square under canvas and open air. He talks about it the way soldiers talk about a good campaign.",
	},
	["sw.muse.w19.rebuild.012"] = {
		"The clerks say the rebuilding's accounts fill three volumes in the keep. The third is mostly blank pages and apologies.",
		"Somewhere in the keep there's a cabinet of rebuilding accounts nobody opens. Safer that way, a clerk told me. For anyone with a title.",
	},
	["sw.muse.w19.rebuild.013"] = {
		"watches a repair crew unload fresh stone at first light, pale as bread dough beside the weathered wall it is meant to mend.",
		"passes a cart of newly dressed blocks in the early light, their faces still bright from the chisel, waiting beside an old wall gone the color of tea.",
	},
	["sw.muse.w19.rebuild.014"] = {
		"Lordaeron fell to the plague, and the rebuilt walls of Stormwind ended up holding the hopes of more than one kingdom. Nobody built them for that. They're managing.",
		"This city was raised a second time for its own people. Since the north fell, it shelters everyone's. Good stone doesn't ask who it's for.",
		"The masons built for one kingdom. They ended up building for the whole Alliance, and nobody thought to tell them. I'd like to think they'd be proud, under the grudge.",
	},
	["sw.muse.w19.rebuild.015"] = {
		"Every stone here was carried by somebody who'd already lost a house once. That's a kind of stubborn I respect.",
		"People who've built a city twice don't scare easily. Keep that in mind before you pick a quarrel in this town.",
	},
	["sw.muse.w19.rebuild.016"] = {
		"The builders hid things in the walls as they went, a plasterer told me: an old shoe, a copper, a twist of ribbon, for luck. Whenever a wall comes down for repairs, the rebuilding sends the city a small note.",
		"Knock out a patch of plaster in an old Stormwind house, the plasterers say, and you may find a worn-out boot tucked in the wall by some builder for luck. They put it back. Bad form to take it.",
		"A plasterer swears he once opened a wall and found a child's wooden horse in it, wrapped in rag, set there during the rebuilding. He closed the wall again. Some letters aren't addressed to you.",
	},
	["sw.muse.w19.regent.001"] = {
		"Bolvar Fordragon wears his armor even at the council table, the guards say, as if a real fight might call him away at any moment. As if he hoped it would.",
		"They say the regent never takes off his plate, not even to read petitions. A paladin keeping himself ready for the one battle a throne won't let him go to.",
	},
	["sw.muse.w19.regent.002"] = {
		"The soldiers call him the Highlord and never the regent. The nobles call him the regent and never the Highlord. Count which word a man uses and you know where he stands.",
		"One man, two titles, and the city split down the middle between them: 'Highlord' in the barracks, 'regent' in the fine houses. Bolvar answers to both and smiles at neither.",
	},
	["sw.muse.w19.regent.003"] = {
		"A regent signs every order on someone else's behalf. Nobody ever writes 'thank you' in the margin.",
		"Every page Bolvar seals is a promise to give the whole kingdom back one day, in good order, to a man nobody can find.",
		"Ruling for someone else must be like carrying a stranger's child through a crowd: you hold on harder than you would to anything of your own.",
	},
	["sw.muse.w19.regent.004"] = {
		"The regent gets the complaints and the boy gets the cheers. Somebody worked that out very carefully, and I doubt it was Bolvar.",
		"Bad news comes down from the keep in the regent's name, good news in the king's. Tidy system, unless you happen to be the regent.",
	},
	["sw.muse.w19.regent.005"] = {
		"Bolvar never sits on the throne. He stands beside it, every hour of every audience, and a whole kingdom has learned to read something into that.",
		"There's a chair nobody offers the regent, and he'd refuse it if they did. He stands beside the boy instead, and the standing is the message.",
	},
	["sw.muse.w19.regent.006"] = {
		"You can tell how the regent slept by the length of the latest decree. This week's are very short.",
		"Short decrees, short tempers up in the keep. Long ones mean somebody got some rest.",
	},
	["sw.muse.w19.regent.007"] = {
		"A paladin is meant to go where the trouble is. Bolvar has to sit still and let the trouble come to him in writing, page after page.",
		"For a knight sworn to the Light, a council chamber must feel like a cell with very good manners.",
	},
	["sw.muse.w19.regent.008"] = {
		"Highlord, regent, guardian, councilor. Fordragon has more titles than hours to use them, and spends every one on another man's kingdom.",
		"I've heard Fordragon called four different things in one street, and every one of them meant 'the man holding it together'.",
	},
	["sw.muse.w19.regent.009"] = {
		"The veterans say Fordragon earned his rank in the field, not at a dinner. It shows in how the soldiers salute him: properly, and when no officer is watching.",
		"Old soldiers stand straighter when the regent's name comes up. Whatever the nobles think of him, he was one of theirs before he was anyone's regent.",
	},
	["sw.muse.w19.regent.010"] = {
		"When Varian comes home, Bolvar will hand back the kingdom and go back to being a soldier. Everyone says 'when'. The regent says it loudest.",
		"In the keep it's always 'when the king returns', never 'if'. Fordragon insists on it, the clerks say, and corrects anyone who slips.",
		"Every banquet in the keep ends with a toast to the king's return. The regent drinks it standing, the servants say, and never sets the cup down early.",
	},
	["sw.muse.w19.regent.011"] = {
		"hears the regent's name twice in a short walk, once with respect and once with a sigh, and both times from tired people.",
		"catches the name 'Fordragon' in three conversations between one corner and the next: a complaint, a blessing, a bet.",
	},
	["sw.muse.w19.regent.012"] = {
		"Some say the regent listens too closely to Lady Prestor. Others say he listens to everyone, and she simply makes sure she speaks last.",
		"Whoever stands nearest the regent stands nearest the kingdom, and lately, the gossip goes, it's always the same graceful figure. People say it, then look round to see who heard.",
	},
	["sw.muse.w19.regent.013"] = {
		"I'd sooner face an ogre than do the regent's job. Ogres, at least, don't file appeals.",
		"Running a kingdom for a boy and a missing man? I'll take my chances with the wolves, thanks.",
		"Answering every farmer, every lord and every envoy in someone else's name. I'd rather muck out a stable.",
	},
	["sw.muse.w19.regent.014"] = {
		"watches the regent bend to say something to the boy on the throne, and the whole hall pretend not to be watching the same thing.",
		"sees Bolvar Fordragon stoop toward the young king to murmur a word, his armor creaking, while the courtiers find a sudden interest in their gloves.",
	},
	["sw.muse.w19.regent.015"] = {
		"Nobody cheers a regent. If he does the job perfectly, the best he can hope for is to be forgotten the day the king rides in.",
		"A regent's finest hour is the one in which he stops being needed. Bolvar works toward it every day, and it must be a lonely kind of ambition.",
	},
	["sw.muse.w19.regent.016"] = {
		"Whatever Ironforge and Darnassus say, the Alliance still turns toward this keep when it needs an answer, and right now the answer comes in Bolvar's voice.",
		"Four peoples in our Alliance, and in hard times all of them look to a regent who never asked for the job. We could have done a lot worse.",
	},
	["sw.muse.w19.ripple.001"] = {
		"catches a boy skipping a flat stone along the canal, three hops and a sink, and a passing boatman awarding him a grave nod of approval.",
		"counts the hops of a skipped stone across the water, one, two, three, four, and watches the rings it leaves behind, until a boat comes through and wipes out the score.",
	},
	["sw.muse.w19.ripple.002"] = {
		"The ducks of the canals are the most confident citizens of Stormwind. They cross wherever they like, and the boats wait.",
		"No guard, no noble and no boatman in this city has ever told a canal duck where to go. Not in any way the duck has listened to.",
		"Canal ducks have the run of the city: water when they like, steps when they're tired, and a bread-throwing public on every bridge.",
	},
	["sw.muse.w19.ripple.003"] = {
		"A duck on the canals pays no tax, owes nobody a bow, and gets bread thrown at it for free. I've chosen the wrong career.",
		"Ducks in this city: no rent, no taxes, and nobody makes them stand when the regent goes by. Sign me up.",
	},
	["sw.muse.w19.ripple.004"] = {
		"catches {g:his|her} own face in a still patch of canal, and loses it a moment later to a single falling leaf.",
		"glances down at the canal and finds {g:his|her} reflection looking back, a little greener and a little wiser, until a passing boat shakes it to pieces.",
		"leans over the canal just far enough to see a face in it, and a cloud of small fish scatters out of the reflection like startled thoughts.",
	},
	["sw.muse.w19.ripple.005"] = {
		"You can't see the bottom of a canal here. You see your own face, a hand's depth of green, and then nothing you'd want to know about.",
		"Clear as soup, these canals. I'd not put my hand in for a gold coin. Maybe for two.",
	},
	["sw.muse.w19.ripple.006"] = {
		"notices rings spreading on the still water where a fish has come up for something and thought better of it.",
		"follows a slow ring widening across the canal from nowhere in particular, a fish or a dropped seed, until it touches the wall and comes apart.",
	},
	["sw.muse.w19.ripple.007"] = {
		"pauses at the mouth of a bridge, where the canal throws the daylight up against the arch and the stones shiver with it as if they were the ones moving.",
		"looks up at the underside of a bridge, all trembling bands of light thrown up off the water, a ceiling that will not keep still.",
	},
	["sw.muse.w19.ripple.008"] = {
		"The canal water changes its face more often than a courtier: glassy, wrinkled, bottle green, brown after the barges have churned it, and once, briefly, almost blue.",
		"Some days the canals lie flat as a tabletop, some days they fidget, and some days they look as if they're about to say something. They never do.",
	},
	["sw.muse.w19.ripple.009"] = {
		"A boat passes and is gone, and its wake goes on knocking at the walls for a long while after, all down the canal. Some people are like that.",
		"Long after the boat has turned the corner, its wake is still arriving at the steps, small and patient. That's how some goodbyes work.",
		"A wake travels the whole length of a canal just to lay itself down on the bottom step and stop. A long journey for a very small arrival.",
	},
	["sw.muse.w19.ripple.010"] = {
		"lingers as a pale haze lifts off the canals at dawn, unhurried, the moored boats appearing under it one by one as if being unwrapped.",
		"stops on a bank at dawn where the water still holds a thin gray veil, and a single duck cuts a clean line through it.",
	},
	["sw.muse.w19.ripple.011"] = {
		"notices a row of bare feet dangling over the canal edge: five children, ten feet, and only the smallest pair not quite reaching the water, to its owner's great outrage.",
		"passes a row of children sitting on the canal wall, heels drumming the stone, each daring the next to put a foot in first.",
	},
	["sw.muse.w19.ripple.012"] = {
		"Water is the one thing in a city that never quite obeys. The stone does what the masons told it to. The canals do as they please, a finger's width here and there.",
		"Every wall in Stormwind stands where it was put. The water was put in its canals too, and it has been testing the edges ever since.",
	},
	["sw.muse.w19.ripple.013"] = {
		"Canal water. Barely moves, never hurries, and still it gets into everything.",
		"One splash from a passing boat and you smell of canal for the rest of the day. Worth knowing before you lean over.",
		"The canals don't splash. They wait for a boat to do it for them, aimed at whoever's wearing their good clothes.",
	},
	["sw.muse.w19.ripple.014"] = {
		"We humans build our cities on water and then spend centuries arguing with it. Stormwind at least had the sense to cut its water into straight lines first.",
		"Human cities are always built beside water: a river, a lake, a bay. Stormwind brought the water inside and taught it to walk in lines.",
	},
	["sw.muse.w19.ripple.015"] = {
		"follows the progress of a hat floating down the canal, its owner trotting along the bank beside it and keeping pace, unable to do anything but watch it go.",
		"stops to watch a straw hat sail serenely down the canal, turning slow circles, with half a street running along the bank shouting advice at it.",
	},
	["sw.muse.w19.ripple.016"] = {
		"Children drop pebbles off the bridges to find out how deep the canals are. The answer is always 'plop', which tells them nothing and satisfies them entirely.",
		"Every child in Stormwind has dropped a pebble off a bridge and leaned over to see where it went. The canal keeps the pebble and gives back a ring, which seems a fair trade to them.",
	},
	["sw.muse.w19.rivet.001"] = {
		"One dwarf in the Dwarven District makes nothing but nails, thousands a week, and talks about them the way a jeweler talks about rings. I believe every one of them is perfect.",
		"Somebody has to make the nails. In the Dwarven District it's one stubborn dwarf who says a good nail outlives the house, and gets quite heated on the subject.",
	},
	["sw.muse.w19.rivet.002"] = {
		"The sound of the Dwarven District isn't only hammers. Listen beneath them: the quick light tick of someone setting rivets in a mail shirt, patient as a clock.",
		"Under the big hammer blows runs a smaller sound, tick, tick, tick, an armorer closing the rings of a mail shirt one rivet each. It never hurries and it never stops.",
		"Under the forges runs a rhythm that takes a while to hear: the armorers riveting mail, link after link, as steady as a mill wheel.",
	},
	["sw.muse.w19.rivet.003"] = {
		"catches a dwarf armorer holding a dented breastplate up to the lamp, squinting, and setting it down with the look of a surgeon who has met this patient before.",
		"lingers by an armorer's bench as a dwarf runs a thumb along a split seam in somebody's mail and clicks his tongue, the verdict of an old judge.",
	},
	["sw.muse.w19.rivet.004"] = {
		"The Alliance is mostly rivets, a smith told me: small, ugly, and holding everything up. I think he meant the dwarves and gnomes who stayed to work in Stormwind.",
		"An armorer told me treaties are the big plates, and what holds them together is rivets, little things nobody looks at, like a dwarf who stayed on to work in a human city.",
		"Kings sign the treaties, a dwarf said over his bench, and smiths keep them. He didn't look up, and he didn't say which kings.",
	},
	["sw.muse.w19.rivet.005"] = {
		"That dwarf looked at the state of my gear and asked, very gently, whether I had enemies or just bad habits.",
		"Every smith in the Dwarven District inspects your kit the same way: one long look, one long sigh, then the price.",
		"Show a dwarf a broken strap and he'll fix it. Show him how it broke and he'll want a word.",
	},
	["sw.muse.w19.rivet.006"] = {
		"Somebody once counted the rivets in the tram cars, a gnome boasted to me. Nobody has checked her number, and nobody dares.",
		"Ask a gnome how many rivets hold the tram together and you'll get an exact number, and a look that dares you to count.",
	},
	["sw.muse.w19.rivet.007"] = {
		"pauses to watch two dwarves carry a long iron beam down the street, calling the steps in a rhythm of their own, the crowd parting round them like water round a log.",
		"steps back against a wall as two dwarves bear a length of iron past at shoulder height, singing out a count so the two ends never argue.",
	},
	["sw.muse.w19.rivet.008"] = {
		"Half the locks in Stormwind came out of the Dwarven District. Some of the keys, I suspect, went out the back door.",
		"Dwarves make most of the city's locks, and dwarves have long memories. Somewhere in the Dwarven District is someone who could open half of Stormwind, and is too proud to.",
	},
	["sw.muse.w19.rivet.009"] = {
		"Now and then a sharp crack comes out of the Dwarven District and nobody there flinches: a dwarf proving a gun barrel into a sandbag. Only visitors jump.",
		"A crack like a splitting beam, and a puff of smoke from a doorway. The dwarves around don't even look: somebody's testing a barrel, and the sandbag never complains.",
	},
	["sw.muse.w19.rivet.010"] = {
		"Dwarven steel on a human soldier, gnome gears in a human lock. Say what you like about the Alliance; it's well riveted.",
		"Human walls, dwarven iron, gnome gadgets. The Alliance holds together the way good armor does: lots of small pieces, each doing its job.",
	},
	["sw.muse.w19.rivet.011"] = {
		"Behind one workshop a mechanostrider stands on three legs, waiting for parts that only ever came from Gnomeregan. It has waited a long while. Its gnome oils it every week anyway.",
		"There's a gnomish strider in a yard off the Dwarven District's main street, one leg missing and a cloth over its head like a hooded horse. Its owner says the part is coming. It has been coming for years.",
	},
	["sw.muse.w19.rivet.012"] = {
		"A gnome in the Dwarven District fits iron hands and hinged knees for soldiers back from the war. Her workshop is very quiet, and very busy.",
		"Near the forges, in a workshop with no sign, gnomes make jointed iron fingers and braces for knees the war took apart. Nobody waits outside it laughing.",
	},
	["sw.muse.w19.rivet.013"] = {
		"notices a dwarf mending a cart axle in the middle of the street, the cart propped on a stack of anvils, while its human owner hovers and is told, kindly, to go away.",
		"follows, with some interest, a quarrel between a dwarf and a human over a broken axle, the human arguing with gestures and the dwarf with a hammer, until the axle settles it by holding.",
	},
	["sw.muse.w19.rivet.014"] = {
		"Dwarven mail lasts. In the Dwarven District there are mail shirts older than the city walls, still in service, passed from owner to owner with the price going up each time.",
		"The smiths in the Dwarven District say a good dwarven mail shirt outlives three owners and a dragon. They're joking about the dragon. Probably.",
		"Buy dwarven mail and you're only borrowing it, the armorers like to say. It will be on somebody else's back long after yours has given up.",
	},
	["sw.muse.w19.rivet.015"] = {
		"Dwarven apprentices spend their first year on rivets and nothing else, the armorers say. Ten thousand of them, all the same, before anyone lets them near a plate.",
		"The youngest hands in the Dwarven District sit in a row at a long bench, setting rivets into scrap. Nobody wears their work. It goes back in the furnace, and they start over.",
		"A row of dwarf apprentices tapping rivets into scrap iron, hour after hour. Every bit of it goes back to be melted. A smith told me the iron isn't the thing being made.",
	},
	["sw.muse.w19.rough.001"] = {
		"Somewhere between the Trade District and Old Town the paint gets cheaper, the shutters get thicker and the guards start walking in pairs.",
		"You can see where the city stops polishing itself: the window boxes give out, the doors lose their brass, and the patrols double up.",
	},
	["sw.muse.w19.rough.002"] = {
		"There's a shop in Old Town that will buy anything and ask nothing. Its window holds a single boot, a silver spoon and a lute with no strings, and the stock changes every week.",
		"A narrow shopfront off an Old Town lane: one fine glove, one candlestick, one wedding ring. The owner looks at you as if he were pricing your coat.",
	},
	["sw.muse.w19.rough.003"] = {
		"passes a broad man leaning in a doorway with his arms folded, doing nothing at all with great professional skill.",
		"notes a pair of large, quiet men propping up the frame of a door, paid, by the look of them, to be in the way.",
	},
	["sw.muse.w19.rough.004"] = {
		"The rough end of the city is full of hired arms between contracts, sitting on steps, mending straps, waiting for some caravan master to need a frightening face.",
		"Sellswords in Old Town wait the way farmers wait for good weather: patiently, and ready to curse whatever comes.",
	},
	["sw.muse.w19.rough.005"] = {
		"The moneylenders of Old Town have the kindest smiles in the city. The interest is where they keep the rest of their face.",
		"In the rough quarter a loan comes with a handshake and someone who remembers it. The handshake is free. The remembering costs you every week.",
		"Borrow in Old Town and you'll never be lonely: someone will always know exactly where you are.",
	},
	["sw.muse.w19.rough.006"] = {
		"The poorest lanes are where a door is most often left open for a neighbor. Nobody in Old Town has much, and somehow everyone has a spare bowl.",
		"Rough streets, soft habits: a pot of soup passed over a wall, a child minded by whoever's in, a debt forgotten on purpose.",
	},
	["sw.muse.w19.rough.007"] = {
		"Keep your purse in front, your eyes up, and your opinions to yourself. That's the whole map of the rough end of town.",
		"Nice quarter. Lovely people. I'll be counting my fingers on the way out.",
		"Rough end of town. Walk as if you'd paid for the street.",
	},
	["sw.muse.w19.rough.008"] = {
		"pauses by a knife-grinder working his wheel at a corner, sparks spitting onto the cobbles, a queue of quiet customers holding things wrapped in cloth.",
		"watches a grinder pump his treadle at the mouth of a lane, putting an edge on a blade whose owner stands well back and says nothing.",
	},
	["sw.muse.w19.rough.009"] = {
		"Some rooms in the rough quarter are let in halves: a baker sleeps through one end of the clock, a watchman through the other, and the blanket never cools.",
		"Two lodgers, one bed, never awake in the same room. In Old Town that's not a riddle; it's the rent.",
	},
	["sw.muse.w19.rough.010"] = {
		"In a back room off an Old Town lane, a card game has been running so long that the players have changed and the deck hasn't.",
		"Card sharps in Old Town don't cheat, they'll tell you. They simply know the cards better than the cards know themselves.",
	},
	["sw.muse.w19.rough.011"] = {
		"sees two men shake hands a moment longer than friendship needs, and something small change pockets between them.",
		"catches the end of a handshake in a doorway, the kind that leaves one palm a little heavier, and both men walking off in opposite directions.",
	},
	["sw.muse.w19.rough.012"] = {
		"Every city keeps a corner for whatever it would rather not look at. Stormwind's is barely a canal away from the fine houses, which must make for awkward views.",
		"The rough quarter isn't at the edge of the city at all. It sits right in the middle, the way a sore tooth does.",
	},
	["sw.muse.w19.rough.013"] = {
		"Our capital likes to be seen from the gate, all white and blue. I trust it more after a walk through its rough end, where it stops posing.",
		"Proud as we are of this city, it's the patched corners I end up fond of: a kingdom with its sleeves rolled up.",
	},
	["sw.muse.w19.rough.014"] = {
		"watches a woman scrub her doorstep white in the dingiest lane of the quarter, then stand back, hands on hips, daring the street to dirty it.",
		"notices one spotless step in a row of grimy ones, and an old man sitting on it with a broom across his knees, guarding it.",
	},
	["sw.muse.w19.rough.015"] = {
		"Knuckles in the rough quarter tell stories: a letter on each, a tiny anchor from some port up north, a ring of ink where a real ring used to be.",
		"Half the hands in Old Town are inked. You learn not to ask about the names; some belong to people who would rather not be asked after.",
	},
	["sw.muse.w19.rough.016"] = {
		"Rough streets. Friendly enough, so long as you don't owe anyone money.",
		"I like these streets. Nobody pretends, and the soup's cheap.",
		"Rough quarter. Honest prices, dishonest dice.",
	},
	["sw.muse.w19.ruin.001"] = {
		"A crew digging a new drain hit a band of black earth a hand deep, the foreman told me, and every man stopped shoveling at once. They knew what it was. They loaded it into the cart without a word.",
		"Dig anywhere in Stormwind deeper than a cellar, the laborers say, and the spade comes up gray. They don't call it dirt. They call it the old city, and they're careful where they tip it.",
		"One of the drain diggers keeps a jar of that black layer on a shelf by his bed. The only piece of the first Stormwind he'll ever own, he says.",
	},
	["sw.muse.w19.ruin.002"] = {
		"stops beside a paving slab lifted for repair; the stone beneath it is darker and soot-stained, and the workman sets the new one down over it without a glance.",
		"watches a road-mender pry up a cracked cobble and pause at the blackened, older stone under it, before he tamps the fresh one into place on top.",
		"lingers by a gap in the street where the paving has been taken up and sees, under the fresh sand, a few old cobbles gone black as hearth bricks.",
	},
	["sw.muse.w19.ruin.003"] = {
		"Here in the keep a king was killed by someone he had let close. An old guard told me the post nearest that spot is the one nobody asks for, and everyone blames the draft.",
		"King Llane died inside these walls, the old guards say, though not these stones. They still lower their voices on one stretch of floor, and they'd deny it if you asked.",
	},
	["sw.muse.w19.ruin.004"] = {
		"People of a certain age in Stormwind say 'before' and leave it there. Before what, nobody asks. Anyone with gray hair knows.",
		"'That was before,' an old cooper said of a shop, a song, a whole street, and didn't finish. In this city, before needs no second half.",
		"There's a word the older folk here use without an ending: before. Before, the market was bigger. Before, the bread was cheaper. Nobody makes them say before what.",
	},
	["sw.muse.w19.ruin.005"] = {
		"Ask three old-timers where the fish market stood in the old city. Four answers and a shouting match.",
		"Every gray head in Stormwind can show you exactly where the old gate was. They all point different ways.",
	},
	["sw.muse.w19.ruin.006"] = {
		"A boatman showed me a coin he'd raked out of the canal mud, black as a beetle, minted under King Llane. He won't spend it. It's the one coin in Stormwind, he says, that owes nobody anything.",
		"Now and then the canal mud gives up an old coin from Llane's reign, warped by the fire. The boatmen keep them for luck and turn down every offer, however good.",
		"The boatmen have a name for the old coins the canals cough up: drowned crowns. Worthless at the bank, worth a good deal in a tavern if you tell it right.",
	},
	["sw.muse.w19.ruin.007"] = {
		"Hardly a wall in Stormwind is older than the burning. The oldest things here walk with canes.",
		"Young walls, this city. The truly old things sit on benches and feed the pigeons.",
		"Want to see what's left of the first Stormwind? Look at the faces on the benches, not the stone.",
	},
	["sw.muse.w19.ruin.008"] = {
		"glances up at the low ceiling, where one beam is charred black along its whole length, far older than the plaster around it, and kept anyway.",
		"notices that a crossbeam overhead is scorched deep into the grain, a survivor plainly older than the room, left in place by someone who knew good oak.",
	},
	["sw.muse.w19.ruin.009"] = {
		"Some of the old soldiers won't trust an envoy, any envoy, from anyone. A king of Stormwind was killed by someone he'd let into his own keep, and they learned that lesson on behalf of the whole city.",
		"Llane let someone close and died of it, the veterans say, and they've eyed every smiling visitor since. I can't call it wisdom. I can't quite call it wrong.",
	},
	["sw.muse.w19.ruin.010"] = {
		"falls in behind an old man who turns at corners that aren't there, following the streets of a city long gone, until he catches himself and takes the new way round.",
		"sees an elderly woman pause at a blank wall, as if a lane once ran straight through it, before she shakes her head and goes around.",
		"keeps pace for a while with a stooped old walker who slows at certain spots for no reason the street can show, as though stepping over thresholds that burned long ago.",
	},
	["sw.muse.w19.ruin.011"] = {
		"Orcs burned this city once, in a war fought by a Horde with no tauren in it and no Forsaken. The guards don't care about the difference. In their boots, neither would I.",
		"The scorch marks under the new stone were made by orcs, long before Thrall. Nobody here is going to listen to that distinction, and I can't blame them.",
	},
	["sw.muse.w19.ruin.012"] = {
		"In weather like this, an old boatman swears, the fog shows the towers of the first city for a moment, taller and thinner than the new ones. He says it as plainly as the price of a fare.",
		"Fog over the rooftops, and somewhere a gray head is telling a child that the old towers come back on days like this. The child is looking. So, a little, am I.",
	},
	["sw.muse.w19.ruin.013"] = {
		"Lovely city. The one underneath was lovely too, by all accounts.",
		"Everyone admires the new walls. The old folk are too polite to say they've watched better ones fall.",
		"Fine walls. The gray heads on that bench remember finer, mind, and they'll say so for a cup of something.",
	},
	["sw.muse.w19.ruin.014"] = {
		"The rubble of the old city didn't go anywhere, a builder told me. It went down: into the footings, the embankments, the cores of the thick walls. Stormwind stands on its own bones.",
		"Nobody carted the broken city away. They packed it into the foundations and built on top, an old laborer said, so every new wall rests on a piece of the one before.",
		"Where did the rubble go? Under my boots, the masons' crews would tell you. A city that wastes nothing, not even its own ruin.",
	},
	["sw.muse.w19.ruin.015"] = {
		"Humans in this city count the years from the burning, whether they mean to or not. Married five years after, the bakery opened twelve after. I catch myself doing it too.",
		"Among us, in Stormwind, the burning is the line every date is measured from. Ask an old human when something happened and the answer starts there.",
	},
	["sw.muse.w19.scar.001"] = {
		"pauses under an old archway whose underside still carries a brown bloom of soot, the kind no scrubbing lifts, high where the flames must have curled.",
		"glances up beneath an arch and finds a smudge of ancient smoke on the curve of its stones, faint as a thumbprint and just as stubborn.",
	},
	["sw.muse.w19.scar.002"] = {
		"In some of the oldest cellars the stones have gone pink, a laborer told me. Fire does that to stone. Tap one with a key and it rings flatter than its neighbors, like a voice that's done too much shouting.",
		"Burnt stone turns rosy and dull, the builders say, and sounds wrong when you knock on it. There are cellars in Stormwind where every wall gives that dead little note.",
	},
	["sw.muse.w19.scar.003"] = {
		"The gardeners say one of the old trees here carries a black seam deep in its bark from the burning, closed over long since. They point it out to nobody, but they water that one first.",
		"A gardener showed me a tree whose trunk folds around an old dark wound, healed into a long scar. Older than the walls around the Park, he says. It was here when the rest was ash.",
	},
	["sw.muse.w19.scar.004"] = {
		"sits for a moment on a stone bench and finds that its seat is a length of fluted column laid on its side, plainly part of something far grander once.",
		"rests a hand on a low bollard by the street and finds it carved with the curl of a capital, a piece of some old colonnade set to humbler work.",
		"notices that the step of a modest shop is a slab of carved cornice turned face down, its leaves and scrolls showing only along the worn edge.",
	},
	["sw.muse.w19.scar.005"] = {
		"One step on the approach to the keep is a different stone from the rest, darker and worn deeper. The guards say it's the one piece of the old keep the builders put back, on purpose, so every king would have to tread on it.",
		"Look closely at the keep's steps and one of them doesn't match: older, darker, hollowed by feet nobody remembers. Kept on purpose, the guards claim, so the new keep stands on the old.",
	},
	["sw.muse.w19.scar.006"] = {
		"notices an old iron hinge pin rusted to a stub in a newer doorframe, the door it once held long gone, the new stone fitted neatly around it.",
		"spots a lump of ancient iron sunk in the side of a doorway, holding nothing, the last of some hinge that outlived its door and was simply built around.",
	},
	["sw.muse.w19.scar.007"] = {
		"On the sill of an old window there's a hardened drip of lead, gray and puckered. The roofs ran like candle wax when the city burned, the old woman upstairs says, and nobody ever had the heart to chisel it off.",
		"A little frozen splash of metal on a ledge, the kind you'd scrape away without thinking. It's lead from the burning roofs, the neighbors say, and they'll scold you for touching it.",
	},
	["sw.muse.w19.scar.008"] = {
		"finds a row of scratched tally marks low on a dark old wall, dozens of them in fives, and nobody passing knows who was counting, or what.",
		"crouches by a weathered foundation stone covered in small scored lines in bundles of five, a count somebody kept long before this street had its name.",
	},
	["sw.muse.w19.scar.009"] = {
		"See those little square holes up the wall? Scaffold sockets from the rebuilding. The pigeons moved in early and never paid rent.",
		"Every big wall in Stormwind has a row of holes up top where the scaffolding sat. Now each one has a pigeon looking out like a lodger.",
		"The rebuilding left holes for the scaffold beams. The pigeons took them before the mortar dried. Best real estate in the city.",
	},
	["sw.muse.w19.scar.010"] = {
		"In rain like this, the locals say, one old wall in the city weeps soot: a gray streak runs down from a crack no mason has managed to close. They call it the old city crying, and laugh, and don't look at it.",
		"Rain on the old stonework, and here and there a thin dark trickle seeps out of the joints, ash still washing loose after all this time, if you believe the boatmen.",
	},
	["sw.muse.w19.scar.011"] = {
		"We humans don't throw away a burnt lintel. We turn it over, set the clean side facing out, and put it back over the door. Half the old houses in Stormwind wear their scars on the inside.",
		"My people kept every stone the fire left them, scorched or not. Turn the black face inward, set it again, keep going. That's the whole method, and the city stands on it.",
	},
	["sw.muse.w19.scar.012"] = {
		"That crack in the arch? The masons left it alone, I'm told. Something about letting the old wall have its say.",
		"Some cracks in Stormwind get mended. A few, the locals say, are left alone out of respect. Don't ask me which.",
		"Mind that crack. The old folk get touchy if anyone talks of filling it.",
	},
	["sw.muse.w19.scar.013"] = {
		"watches the dusk find the old scorched courses of a wall first, sinking them into dark while the newer stone above still holds the last of the light.",
		"sees the fading light leave the blackened lower stones of a wall well before the pale ones, as if the old city were the first to turn in.",
	},
	["sw.muse.w19.scar.014"] = {
		"Here in the Trade District a shopkeeper showed me the scorch mark on his doorstep and charged me nothing for the history. In this quarter, that's the rarest thing on offer.",
		"A cloth merchant keeps a blackened stone from the old city set into his counter. His customers rest their purses on it while they haggle. He claims it brings him luck, and his prices suggest it does.",
	},
	["sw.muse.w19.scar.015"] = {
		"By lamplight the patched walls show plainer than they do by day: pale new stone, dark old stone, set side by side like a quilt somebody kept mending instead of replacing.",
		"The lamps are lit, and the city's mends show: a dark square here, a pale stretch there, the whole of Stormwind patched like a coat worn through two wars.",
	},
	["sw.muse.w19.scar.016"] = {
		"Every burn mark in the Mage Quarter is either 'war' or 'lessons'. Nobody's ashamed of the war ones.",
		"Some of these scorches are orcs and some are apprentices. The apprentices' ones sit lower and come with an apology.",
		"Old burns, new burns. The locals can tell you which came from the orcs and which from a student. Different smell, they say.",
	},
	["sw.muse.w19.sentry.001"] = {
		"keeps an eye on a sentry's helmet bobbing along the top of the wall, showing in each gap of the battlements and vanishing behind each merlon, steady as a slow drum.",
		"follows a guard's helmet along the battlements above: there, gone, there, gone, the whole length of the wall.",
	},
	["sw.muse.w19.sentry.002"] = {
		"The guards at the gate never ask where you're from. They look at your boots, your pack and your hands, and by then they know.",
		"Nobody at the gate stops you with questions. The questions are in the way the guards' eyes drop to your hands and climb back up to your face.",
		"A gate guard's stare is a kind of ledger. You walk past it and find you've been written in.",
	},
	["sw.muse.w19.sentry.003"] = {
		"Ask a gate sentry how many carts came through since the last bell and he'll tell you. Ask how many people and he'll tell you that too, and which ones he didn't like.",
		"Gate guards keep a tally in their heads. I asked one for it. Forty-one carts, he said, and one of them is lying about the turnips.",
	},
	["sw.muse.w19.sentry.004"] = {
		"catches a gate sentry easing the weight from one leg to the other the moment the sergeant's back is turned, then snapping still as the sergeant turns round.",
		"notices a guard at the gate flex the fingers of one gauntlet, slowly, as if counting them, without moving anything else at all.",
	},
	["sw.muse.w19.sentry.005"] = {
		"The sentries on the walls spend the whole watch with their backs to the city they guard. They know it by its noise, the way you know a friend's voice from the next room.",
		"A wall sentry looks outward all watch long. Everything they protect is behind them, heard and never seen. That takes a kind of trust all its own.",
		"Up on the walls the city is a sound at your back: carts, bells, someone laughing in a yard. The sentries' job is to keep facing the other way.",
	},
	["sw.muse.w19.sentry.006"] = {
		"squints up through the storm at the wall, where the sentries stand hunched in their cloaks between the merlons, still at their posts and plainly regretting it.",
		"sees a sentry on the battlements tuck his chin into his collar as the storm throws water across the stones by the bucketful.",
	},
	["sw.muse.w19.sentry.007"] = {
		"Watch the foot of the wall long enough and you'll see a basket go up on a rope: bread, a jug, a note. Even the sentries of Stormwind have someone who remembers lunch.",
		"A basket on a long rope, hauled hand over hand up the face of the wall. Somewhere above, a sentry's supper has arrived, and the whole tower cheers in a whisper.",
	},
	["sw.muse.w19.sentry.008"] = {
		"Quiet at the gate? Good. May it bore you senseless till the bell.",
		"Long watch, friend? The wall will still be here when you're relieved. So will you, with luck.",
	},
	["sw.muse.w19.sentry.009"] = {
		"Now and then a call goes along the walls, tower to tower, too far off to make out. All's well, I assume. Nobody runs, so it must be.",
		"A shout from one tower, an answer from the next, and the next: a long relay going round the city above the roofs. Nobody in the street even looks up.",
		"The calls along the wall come round like the hand of a slow clock. You stop hearing them, until one comes late.",
	},
	["sw.muse.w19.sentry.010"] = {
		"Past the gate guards without a second look. Either the hood is doing its work, or Stormwind's watch is saving its suspicion for someone more interesting.",
		"Every sentry I pass is a coin toss I keep winning. I try not to think about how many coins are left.",
	},
	["sw.muse.w19.sentry.011"] = {
		"steps aside as the gate guards come to attention for a weary company marching in, mud to the knees, and an officer too tired to make it crisp returns the salute.",
		"watches the sentries at the gate snap their halberds upright as a mud-spattered troop of soldiers files in, and the soldiers barely manage to look up.",
	},
	["sw.muse.w19.sentry.012"] = {
		"Somebody on the walls is whistling the same four notes over and over. By the hundredth time I'd have pushed him off; his sergeant must have endless patience.",
		"A tune drifts down from the ramparts, a sentry whistling to stay awake. It's always the same tune, and it's always flat.",
	},
	["sw.muse.w19.sentry.013"] = {
		"passes the gate under the night lamps, where the sentries' faces come and go in the light like coins turned over in a hand.",
		"walks by the night watch at the gate, two figures with lamplight on their helmets and the dark road behind them.",
	},
	["sw.muse.w19.sentry.014"] = {
		"looks on as a gate guard lifts the canvas on a wagon with the butt of a halberd, peers underneath at a load of cabbages, and waves it on with deep disappointment.",
		"waits while a sentry prods a pile of sacks on a cart, the carter rolling his eyes at the sky as if this happens every trip. It probably does.",
	},
	["sw.muse.w19.sentry.015"] = {
		"Watch the gate long enough and you can rank all of Stormwind by the guards' salutes: a nod for farmers, a straight back for soldiers, a clatter of halberds for any carriage with a crest on the door.",
		"The gate sentries have a whole grammar of greeting. Carters get a grunt, pilgrims a nod, and a noble's carriage a salute so sharp you could slice bread with it.",
		"I've learned more about the ranks of this city from how the guards at the gate stand than from any herald.",
	},
	["sw.muse.w19.sentry.016"] = {
		"A sentry told me that from the highest tower on the wall you can watch the forest roll all the way to the hills, and that after a month of it you stop looking. I'd like the month.",
		"Nobody in Stormwind sees further than the tower guards. Ask them what they look at, though, and it's always the same list: the road, the carts, the sky, and the clock in their heads.",
	},
	["sw.muse.w19.sentry.017"] = {
		"You, up on the wall! Anything coming? No? Lucky you, then.",
		"Quiet out on the road? Shout down if it isn't, will you?",
	},
	["sw.muse.w19.sigil.001"] = {
		"Someone draws chalk circles on certain doorsteps in the quarter, and someone else scrubs them off. However often I pass through, I've never caught either of them at it.",
		"Fresh chalk on a doorstep: a circle, three marks inside. By the next bell it's washed away and the step is still wet. A quiet argument, fought in chalk and water.",
	},
	["sw.muse.w19.sigil.002"] = {
		"Some doors in the quarter carry a little carved sign above the latch. Ask what it does and you'll get a pleasant smile that means: nothing you need to know about.",
		"A small sign cut into the frame beside a door handle, worn smooth by thumbs. Whatever it guards, the household touches it going in and coming out, out of habit.",
		"The carved signs on the doors near the tower are all slightly different, like the knockers on a street of fine houses. Each family, it seems, has its own way of saying keep out.",
	},
	["sw.muse.w19.sigil.003"] = {
		"watches a little girl chalk a mage's sign onto a wall, tongue between her teeth, then step back and wait. Nothing happens. She looks relieved, and then very let down.",
		"pauses beside a row of children copying the mages' signs onto a wall in chalk, all of them squinting at their work as though it might hatch.",
	},
	["sw.muse.w19.sigil.004"] = {
		"The City Watch carries a list of signs to report if they turn up on a wall, a guard told me. Not one of them knows what the signs mean, which I suspect is the point.",
		"In a guardhouse somewhere, the guards say, hangs a sheet of strange marks copied out by a mage, with one instruction underneath: if you see this, fetch someone. Don't read it aloud.",
		"A guard once showed me the back of his hand, covered in signs copied from a wall in ink so he could report them properly. He'd been scrubbing at it for three days.",
	},
	["sw.muse.w19.sigil.005"] = {
		"Under the Lamb, they whisper, there's a circle on the floor that nobody is allowed to scrub. The charwomen of the quarter will clean anything else in Stormwind, at half the price.",
		"Below the Slaughtered Lamb, the rumor goes, lies a ring drawn on stone that is older than the tavern. The tavern was built around it. Nobody says by whom.",
		"Ask about the cellar floor of the Lamb and the answers all agree on one thing only: whatever is drawn there, it was not drawn by anybody who still drinks upstairs.",
	},
	["sw.muse.w19.sigil.006"] = {
		"notices a small mark scratched into the stone beside a door, a circle crossed twice, and keeps {g:his|her} hands to {g:himself|herself}.",
		"pauses at a doorframe carved with a tiny crossed circle, half reaches toward it, then draws the hand back.",
		"lets {g:his|her} eyes rest on a mark scratched beside a lintel, and walks on with both hands kept well away from it.",
	},
	["sw.muse.w19.sigil.007"] = {
		"Whatever that mark on the door means, I'll knock somewhere else.",
		"Funny little sign on that door. I'll admire it from here.",
		"Chalk circle on the step. I'll take the next house, thanks.",
	},
	["sw.muse.w19.sigil.008"] = {
		"Everywhere else a shop hangs a boot or a loaf over its door. In the Mage Quarter, a symbol, and you're expected to know.",
		"Three dots and a bar on a sign. Is that a shoemaker or the end of the world?",
		"Ring with a tail over the door. I'm told that means 'candles'. I'm told a lot of things.",
	},
	["sw.muse.w19.sigil.009"] = {
		"When a mage of the tower dies, the apprentices are said to draw one last sign on the door of the empty room. Nobody opens that door for a year, and nobody asks why.",
		"A door in the quarter with a sign drawn on it in silver and a strip of black cloth on the handle. A mage's room, the neighbors say. It will stay shut until the year turns.",
	},
	["sw.muse.w19.sigil.010"] = {
		"At dusk the signs on certain doors begin to glow, faint as embers, and the people of the quarter walk home by them as if by lamps.",
		"As the light fails, small marks on the doorframes of the quarter wake one by one, a pale silver, and the street finds its way by them.",
	},
	["sw.muse.w19.sigil.011"] = {
		"A rune cut in stone, now that's a promise. These human signs in chalk and ink, gone in a week? Promises made over ale.",
		"Give me a rune hammered into good granite. The mages draw theirs in ink and then wonder why a dwarf won't lean on their doorframes.",
		"Ink fades, chalk smears. If the mages of Stormwind want their signs to outlast them, they know where to find a dwarf with a chisel.",
	},
	["sw.muse.w19.sigil.012"] = {
		"Human mages draw their circles freehand and call it tradition. A gnome would use a compass, finish in half the time, and the circle would actually be round.",
		"I measured one of the mages' chalk circles in the street. Off true by a full finger's width. It works anyway, somehow, and that offends me on principle.",
	},
	["sw.muse.w19.sigil.013"] = {
		"follows with {g:his|her} eyes a street sweeper working the length of the lane with great care, lifting the broom clean over every mark drawn on the cobbles.",
		"notices how the sweepers of {subzone} leave little islands of dust around the signs chalked on the stones, sweeping right up to them and no further.",
	},
	["sw.muse.w19.sigil.014"] = {
		"With every flash of the storm, lines show for an instant on the walls of the mages' tower, a whole script nobody sees by daylight, gone again before the thunder.",
		"Lightning over the quarter, and in its white glare the tower is written all over, top to bottom. Then dark, plain stone, and the rumble rolling away over the roofs.",
	},
	["sw.muse.w19.skies.001"] = {
		"Rain on slate sounds thinner than rain on thatch, sharper, like a crowd of very small people applauding politely.",
		"Listen to it on these roofs. Slate doesn't drum the way thatch does; it ticks, like a clerk counting out coppers.",
		"The rain has found every roof in Stormwind and is going over them slate by slate, like a tax inspector.",
	},
	["sw.muse.w19.skies.002"] = {
		"listens to the rain find its way through some loose slate overhead and drip into a bucket set out long ago, with a steady, tinny note.",
		"keeps half an eye on a pot on the floor catching the drip from a leak in the ceiling, the plink of each drop keeping time under the murmur of the room.",
	},
	["sw.muse.w19.skies.003"] = {
		"Each roll of thunder goes over the city like a loaded cart across a wooden bridge, slow and heavy, and the window glass hums after it.",
		"The thunder here bounces. It hits the walls, comes back off the towers, and arrives three times, each one a little more tired.",
	},
	["sw.muse.w19.skies.004"] = {
		"blinks as a flash of lightning lays the whole city bare for an instant, every slate and spire drawn in white, and then takes it all back.",
		"is caught mid-step by a flash that turns the streets white as paper, and in the dark that follows counts, half aloud, until the thunder comes.",
	},
	["sw.muse.w19.skies.005"] = {
		"They named the place Stormwind. I don't know why everyone looks so surprised.",
		"Storm over Stormwind. Whoever named this city was very honest.",
		"Proper Stormwind weather, this. At last the name makes sense.",
	},
	["sw.muse.w19.skies.006"] = {
		"The fog settles on everything in small cold beads: cloaks, railings, the whiskers of a cat in a doorway. Stormwind has gone soft at the edges and damp all through.",
		"In fog the city smells stronger. Bread, smoke, the canals, all of it hanging in the air with nowhere to go.",
	},
	["sw.muse.w19.skies.007"] = {
		"Fog like this, I'd keep a hand on my purse. Lovely weather for pickpockets.",
		"Fog this thick, every cutpurse in the city just got a holiday.",
		"Where did the street go? It was here a minute ago.",
	},
	["sw.muse.w19.skies.008"] = {
		"Swifts are out over the rooftops, screaming in tight circles around the towers. A clear sky makes the whole city feel a size larger.",
		"Not a cloud. The washing on every line will be dry before the next bell, and every cat in Stormwind has found a warm slate to lie on.",
	},
	["sw.muse.w19.skies.009"] = {
		"watches the first light touch only the very tops of the towers, a few high windows flashing gold while the streets below are still gray and yawning.",
		"sees dawn reach the weathervanes first, then the slates, then the upper windows, as though the city were being dressed from the hat down.",
	},
	["sw.muse.w19.skies.010"] = {
		"Dusk, and every kitchen in Stormwind is going at once. Onions, mostly. The whole city smells like a stew that hasn't decided what it is.",
		"As the light goes, the smell of suppers rises from every chimney and doorway: onions, mutton, a hint of burned fat. Stormwind cooks for itself at last.",
	},
	["sw.muse.w19.skies.011"] = {
		"Somebody ought to put a roof over this whole city. The dwarves would know how.",
		"All this fine stonework, and not one of them thought to cover the streets.",
	},
	["sw.muse.w19.skies.012"] = {
		"The moon is resting on one of the high spires as if somebody had balanced it there and backed away very carefully.",
		"A big pale moon over the rooftops, bright enough to make the slates shine like wet fish.",
		"The stars over Stormwind are fewer than over Elwynn; the lamps talk most of them out of showing up. The moon, at least, refuses to be outshone.",
	},
	["sw.muse.w19.skies.013"] = {
		"watches two children race scraps of wood down a gutter swollen with rain, shrieking as one boat vanishes into a drain and the other sails on to glory.",
		"stops to see a pair of children chase a walnut shell down the running gutter, the rain plastering their hair flat, both of them perfectly happy.",
	},
	["sw.muse.w19.skies.014"] = {
		"Every loose shutter and badly hung sign in the city has been waiting for a storm like this one. They're all saying so at once.",
		"In a storm you learn which shop signs were nailed up properly. Most of them, it turns out, were not.",
	},
	["sw.muse.w19.soot.001"] = {
		"Stormwind's white stone stops being white about ten paces into the Dwarven District. The masons gave up scrubbing long ago.",
		"Every wall in the Dwarven District wears a smudge at the height of a dwarf's shoulder, where a thousand sooty shoulders have leaned. Nobody cleans it; it would only come back.",
	},
	["sw.muse.w19.soot.002"] = {
		"brushes a smudge of soot off a sleeve, considers it, and gives up: in the Dwarven District the coat will only collect more.",
		"notices a fine dark dust settling on both sleeves and rubs at it, which spreads it into a neat gray stripe.",
	},
	["sw.muse.w19.soot.003"] = {
		"From almost anywhere in Stormwind you can find the Dwarven District by its smoke, a dark thread standing over the roofs. Lost travelers follow it like a road.",
		"The forges send up a thin dark column the whole city can steer by. Ask a child the way to the tram and the child just points at the smoke.",
		"A dozen towers to steer by in Stormwind, and one smudge of smoke. Strangers ask for the towers; the locals point at the smudge.",
	},
	["sw.muse.w19.soot.004"] = {
		"Wear dark colors to the Dwarven District. It will darken them anyway, but this saves time.",
		"Anything pale that goes into the Dwarven District comes out the color of a forge. Dress accordingly.",
	},
	["sw.muse.w19.soot.005"] = {
		"passes a dwarf coming off a shift at the forge, black to the eyebrows except for two pale rings where the goggles sat, and has to look away to keep from smiling.",
		"meets a gnome stepping out of a workshop with a perfect clean mask around the eyes where the goggles were, and the rest of her the color of a chimney.",
	},
	["sw.muse.w19.soot.006"] = {
		"The soot in the mortar of the oldest forges lies in layers, like the rings of a tree. Near the bottom is the first fire anyone lit there after the rebuilding.",
		"Scrape the black off a forge wall in the Dwarven District and there's more black underneath, years of it, all the way back to the first fire lit in the new city.",
	},
	["sw.muse.w19.soot.007"] = {
		"Every so often a noble petitions the court to move the forges outside the walls, for the smoke. The petition goes to a clerk, the clerk goes to a dwarf for a new lock, and that's the end of it.",
		"The nobles upwind complain about the forge smoke. The nobles downwind complain louder. The dwarves keep hammering, having heard worse from better.",
		"One noble family sends a letter about the smoke every season. The dwarves of the Dwarven District have kept every one, they say, and use them to light the forges.",
	},
	["sw.muse.w19.soot.008"] = {
		"The Dwarven District is always a shade dimmer than the rest of Stormwind, as if it had drawn a curtain. After the shine of the Trade District, the eyes are grateful.",
		"Walking into the Dwarven District is like stepping into the shade of a big tree, except the tree is made of smoke and smells of coal.",
	},
	["sw.muse.w19.soot.009"] = {
		"Ten minutes in the Dwarven District and I can taste the coal. The dwarves say you stop noticing. The dwarves would.",
		"Coal dust in my collar, coal dust on my tongue. This district gets into you, grain by grain.",
		"I've been here a quarter of an hour and I'm already a shade darker. Give me a week and I'll pass for a smith.",
	},
	["sw.muse.w19.soot.010"] = {
		"Some old soldiers in the street look up at the forge smoke a moment too long. This city once saw a different kind of smoke over its roofs, and some people remember.",
		"A column of smoke over Stormwind means work now: forges, bread, a gnome's mistake. There are gray heads in this city who had to learn that, slowly.",
	},
	["sw.muse.w19.soot.011"] = {
		"waits inside a smithy door while the smith works, the walls as black as the inside of a pot and hung with tongs, each one inside its own outline painted on the stone.",
		"glances round a dwarf's smithy, where every tool hangs on the black wall within a pale painted outline of itself, and one outline stands empty.",
	},
	["sw.muse.w19.soot.012"] = {
		"Soot under the fingernails is a dwarf's idea of clean. Humans scrub it off and wonder why we laugh.",
		"A human just handed me a cloth for my face, very kindly. I thanked them and put it in my pocket. The soot stays; it's honest.",
	},
	["sw.muse.w19.soot.013"] = {
		"Even the city guard looks dustier on the Dwarven District rounds. A tabard goes in blue and gold and comes out the color of a coal scuttle.",
		"You can tell which guards draw the forge streets: their tabards are a tired sort of blue, and they've stopped minding.",
	},
	["sw.muse.w19.soot.014"] = {
		"watches the rain run black off the eaves of the Dwarven District, carrying the soot of the forges down to the gutters in thin dark ribbons.",
		"stands under an eave while the rain washes the district's soot into the gutters, the water running the color of strong tea toward the canal.",
	},
	["sw.muse.w19.soot.015"] = {
		"Engineering smells of hot oil, singed hair and blasting powder. In the Dwarven District you learn to tell them apart, and to worry about the third.",
		"The Dwarven District has its own perfume: lamp oil, coal, and the sharp black reek of blasting powder that makes every dwarf look round to see who's holding it.",
		"Coal smoke means a forge, oil smoke means a gnome, and blue smoke means you should already be somewhere else. Every child in the Dwarven District knows the colors.",
	},
	["sw.muse.w19.soot.016"] = {
		"At the end of the forge row stands a trough where the smiths wash, in water so black it looks like ink. Their hands come out no cleaner; they say it's about the gesture.",
		"The water in the dwarves' rinsing trough is never anything but black. Washing, one told me, is how you tell the forge you're done.",
	},
	["sw.muse.w19.spire.001"] = {
		"Three times I've counted the windows on that tower. Three different numbers. I'm done counting.",
		"That tower has either thirty windows or thirty-four, depending on who counts and, I suspect, on its mood.",
		"Count the windows on that tower. Go on. Then count them a second time and tell me I'm wrong.",
	},
	["sw.muse.w19.spire.002"] = {
		"looks up at the Wizard's Sanctum just as a curtain at one of its highest windows twitches shut.",
		"glances up at the mages' tower and catches a shape at a window near the top, watching the street, before it steps back out of sight.",
		"notices a small light moving from window to window up the side of the tower, as if someone were climbing the stairs with a lamp, and loses it near the top.",
	},
	["sw.muse.w19.spire.003"] = {
		"People walk into the Wizard's Sanctum and don't always walk out of its door. The mages call that a portal. The guard at the corner who counts heads calls it a nuisance.",
		"Somebody climbs the stairs of the Sanctum and, as far as the street can tell, never comes down. Off to Ironforge in a blink, the apprentices say, as if that were an ordinary way to leave a building.",
		"Seven people went into the tower while I stood across the way, and four came out. Nobody else in the street was counting, which tells me everything about how normal that is.",
	},
	["sw.muse.w19.spire.004"] = {
		"The apprentices swear the stairs of the Wizard's Sanctum are longer going up than coming down. They're the ones carrying the books, so I believe them.",
		"Ask an apprentice how many steps the tower has and you'll get a groan long before you get a number.",
		"An apprentice comes out of the tower red in the face, carrying nothing at all, and sits down on the bottom step as if it had been a very long way.",
	},
	["sw.muse.w19.spire.005"] = {
		"With the sun on it, the tower lays a long finger of shade across the rooftops, and all day it creeps round the quarter like the gnomon of a sundial the size of a district.",
		"By day the shadow of the mages' tower walks the roofs of the quarter, slow as a cat, one house after another, never stopping anywhere for long.",
	},
	["sw.muse.w19.spire.006"] = {
		"The door of the Wizard's Sanctum is never locked, they say in the quarter. It doesn't need to be: everyone inside knows who opened it before the latch has dropped.",
		"No bar on the mages' door, no bolt, no guard to speak of. The neighbors say the house always knows who has come in, and that this is worse than any lock.",
		"A thief who drinks in Old Town told me he'd rob the keep before the tower. The keep, at least, only has guards.",
	},
	["sw.muse.w19.spire.007"] = {
		"At night the top of the tower glows faintly, and moths come up from the canals to climb it, a slow gray spiral that never reaches the light.",
		"After dark, moths rise from every corner of the quarter and wind up the tower in a loose spiral, toward a violet they never quite reach.",
	},
	["sw.muse.w19.spire.008"] = {
		"From the right corner you can see the cathedral's towers and the mages' tower at once: two ways of asking the world for more than it gives.",
		"The Cathedral and the Wizard's Sanctum share a skyline and seldom mention each other. One of them asks. The other studies how to take.",
	},
	["sw.muse.w19.spire.009"] = {
		"If that tower ever falls over, it'll be on purpose, and somebody will write a treatise about it.",
		"Somebody ought to measure that tower. Somebody probably has, and got an answer they didn't like.",
		"That tower's been leaning a hair to the left. Or I have. Hard to say on this street.",
	},
	["sw.muse.w19.spire.010"] = {
		"In this fog the mages' tower disappears from the bottom up, until only the violet at its top is left, hanging over the city like a lamp nobody is holding.",
		"Fog has swallowed the tower to the shoulders. What's left floats above the rooftops, a violet smudge with nothing underneath it.",
	},
	["sw.muse.w19.spire.011"] = {
		"Rain sheets down the mages' tower, and near the top it seems to think better of it and go somewhere else.",
		"Every roof in the quarter is streaming with rain. The very tip of the tower is dry. I've stopped expecting anyone to explain.",
	},
	["sw.muse.w19.spire.012"] = {
		"cranes {g:his|her} neck to follow the mages' tower up past the rooftops, and has to look away before reaching the top.",
		"tips {g:his|her} head back to take in the whole height of the Wizard's Sanctum, then rubs the back of {g:his|her} neck and gives it up halfway.",
		"follows a pair of crows up the length of the mages' tower until they veer off, well short of the top, as if they had thought better of it.",
	},
	["sw.muse.w19.spire.013"] = {
		"Here in the Mage Quarter everyone gives directions from the tower: two streets past it, left of it, under it if you're unlucky.",
		"Ask the way here and every answer starts with the tower. Behind the tower, beside the tower. In the Mage Quarter it's the only compass anyone trusts.",
		"Every street here bends a little toward the tower, the way plants bend toward a window. Nobody in the quarter can say whether it was meant.",
	},
	["sw.muse.w19.spire.014"] = {
		"The mages in that tower are Stormwind's own sons and daughters in violet. When they get it right, the kingdom stands taller; when they get it wrong, it's our street that smokes.",
		"Humans have always reached a little too far. The tower is just the part of us that does it on purpose, and takes notes.",
	},
	["sw.muse.w19.spy.001"] = {
		"Ask three people in Old Town where SI:7 keeps its door. One points, one shrugs, and one asks why you'd like to know. The third is the one to remember.",
		"There's an easy way to find SI:7: ask about it loudly in Old Town and wait. It finds you, usually before the end of the street.",
		"In Old Town the question of where SI:7 might be is answered mostly by people taking a sudden interest in their shoes.",
	},
	["sw.muse.w19.spy.002"] = {
		"notices a man in a plain coat reading a posted notice for far longer than it could take anyone to read it, and moves on before he finishes.",
		"passes a fellow studying a bill nailed to a post with great devotion. It announces a lost goat. He has been on it a long while.",
	},
	["sw.muse.w19.spy.003"] = {
		"There's a doorway in Old Town that people walk past a little faster, eyes on the cobbles. Ask them why and they look honestly puzzled. Their feet know something they don't.",
		"Nobody in Old Town will tell you which door belongs to SI:7. Watch where the crowd speeds up without meaning to, though, and you have a fair guess.",
	},
	["sw.muse.w19.spy.004"] = {
		"SI:7? Never heard of it. That's the correct answer around here, I'm told.",
		"What's SI:7? Exactly. Nobody knows, and nobody asks twice.",
		"Spies? In Stormwind? I wouldn't know. Nobody would. That's the trick of it.",
	},
	["sw.muse.w19.spy.005"] = {
		"A man in Old Town has been mending the same cartwheel by the same wall for as long as anyone remembers, and the wheel never seems to get any rounder.",
		"One cartwheel, one wall, one patient man with a mallet, and the wheel no closer to finished. Somebody in Old Town is paid to look busy, and has the look perfected.",
	},
	["sw.muse.w19.spy.006"] = {
		"Old Town gossips about everyone, all day long. For a spy it must be like hiding in a flock of starlings: too much noise to pick out one voice.",
		"In a quarter where everybody whispers, one more whisper goes unnoticed. SI:7 could hardly have picked a better neighborhood.",
		"The best place to keep a secret is a street already full of them. Old Town is that street.",
	},
	["sw.muse.w19.spy.007"] = {
		"glances up at a window above the lane that stands open exactly a hand's width, no more and no less, as it has every time anyone looked.",
		"notices one shutter in a row of closed ones left ajar by a finger's gap, and the shadow of someone sitting very still behind it.",
	},
	["sw.muse.w19.spy.008"] = {
		"Every face in this city might be SI:7. Most aren't. Standing in the enemy's capital, 'most' is not a comforting word.",
		"Somewhere in Old Town there are people whose whole work is noticing someone like me. I keep my hood straight and my pace dull.",
	},
	["sw.muse.w19.spy.009"] = {
		"Children in Old Town play at SI:7, and the game never gets started: the first rule is that nobody may know who's playing.",
		"A pack of children were playing spies by the canal. The winner, they agreed, was whoever nobody could remember being there. The argument went on for a long time.",
	},
	["sw.muse.w19.spy.010"] = {
		"It must be a dull trade, the way SI:7 practices it: a doorway, a long wait, another doorway. The songs leave all that out.",
		"Spying, if Old Town's rumors are right, is mostly the art of being bored in public without looking bored.",
	},
	["sw.muse.w19.spy.011"] = {
		"With the king missing and a boy holding the seal, someone in this city still has to know things. I'd guess that someone works out of Old Town, and sleeps very little.",
		"An empty throne makes a kingdom nervous. Nervous kingdoms lean hardest on the people nobody sees, the ones behind the door in Old Town that isn't there.",
	},
	["sw.muse.w19.spy.012"] = {
		"hears three low whistled notes from somewhere above the lane, and a moment later an answering three from farther off. Nobody else in the street looks up.",
		"catches a short whistle from one rooftop and its echo from another, too neat to be a bird, and notices that the people around pretend not to have heard.",
	},
	["sw.muse.w19.spy.013"] = {
		"SI:7 keeps our kingdom safe; everybody says so. I'm grateful. I'd simply like to be grateful from the far side of the city.",
		"Our people built SI:7 so the rest of the kingdom could sleep. I sleep fine. I just don't linger in Old Town after asking awkward questions.",
	},
	["sw.muse.w19.spy.014"] = {
		"If anyone from SI:7 is listening: I'm on your side, and I tip well.",
		"Whoever's following me, you might as well carry my bags.",
		"If somebody's taking notes on me, write down that I greeted everyone nicely.",
	},
	["sw.muse.w19.spy.015"] = {
		"I passed someone on a corner a moment ago. Coat, hat, face. I can't recall a single thing about any of the three, which in Old Town is a description in itself.",
		"The most memorable thing about some folk in Old Town is how quickly they're forgotten. I suspect that takes years of practice.",
	},
	["sw.muse.w19.stall.001"] = {
		"Every shop in Stormwind has its own way of opening: a shutter banged up, a broom across the step, a cat let out, a kettle put on. You can learn a street by its opening noises.",
		"Shopkeepers open up in the same order every day: shutter, broom, sign, and then a long look up and down the street to see who else opened first.",
	},
	["sw.muse.w19.stall.002"] = {
		"Every shopkeeper in this city says 'for you, a special price'. I've yet to meet the person the regular price is for.",
		"'A special price, just for you.' I've heard it in four shops on one street. I'm starting to feel very special.",
		"Special price, special price. If everyone gets the special one, which poor soul pays the ordinary?",
	},
	["sw.muse.w19.stall.003"] = {
		"There's a chair by the hearth at the Gilded Rose that nobody sits in for long. Not because it's hard. Because it's soft, and the city has errands waiting.",
		"The best chair in the Gilded Rose is the one by the fire, and the trouble is that it knows it. Sit down for a moment and the moment goes soft at the edges.",
	},
	["sw.muse.w19.stall.004"] = {
		"stops to watch a shopkeeper chalk new prices on a board, rub one out with a sleeve, and chalk it in again a copper higher.",
		"lingers by a shop door where a hand-lettered board is being corrected for the third time, the chalk squeaking upward.",
	},
	["sw.muse.w19.stall.005"] = {
		"Here and there a shop stands shuttered under a faded sign. The neighbors say the owner went west to buy cheap grain and never came back up the road.",
		"On more than one street a shutter hasn't opened in a long while. Ask next door and you hear the same story: a cart to Westfall for cheap grain, and the road kept the cart.",
	},
	["sw.muse.w19.stall.006"] = {
		"Hot chestnuts in a twist of paper, a wedge of cheese and a cup of cider from a cart. Who needs an inn?",
		"Cheese from one cart, cider from the next, chestnuts from a boy with a brazier. Stormwind feeds you if you keep walking.",
	},
	["sw.muse.w19.stall.007"] = {
		"Shopkeepers here swear they can tell a buyer from a browser by how the bell over the door rings. A buyer pushes. A browser lets the door ask permission.",
		"Ask any shopkeeper: the little bell over the door tells the whole story. A hard jangle means coin; a timid tinkle means 'just looking'.",
		"A shopkeeper looks up at the jangle of the door and has already decided: buyer, browser or thief. Rarely wrong, and never about the thief.",
	},
	["sw.muse.w19.stall.008"] = {
		"pauses at a shop window, where a single pair of fine gloves lies on velvet with no price on it at all, which says everything about the price.",
		"drifts past a window showing one silver ring on a cushion and no tag, the surest sign of a price nobody should ask.",
	},
	["sw.muse.w19.stall.009"] = {
		"Behind half the counters in Stormwind there's a child doing sums on a slate, learning the family trade the slow way, one sum after another.",
		"A shopkeeper's daughter sits on the counter adding up a customer's bill on her fingers, faster than her father with his ledger. That shop will be in good hands.",
	},
	["sw.muse.w19.stall.010"] = {
		"Whatever else fails in a city full of travelers, the cobblers never go short. The world eats boots first.",
		"The cobblers must be the richest folk in Stormwind. Every road in the kingdom chews through soles and sends the bill to their benches.",
	},
	["sw.muse.w19.stall.011"] = {
		"Never trust a shop with dust on the counter. Never trust one without any, either. Stormwind has plenty of both.",
		"Dusty counter, sleepy seller. Spotless counter, sharp seller. Pick your danger.",
		"Clean shop, clever seller. Dusty shop, lazy seller. Either way, count your change.",
	},
	["sw.muse.w19.stall.012"] = {
		"ducks under a low striped awning and comes out the other side being offered a hat.",
		"sidesteps a stack of baskets spilling into the street, then a second stack, then a shopkeeper who seems to have been waiting for exactly this.",
	},
	["sw.muse.w19.stall.013"] = {
		"Some shopkeepers in the Trade District still have Lordaeron in their voices. They don't talk about the shops they left behind; they just keep the new ones very clean.",
		"You hear northern accents behind a few counters, folk who kept shops in Lordaeron before the plague. They never mention them. Their counters shine as if polishing could keep anything from happening twice.",
	},
	["sw.muse.w19.stall.014"] = {
		"A chandler's shop smells the same in every age of the world: tallow, wick and patience. Kings come and go; the candles don't notice.",
		"Walk past a candlemaker's door and you're nowhere in particular, in no year at all. Wax has never cared who sits on the throne.",
	},
	["sw.muse.w19.stall.015"] = {
		"Not one merchant in this city has asked where my coin was minted. Gold doesn't pick sides. I'd better not admire that too much.",
		"The shopkeepers smile at me as they would at anyone. As long as the coin is good, so am I. A strange thing to learn behind enemy walls.",
	},
	["sw.muse.w19.stall.016"] = {
		"turns an apple over at a fruit stall, looking for the bruise, and finds the stallkeeper's eye already on it.",
		"lifts a pear from a heap to check its underside, meets the seller's flat stare, and sets it back exactly where it was.",
	},
	["sw.muse.w19.stall.017"] = {
		"passes a row of travelers' boots set out by an inn door to be cleaned, muddy toes all pointing at the street as if eager to leave.",
		"glances at the line of boots left outside an inn for the boot boy, each pair caked in the dirt of a different road.",
	},
	["sw.muse.w19.stall.018"] = {
		"is offered a sliver of cheese on the point of a knife by a cheesemonger who seems to have picked {g:him|her} out of the whole crowd.",
		"finds a sample of smoked sausage held out under {g:his|her} nose by a stallholder with the patient smile of someone who knows how this ends.",
	},
	["sw.muse.w19.statue.001"] = {
		"The pigeons have worked out what the sculptors never meant: a stone hero has very good shoulders for sitting on.",
		"Whatever the statues in the valley were raised to remember, the pigeons have their own opinion, and they leave it on the helmets.",
		"Every statue in the valley wears a pigeon or two like a badge of office. The heroes never complain; it's the one thing they share with the guards.",
	},
	["sw.muse.w19.statue.002"] = {
		"Stand under any of the great statues long enough and you'll hear two travelers name it differently, and a third tell them both they're wrong. The statue has never once settled the argument.",
		"Ask three people at the gate who the stone figure on the left is meant to be and you'll get three names and a quarrel. I've stopped asking; I like the quarrel better.",
		"Nobody agrees on the names of the statues by the gate, which suits the city: any grandfather in Stormwind can point at one and swear he served under it.",
	},
	["sw.muse.w19.statue.003"] = {
		"stops at the foot of a statue and studies the chisel marks along the hem of its stone cloak, each one small, patient and exactly where it should be.",
		"looks past the stern stone face to the plinth, where some mason left the faint grooves of a chisel nobody was ever meant to notice.",
		"crouches to look at the base of a statue, where the stone boot meets the plinth so cleanly that it is hard to say where one carver stopped and the next began.",
	},
	["sw.muse.w19.statue.004"] = {
		"Best seat in the city: the step of a statue's plinth. Free, and the company never interrupts.",
		"I've eaten lunch at the feet of a hero. The hero didn't ask for a bite, which is more than I can say for the guards.",
	},
	["sw.muse.w19.statue.005"] = {
		"None of the statues looks down at the road. Their eyes are fixed somewhere over the crowd, on whatever the sculptors thought a hero ought to be looking at.",
		"The great figures along the bridge never meet anyone's eye. They look past the crowd, far off, as if they had somewhere better to be and were too polite to say.",
		"Nobody has ever caught a statue's gaze in the Valley of Heroes. They stare over every head at something the rest of the city can't see.",
	},
	["sw.muse.w19.statue.006"] = {
		"There's an old soldier who crosses the bridge most days and never once looks up at the statues. Whatever he knows about heroes, he isn't telling them.",
		"Most people slow down under the great statues. I watched a man with a soldier's limp speed up instead, eyes on the paving, as if one of them might call his name.",
		"The statues mean one thing to people who've read about heroes and another to people who stood next to a few. You can tell the difference by who looks up.",
	},
	["sw.muse.w19.statue.007"] = {
		"watches a child dash up onto a plinth, slap a stone boot for luck and sprint off before the nearest guard can finish frowning.",
		"notices one toe of a great stone boot worn bright and smooth, polished by every passing hand that wanted a little luck from it.",
	},
	["sw.muse.w19.statue.008"] = {
		"Walk close enough to the statues and the heroes disappear. What's left is a very large boot, a very long shin and the underside of a chin.",
		"From the road you see a hero. From the foot of the plinth you see mostly knee. Greatness, it turns out, depends on where you stand.",
		"Those statues were made to be seen from the far end of the bridge. Up close, a hero is mostly a tremendous belt buckle.",
	},
	["sw.muse.w19.statue.009"] = {
		"Lichen has started in the folds of the statues' cloaks, a pale green that will take a lifetime to reach the shoulders. Stone ages too; it just isn't in a hurry.",
		"There's moss in the crook of a stone elbow by the gate. Give it long enough and the heroes will wear green whether the city likes it or not.",
	},
	["sw.muse.w19.statue.010"] = {
		"I always nod to the statues on the way past. Somebody should, and they've earned a nod.",
		"My respects, all of you up there. Whoever you were.",
		"Don't mind me, I'm only passing through. You lot carry on looking grand.",
	},
	["sw.muse.w19.statue.011"] = {
		"Somebody leaves flowers at the foot of one plinth, always the same one. I've never seen who. The statue doesn't say either.",
		"Fresh flowers at the base of one statue, tied with string, no note. Whoever brings them doesn't need the city to know which hero they mourn.",
		"Under one statue there's a little heap of things nobody touches: a flower gone brown, a button, a folded scrap of paper. The sweepers go around it.",
	},
	["sw.muse.w19.statue.012"] = {
		"walks through the long shadows the statues lay across the bridge, cool, warm, cool, warm, like passing a row of open doors.",
		"steps from one statue's shadow into the sunlight and back into the next, the bridge striped with the shapes of heroes.",
	},
	["sw.muse.w19.statue.013"] = {
		"Fair work on the statues, I'll grant the humans that. The joints at the ankles are clean. Whoever cut them had a dwarf's patience and a human's hurry, and the patience won.",
		"I've spent longer than I'd admit studying how the statues sit on their plinths. No pins that I can see. Good stone, set true. Somebody in this city learned from the right people.",
	},
	["sw.muse.w19.statue.014"] = {
		"Huge stone figures on both sides of the bridge, the heroes of the people whose capital I'm walking through. I keep my eyes down. Statues don't report to guards, but I'm taking no chances.",
		"Every statue here probably earned its fame against the Horde. I keep a polite pace beneath them and count how far it is to the other end.",
	},
	["sw.muse.w19.statue.015"] = {
		"Somebody's job in this city is to climb a ladder and wash the face of a hero. I hope they're paid by the face.",
		"There was a man on a ladder by the gate, scrubbing a stone nose with a brush and a bucket. Glory needs upkeep, like everything else.",
		"Even heroes need their faces washed. In Stormwind that takes a ladder, a bucket and one very patient man.",
	},
	["sw.muse.w19.statue.016"] = {
		"watches the rain run down a great stone face and drip steadily from its chin, as if the hero had just been given some bad news.",
		"watches rainwater gather in the folds of a statue's stone cloak and spill from the hem in a thin, patient stream onto the plinth.",
	},
	["sw.muse.w19.statue.017"] = {
		"Big, aren't they? I always feel I ought to apologize for something when I walk underneath.",
		"Every time I pass under those statues I check my boots are clean. Nobody told me to. They just look like they'd notice.",
	},
	["sw.muse.w19.steps.001"] = {
		"Street musicians aren't allowed to play on the cathedral steps, the guards say. So they stand on the paving at the very bottom, one toe from the lowest stair, and play hymns. Nobody can find a rule against it.",
		"There's a rule against music on the cathedral steps, the fiddlers grumble. So one plays at the foot of them instead, every tune a hymn, and the priests have given up pretending to mind.",
	},
	["sw.muse.w19.steps.002"] = {
		"Best bench in Stormwind? The cathedral steps. Bring a pie; the priests don't mind crumbs.",
		"Half the pies in this city get eaten on the cathedral steps. The priests step over the crumbs with great dignity.",
	},
	["sw.muse.w19.steps.003"] = {
		"watches two children race scraps of bark across the square's fountain, shrieking and splashing, while a priest on the steps pretends very hard not to see.",
		"pauses at the edge of the fountain, where a little fleet of folded parchment boats is foundering under the spout, watched over by a very serious small admiral.",
	},
	["sw.muse.w19.steps.004"] = {
		"Couples arrange to meet by the fountain in Cathedral Square. It's hard to start a quarrel in front of the cathedral, and harder to stay angry on those steps.",
		"Lovers in this city pick the cathedral fountain for their difficult talks. Something about all that height overhead keeps the voices down.",
		"Nobody shouts at a sweetheart by the cathedral fountain. That's why so many hard things get said there, softly, with the water covering the worst of it.",
	},
	["sw.muse.w19.steps.005"] = {
		"The flower seller at the foot of the cathedral steps never asks what you need. She looks at your face and hands you white lilies or yellow roses, and she's never wrong.",
		"Funeral or wedding, the flower woman by the cathedral can tell before you open your mouth. White for one, yellow for the other, and the same price either way.",
	},
	["sw.muse.w19.steps.006"] = {
		"steps out of the way of a wedding party spilling down the cathedral steps in a flurry of petals, half of which end up floating in the fountain.",
		"watches a newly married pair come down the steps of the cathedral under a cloud of petals, the bride holding her hem, the groom holding on to the bride.",
	},
	["sw.muse.w19.steps.007"] = {
		"Pilgrims who reach the cathedral nearly always sit down on the bottom step before going in. After all those miles, they say, you have to arrive with your feet before you arrive with the rest.",
		"Watch any pilgrim at the cathedral: they sit on the lowest step first, unlace a boot, look up for a long while. Going in can wait a little longer than the road did.",
		"A pilgrim's arrival at the cathedral has two parts: sitting on the bottom step, and everything after. The first part sometimes takes longer.",
	},
	["sw.muse.w19.steps.008"] = {
		"Some pilgrims at the cathedral come from Lordaeron, from towns that aren't there anymore. They pray for places, not people. It's a sound I hadn't heard before.",
		"There are refugees from the north on the cathedral steps who still give their home town when asked where they're from, as if the name could hold the walls up.",
	},
	["sw.muse.w19.steps.009"] = {
		"Meet me at the cathedral fountain. Everybody can find it, and nobody's ever been robbed there.",
		"Cathedral fountain, then. If I'm late, sit on the steps. Somebody will give you soup.",
		"If you lose me, try the cathedral fountain. Any child in the city can point the way.",
	},
	["sw.muse.w19.steps.010"] = {
		"pauses at the foot of the cathedral as rain sheets down its steps in a thin, glassy waterfall, the beggars huddled in the doorway arch above.",
		"watches the rain turn the cathedral steps into a long stair of running water, a lone acolyte coming down it with his robe held high and his dignity higher.",
	},
	["sw.muse.w19.steps.011"] = {
		"When paladins leave for the north they gather first on the cathedral steps, kneel once, rise together and go. The Alliance sends its prayers out walking.",
		"Paladins setting out for the north take leave on the cathedral steps: one knee, one word, a last look at the doors. Then down to the gate in good order, and the whole Alliance in their debt.",
	},
	["sw.muse.w19.steps.012"] = {
		"A sausage seller moves his cart a little closer to the cathedral every week. The priests move it back. Neither side has ever mentioned it to the other.",
		"A quiet war goes on in Cathedral Square between the priests and a pie cart. The cart creeps toward the steps; the acolytes wheel it back. Nobody raises a voice.",
		"Each week the sausage cart sits a stride nearer the cathedral steps, and each week an acolyte rolls it back without a word. It may be the longest siege in Stormwind.",
	},
	["sw.muse.w19.steps.013"] = {
		"notices a dusty pilgrim sitting on the fountain's rim with both bare feet in the water, eyes shut, while an acolyte hovers nearby trying to decide whether to object.",
		"passes a gray-bearded pilgrim soaking his road-sore feet in the fountain, walking stick across his knees, looking as if he has already received whatever he came for.",
	},
	["sw.muse.w19.steps.014"] = {
		"Three priests have offered to pray for me since I crossed the square. I must look worse than I feel.",
		"Every priest on these steps wants a word with the Light on my behalf. Do I really look that rough?",
	},
	["sw.muse.w19.steps.015"] = {
		"Every street that reaches Cathedral Square seems to tilt your chin up as you come out of it. Whoever laid out the square knew exactly what they wanted from a neck.",
		"Come into Cathedral Square from any side and your eyes go up before you decide anything. That's not faith; that's good masonry.",
		"Cathedral Square is built to make you look up. By the time your eyes come back down, you've usually forgotten what you were cross about.",
	},
	["sw.muse.w19.steps.016"] = {
		"watches the shadow of the cathedral's bell tower slide across the square like the hand of a slow clock, stepping over beggars and pilgrims alike.",
		"follows the long shadow of the cathedral as it creeps across the paving, cooling the fountain and leaving the steps in bright sun.",
		"notices how far the cathedral's shadow has moved since the last bell; it now lies across the fountain like a dark cloth.",
	},
	["sw.muse.w19.stockade.001"] = {
		"The guards outside the Stockade stand facing the door instead of the street. That's all the news anyone needs about how things are going in there.",
		"Most guards in this city watch the street. The ones at the Stockade watch a door, very hard, as if it might try something.",
		"If you want to know how safe the Stockade is, don't ask a guard. Watch where the guards at its entrance keep their eyes. Not on you.",
	},
	["sw.muse.w19.stockade.002"] = {
		"A prison raised by masons and now half full of men who used to be masons. Somebody down there must know exactly which stones are loose.",
		"They lock the Defias in the Stockade, behind walls the Defias' own hands may have set. I'd check the mortar, if I were the warden.",
	},
	["sw.muse.w19.stockade.003"] = {
		"passes a woman waiting near the Stockade with a bundle tied in a cloth, holding it with both hands as if someone might ask her to prove it was hers.",
		"notices a small queue near the Stockade: a mother, an old man, a boy, each with a parcel, none of them looking at the others.",
		"sees a guard at the Stockade take a parcel from an old woman, weigh it in one hand and nod, and the old woman thank him as though he had given her something.",
	},
	["sw.muse.w19.stockade.004"] = {
		"Half the names in the Stockade's ledger are false, a guard admitted to me, and the clerk writes them down in his best hand anyway. A wrong name, spelled properly, is still paperwork.",
		"The clerk who keeps the Stockade's register knows most of those names are invented. He just asks for them to be spelled out.",
		"Every prisoner gives a name at the Stockade, and never the same one twice, the clerk says. He's started writing 'as before' in the margin.",
	},
	["sw.muse.w19.stockade.005"] = {
		"In the Stockade a man can sit for a stolen loaf. Nobody has ever sat there for a mason's wages. The law of this city has excellent eyesight, and looks mostly downward.",
		"Steal a ham, see the Stockade. Steal a whole guild's wages and you're asked to supper in the finest houses. Same city, same law, two doors.",
	},
	["sw.muse.w19.stockade.006"] = {
		"Prisoners aren't the only ones afraid of the Stockade. Among the guards, 'you'll be on Stockade duty' is the threat that makes a lazy one straighten up.",
		"A sergeant doesn't shout at a sloppy guard. He mentions, quite gently, that the Stockade is short of hands. The polish improves at once.",
		"The worst posting in the watch has no view, no passersby and no daylight. Guards who draw it come off shift blinking, and the others are kind to them for a while.",
	},
	["sw.muse.w19.stockade.007"] = {
		"sees a released prisoner step out near the Stockade at first light, blink at the empty street, and stand there a long moment as if waiting for permission to walk.",
		"watches a man with a small sack and a pale face come out of the Stockade into the dawn quiet, look both ways, and choose neither for a while.",
	},
	["sw.muse.w19.stockade.008"] = {
		"If anyone from the Stockade asks for volunteers, I'm busy. I'm always busy. I keep a very full calendar of being elsewhere.",
		"The Stockade? I'll admire it from out here, thank you. It looks lovely with the door shut.",
	},
	["sw.muse.w19.stockade.009"] = {
		"No windows in the Stockade, the guards say. The prisoners keep time by the meals and the changes of the watch, and the ones who've been there longest stop keeping it at all.",
		"In this city there are men who can't tell the hour, a guard told me, except by the tread of the boots coming to change places outside their door.",
	},
	["sw.muse.w19.stockade.010"] = {
		"A letter-writer sets up a stool near the Stockade and writes pleas for prisoners' families at a copper a page. He's very good. Every one of his clients is innocent.",
		"Near the Stockade there's a scribe for hire who writes appeals to the regent for those who can't. He reuses his best sentences. Mercy, it turns out, has a house style.",
	},
	["sw.muse.w19.stockade.011"] = {
		"If they catch me in this city, I doubt they'd waste a cell in the Stockade on me. That's the only comfort I can find in the thought, and it isn't much.",
		"The Stockade is for their own thieves. Whatever they keep in store for someone like me, it hasn't got a door that opens again.",
	},
	["sw.muse.w19.stockade.012"] = {
		"steps aside for two guards walking a sullen prisoner toward the Stockade, the prisoner insisting all the way that they've taken the long route.",
		"makes way for an escort of guards and one grumbler with his hands tied, who stops just long enough to tell the onlookers he knows a much quicker way to the Stockade.",
	},
	["sw.muse.w19.stockade.013"] = {
		"There's a smith in the Dwarven District who makes shackles for the watch. He says business has never been better, and says it like a man who wishes it were worse.",
		"Somebody has to make the irons the Stockade uses. The dwarf who does it keeps them at the back of the shop, under a sack, as if they embarrassed the rest of his work.",
	},
	["sw.muse.w19.stockade.014"] = {
		"Most of the men in the Stockade are ours: farmers' sons from Westfall, laborers with nothing left, a few who believed the wrong speech. Locking them up is the easy part of being a kingdom.",
		"Human thieves in a human prison, put there by human guards. Whatever went wrong with this kingdom, nobody had to come from outside to do it.",
	},
	["sw.muse.w19.stockade.015"] = {
		"Somebody in the Stockade is having a worse day than me. I find that oddly comforting.",
		"However this goes, at least I'm not in the Stockade. Low bar. Still a bar.",
	},
	["sw.muse.w19.tavern.001"] = {
		"Behind the bar of the Pig and Whistle hangs a board of chalked debts. Some names have been there so long the chalk has turned to a ghost on the wood.",
		"The tavern's slate of unpaid tabs is a history of Old Town in its own way: who drank, who promised, and who left by the back door.",
	},
	["sw.muse.w19.tavern.002"] = {
		"Above the tavern's hearth stands a row of cups set upside down. The regulars never explain them, and nobody has to ask twice.",
		"A cup turned over on a tavern shelf means someone isn't coming back for it. The Pig and Whistle has a long shelf.",
	},
	["sw.muse.w19.tavern.003"] = {
		"pauses as the door of the Pig and Whistle bangs open, lets out a gust of song, smoke and argument, and swings shut on all three.",
		"hears the tavern door open behind {g:him|her}: a wave of noise, a whiff of mutton, then the latch, and the lane is quiet once more.",
	},
	["sw.muse.w19.tavern.004"] = {
		"People in the Pig and Whistle speak a little louder than they do outside, and a little more truthfully. It's the ale, or the low ceiling, or both.",
		"Every tavern either lowers voices or raises them. Old Town's raises them, and somewhere around the third cup the lies get noticeably worse.",
	},
	["sw.muse.w19.tavern.005"] = {
		"Whatever's in the pot and whatever's in the barrel. I'm not fussy, and I suspect neither is the cook.",
		"One of whatever that is, please. No, don't tell me what it is.",
		"Something hot, something to drink and a stool that doesn't wobble. I'll settle for two out of three.",
	},
	["sw.muse.w19.tavern.006"] = {
		"Songs in the Pig and Whistle start at one table, cross the room picking up voices, and die at the far end where nobody knows the second verse.",
		"Somebody starts a tune in a tavern corner, the room joins for the chorus, and the verse after it falls apart into laughter. That's the whole performance, every time.",
	},
	["sw.muse.w19.tavern.007"] = {
		"watches two veterans at a nearby table refight an old battle with salt cellars and bread crusts, arguing over where the river was.",
		"glances at a table where an old soldier marshals a line of cups against a single crust of bread, and the crust, apparently, is winning.",
	},
	["sw.muse.w19.tavern.008"] = {
		"It's late, and from the direction of Old Town a tavern is still going strong: one stubborn song that nobody has the heart to finish.",
		"The rest of the city has gone to bed. The Pig and Whistle, by the sound of it, has decided not to.",
	},
	["sw.muse.w19.tavern.009"] = {
		"Half of Old Town can't pass the Pig and Whistle without whistling. The other half has learned to hate the half that does.",
		"Walk by the tavern and someone near you will whistle; it's practically the law. I've caught myself at it, and I'm not proud.",
		"Name a tavern after a pig and a whistle and you can't complain when the whole lane whistles at your door. I suspect the owner rather likes it.",
	},
	["sw.muse.w19.tavern.010"] = {
		"There's always someone in a tavern corner who orders two cups and drinks one. The barkeep fills both without a word.",
		"A man alone at a small table, a second cup full in front of the empty stool. Nobody sits there. Nobody would dream of it.",
	},
	["sw.muse.w19.tavern.011"] = {
		"In the Pig and Whistle a good rumor buys a cup and a great one buys the round. A dull truth buys nothing at all.",
		"Rumor is the tavern's second currency. I've watched a soldier pay for his supper with the name of a new sergeant, and get change.",
		"Information is cheap at the tavern and gossip cheaper. The trick is telling which of the two just sat down beside you.",
	},
	["sw.muse.w19.tavern.012"] = {
		"follows the smell of frying onions and sausage down the lane to its source, a tavern kitchen window propped open with a ladle.",
		"lingers by a kitchen window at the back of the tavern, where a cook with forearms like hams flips something sizzling and never looks up.",
	},
	["sw.muse.w19.tavern.013"] = {
		"A round at the Pig and Whistle, then. Somebody ought to drink to the regent; he looks like he needs it.",
		"If I'm buying, it's the Pig and Whistle. If you're buying, somewhere with chairs that match.",
	},
	["sw.muse.w19.tavern.014"] = {
		"Rain fills the Old Town tavern with people who only stepped in to get dry. Three cups later they're still drying, very thoroughly.",
		"Every downpour is good business for the Pig and Whistle. Nobody comes in for the ale, of course. Only for the roof.",
	},
	["sw.muse.w19.tavern.015"] = {
		"The tavern keeper knows every regular by their drink and not one by name. In Old Town that's a kind of courtesy.",
		"Dark ale for the corner stool, cider by the window, two of the strong stuff for the man who never takes off his gloves. Names don't come into it.",
	},
	["sw.muse.w19.tavern.016"] = {
		"steps around a man asleep against the tavern wall, hat over his face, and a single copper that somebody has kindly placed on the brim.",
		"edges past a sleeper slumped on the tavern step, snoring gently into his collar, one boot unlaced and the other nowhere to be seen.",
	},
	["sw.muse.w19.tavern.017"] = {
		"The Pig and Whistle? Follow the singing. If it's in tune, you've gone the wrong way.",
		"Looking for the tavern? Walk until you hear somebody losing at dice and somebody else enjoying it.",
		"That tavern's easy to find. Follow anyone with a thirst and a grievance.",
	},
	["sw.muse.w19.tinker.001"] = {
		"A gnome tinkers at a stall built from two crates and a borrowed door, fixing locks and lanterns for coppers. The stall itself has hinges in places nobody asked for.",
		"One gnome's workbench is a door laid across two barrels, and she has fitted it with a vise, a lamp on a swinging arm and a drawer that opens by itself. She charges a copper to fix a lock.",
	},
	["sw.muse.w19.tinker.002"] = {
		"A gnome showed me the pin she keeps inside her coat, a little brass cog. Gnomeregan's, she said, and buttoned the coat again.",
		"Brass cogs pinned to the inside of the lapel, never the outside. Ask a gnome in Stormwind what it means and you'll hear a city's name, then a change of subject.",
		"Half the gnomes in the Dwarven District wear something from Gnomeregan where nobody can see it: a cog, a washer on a string, a key to a door that's underwater or worse.",
	},
	["sw.muse.w19.tinker.003"] = {
		"stops to watch a gnome test a contraption on the cobbles: it whirs, hops twice and sits down, and the gnome makes a note as if this were exactly the plan.",
		"jumps aside for a small clockwork thing trundling across the street, chased by its gnome, who is shouting numbers at it rather than a name.",
		"steps over a ticking brass box crossing the street on six little legs, and a moment later over the length of string that is, apparently, steering it.",
	},
	["sw.muse.w19.tinker.004"] = {
		"I took a lantern to a gnome to have the wick changed. It came back with a crank, a shutter and opinions.",
		"Never ask a gnome for a small repair. There's no such thing, only small beginnings.",
		"The gnome who mended my lamp gave it back doing four things, and one of them, I'm told, is light.",
	},
	["sw.muse.w19.tinker.005"] = {
		"The gnomes who teach engineering in the Dwarven District take humans, dwarves, anyone with coin and steady fingers. By the second week every student has the same singed eyebrows.",
		"Engineering students are easy to spot in Stormwind: ink on the fingers, a burn on the thumb, and a habit of looking at a door and counting its screws.",
		"You can pick out the engineering apprentices in any crowd. They walk past a cart and look at its wheels; they walk past a lock and look at its hinges.",
	},
	["sw.muse.w19.tinker.006"] = {
		"A bang from a gnome's workshop and the whole Dwarven District looks up, waits, and when no second bang comes, goes back to work. The second bang is the one to worry about, the smiths say.",
		"The dwarves keep a rule about gnome workshops: one bang is an experiment, two is a lesson, three and you fetch a bucket.",
	},
	["sw.muse.w19.tinker.007"] = {
		"Inside one gnome workshop there's a board of names in chalk: those who got out of Gnomeregan, a tinker told me. A new one goes up whenever word comes down the tram.",
		"The gnomes keep a list on a slate by a workbench, names of the ones who made it out. Nobody ever rubs one off. Now and then, very rarely, somebody adds one.",
		"A chalk list on a workshop wall, mostly names I can't pronounce. The gnome who keeps it says it isn't a memorial. It's the other kind of list.",
	},
	["sw.muse.w19.tinker.008"] = {
		"watches a gnome climb onto an upturned bucket to see over a shop counter, and the dwarf behind it, without looking up, slide a second bucket over for next time.",
		"notices that a sturdy crate stands beside most of the counters along the street, worn smooth in the middle: the step the gnomes use to be seen over the top.",
	},
	["sw.muse.w19.tinker.009"] = {
		"Many doors in the Dwarven District have a second, smaller handle set low. Nobody remembers who fitted the first; now every new door gets one.",
		"Somebody started fitting the doors of the Dwarven District with a second knob at gnome height, and the habit spread. A city makes room for its guests in small brass ways.",
	},
	["sw.muse.w19.tinker.010"] = {
		"Hand a gnome something broken and step back. Not for safety. They need room to pace.",
		"Watch your boots around the gnome workbenches. Half of what's lying on the ground is still running.",
	},
	["sw.muse.w19.tinker.011"] = {
		"Gnome children in the Dwarven District learn to count on gears before fingers, a tinker told me, laughing; then he stopped laughing. There are few enough of them left to teach.",
		"On a Stormwind doorstep, a gnome teaching a little one to strip a lock. In another life it would be a workshop in Gnomeregan. She doesn't seem to think about that, and then she does.",
	},
	["sw.muse.w19.tinker.012"] = {
		"Stormwind lends us benches, coin and very polite stares. One day we'll have our own city back, and I'll miss the stares, a little.",
		"Every gnome in the Dwarven District is a guest who works harder than the hosts. That isn't pride talking. Well. Not only pride.",
		"We gnomes have made a corner of a human city run like a clock. When Gnomeregan is ours again, I hope someone here remembers how to wind it.",
	},
	["sw.muse.w19.tinker.013"] = {
		"Dwarven smiths and gnomes still argue about the Second War: who built the better machines, whose flying contraptions came down more often. It's the friendliest quarrel in Stormwind.",
		"Dwarf and gnome side by side at one bench, still bickering over whose engines won the Second War. Neither will give an inch, and neither would want the other to.",
	},
	["sw.muse.w19.tinker.014"] = {
		"picks up a small brass spring rolling down the street and holds it out; a gnome hurrying the other way takes it, inspects it, gives grave thanks, and tosses it into a bucket of identical springs.",
		"returns a runaway cog to a gnome searching for it on hands and knees, and is thanked as warmly as if it had been a lost ring.",
	},
	["sw.muse.w19.tinker.015"] = {
		"Gnomes in Stormwind write everything down in a hand so small that only another gnome could read it. The guards find it suspicious. The gnomes find paper expensive.",
		"There are notebooks in every gnome workshop, filled edge to edge in writing the size of ant tracks. It looks like secrecy. It's mostly thrift.",
		"A gnome's notebook is a whole library in a pocket: margins full, the inside of the cover full, and a final note squeezed along the spine.",
	},
	["sw.muse.w19.tinker.016"] = {
		"If you want to learn engineering, start by learning to stand very still near people who already know it.",
		"First lesson of engineering, as far as I can see: duck. The rest is numbers.",
	},
	["sw.muse.w19.trade.001"] = {
		"You can always pick out a tailor's apprentice: pins stuck through the collar, loose thread on both sleeves, and the start of a squint they'll keep for life.",
		"Tailors' apprentices walk the streets with a pincushion strapped to one wrist and their eyes on everyone's hems. They can't help it. Neither could their masters.",
	},
	["sw.muse.w19.trade.002"] = {
		"Leatherworkers smell of their trade: oak bark, oil and something best not asked about. You know one has passed by the way the crowd parts politely.",
		"There's no hiding a leatherworker in a crowd. The smell of tanning oil arrives first and stays after, like a guest who knows the family.",
	},
	["sw.muse.w19.trade.003"] = {
		"An alchemist's fingertips are stained in colors no flower ever wore. Shake hands with one and check your own afterward.",
		"The alchemists of this city have hands like a painter's rag: blue at the nails, green at the knuckles, and a faint violet nobody will explain.",
	},
	["sw.muse.w19.trade.004"] = {
		"Rule one of the trades: never drink anything an alchemist's apprentice calls 'probably fine'.",
		"If an apprentice alchemist offers you a sample, ask what it did to the last one who tried it. If they have to think, decline.",
		"Any potion an apprentice describes with the word 'mostly' is a potion for somebody else.",
	},
	["sw.muse.w19.trade.005"] = {
		"In some kitchen in this city a cook is teaching a hardened soldier how not to burn an egg, and neither of them has had a harder lesson all year.",
		"Cooking is the trade that humbles heroes. Many a veteran who stared down ogres has gone pale over a sauce that split, or so the cooks tell it.",
	},
	["sw.muse.w19.trade.006"] = {
		"Enchanters take a perfectly good pair of gloves, turn it into a pinch of glittering dust, and sell you the dust to put on a different pair. Magic, they call it. I call it the cleverest trade in Stormwind.",
		"An enchanter's whole craft is unmaking one fine thing to sweeten another. Somewhere in that is a lesson about cities, but the dust gets in my eyes.",
	},
	["sw.muse.w19.trade.007"] = {
		"steps over a gutter running faintly blue where some dyer has emptied a vat, the color winding off toward the nearest canal.",
		"skirts a puddle tinted a startling green below a dyer's back door, and glances down at {g:his|her} boots to make sure they're still the usual color.",
	},
	["sw.muse.w19.trade.008"] = {
		"The best trainers in the city let their apprentices ruin the first bolt of cloth. It's cheaper than letting them ruin the hundredth.",
		"A master who corrects every stitch raises a careful apprentice. One who lets a stitch go crooked now and then raises a tailor.",
	},
	["sw.muse.w19.trade.009"] = {
		"The trade trainers here teach for coin, and they're careful never to teach a stitch more than the fee covers.",
		"Pay a trainer for one recipe and you'll get one recipe, said once, clearly. The second telling is a separate fee.",
		"A trainer's knowledge comes in neat little portions, each one priced. They're not stingy. They're merchants who happen to know things.",
	},
	["sw.muse.w19.trade.010"] = {
		"stops to watch an apprentice chase a runaway bolt of cloth down a sloping street, the roll unwinding faster than the boy can run.",
		"steps neatly over a long ribbon of unrolling linen, then turns to see a red-faced apprentice reeling it in, hand over hand, from the far end of the street.",
	},
	["sw.muse.w19.trade.011"] = {
		"Salt from Kul Tiras, iron from Ironforge, herbs from the elves' far forests, wool from Elwynn. Stormwind makes little of what it sells. It's a crossroads that learned to charge for standing in it.",
		"Lay a Stormwind shop's shelves out on a map and they'd cover half the world: Kul Tiran salt, dwarven iron, elven herbs, Elwynn wool. The city's real trade is being in the middle.",
	},
	["sw.muse.w19.trade.012"] = {
		"Some goods never reach Stormwind now: silver from Lordaeron, wool from behind the Gilneas wall, the hard cheese of Alterac. Old merchants still name them, the way people mention the dead at supper.",
		"Ask an old trader what's missing from the market and the list is a map of lost kingdoms. Lordaeron, Alterac, Gilneas behind its wall. Then he goes back to selling Elwynn cheese.",
	},
	["sw.muse.w19.trade.013"] = {
		"Linen, wool, silk, mageweave. You can tell how far along a tailor is by which cloth they complain about.",
		"Young tailors curse linen. Old tailors curse mageweave. None of them ever stops cursing; that's the trade.",
		"Ask a tailor how the work's going and the answer is a cloth: 'Silk, still.' It's a rank, like a soldier's.",
	},
	["sw.muse.w19.trade.014"] = {
		"Half the cloth cut in this city ends up as bandages or banners at the front. The tailors are in this war too, armed with needles.",
		"Somebody in Stormwind sewed every tabard the Alliance bleeds in. Nobody hands the tailors a medal, but the war would go naked without them.",
	},
	["sw.muse.w19.trade.015"] = {
		"wrinkles {g:his|her} nose at a sharp, sweetish smell drifting out of some alchemist's open doorway, then sniffs again to be sure.",
		"pauses as a puff of lilac vapor rolls out of a workshop window and melts over the street, leaving a smell of burnt sugar and old coppers.",
	},
	["sw.muse.w19.trade.016"] = {
		"Leatherworkers will buy anything an adventurer drags back: wolf, boar, raptor, and the occasional thing with too many legs. They pay by the hide and never ask about the legs.",
		"Bring a leatherworker a stack of wolf hides and they'll name a price before you've finished unrolling them. Bring them something stranger and they'll name a lower one.",
	},
	["sw.muse.w19.trade.017"] = {
		"There's a look an apprentice gets the first time a stranger pays real coin for something they made. Ask any master in this city; they all remember wearing it.",
		"The first coin an apprentice earns with their own hands is never spent, the tailors say. It gets nailed above the workbench, or carried until it's worn smooth.",
	},
	["sw.muse.w19.trade.018"] = {
		"A torn cloak, a split boot, a cracked buckle: this city has a trade for every way a traveler comes apart.",
		"Whatever's broken, somebody in Stormwind makes a living fixing it. Except the prices. Nobody fixes those.",
		"Rip it, crack it, scorch it. Somebody on these streets will mend it by the next bell and charge for the privilege.",
	},
	["sw.muse.w19.trade.019"] = {
		"Humans put a price on everything here, even cut flowers. In Darnassus you'd simply be given one. I can't decide whether to be shocked or to buy a bunch.",
		"Flower sellers here ask two coppers for a sprig of what grows wild under every tree in Teldrassil. I think I'll pay. One should learn a custom before judging it.",
	},
	["sw.muse.w19.trade.020"] = {
		"tugs at a loose thread on one cuff, and the cuff gets noticeably shorter.",
		"pulls a stray thread from a sleeve, then watches the seam begin, very slowly, to open after it.",
	},
	["sw.muse.w19.trade.021"] = {
		"If I ever stop wandering, I'll learn tailoring. No inn ever turns away someone who can fix its curtains.",
		"Someday I'll take up leatherwork and stay put. Then I'll find out what my boots keep complaining about.",
	},
	["sw.muse.w19.tram.001"] = {
		"feels the draft rising from the tram tunnel tug at {g:his|her} cloak a moment before the rumble of an arriving car reaches the street.",
		"watches the dust on the tram ramp lift and swirl for no reason anyone in the street can see, then hears the car, far below.",
		"turns as the air at the mouth of the tram shifts all at once, cool and smelling of wet rock, pushed up the ramp ahead of a car still out of sight.",
	},
	["sw.muse.w19.tram.002"] = {
		"In the houses nearest the tram the cups shiver on the shelf whenever a car passes underground. The people who live there stopped noticing; their guests never do.",
		"Live close to the tram and your crockery learns the timetable: a rattle on the shelf, a hum in the floor, and a car has come in under the city.",
	},
	["sw.muse.w19.tram.003"] = {
		"The ramp down to the tram is the only place in Stormwind where open air turns to lamplight in thirty paces. Halfway down, it already feels like Ironforge.",
		"Thirty steps down toward the tram and the city's noise thins to a hum, the stone goes cool, and the lamps take over. A borrowed piece of Ironforge, set into Stormwind's floor.",
	},
	["sw.muse.w19.tram.004"] = {
		"Whoever said every road leads to Stormwind never took the one that runs underneath it.",
		"All roads lead to Stormwind, people say. The tram is the one that leaves it by the cellar.",
	},
	["sw.muse.w19.tram.005"] = {
		"You can tell who just rode the tram by their clothes: still buttoned up and scarved for Dun Morogh, in a street that never needed either.",
		"Travelers off the tram climb into the street wrapped in furs, dressed for Dun Morogh, and start peeling off layers before they reach the bank.",
		"Most days a pile of discarded mufflers lies at the top of the tram ramp. Ironforge sends its visitors south dressed for the mountain, and Stormwind undresses them.",
	},
	["sw.muse.w19.tram.006"] = {
		"makes room at the top of the tram ramp for a dwarf hauling a barrel up step by step, who refuses help twice and accepts it the third time without comment.",
		"holds the edge of a barrel steady for a dwarf heaving it up from the tram, and is rewarded with a nod and a muttered remark about human stairs.",
	},
	["sw.muse.w19.tram.007"] = {
		"Halfway through the tunnel the dwarves' half meets the gnomes' half, the miners say, and the seam is out by the width of a thumb. Neither side will say whose thumb.",
		"The tunnel was dug from both ends at once, as the story goes, and met in the middle a finger's width out of true. Dwarves blame the gnomes' numbers; gnomes blame the dwarves' fingers.",
		"Every dwarf in the Dwarven District knows where the tunnel's crooked join is, and every gnome swears there isn't one. The tram, for its part, rides straight through the argument.",
	},
	["sw.muse.w19.tram.008"] = {
		"A tunnel straight to Ironforge, under the water, and the Alliance rides it like a cart to market. I'd give a lot to know how many guards wait at the far end.",
		"A short ride apart beneath the water: Stormwind and Ironforge. Whatever the Horde plans, it had better stop counting on the leagues between them.",
	},
	["sw.muse.w19.tram.009"] = {
		"listens at the head of the tram ramp to the long, hollow rumble rising out of the tunnel, a sound so deep it reaches the soles of the boots before the ears.",
		"pauses where the street tips down toward the tram, as a low rumble climbs out of the tunnel and fades again, like a giant clearing its throat under the city.",
	},
	["sw.muse.w19.tram.010"] = {
		"Gossip from Ironforge comes up the tram a few hours fresh. By the time it reaches the Trade District it has grown a beard.",
		"A rumor from Ironforge reaches the Dwarven District first, then the forges, then the taverns. By Cathedral Square it has changed sides twice.",
		"News from Ironforge arrives in Stormwind by tram and leaves the Dwarven District by every voice at once, a little bigger with each telling.",
	},
	["sw.muse.w19.tram.011"] = {
		"At night, with the forges banked, you can hear the tram from the street: a far rumble, a pause, a far rumble. Like something very large turning over in its sleep.",
		"Late at night, with the anvils quiet, the tram is the loudest thing in the Dwarven District: a rumble in the ground, then nothing, then the rumble coming back the other way.",
	},
	["sw.muse.w19.tram.012"] = {
		"Ironforge? Find the Dwarven District, take the stairs down, and keep going till the beards outnumber you.",
		"For Ironforge you go down, and then a long way north. Mind the step.",
		"The way to Ironforge starts in the Dwarven District and ends under a mountain. The middle part's wet.",
	},
	["sw.muse.w19.tram.013"] = {
		"Every time the tram comes in on time, part of me wants to stand on the platform and bow on behalf of every gnome who ever drew a line on paper.",
		"Gnomes dug half that tunnel and drew all of it. When a human rides it and doesn't scream, I take that as applause.",
	},
	["sw.muse.w19.tram.014"] = {
		"turns to see a dwarf and a human part at the head of the tram ramp with a handshake that becomes, after a moment's hesitation, a clumsy embrace.",
		"sees two old soldiers, one dwarf and one human, say goodbye at the mouth of the tram with a long handshake and no words at all.",
		"lingers as a human woman sees a dwarf off at the tram, pressing a wrapped loaf into his hands, which he protests against and keeps.",
	},
	["sw.muse.w19.tram.015"] = {
		"In fog, forge smoke and fog become one thing, and the Dwarven District simply goes missing, all but the hammers somewhere inside it.",
		"Fog and forge smoke together turn the Dwarven District into a guess: a red glow, a clang, a dwarf's voice, and nothing you could point to.",
	},
	["sw.muse.w19.tram.016"] = {
		"The tram never waits for anyone. It comes, it stops, it goes. In a city of nobles who keep everyone waiting, there's something restful in that.",
		"Nobody holds the tram for a lord. The car comes in, waits as long as it waits, and leaves on gnome time, which is exact and unbribable.",
	},
	["sw.muse.w19.urchin.001"] = {
		"becomes aware of a small boy a few steps behind, copying {g:his|her} walk with merciless accuracy, while the street around tries very hard not to laugh.",
		"catches, in the glass of a shop window, a little girl behind {g:him|her} imitating {g:his|her} stride exactly, down to the swing of the arms.",
		"turns a corner and hears, a moment later, a burst of giggles and small boots trying very hard to sound like {g:his|hers}.",
	},
	["sw.muse.w19.urchin.002"] = {
		"The quickest post in Stormwind isn't the mailbox. It's a barefoot girl with a copper in her fist and every alley of the city in her head.",
		"Give a street boy a copper and a message and it's across the city before the ink dries. He knows ways through that are on no map, most of them over walls.",
	},
	["sw.muse.w19.urchin.003"] = {
		"Directions from a street kid cost a copper. Directions from a guard are free. Guess which ones were right.",
		"Paid a child a copper to show me the way. Best coin I've spent in this city.",
		"The kid wanted two coppers to show me the way. I offered one. It ended at one and an apple. Hard bargainer.",
	},
	["sw.muse.w19.urchin.004"] = {
		"A noble's son in velvet, walking beside his tutor, stared at a pack of street children playing in the gutter. They stared back. I couldn't tell which side envied the other more.",
		"Through the railings of a fine house a boy in a lace collar watches the street children race. They watch him back, and his clean boots. Neither side would trade, and both are thinking about it.",
	},
	["sw.muse.w19.urchin.005"] = {
		"watches three urchins ride the tailboard of a passing cart, dropping off one by one as the driver's whip goes searching behind him.",
		"sees a pair of street children hop onto the back of a slow wagon, ride it over a bridge, and leap down laughing before the carter can turn.",
		"notices a small hand clinging to the back of a passing wagon, then another, then a whole row of grinning faces bound for nowhere in particular.",
	},
	["sw.muse.w19.urchin.006"] = {
		"Here in the Dwarven District the children sweep the forge floors for dropped nails and sell them back to the same smiths, a copper a handful. The smiths know. They pay anyway.",
		"The district's children pick bent nails out of the cracks by the forges and sell them back, a copper a handful, to the smiths who dropped them. Everyone is satisfied with the arrangement.",
	},
	["sw.muse.w19.urchin.007"] = {
		"How many have I beaten? I stopped counting, kid. Don't make it a thousand when you tell your friends.",
		"No, I won't tell you the gory bits. Ask me again when you're taller. Much taller.",
	},
	["sw.muse.w19.urchin.008"] = {
		"Not every orphan in Stormwind sleeps at the orphanage. Some prefer the rooftops and the arches under the bridges, where nobody tells them when to wash.",
		"The matron can't climb. That's why a few of the city's orphans live up on the roofs instead: free as pigeons, and about as well fed.",
	},
	["sw.muse.w19.urchin.009"] = {
		"steps carefully around a chalk drawing on the cobbles, a lion with six legs and a crown, while its artist glares up to make sure.",
		"avoids treading on a child's chalk knight sprawled across the stone, whose sword is longer than the street is wide, and receives a curt nod from the artist.",
		"halts at the edge of a chalk dragon that fills half the lane, and is directed by a boy with green fingers to walk around the tail.",
	},
	["sw.muse.w19.urchin.010"] = {
		"The children of the Mage Quarter play at daring: who can stand longest under an apprentice's window once something starts to hum. The winners have no eyebrows.",
		"In the Mage Quarter, a dare means touching the door of the tower and running. Every child in the street has done it; none of them has ever seen that door open.",
	},
	["sw.muse.w19.urchin.011"] = {
		"Two boys race bits of straw down the gutter, cheering each one under little bridges of fallen leaves. Whoever dug the canals must have started like this.",
		"A row of children crouch over the gutter, racing twigs and shouting the names of real bridges as the twigs slide under nothing at all.",
	},
	["sw.muse.w19.urchin.012"] = {
		"Mind that cart, you lot. The driver's had a long day, and his horse a longer one.",
		"Don't run on the bridge, you'll... and there it is. Up you get. Nothing broken.",
	},
	["sw.muse.w19.urchin.013"] = {
		"is offered a boot cleaning by a grimy small boy whose price goes up each time he looks at the boots.",
		"receives from a street girl an offer to polish those boots, with a price, then a second and higher price once she has seen the state of them.",
	},
	["sw.muse.w19.urchin.014"] = {
		"The refugee children from Westfall don't play quite like the city children. Every so often one stops and looks west over the rooftops, as if to check that the smoke is still far away.",
		"You can tell which of the street children came from Westfall: they never leave bread on a plate, and they go quiet whenever someone shouts 'fire'.",
	},
	["sw.muse.w19.urchin.015"] = {
		"All right, you can walk with me as far as the bridge. But you carry nothing and you ask nothing.",
		"You've been following me three streets now. Either you're a spy or you're bored. Both, probably.",
	},
	["sw.muse.w19.vault.001"] = {
		"The bank will rent you one more slot for your things, and the next one for more, and the one after that for a small fortune. The bank has studied hoarders closely.",
		"Every extra shelf in a bank vault costs more than the one before. The bankers call it fair. I call it knowing their customers.",
	},
	["sw.muse.w19.vault.002"] = {
		"The bank must be the quietest room in Stormwind. Coins are counted there in whispers, as if loud money might get ideas.",
		"Step into the bank and the street drops away. Nobody shouts near that much gold. It feels like a prayer of the wrong kind.",
		"Whatever the bank is guarding, it guards it with silence first. The clerks talk as softly as librarians, and half as often.",
	},
	["sw.muse.w19.vault.003"] = {
		"turns a coin over, tests its edge with a thumbnail the way bankers do, and looks faintly embarrassed to be caught at it.",
		"rings a coin against a fingernail and listens, head tilted, like a banker who suspects the whole world.",
	},
	["sw.muse.w19.vault.004"] = {
		"Hand a clipped coin across the bank counter and the clerk gives it back without a word. The look comes free, and follows you out the door.",
		"Bankers can spot a shaved silver piece by the sound it makes on the counter. A sound I'd never notice; a sound they never stop hearing.",
	},
	["sw.muse.w19.vault.005"] = {
		"Old bankers say that when the first city fell, the clerks carried the ledgers north before they carried much else. The debts survived the war. Not everyone did.",
		"The ledgers came through the First War, the clerks like to tell you, when half the city didn't. Whatever else burned, somebody still owed somebody.",
	},
	["sw.muse.w19.vault.006"] = {
		"Safe from thieves, safe from fire, and mostly safe from me. That's my coin, in the bank.",
		"Money in the bank is like a friend in the Stockade: perfectly safe, and you need permission to visit.",
		"My coin sleeps better in the bank than I do at any inn.",
	},
	["sw.muse.w19.vault.007"] = {
		"shakes a few coins in a loose fist, a sum too small to trouble a banker with and too large to forget about.",
		"lets a handful of coppers spill from one palm into the other, a small bright noise inside the city's larger one.",
	},
	["sw.muse.w19.vault.008"] = {
		"Rumor in the Trade District: the crown keeps an account at the bank like anyone else, and it's overdrawn like anyone else. Nobody repeats that near a guard.",
		"The clerks won't say who the bank's biggest debtor is. They just glance toward the keep and change the subject.",
	},
	["sw.muse.w19.vault.009"] = {
		"The bank still keeps accounts for soldiers who marched out and never came back. Nobody closes them. Closing one means writing a word in the ledger that nobody wants to write.",
		"In the bank's books are names with nobody left to ask after them. The clerks copy them into each new ledger, year after year, in their best hand.",
		"Every bank has its quiet shelf: accounts of the ones who went north and stayed there. Interest still accrues. Nobody collects it.",
	},
	["sw.muse.w19.vault.010"] = {
		"Bank first. Then I'll know exactly how poor I am.",
		"One trip to the bank and I'll know whether this is a meat pie sort of hour or a dry bread one.",
	},
	["sw.muse.w19.vault.011"] = {
		"The guards at the bank never once glance at the coin going past them. That's the training. Everyone else's eyes go straight to it.",
		"A bank guard stands all day beside more gold than a Westfall village will see in a lifetime and looks only at the door. I couldn't do it.",
	},
	["sw.muse.w19.vault.012"] = {
		"counts something on {g:his|her} fingers, lips moving silently: the private arithmetic of what to keep, what to store and what to sell.",
		"sorts through a pack with great seriousness, setting out one pile to keep, one to store, and one that looks very much like the first.",
	},
	["sw.muse.w19.vault.013"] = {
		"Coin in a Stormwind bank is a strange sort of roof. You can't sleep under it, but you sleep better for knowing it's there.",
		"Whatever happens out on the roads, a little of me stays safe behind the bank's counter. It isn't much, but it's a part of me that doesn't have to come along.",
	},
	["sw.muse.w19.vault.014"] = {
		"If the bankers ran the war, the enemy would be paying interest by now.",
		"Put a banker in charge of the army and every retreat would come with a late fee.",
	},
	["sw.muse.w19.vault.015"] = {
		"Under the bank there's a door thicker than a man is tall, the clerks say, and a key only two people in the city have ever touched. I believe in the door. I'm less sure about the two.",
		"Bank clerks speak of the vault door the way priests speak of relics: never seen it open, wouldn't want to, glad it's there.",
	},
	["sw.muse.w19.vault.016"] = {
		"gives way to a courier with a small iron strongbox chained to one wrist and a guard at each elbow, all three walking as if the cobbles might steal.",
		"makes way for two guards escorting a clerk who carries a locked coffer against his chest like a sleeping infant.",
	},
	["sw.muse.w19.vault.017"] = {
		"Bankers: the only folk in Stormwind who smile less than the guards, and they're paid better for it.",
		"A guard of the keep might crack a grin, given a year. A banker, never. It must be written into their contracts.",
	},
	["sw.muse.w19.veteran.001"] = {
		"A few old soldiers in Stormwind spent years guarding the internment camps after the Second War. Now the orcs they guarded have a city of their own across the sea, and those men sit very still when it comes up.",
		"A veteran told me he stood guard over orcs for years, then heard they'd walked out and built a nation. He didn't sound angry. He sounded like a man adding up a column that won't balance.",
	},
	["sw.muse.w19.veteran.002"] = {
		"watches an old soldier take a flight of steps sideways, bad knee leading, with the patience of someone who has climbed worse walls in worse company.",
		"steps aside for a veteran working his way down the stairs on one stiff leg and one good one, chin up as if inspecting a rampart.",
		"waits at the foot of a stair while an old soldier comes down it with a hand on the wall, testing each step as if it might be undermined.",
	},
	["sw.muse.w19.veteran.003"] = {
		"Ask a Second War veteran about the dragons and he'll glance upward before he answers. The orcs had red dragons in that war, they say, and some habits outlive the war that taught them.",
		"A big shadow crossed the street and three old men on a bench looked up at once. 'Dragons,' one muttered, and laughed at himself. The others didn't laugh.",
	},
	["sw.muse.w19.veteran.004"] = {
		"One old soldier wears his tabard from the Second War on feast days, the blue washed out to the color of dishwater. The crest on it belongs to an alliance that mostly isn't there anymore.",
		"A faded tabard of the old war, cut in a fashion no tailor uses now, goes by on a stooped back. The man inside it nods to the guards. They nod back, a little more carefully than usual.",
		"The young guards stand straighter when that old tabard passes, I've noticed, though not one of them could name the kingdom on its crest.",
	},
	["sw.muse.w19.veteran.005"] = {
		"The crown pays its old soldiers in gratitude, they tell me. Lovely currency. The baker won't take it.",
		"Thanks spend beautifully at a parade, says the old soldier at the cobbler's bench. The rest of the year he mends boots.",
	},
	["sw.muse.w19.veteran.006"] = {
		"Want the Second War told straight? Find a veteran sober. Want it told well? Buy him two ales.",
		"A sober veteran gives you the dates. A merry one gives you the war.",
		"Every veteran tells the Second War differently. The good ones admit it.",
	},
	["sw.muse.w19.veteran.007"] = {
		"notices an old man in the crowd touch two fingers to his brow as he comes in sight of the keep, a salute nobody asked of him, and walk on.",
		"sees a gray-bearded veteran slow for a single step when the keep comes into view, give it the smallest of salutes, and carry on with his shopping.",
		"catches a pair of old soldiers lifting their hands to their brows at the same instant, toward the keep, without breaking off their argument about turnips.",
	},
	["sw.muse.w19.veteran.008"] = {
		"listens to an old soldier at the bar name every place he has slept in his life, kingdom by kingdom, and fall silent somewhere in the north before the list is done.",
		"overhears a veteran counting off on his fingers the towns he marched through, running out of fingers, and then simply stopping.",
	},
	["sw.muse.w19.veteran.009"] = {
		"The oldest veterans fought for Llane, before there was a regent or a boy on the throne. Of everyone in Stormwind, they say the least about the empty chair. They've watched one emptied before.",
		"A few graybeards in this city served under King Llane. When the talk turns to the missing king, they go quiet and look into their cups. They know how the waiting sometimes ends.",
	},
	["sw.muse.w19.veteran.010"] = {
		"The veterans call the Second War the first time the human kingdoms fought as one, and they talk about it like a marriage gone sour: proud of the wedding, careful about the rest.",
		"Lordaeron, Stromgarde, Kul Tiras, dwarves and elves in one line: the old soldiers list them the way you'd list the guests at a feast long over. Half those houses barely speak now.",
	},
	["sw.muse.w19.veteran.011"] = {
		"passes an old soldier on a doorstep oiling the head of a pike that hasn't seen a war in years, working each spot of rust out with a thumb, slowly, like a chore he enjoys.",
		"notices a veteran outside a lodging house rubbing oil into an old halberd, though it's plain he will never carry it anywhere again.",
	},
	["sw.muse.w19.veteran.012"] = {
		"A human veteran who fought beside the dwarves in the Second War never pays for his own ale in the Dwarven District, they say. The dwarves remember who held the line with them, and they remember it in rounds.",
		"In the Dwarven District there's an old human soldier whose cup is always full and whose purse never comes out. He held a pass beside dwarves once. That debt, at least, gets paid every day.",
	},
	["sw.muse.w19.veteran.013"] = {
		"That old soldier by the fountain eats like somebody's about to take the bowl. The war taught him that and never took it back.",
		"Watch the veterans in the soup line: they all eat fast with an arm around the bowl. Some lessons never get discharged.",
		"See how that old soldier sleeps on the bench, boots on, one hand on his pack? Nobody's told him the war ended. Or they have, and he didn't believe it.",
	},
	["sw.muse.w19.veteran.014"] = {
		"That old human on the bench stood guard over orc prisoners once; I'd bet on it. He looks at me like a clerk at a sum he was told had been settled.",
		"The veterans watch me longest. They fought the Horde before it was the Horde I walk with, and they can't see the difference. In their place, I'm not sure I would.",
	},
	["sw.muse.w19.veteran.015"] = {
		"Rain on Stormwind, and the old soldiers' joints know it first. A veteran told me he can name every wound he took by which one aches when the weather turns.",
		"Watch the benches empty when the rain comes: the old soldiers go first, rubbing knees and shoulders, each ache a battle they'd rather not discuss.",
	},
	["sw.muse.w19.veteran.016"] = {
		"Veterans who were at Blackrock Spire don't tell the battle. They tell the moment word went down the line that Lothar had fallen, and what the line did next, which was hold.",
		"Lothar died at Blackrock Spire, and the soldiers who heard it there still describe a silence that went through ten thousand men at once, then a roar. They don't describe the fighting. Just that.",
		"Of the whole Second War, one old soldier told me, he remembers best the moment the Lion's banner went down and nobody ran. He tells it with his hands flat on the table, very still.",
	},
	["sw.muse.w19.vigil.001"] = {
		"Lists of names come back from the fighting and the priests pin them beside the cathedral doors. People read them with one finger, line by line. You can tell from across the square when a finger stops.",
		"There's a board by the cathedral where the names of the fallen go up. Nobody reads it out loud. They trace it, slowly, and either walk away lighter or don't walk away for a while.",
		"By the cathedral doors hang the lists from the front. Nobody reads them aloud, and nobody reads them fast.",
	},
	["sw.muse.w19.vigil.002"] = {
		"A candle burns in the cathedral for the missing king, the acolytes say, and nobody admits to lighting it. When it gutters, one of them replaces it without being asked.",
		"There's one candle in the cathedral that is never allowed to go out. For King Varian, people whisper. The priests won't say, and keep trimming the wick.",
	},
	["sw.muse.w19.vigil.003"] = {
		"Before a paladin takes the oath, the acolytes say, they keep watch alone before the altar from the last bell to the first, standing in their plate. The kneeling comes after.",
		"A paladin's oath comes at the end of a long vigil in the cathedral, the squires say: full plate, no chair, until the legs forget they are legs. I'd like to see the face that walks out.",
	},
	["sw.muse.w19.vigil.004"] = {
		"stops in the dark square to look up at the cathedral windows, where a few candles inside keep the colored glass faintly awake.",
		"lingers below the cathedral as the square empties for the night, its high windows glowing low and amber from the candles of those still keeping watch.",
	},
	["sw.muse.w19.vigil.005"] = {
		"After a funeral at the cathedral the mourners always stall on the steps. The service is over and the rest of their lives hasn't started yet.",
		"You can tell a funeral has just ended by the people on the cathedral steps who don't seem to know which way the city is.",
		"Funerals end and mourners don't. They stand on the cathedral steps where the service left them, waiting for someone to tell them what comes next.",
	},
	["sw.muse.w19.vigil.006"] = {
		"Off to one side of the cathedral is an aisle where the candles have burned down and nobody comes. I go there to want nothing for a while.",
		"In a back corner of the cathedral, past the last of the candles, the city finally stops asking me for things.",
	},
	["sw.muse.w19.vigil.007"] = {
		"Quietly. There's someone in there keeping vigil, and grief hears everything.",
		"Lower your voice near the cathedral. Somebody inside is sitting with their dead.",
		"Softly here. Somebody's keeping watch for the dead.",
	},
	["sw.muse.w19.vigil.008"] = {
		"Some old priestess of the cathedral has sat by more deathbeds than any soldier has seen battles. You can see it in how slowly she listens.",
		"Among the cathedral's priests there's one who has heard more last words than anyone in Stormwind. I'd know her by her patience.",
	},
	["sw.muse.w19.vigil.009"] = {
		"The chandler who supplies the cathedral can tell you how the war is going without reading a single report. She counts vigil candles.",
		"Ask the candle sellers near the cathedral how the kingdom fares. They don't read dispatches; they watch how fast the tall white candles go.",
		"Once the chandler's by the cathedral sells out of vigil candles, the whole street knows a bad dispatch came in.",
	},
	["sw.muse.w19.vigil.010"] = {
		"Sit still in the cathedral long enough and the building starts to talk: a bench creaks, a wick spits, a priest's knee cracks as he kneels.",
		"After a while the silence in here turns out to be full: wicks ticking, robes whispering on stone, somebody's stomach complaining in the third row.",
	},
	["sw.muse.w19.vigil.011"] = {
		"The hardest candles in the cathedral are the ones for the missing. You can't mourn them and you can't stop. They burn with a kind of question in them.",
		"A candle for the dead is a goodbye. A candle for the missing is a door left open, and the cathedral is full of open doors.",
		"Some of the candles in the cathedral are lit for people who might walk in tomorrow. Those are the ones the acolytes trim most gently.",
	},
	["sw.muse.w19.vigil.012"] = {
		"passes an old soldier carrying a single white candle in both hands through the street, as carefully as if it were already lit.",
		"steps aside for a woman in black who holds a tall unlit candle upright before her, threading the street toward the cathedral without once looking down.",
	},
	["sw.muse.w19.vigil.013"] = {
		"When the cathedral starts lighting its candles at dusk I say the old words without moving my lips. Not for me. For whoever out there has nobody saying them.",
		"Dusk, and the cathedral windows warm up one by one. I keep a short prayer for this hour: for the roads, and everyone still on them.",
	},
	["sw.muse.w19.vigil.014"] = {
		"When a hymn ends in the cathedral there's a moment nobody will break. Then someone's boot scrapes, and the whole congregation settles back into being people.",
		"The best part of any hymn in the cathedral is the hush after it, before the first cough. Everyone holds still, as if the last note might come back.",
		"When the singing stops in the cathedral, the silence that follows is the loudest thing in Stormwind, for about as long as it takes somebody to clear a throat.",
	},
	["sw.muse.w19.vigil.015"] = {
		"Fog has eaten the cathedral to the doors. All that's left of it is the candlelight inside, floating in the gray like a lantern on water.",
		"In this fog the cathedral is gone except for its windows, a few smudges of candle gold hanging over the square with nothing holding them up.",
	},
	["sw.muse.w19.vigil.016"] = {
		"stands aside as a small funeral procession files toward the cathedral, the mourners' feet keeping a slower time than the street around them.",
		"lets a line of mourners in dark wool pass on their way to the cathedral, the whole street seeming to quiet for the length of them.",
		"steps back against a wall for a funeral party, six bearers and a plain box, and a hush that travels with them like a second procession.",
	},
	["sw.muse.w19.vigil.017"] = {
		"Light a candle for someone, if you like. The acolytes never ask who it's for.",
		"The cathedral will sell you a candle and never ask whom it's for. Discretion, at a copper apiece.",
		"One candle, one name, and nobody asking which. I like that about the cathedral.",
	},
	["sw.muse.w19.wagon.001"] = {
		"You can tell where a wagon's from before it's through the gate. Lakeshire wagons smell of lake and fish. Darkshire wagons come in fast, the driver looking back over his shoulder.",
		"The Redridge wagons arrive mud-caked and talkative. The ones from Duskwood arrive quickly and quietly, and the drivers want a drink before they want their pay.",
		"According to the gate guards, a wagon's road can be read from its mud: red for Redridge, black for Duskwood, and pale dust for anything out of Elwynn's fields.",
	},
	["sw.muse.w19.wagon.002"] = {
		"passes a line of wagons drawn up along the road, drovers moving from horse to horse tugging at buckles, a clerk with a ledger counting barrels for the third time.",
		"skirts a wagon train waiting to leave, where somebody is arguing with somebody else about whose crate goes on top and the horses have long since stopped listening.",
	},
	["sw.muse.w19.wagon.003"] = {
		"Want to learn to swear in every accent of the kingdom? Stand by the gate when two wagons try to pass at once.",
		"Two wagons, one gate, no patience. Best free lesson in cursing this city has to offer.",
	},
	["sw.muse.w19.wagon.004"] = {
		"The supply wagons for Lakeshire go out heavy and come back empty, and the drivers don't talk about the road. Whatever is going on in Redridge, it eats bread and boots.",
		"Some wagons leave Stormwind loaded with sacks of flour and bundles of spears for the towns that write asking for help. They come back light, with letters asking for more.",
	},
	["sw.muse.w19.wagon.005"] = {
		"A gryphon came in low over the wall, and every guard at the gate ducked a little without meaning to, then pretended to be checking their boots.",
		"When a gryphon clears the wall close enough to hear its wings, the carters' horses all flatten their ears at once, and so, I notice, do the carters.",
	},
	["sw.muse.w19.wagon.006"] = {
		"sees a lone traveler go out under the arch of the gate and keep walking, smaller and smaller on the road beyond, without once looking back.",
		"follows with {g:his|her} eyes a pair of travelers leaving by the gate, their packs bobbing in step, until the road takes them round a bend into the trees.",
	},
	["sw.muse.w19.wagon.007"] = {
		"Everyone who comes through the gate is the hero of their own day. The gate has seen thousands of them and treats each one exactly the same: a draft, a patch of shade, and then the noise.",
		"Heroes, peddlers, widows, runaways: the gate lets them all in at the same pace. I find that more comforting than any statue.",
		"The gate doesn't care who you were on the road. Through the arch, you're one more pair of boots on the paving.",
	},
	["sw.muse.w19.wagon.008"] = {
		"The gate's only the start. Then the bridge, then the statues, then half the Trade District, and only then the bank. Stormwind makes you earn your shopping.",
		"Whoever planned this city put the front door a very long way from everything a traveler wants.",
	},
	["sw.muse.w19.wagon.009"] = {
		"A noble's carriage, all lacquer and crests, stuck behind a dung cart at the gate. The horses of both looked equally bored; only the people inside seemed to think it mattered.",
		"There's some justice in a city where a gilded carriage has to wait its turn behind a wagon of manure. Not much justice, but some.",
	},
	["sw.muse.w19.wagon.010"] = {
		"watches a chain of porters empty a wagon sack by sack, each swinging the load to the next with a grunt, the rhythm so steady it could keep time for a dance.",
		"stops to watch a wagon unloaded by five pairs of hands passing crates down a line, nobody speaking, nobody dropping anything, all of it done before a bell could finish.",
	},
	["sw.muse.w19.wagon.011"] = {
		"At dusk the wagons that left it too late go out with lanterns already lit on their poles, the drivers hoping the road stays quiet as far as Goldshire.",
		"Lanterns swing from the wagon poles as the last carts head out at dusk. Goldshire isn't far, but nobody likes the stretch under the trees when the light goes.",
	},
	["sw.muse.w19.wagon.012"] = {
		"You learn what people want most from the first thing they ask the gate guards. Farmers ask for the market, soldiers for a hot bath, and everyone else asks where to sit down.",
		"Listen to the first questions people put to the guards at the gate. Where's the bank, where's the inn, where's the man who owes me money. The guards answer the first two.",
		"'Which way to the bank?' The guards at the gate must hear it a thousand times a week. They've stopped answering in words and simply point.",
	},
	["sw.muse.w19.wagon.013"] = {
		"Somebody always seems to be leaving with everything they own lashed to a wagon: a chair upside down on top, a cradle, a cat in a basket. The gate sees off whole lives and never asks why.",
		"A wagon piled with a whole household went past me, bedframe and pots and a birdcage on top. Wherever they were going, they'd decided it wasn't Stormwind.",
		"People leave this city as well as come to it. You only notice when the wagon has a rocking chair roped on top.",
	},
	["sw.muse.w19.wagon.014"] = {
		"steps back among the onlookers as a column of soldiers marches out toward the gate, boots in step on the bridge, and a few people in the crowd call out names.",
		"stands aside with everyone else while a company in fresh tabards tramps out across the bridge, and somewhere behind, someone keeps waving long after it can help.",
	},
	["sw.muse.w19.wagon.015"] = {
		"Coming in, the guards give you a once-over. Going out, nobody looks twice. Stormwind cares who it lets in and trusts the world to deal with the rest.",
		"The gate has two faces. Inbound, it studies you. Outbound, it has already forgotten you, and the road can have whatever's left.",
	},
	["sw.muse.w19.wagon.016"] = {
		"Whose wagon is this? It's been parked across the road so long the pigeons have filed a claim.",
		"Somebody move that wagon before it puts down roots.",
	},
	["sw.muse.w19.watch.001"] = {
		"At the corner by the bank, the paving stone under the guard's halberd has a pale dent in it. Years of the same butt, set down in the same spot, by whoever happens to be on duty.",
		"Somewhere in this city is a cobble with a little hollow worn into it by a halberd's butt. Same post, same stone, one guard after another, until the stone gave in first.",
		"Guards come and go at the posts; the dents their halberds leave in the paving stay. You could map the whole watch by its little holes.",
	},
	["sw.muse.w19.watch.002"] = {
		"notices two guards at a handover check each other's straps and buckles, quick and thorough, before one of them is allowed to go.",
		"sees a guard going off duty tug once at the strap of the one coming on, find it sound, and leave without a word.",
		"spots a guard about to go off duty straightening a younger one's helmet with two fingers, the way an aunt fixes a collar.",
	},
	["sw.muse.w19.watch.003"] = {
		"On duty, a guard of this city never leans on a wall. He leans on the halberd instead, at an angle very carefully chosen so that it doesn't count.",
		"No leaning, the sergeants say. So the guards lean on their halberds, a hair off true, and every sergeant in Stormwind pretends that is standing.",
		"A sergeant never sees a guard lean, the guards say, only a halberd that has drifted a little from upright. Halberds are always drifting.",
	},
	["sw.muse.w19.watch.004"] = {
		"A guard by the tram ramp has learned to say 'lost', 'stolen' and 'which way' in Dwarvish. His accent makes the dwarves wince, and they answer him anyway, slowly, like a favor.",
		"Four peoples, one watch. I just heard a guard repeat a gnome's complaint back to him, word by careful word, to be certain every grievance was in the right order.",
		"Somebody in the watch has taught himself enough Gnomish to understand 'it wasn't supposed to do that'. He says it covers most of the complaints he gets.",
	},
	["sw.muse.w19.watch.005"] = {
		"The watch keeps what the city drops: one glove, a child's shoe, a key to nobody knows what. A guard told me most of it is never asked for. People lose things and decide they never had them.",
		"Somewhere the guards keep a box of found things. A single glove waits in it for its other hand, which may be anywhere in the kingdom by now.",
		"Found things stay with the watch for a season, and then they're given away. There's a beggar in this city wearing three odd gloves, each one still waiting to be claimed.",
	},
	["sw.muse.w19.watch.006"] = {
		"Whatever else wobbles at court, the guards say, their pay comes on the right day. They say it the way you'd touch wood.",
		"The king is missing, the nobles are bickering, and the watch is still paid on the day. Every guard who mentions it sounds faintly surprised, and very careful not to jinx it.",
		"Very little at court earns the guards' trust, I think, except the paymaster. He comes on the day, every time, and they speak of him almost tenderly.",
	},
	["sw.muse.w19.watch.007"] = {
		"You can tell an off-duty guard without the tabard. He still picks the corner table, still watches the door, and still stands up straight to drink.",
		"Take away the blue and gold and a city guard is still a city guard: chair turned to face the room, ale held at attention.",
	},
	["sw.muse.w19.watch.008"] = {
		"Yes, it's me again. No, I haven't done anything. I just have one of those faces you keep seeing.",
		"Same traveler as before, guard. I'm only walking in circles because the canals made me.",
		"You've seen me twice already? Then you know I'm harmless. Dull, even.",
	},
	["sw.muse.w19.watch.009"] = {
		"hears a guard on one bank whistle two short notes to a guard on the other, who answers with one long one; whatever was said, both of them seem satisfied.",
		"catches a whistled exchange between two guards across the water, short, short, long, and looks from one to the other, none the wiser.",
		"listens to two guards trade whistles from bank to bank, a whole conversation in three notes, without understanding a syllable of it.",
	},
	["sw.muse.w19.watch.010"] = {
		"'Move along, friends.' In the mouth of a Stormwind guard, 'friends' does a great deal of work. Most of it is warning.",
		"Everyone is 'friend' to the guards here. It's polite, it's friendly, and it means 'I've remembered your face'.",
		"Every Stormwind guard has the same voice for 'good day' and 'that's far enough'. Learning to hear the difference is the first thing the city teaches.",
	},
	["sw.muse.w19.watch.011"] = {
		"The watch is thin for a city this size. The guards say half their old comrades were sent off to the kingdom's other troubles and never sent back.",
		"Ask a sergeant how many guards the city needs and how many it has. He'll give you two numbers and no opinion.",
		"Count the guards between the gate and the keep, then count the posts. The posts win, and the guards walk faster to make up the difference.",
	},
	["sw.muse.w19.watch.012"] = {
		"Nobody sings about the city watch, and they'd be embarrassed if anyone did. Still, every one of them would step in front of me without being asked. I'd like to be worth it.",
		"Under the polish, the watch is a few hundred tired people who've agreed to stand between this city and whatever comes for it. Our side doesn't thank them nearly enough.",
	},
	["sw.muse.w19.watch.013"] = {
		"observes a guard taking down a shopkeeper's complaint in a little book, licking the stub of a pencil between every word as if each one cost him something.",
		"lingers while a guard writes up a stolen basket in a cramped hand, reads it back aloud to its owner, and corrects a single word with enormous care.",
	},
	["sw.muse.w19.watch.014"] = {
		"Here in Old Town the guards know everyone's first name, and use their last. It's how you tell a greeting from a warning.",
		"Old Town guards don't need to ask who you are. They ask how your cousin is doing, and that's worse.",
		"In Old Town a guard who calls you by name is being friendly. A guard who calls you by your father's name has been reading something.",
	},
	["sw.muse.w19.watch.015"] = {
		"My business in the city? Walking, mostly. Looking lost, occasionally. I'm very good at both.",
		"Business? Some shopping, some sightseeing, absolutely no trouble. You can write that down.",
	},
	["sw.muse.w19.watch.016"] = {
		"Long watch, guard? Don't answer that. I know you're not allowed to look tired.",
		"You were standing right there the last time I passed, too. Do they ever let you sit, or is that treason?",
		"Stand easy. I won't tell your sergeant.",
	},
	["sw.muse.w19.watch.017"] = {
		"Thanks for standing there, guard. Somebody has to, and I'm glad it isn't me.",
		"I sleep better in this city knowing someone's awake on that corner. Carry on.",
	},
	["sw.muse.w19.watch.018"] = {
		"Is there a law against looking lost? No? Then I'm the most law-abiding soul in the city.",
		"Is it illegal to stand on a bridge without knowing which way to go? Because if it is, half the city's under arrest.",
	},
	["sw.muse.w19.widow.001"] = {
		"At the pie stall an old woman asks for two, then corrects herself before the vendor can move: one. She must have said 'two' for forty years, and the mouth is slow to learn.",
		"A widow at the bread stall orders two loaves out of habit, catches herself, and takes one. The baker wraps it without a word, the way anyone decent would.",
		"The cheese-seller cuts a widow's wedge in half before she asks. He has known her long enough to know what she asks for now.",
	},
	["sw.muse.w19.widow.002"] = {
		"passes a woman in faded black sweeping her doorstep and talking, warmly, to someone indoors who never answers.",
		"overhears an old widow on her step telling the empty doorway behind her the price of eggs, and pausing politely for a reply.",
	},
	["sw.muse.w19.widow.003"] = {
		"There are a great many women in black in Stormwind, and most of that black has faded to gray. Grief that old has stopped being news and become a color.",
		"A widow's black fades in the wash. In this city you can tell which war took the husband by how gray the mourning has gone.",
	},
	["sw.muse.w19.widow.004"] = {
		"The sign over the cobbler's still carries a man's name. His widow runs the shop now, and when customers ask for him she says he's out, which in a way is true.",
		"A widow keeps her husband's shop, his tools, and his name painted over the door. She's better at the trade than he ever was, the neighbors whisper, but nobody would dream of repainting.",
	},
	["sw.muse.w19.widow.005"] = {
		"On one doorstep a few widows gather to shell peas and compare late husbands: the snoring, the stubbornness, the one good dance. They laugh more than anyone else in the street.",
		"The widows of one lane share a step and a basket of mending, and speak of their dead husbands the way you'd speak of difficult, beloved neighbors who've moved away.",
	},
	["sw.muse.w19.widow.006"] = {
		"That woman wears two rings on a cord at her neck, one large, one small. You don't ask. You just let her go first at the counter.",
		"A ring too big for any of her fingers hangs from a ribbon at her throat. She touches it when the bells ring. I've stopped pretending not to see.",
		"Older women in the city sometimes wear a man's ring on a string around the neck. It is not a fashion. Nobody here mistakes it for one.",
	},
	["sw.muse.w19.widow.007"] = {
		"When a guard falls on the Westfall road, the guards say, the widow gets his tabard back folded square and a purse that won't see out the season. The tabard she keeps.",
		"A folded tabard of blue and gold lies in a window down one lane, faded where the light reaches it. The guards who walk past straighten their own a little.",
	},
	["sw.muse.w19.widow.008"] = {
		"follows the slow work of a widow at an upper window closing her shutters as the light goes, one, then the other, slowly, like someone ending a conversation.",
		"sees an old woman at a high window take a last look down the street as dusk comes on, as though counting everyone home, before she draws the shutters.",
	},
	["sw.muse.w19.widow.009"] = {
		"Some of the widows in this city lost their men to the Defias; a few lost them to the Defias' cause. They shop at the same stalls and are terribly polite to one another.",
		"Two widows on one lane: one husband died guarding the Westfall road, the other died on the wrong side of it. They nod to each other every day, and that nod costs them both something.",
	},
	["sw.muse.w19.widow.010"] = {
		"Not all the black in this city is mourning. One widow on the lane says she wears it because it hides the soot, and that her husband, rest him, never noticed what she wore anyway.",
		"A widow down by the forges has worn black for ten years and makes no secret of the reason. 'Doesn't show the soot,' she says, 'and he'd have laughed.'",
	},
	["sw.muse.w19.widow.011"] = {
		"Half the households in this city keep a name in mind for someone the orcs took, in the First War or the Second. Grief here is almost a kind of citizenship.",
		"Ask any old woman in Stormwind and she'll name someone the wars took from her. Humans keep their dead close; in this city it gets crowded.",
	},
	["sw.muse.w19.widow.012"] = {
		"is pressed by an old woman in faded black to take a still-warm bun from her basket, 'since nobody eats them now'.",
		"is stopped by a widow with a basket of buns she still bakes for two out of habit, and handed the spare one with orders to eat it properly, sitting down.",
	},
	["sw.muse.w19.widow.013"] = {
		"An old woman stops on the same bridge every time the bells ring for a funeral, any funeral, and stands there until it's done. Hers was long ago, someone told me. She keeps attending.",
		"Whenever a funeral passes, whoever it's for, the same widow walks behind it for a street or two and then turns off. She knew none of them. She knows the walk.",
	},
	["sw.muse.w19.widow.014"] = {
		"After you, ma'am. Please. I'm in no hurry at all.",
		"Let me take that basket as far as the corner for you. It's on my way, whatever my way is.",
		"Mind the cart, ma'am. Take my arm as far as the other side.",
	},
	["sw.quest_complete.w19.after.001"] = {
		"stands a moment with nothing to do, which in Stormwind lasts about as long as it takes a stranger to ask {g:him|her} the way.",
		"has barely turned from the business when a lost pilgrim asks {g:him|her} for directions, as if finished work showed on the face.",
		"takes ten steps before someone asks the way to the bank, and points without even looking, the way locals do.",
	},
	["sw.quest_complete.w19.after.002"] = {
		"That odd stretch right after a job, when nobody needs anything from me and I can't remember what I wanted before they did.",
		"The first minutes after are always the strangest. My hands are free and my head hasn't caught up with them.",
		"Right after is a strange country. Nobody needs me, and I've forgotten what it was I needed.",
	},
	["sw.quest_complete.w19.after.003"] = {
		"sets off at a brisk pace, then slows at the first corner on realizing there is, for once, nowhere to be.",
		"walks away quickly out of pure habit, and only two streets later remembers there is no reason to hurry.",
		"starts off at a job's pace, catches the mistake halfway down the street, and lets the stride go loose.",
	},
	["sw.quest_complete.w19.after.004"] = {
		"Funny: while the job was on my mind the whole city was muffled. Now every cart and crier is back at full volume.",
		"The noise of Stormwind comes back all at once, as if somebody opened a door. I hadn't noticed I'd stopped hearing it.",
		"Only now do I hear the street again: hammers, haggling, a dog with opinions. The job had been standing in front of all of it.",
	},
	["sw.quest_complete.w19.after.005"] = {
		"stops at a public basin to rinse both hands, and stays there a little longer than clean hands require.",
		"dips both hands in the cold water of a street basin and leaves them there a moment after they are already clean.",
	},
	["sw.quest_complete.w19.after.006"] = {
		"Now. What was I doing before I said yes to that?",
		"Before all this I was on my way somewhere. Anyone see where?",
		"I had plans before I got involved. Small ones. I think they involved a chair.",
	},
	["sw.quest_complete.w19.after.007"] = {
		"I catch my face in a shop window and it looks faintly pleased with itself. Fair enough. Let it.",
		"A glimpse of myself in a glazier's window: the look of someone who just did a thing properly. I'll allow it, for one street.",
		"My reflection in a polished doorplate looks smug. I've no idea where it gets that from.",
	},
	["sw.quest_complete.w19.after.008"] = {
		"pulls a creased scrap of paper from a pocket, finds the line that matters, and scores it through with a thumbnail.",
		"takes out a much-folded list, runs a finger down it, and crosses one line out with a stub of charcoal.",
	},
	["sw.quest_complete.w19.after.009"] = {
		"Finishing one job is how I find out how many others I've been ignoring. The list behind this one has grown teeth.",
		"With that off the pile I can finally see the pile. It's taller than I'd hoped.",
	},
	["sw.quest_complete.w19.after.010"] = {
		"picks up a glove someone has dropped, looks about for its owner, and in the end lays it on a windowsill where it might be found.",
		"notices a fallen glove in the street, turns all the way round for whoever lost it, and props it on a doorstep, fingers up.",
		"finds a child's wooden toy lying in the gutter, sets it on the nearest step, and walks on without waiting to see who claims it.",
	},
	["sw.quest_complete.w19.after.011"] = {
		"Give me a moment. I'd like to stand here and be finished for a little while.",
		"Nobody hand me anything. I'm enjoying having empty hands.",
		"Just a moment's peace, please. I've earned the right to stand about uselessly.",
	},
	["sw.quest_complete.w19.after.012"] = {
		"is bumped by a hurrying clerk with an armful of scrolls, who apologizes to the empty air two paces later.",
		"gets an elbow from a courier in a rush, and a 'sorry' that arrives some way down the street, long after the courier.",
	},
	["sw.quest_complete.w19.after.013"] = {
		"Finished, and nobody in particular to tell. A city this crowded shouldn't feel lonely. It does, a little, for about one street.",
		"There's no one to say 'it's done' to. Thousands of people in earshot, and not one of them is waiting for the news.",
	},
	["sw.quest_complete.w19.after.014"] = {
		"sits down on the step of a front door to rest the legs, and gets up again quickly when the door opens behind {g:him|her}.",
		"takes a seat on a merchant's crate for a moment's rest, until the merchant's long look makes the point without a word.",
		"lowers {g:himself|herself} onto a stone bollard at a street corner, a seat the whole city seems to have agreed is free.",
	},
	["sw.quest_complete.w19.after.015"] = {
		"Even in here Stormwind leaks under the door: wheels, a shout, a dog. The city is waiting for me to step out into it.",
		"Stout walls, a quiet room, and still the street seeps through the shutters, impatient. One more minute under this roof, then I'll answer it.",
	},
	["sw.quest_complete.w19.after.016"] = {
		"stands a little straighter as a patrol of the Watch goes by, for no reason anyone could name, and eases again once it has passed.",
		"feels {g:his|her} back straighten of its own accord as a file of guards marches past, and lets it go only when the last helm has turned the corner.",
	},
	["sw.quest_complete.w19.after.017"] = {
		"I'd like to tell somebody how it went. The baker is busy, the guard pretends not to hear, so I'll tell myself, at length.",
		"I've a whole account of this in me and nobody to hear it. Fine. I'll recite it to my boots as I walk.",
	},
	["sw.quest_complete.w19.after.018"] = {
		"glances back once over a shoulder, half expecting to be called back for something forgotten, and walks on when nobody calls.",
		"turns at the corner for a last look, as people do when a thing has ended more quietly than expected, then goes on.",
	},
	["sw.quest_complete.w19.after.019"] = {
		"The street looks friendlier than it did before. The street hasn't changed. I'm the one who put something down.",
		"Same cobbles, same crowd, and somehow kinder-looking. Finishing a thing does that to a city, briefly.",
	},
	["sw.quest_complete.w19.after.020"] = {
		"Finished with the lamps already lit. The street's gone quiet, and the only others still out are the Watch, looking about as tired as I feel.",
		"Late, and the city's mostly gone to bed. A guard's lantern swings at the end of the street; the guard and I trade the nod of the last two people awake.",
	},
	["sw.quest_complete.w19.after.021"] = {
		"makes way for a line of sleepy apprentices trudging to their masters' workshops, the city's first shift passing someone whose work is already done.",
		"walks off past shutters still closed, meeting only apprentices on their way to work, who look at someone already finished with frank resentment.",
	},
	["sw.quest_complete.w19.after.022"] = {
		"Done, and the rain can do as it likes now. There's nowhere I have to be, so there's no reason to run.",
		"Everyone else is hurrying for cover. I've just finished, so I walk, and the rain can come along if it wants.",
	},
	["sw.quest_complete.w19.after.023"] = {
		"walks off into the fog and is lost to sight within ten paces, as though the city had folded the whole business up and put it away.",
		"turns down a street whose far end the fog has swallowed, and lets it swallow {g:him|her} too, unhurried.",
	},
	["sw.quest_complete.w19.clerk.001"] = {
		"That thanks was delivered in the voice of someone reading down a list. I was somewhere around item four.",
		"Thanked in the tone of a roll call. I half expected to have to answer 'present'.",
		"The words were kind; the voice was the voice of a list being worked through. Stormwind's gratitude has a great many names on it.",
	},
	["sw.quest_complete.w19.clerk.002"] = {
		"waits through a thanks that is broken off twice, once for a passer-by asking the way and once for a runner with a note.",
		"gets {g:his|her} thanks in installments, between other people's questions, and stands patiently until the last installment arrives.",
		"receives the end of a sentence of thanks some moments after its beginning, the middle having gone to somebody else.",
	},
	["sw.quest_complete.w19.clerk.003"] = {
		"The one who thanks you in this city is rarely the one who remembers you. Remembering is somebody else's job, further up, and they're busy.",
		"Thanks are handed out at street level here. Memory is kept higher up, in rooms I'll never see, by people who never met me.",
	},
	["sw.quest_complete.w19.clerk.004"] = {
		"Name? Put down 'the one who did it'. It's accurate.",
		"Title? None. Write 'a passing pair of hands' and underline it.",
		"No rank, no house, no letters after my name. Just the work, I'm afraid.",
	},
	["sw.quest_complete.w19.clerk.005"] = {
		"Half the people who give out work in Stormwind have ink on their fingers. The other half have flour, or soot, or tar. The stain tells you what kind of trouble you're in.",
		"I've learned to read the hands that pay me here: ink means paperwork, soot means the forges, flour means somebody's in a hurry. They're seldom wrong.",
		"In this city you can guess the job from the hand that gives it. Ink-stained ones want something found; scarred ones want something stopped.",
	},
	["sw.quest_complete.w19.clerk.006"] = {
		"goes through the city's whole courtesy in order: the thanks, the nod, one remark about the price of bread, and release.",
		"is taken briskly through the ritual of a Stormwind thanks, word, nod and a short remark on the traffic of the bridges, and then let go.",
		"submits to the polite little ceremony the city keeps for such moments, and is released from it with the precision of a drill.",
	},
	["sw.quest_complete.w19.clerk.007"] = {
		"No, don't get up. I'll see myself out of the conversation.",
		"Don't let me keep you. You've plainly got the next one waiting.",
		"I can see you're busy. Go on; I'll thank myself on your behalf.",
	},
	["sw.quest_complete.w19.clerk.008"] = {
		"For a moment everything else stopped: the papers set down, the next person waved off, both eyes on me. In this city that's a rare kind of pay.",
		"They put down whatever they were holding to say it. In Stormwind, where every hand is always full, that counts for a great deal.",
		"Full attention, for the length of a thank-you. Nobody in this city has that to spare, and I was given it.",
	},
	["sw.quest_complete.w19.clerk.009"] = {
		"tries to read upside down the little book in which the business is being noted, and makes out only the date.",
		"watches the matter go into a battered notebook in tiny cramped letters, and does not ask to see the page.",
		"leans a fraction to see what is being written about the business, catches the word 'satisfactory', and straightens again.",
	},
	["sw.quest_complete.w19.clerk.010"] = {
		"Asked by one of you, thanked by another, paid by a third. Is there a department for gratitude too?",
		"One person for the asking, one for the thanks, one for the coin. Stormwind never does anything with a single pair of hands.",
		"Do I thank you, or the one who thanked me, or the one who paid? I've lost track of the chain of command.",
	},
	["sw.quest_complete.w19.clerk.011"] = {
		"The people who hand out work in this city all have the same look, as if they haven't sat down since the regency began.",
		"Tired eyes behind the thanks. Everyone who keeps Stormwind running seems to be doing it without help, and for longer than anyone intended.",
		"Whoever gives out tasks here thanks you with the face of someone holding up one corner of a kingdom. Most of them are.",
	},
	["sw.quest_complete.w19.clerk.012"] = {
		"Is this the right window for the thanks, or do I queue somewhere else?",
		"Thanks received. Do I take a token and wait to be called for the rest?",
		"Which door do I knock on for the gratitude? There's always a door.",
	},
	["sw.quest_complete.w19.clerk.013"] = {
		"The thanks came in the same voice anyone would use for a delivery of nails. I don't hold it against them; I suspect it's how people here get through the week.",
		"Flat, formal and quick, as if the matter had been a small one. I've learned that in Stormwind the flatter the voice, the bigger the worry it's holding down.",
	},
	["sw.quest_complete.w19.clerk.014"] = {
		"stands by while the matter is written down, blotted, read back in a murmur, and copied out again more neatly.",
		"waits through two drafts of a note about the business, the second apparently the fair copy.",
		"watches a single line about the business written, sanded, squinted at and, after some thought, underlined.",
	},
	["sw.quest_complete.w19.clerk.015"] = {
		"'Good traveler'? I do have a name. Never mind; keep the courtesy, it suits you.",
		"'Friend', is it? Polite of you. You'll want my name for the book, I suppose.",
	},
	["sw.quest_complete.w19.clerk.016"] = {
		"You look as though you need thanking more than I do. So: thank you.",
		"Get some rest, if this city ever lets you. I mean that.",
		"And thank you, for the trust. Now sit down a moment, before you fall down.",
	},
	["sw.quest_complete.w19.clerk.017"] = {
		"The thanks came out of the fog a moment before the face did. In weather like this the whole city is just voices doing business.",
		"Fog on the street, so the pay and the thanks seemed to come from nowhere. A very Stormwind way to be rewarded: politely, by a shape.",
	},
	["sw.quest_complete.w19.clerk.018"] = {
		"There's a queue forming behind me. I'll step aside before it turns ugly.",
		"I'll get out of the way. Stormwind always has someone waiting.",
		"Right behind me is somebody else's trouble. Over to you.",
	},
	["sw.quest_complete.w19.coin.001"] = {
		"Exact to the copper, and handed over as if rounding up were a crime in Stormwind. Possibly it is.",
		"Not a copper more than agreed, not a copper less. This city would sooner lose a tooth than round a sum up.",
		"The pay came to the exact copper. Generosity here is measured with a ruler.",
	},
	["sw.quest_complete.w19.coin.002"] = {
		"is handed the pay folded into a twist of paper, the sum written on the outside in a small, careful hand, and tucks it away unopened.",
		"receives the coin wrapped in a scrap of parchment with the figure inked across it, and pockets the little parcel just as it is.",
		"is given a tidy paper packet of coin, labeled with its own total, the way perhaps only a capital would think to pay.",
	},
	["sw.quest_complete.w19.coin.003"] = {
		"Look at me, a person of means. That should last as far as the Trade District.",
		"Rich! Briefly. The auction house is only a few streets off.",
		"Wealth at last. I give it until the first shop window.",
	},
	["sw.quest_complete.w19.coin.004"] = {
		"Pay in this city always smells of whoever kept it last: ink, lamp oil, onions, incense. You could guess a trade by sniffing the purse.",
		"Every coin handed over in Stormwind carries the smell of its last pocket. Tallow, parchment, a baker's flour. I never sniff mine where anyone can see.",
		"Coins pick up the trade of every hand they cross. These smell faintly of candle wax and somebody's pipe.",
	},
	["sw.quest_complete.w19.coin.005"] = {
		"is handed the pay along with an apology for its size, the apology rather the longer of the two, and accepts both.",
		"receives a modest sum and a long regret that it isn't more, and pockets the coin while the regret is still being explained.",
		"listens to an earnest apology for the size of the reward, nods all the way through it, and puts the reward away regardless.",
	},
	["sw.quest_complete.w19.coin.006"] = {
		"squares the coins on a flat palm with one finger, the way a clerk squares a stack of papers, and tips them into the pouch.",
		"taps the little pile of pay into a neat column against the heel of the hand before letting it drop into the purse.",
		"stacks the pay with the care of a counting-house, every edge aligned, then spoils the effect by tipping it all into the pouch at once.",
	},
	["sw.quest_complete.w19.coin.007"] = {
		"A small boy by the wall watched every coin go into my pouch. Not greedy; just learning what work looks like when it gets paid.",
		"Across the way a child followed the pay from one hand to the other with careful eyes, like someone studying a trade she means to learn.",
		"There was a ragged girl on the steps nearby, watching the pay change hands. In Stormwind even the urchins keep accounts.",
	},
	["sw.quest_complete.w19.coin.008"] = {
		"Straight to the bank with this, before the shops find out.",
		"This goes in a vault. Every merchant between me and the bank will try to talk it out of my pocket first.",
		"To the bank, quickly, and by the back lanes. Shopkeepers in this city have ears like hounds.",
	},
	["sw.quest_complete.w19.coin.009"] = {
		"Is there a tax on this? Don't tell me. I'd rather walk to the bank in ignorance.",
		"Surely the crown wants a slice of this. If its collector is looking for me, I'm very hard to find.",
		"In a kingdom this fond of paperwork there must be a tax on rewards. Nobody mention it.",
	},
	["sw.quest_complete.w19.coin.010"] = {
		"is paid without the hands ever touching: the coins come down into an open palm from a careful inch above it.",
		"holds out a palm and receives the pay dropped into it from just above, with the fastidious courtesy of someone who keeps clean cuffs.",
		"takes the coins as they are let fall one by one, a small clatter of copper, without a finger of the giver brushing {g:his|her} own.",
	},
	["sw.quest_complete.w19.coin.011"] = {
		"Honest pay for honest work. In a kingdom where men put on red masks for want of exactly this, I don't take it lightly.",
		"The Defias began with wages nobody paid. Every fair coin handed over in Stormwind is a small argument against them.",
		"Paid, and paid fairly. Out west there are masked men who would tell you that is the whole of the quarrel.",
	},
	["sw.quest_complete.w19.coin.012"] = {
		"This is too much. No? Well, I won't argue twice.",
		"Are you sure about the sum? I'm asking once. Only once.",
		"That seems generous. I'll protest a little, for form's sake. There, protested.",
	},
	["sw.quest_complete.w19.coin.013"] = {
		"Stormwind coin, for Stormwind work. I'd have done it for less. Nobody needs to know that.",
		"I'd have done this one for nothing, for the kingdom's sake. The kingdom paid anyway. Good; my secret keeps.",
		"The Alliance could have had this from me for a handshake. It paid instead, and properly, which is why it's worth the handshake.",
	},
	["sw.quest_complete.w19.coin.014"] = {
		"pockets the pay quickly, before the rain can get at it, and buttons the flap down over the pouch.",
		"shields the coins from the rain with a cupped hand and gets them into the purse still beaded with water.",
		"hunches over the open pouch against the rain while the pay goes in, then cinches it tight with wet fingers.",
	},
	["sw.quest_complete.w19.coin.015"] = {
		"Paid by lamplight, where copper and silver turn the same color. I'll find out at the bank which it was.",
		"Every coin goes the color of the lamps at this hour. Whatever I was given, it looks like a good deal of something.",
		"The pay changed hands under a street lamp, and the coins came out all alike, little yellow moons with no denomination.",
	},
	["sw.quest_complete.w19.coin.016"] = {
		"The pouch is nicer than what's in it. Stormwind does love its wrapping.",
		"Embroidered drawstring, little brass toggle. This city dresses its money for court.",
		"A purse with a tassel, if you please. The coins inside look slightly embarrassed.",
	},
	["sw.quest_complete.w19.coin.017"] = {
		"Paid before the shops are even open. Coin in hand and nowhere to spend it.",
		"Pay in my pocket and every shutter still down. The city's timing is impeccable.",
		"Early pay, closed shops. For once my coin will have to wait for me.",
	},
	["sw.quest_complete.w19.coin.018"] = {
		"The coins had the look of money saved a little at a time, in a jar or a sock. Someone went without to pay for this.",
		"Not a banker's coin, this. Worn, a little dull, gathered up slowly by the feel of it. I'll spend it carefully.",
		"Small coins, old ones, the kind that sit at the back of a drawer until they're needed. They were needed for me.",
	},
	["sw.quest_complete.w19.duty.001"] = {
		"The regent can't be on every street. Somebody had to be on that one.",
		"Bolvar holds the kingdom; he can't hold every small thing in it. Some of those fall to whoever is passing. This one fell to me.",
		"Up in the keep sits a throne with no grown man on it. The city runs on smaller chairs, and I just sat in one.",
	},
	["sw.quest_complete.w19.duty.002"] = {
		"The decrees carry a child's name. Work like this carries nobody's, which may be why it gets done.",
		"No seal, no herald, no name on it. Small work in a kingdom without its king, and the kingdom keeps going on exactly that.",
	},
	["sw.quest_complete.w19.duty.003"] = {
		"I was paid in full. Not everyone who ever did work for Stormwind can say that.",
		"Paid, and promptly. In this city that's worth noticing; there are whole families in Westfall who could tell you why.",
		"Fair pay for fair work. Say it slowly in Stormwind and watch which faces change.",
	},
	["sw.quest_complete.w19.duty.004"] = {
		"Guards keep the walls, clerks keep the ledgers, priests keep the bells. The loose ends go to whoever's willing. Lately that's me.",
		"Every city has a list of jobs nobody wrote down. Stormwind's just got one line shorter, and nobody will ever see the list.",
		"The Watch has its rounds and the nobles have their councils. In between lie the small jobs, and somebody has to pick them up.",
	},
	["sw.quest_complete.w19.duty.005"] = {
		"Somebody tell the regent he can cross that one off. He'll never hear of it, but tell him.",
		"One less worry for the keep. Not that the keep will ever know it had it.",
	},
	["sw.quest_complete.w19.duty.006"] = {
		"If the king ever rides in again, he'll find a city that kept itself together without him. A thousand small jobs did that. One of them was mine.",
		"Whatever happened to Varian, the city didn't wait to find out. It kept mending itself, errand by errand, and just now the errand was me.",
	},
	["sw.quest_complete.w19.duty.007"] = {
		"The Alliance is a big word for parchment and councils. On a street like this it's smaller: somebody needs help, somebody says yes.",
		"Treaties hold the Alliance together on paper. Work like this holds it together on the cobbles.",
	},
	["sw.quest_complete.w19.duty.008"] = {
		"Did that help Stormwind, or only one person in it? I can't tell, and maybe there's no other way to help a city.",
		"One person helped. Whether the city noticed is another matter. I suspect a city is mostly people who never hear of each other's troubles.",
		"A city is a sum of small rescues, I think. Nobody adds them up, but the total is why the place still works.",
	},
	["sw.quest_complete.w19.duty.009"] = {
		"Their trouble gone, my purse a little heavier. Show me a fairer trade in this city.",
		"One problem less for them, a few coins more for me. The merchants could learn something from a bargain like that.",
	},
	["sw.quest_complete.w19.duty.010"] = {
		"glances up toward the towers of the keep, where somewhere a boy is being taught to rule, then lowers the eyes to the street, where the ruling actually happens.",
		"lifts {g:his|her} eyes to the keep's high towers for a moment, as if to report, and finds no one there to report to.",
	},
	["sw.quest_complete.w19.duty.011"] = {
		"Somebody in Stormwind will sleep a little easier. I wouldn't know them on the street, and that's as it should be.",
		"A small worry gone from one house. The house won't remember my name, and I'd rather it didn't need to.",
		"One less thing keeping someone awake. I'll never meet the pillow, but I'm glad for it.",
	},
	["sw.quest_complete.w19.duty.012"] = {
		"Too many of the city's own are posted far away, on walls with other names. So Stormwind asks whoever's passing through, and whoever's passing says yes.",
		"If the garrisons were home, nobody would need me for jobs like that. They aren't, and the city makes do with the hands it has.",
	},
	["sw.quest_complete.w19.duty.013"] = {
		"Long live the young king, and may his father be found. Until then, the rest of us carry what we can.",
		"The lion still needs feeding, crown or no crown. Glad to do my share.",
	},
	["sw.quest_complete.w19.duty.014"] = {
		"It wasn't glorious work. Most of what keeps a city upright isn't; it's drains and debts and doors that shut properly.",
		"Nobody will sing about that one. Cities aren't held up by songs. They're held up by gutters, hinges and someone willing to bother.",
	},
	["sw.quest_complete.w19.duty.015"] = {
		"stoops to pick a broken bit of crate out of the middle of the street and sets it by a wall, the habit of fixing things not yet switched off.",
		"fastens a shutter banging loose on its hook in passing, as if the hands had not yet been told the work is over.",
	},
	["sw.quest_complete.w19.duty.016"] = {
		"The boy in the keep will inherit a city mended by strangers' hands. I hope someone tells him that, some day, when he's old enough to listen.",
		"Anduin will rule over streets that people like me patched while he sat at his lessons. He'll never know who did it. Good; he'll have enough to remember.",
	},
	["sw.quest_complete.w19.duty.017"] = {
		"A kingdom missing its king leans on whoever's nearest. I'd sooner be leaned on than be the one who stepped aside.",
		"When the crown sits empty the weight spreads out, a little onto everyone. I just carried my little.",
	},
	["sw.quest_complete.w19.duty.018"] = {
		"Plenty of people did this sort of work for Stormwind before me, and none of them got a plaque. Good company, whoever they were.",
		"Others passing through have run errands for this city before me, and others will after. A long line of nameless hands nobody ever wrote down.",
	},
	["sw.quest_complete.w19.duty.019"] = {
		"Work for Stormwind never feels quite like work. More like sweeping the front step of a house the whole Alliance shares.",
		"Whatever I do for this city, I'm doing for every ally who comes through its gate. A shared house needs shared chores.",
	},
	["sw.quest_complete.w19.ledger.001"] = {
		"In some ledger this is now one line, between a delivery of nails and a complaint about a drain. I'm in honest company.",
		"Written down, I'd guess, just below the price of lamp oil and just above a dispute over a fence. That's the right height for it.",
		"Somewhere it'll sit in a column between a broken cart axle and a lost goat. Stormwind's history, one small line at a stroke.",
	},
	["sw.quest_complete.w19.ledger.002"] = {
		"Mark it settled, and blot it properly. I don't want it smudging into the next fellow's line.",
		"Write it neatly, please. I'd hate to be mistaken for a grain order.",
		"In ink, if you would, and blotted well.",
	},
	["sw.quest_complete.w19.ledger.003"] = {
		"This city's books balance to the copper, the scribes like to say. All but one old account, the one with the masons in it.",
		"Stormwind pays what it owes these days, and pays it exactly. It learned the price of the other way out in Westfall.",
	},
	["sw.quest_complete.w19.ledger.004"] = {
		"In some counting room of the Trade District my bit of work will become a figure in a column. It'll look very small there, which is how it should look.",
		"By the time this reaches a counting room it'll be three figures and a date. Everything else about it stays with me.",
		"Reduced to a sum, the work will look like nothing much. Sums are like that. They leave out the walking.",
	},
	["sw.quest_complete.w19.ledger.005"] = {
		"Do you keep a list of everyone who's helped? How long is it? Am I near the top?",
		"Is there a book of names for this sort of thing? I'd like to know what company I'm keeping.",
		"Is my name going in a book somewhere? Put it beside someone pleasant.",
	},
	["sw.quest_complete.w19.ledger.006"] = {
		"Every honest job done in this city is a line on the good side of the kingdom's ledger. Somebody has to keep writing there, with the Defias so busy on the other.",
		"The kingdom keeps two columns, it seems to me: what's been mended and what's been broken. I've just added to the shorter one.",
		"Somewhere a page of Stormwind's troubles got one line shorter. The page is long, but the ink only goes one way.",
	},
	["sw.quest_complete.w19.ledger.007"] = {
		"is asked for {g:his|her} name for the record, says it twice, letter by letter, and watches it written down a third way.",
		"gives {g:his|her} name for the record and watches the quill improve on it, with great confidence.",
		"repeats {g:his|her} name for the record, then repeats it again more slowly, and leans in to see the result with resignation.",
	},
	["sw.quest_complete.w19.ledger.008"] = {
		"Every unpaid debt in this kingdom ends up on some desk near the throne eventually. This one, at least, never will.",
		"Somewhere near the throne there must be a pile of the kingdom's unpaid bills, waiting for a king to come back and look at them. I'm glad mine isn't in it.",
	},
	["sw.quest_complete.w19.ledger.009"] = {
		"Pay, thanks, a line in a book. The thanks will have faded by supper; the ink won't. Stormwind trusts ink.",
		"The ink will still be there long after the thanks has faded, and that's the part of me Stormwind will keep.",
		"Words go out of a city like smoke out of a chimney. Ink stays. I know which of the two this place believes.",
	},
	["sw.quest_complete.w19.ledger.010"] = {
		"Put it on my account. I don't have one? Then start one; I'll be back.",
		"Open a page for me. I have a feeling there'll be more lines.",
		"Keep my name handy. I don't intend to stop at one entry.",
	},
	["sw.quest_complete.w19.ledger.011"] = {
		"The old city burned with all its records, the scribes say, and the new one writes everything down twice. I can hardly blame it.",
		"Lose a whole archive to an orcish fire and you'd keep copies of your thank-yous too. Stormwind remembers what forgetting cost it.",
		"The scribes of the first city, it's told, watched its records go up in smoke. Their heirs file everything in triplicate, and nobody here laughs at them for it.",
	},
	["sw.quest_complete.w19.ledger.012"] = {
		"folds a scrap of paper into the pack among a dozen others like it, a small private archive of errands run in this city.",
		"adds a creased note to a bundle of older ones kept in the pack, and ties the string around them again.",
		"writes two words on a slip of paper with a stub of charcoal, considers them, and files the slip away in the pack.",
	},
	["sw.quest_complete.w19.ledger.013"] = {
		"If any of this came out of the crown's purse, it came with a regent's signature on the order. The kingdom pays its debts, king or no king.",
		"No king to put his name to the kingdom's accounts, and the pay still comes on time. Whoever keeps the books for Bolvar keeps them honest.",
	},
	["sw.quest_complete.w19.ledger.014"] = {
		"Whatever goes in the book will be the outcome. The rest of it, the part I'd actually tell, has no column.",
		"Ledgers keep the what and the how much. The why never fits between the lines, so I carry that out myself.",
		"A clerk could total the job in a moment. The bits that mattered don't add up to anything, and I'm keeping them.",
	},
	["sw.quest_complete.w19.ledger.015"] = {
		"No receipt? Then I'll remember for both sides.",
		"Keep your copy. I'll keep mine up here.",
		"If anyone asks, I was paid in full. I'll swear to it, if you will.",
	},
	["sw.quest_complete.w19.ledger.016"] = {
		"Broad day, and the city's books are wide open: every counter busy, every quill moving. Mine is one small entry in a very full day.",
		"At this hour half of Stormwind seems to be writing something down. My bit went in among the rest, between two louder ones.",
	},
	["sw.quest_complete.w19.ledger.017"] = {
		"Some day a clerk not yet born will audit this line and wonder who I was. I hope my name puzzles them a little.",
		"Years from now somebody will dust off the book this went into and frown at my name. Hello, whoever you are. It went well.",
		"Long after the coin is spent, the entry will still be there, waiting for a reader. I'd like to think it reads kindly.",
	},
	["sw.quest_complete.w19.nod.001"] = {
		"nods back, and a small child nearby, who has been watching, nods too, very gravely, at the air.",
		"returns the nod and catches a little girl across the way practicing the same motion, solemnly, on her own reflection in a window.",
	},
	["sw.quest_complete.w19.nod.002"] = {
		"A Stormwind nod goes up, not down: the chin lifts, the eyes half close. You're acknowledged and dismissed in a single movement.",
		"That was the upward nod, the one the nobles use. It means 'well done' and 'that will be all', and never quite settles on which.",
		"Chin raised a fraction, lids lowered a fraction: the city's genteel nod. I've been approved of and sent off at once.",
	},
	["sw.quest_complete.w19.nod.003"] = {
		"A nod! Careful, I hear they're rationed in this city.",
		"That's a whole nod. You'll spoil me.",
		"A nod, and so promptly. Stormwind must be in a generous mood.",
	},
	["sw.quest_complete.w19.nod.004"] = {
		"nods, is nodded at, nods once more by accident, and the exchange threatens to go on until somebody has the sense to step back.",
		"gets caught in a polite loop of nods with the other party, each answering the last, until a stranger's question breaks it up.",
		"dips the head, receives a dip in return, and answers that out of reflex, the two of them bobbing like boats tied side by side.",
	},
	["sw.quest_complete.w19.nod.005"] = {
		"Not much was said, but the nod held a moment longer than it had to. In a city this busy, that's as warm as public life gets.",
		"One nod, held just past the polite length. Stormwind doesn't do embraces in the street; it does that.",
		"The nod stayed down an instant too long to be mere manners. From a capital, I'll take that as affection.",
	},
	["sw.quest_complete.w19.nod.006"] = {
		"My nod came out too deep, nearly a bow. Someone will take me for a petitioner at court.",
		"I overdid the nod. Halfway down it turned into a bow, and there was no graceful way back up.",
		"Too much nod. Far too much. I looked like someone thanking a duke for a pardon.",
	},
	["sw.quest_complete.w19.nod.007"] = {
		"is thanked with a finger lifted to a hat brim, or to where a hat brim would be, a courtesy that seems older than the street itself.",
		"receives the brief tip of a cap and, having no cap of {g:his|her} own to hand, tips an imaginary one in reply.",
		"answers a touch to a hat brim with a touch to the forehead, the nearest brim available.",
	},
	["sw.quest_complete.w19.nod.008"] = {
		"Same to you. And good luck with the next ten.",
		"And to you. May your next problem be a smaller one.",
		"Right back at you, with my compliments to whoever's next.",
	},
	["sw.quest_complete.w19.nod.009"] = {
		"Everybody in this city thanks me downward. I've decided to take the angle as respect and the words as meant.",
		"Thanked from a great height, as usual. Humans can't help it, and the ones who crouch to do it are worse.",
		"A nod from up there, aimed somewhere over my hat. The intention arrived, at least.",
	},
	["sw.quest_complete.w19.nod.010"] = {
		"Humans nod as if they're afraid of bruising their necks. A thanks in Ironforge comes with a clap on the back that rattles your teeth.",
		"Polite, this lot. A dwarf would have thanked me with a slap on the shoulder and a round of stout. Here it's a nod, and the street.",
		"A tidy little human nod. Back under the mountain they'd have bought the first round and argued over the second.",
	},
	["sw.quest_complete.w19.nod.011"] = {
		"My people take their time over gratitude. Here it's said and finished before the sentence has properly ended, and it's meant just the same.",
		"Humans thank as if the words were costing them by the moment. Among my own people we'd still be at the first courtesy.",
		"Quick thanks, quickly gone. Humans live as if every word were borrowed. Perhaps, for them, it is.",
	},
	["sw.quest_complete.w19.nod.012"] = {
		"We humans thank the way we build: quickly, squarely, and already eyeing the next wall.",
		"Humans are brisk with gratitude. I should know. We say it, we mean it, and we're halfway to the door.",
		"A short thanks and a long list of things still to do. That's us, the whole race, in one exchange.",
	},
	["sw.quest_complete.w19.nod.013"] = {
		"Judging by that nod, my boots didn't pass inspection. Fair. They've earned the mud.",
		"Short nod, long look at my boots. Stormwind measures a person from the ground up.",
		"You glanced at my boots before you nodded. They do the work; they get the looks.",
	},
	["sw.quest_complete.w19.nod.014"] = {
		"trades a quick nod with the other party under a dripping lintel, both pressed back from the storm, and the business ends in a gesture.",
		"nods once over the din of the storm, since no word would carry, and the matter closes on that.",
		"has the thanks shouted across a span of streaming cobbles, catches perhaps one word in three, and nods to all of them.",
	},
	["sw.quest_complete.w19.nod.015"] = {
		"That's a very official nod. Am I meant to salute?",
		"A proper Stormwind nod, that. Do I bow, or does that start a whole thing?",
	},
	["sw.quest_complete.w19.nod.016"] = {
		"Some nods in this city carry more than courtesy. That one had a hard year folded up inside it, and a little less of it now.",
		"The nod was small, but there was a lot of tiredness behind it, and something in it eased. That's the part I'll keep.",
	},
	["sw.quest_complete.w19.nod.017"] = {
		"has a speck of lint brushed off {g:his|her} shoulder by the other party, absently, as though tidying up the person who has been useful were part of the thanks.",
		"stands still while the other party straightens {g:his|her} collar with two quick tugs, a fussy, oddly fond gesture, before the dismissal.",
	},
	["sw.quest_complete.w19.quip.001"] = {
		"Paid in Stormwind, broke in Stormwind. Shortest road in the kingdom.",
		"From empty purse to full and back to empty, all inside one ring of walls. Very efficient place.",
		"Fresh coin in Stormwind has a shelf life of about two streets.",
	},
	["sw.quest_complete.w19.quip.002"] = {
		"If SI:7 is watching, I'd like it noted that was done very neatly.",
		"Somebody from SI:7 is surely writing this down. Get my name right, whoever you are.",
	},
	["sw.quest_complete.w19.quip.003"] = {
		"I'll be at the Gilded Rose. Urgent matters, knock. Anything else, write it down and lose it.",
		"Anyone needs me, try the Gilded Rose. Try quietly.",
	},
	["sw.quest_complete.w19.quip.004"] = {
		"Not a single guard has given me a suspicious look in the last hour. I must be losing my touch.",
		"Even the guards have stopped eyeing me. Either I've become respectable or they're tired. I suspect the second.",
	},
	["sw.quest_complete.w19.quip.005"] = {
		"Done, and nothing caught fire. By Stormwind standards that's practically a parade.",
		"Finished, and not a single thing exploded. Somebody tell the Mage Quarter how it's done.",
	},
	["sw.quest_complete.w19.quip.006"] = {
		"Quick, before somebody at court finds a way to take credit for it.",
		"Keep it quiet, or some noble will have it in a speech by next week.",
	},
	["sw.quest_complete.w19.quip.007"] = {
		"Good pay. My bookkeeper, who is also me, has already spent it twice in my head.",
		"I've had this coin for a minute and I've already spent it three ways. None of them wise.",
		"This purse has never been so full and so doomed at the same time.",
	},
	["sw.quest_complete.w19.quip.008"] = {
		"More work? Ask later. After a meal, a bath and a nap of unreasonable length.",
		"I'm closed for business. Reopening after food and a long sit, not before.",
	},
	["sw.quest_complete.w19.quip.009"] = {
		"That's one good deed in the tally. I'm saving them up to spend on something I shouldn't.",
		"One more good turn on the books. I like to keep a balance, in case I need to be wicked later.",
	},
	["sw.quest_complete.w19.quip.010"] = {
		"Another small win for the Alliance. Don't spread it around; we want to look modest.",
		"The Alliance thanks me. Probably. Someone ought to write and tell it.",
	},
	["sw.quest_complete.w19.quip.011"] = {
		"Somebody write down the date. On second thought, don't. Nobody would believe it went that smoothly.",
		"That went so smoothly I'm checking my pockets for what it cost me.",
	},
	["sw.quest_complete.w19.quip.012"] = {
		"If they ever put up a statue to this in the Valley of Heroes, I'd like mine sitting down, cup in hand.",
		"No statue for this one, I expect. Just as well; I'd hate to stand by the gate in all weathers.",
	},
	["sw.quest_complete.w19.quip.013"] = {
		"No applause, please. The guards get nervous when crowds start clapping.",
		"Hold the cheering. In this city a crowd making noise brings the Watch at a run.",
		"Please, no cheering. The guard on the next corner already has a hand on the halberd.",
	},
	["sw.quest_complete.w19.quip.014"] = {
		"There's a dwarf down the street who looks like he'd buy an ale for anyone with a good story. I have one, and I can make it better.",
		"This city always has a dwarf willing to stand a round for a tale well told. I'll go and find him, and polish the tale as I go.",
	},
	["sw.quest_complete.w19.quip.015"] = {
		"Who's next? Joking. Nobody's next. I'm going somewhere to sit.",
		"Next! No, wait, not next. That was a reflex. Nobody listen to me.",
	},
	["sw.quest_complete.w19.quip.016"] = {
		"I'd celebrate properly, but celebrating in this city costs money at every door. I'll do it on a bench instead, free of charge.",
		"Celebration plan: walk slowly, look smug, spend nothing. Stormwind will hate it.",
	},
	["sw.quest_complete.w19.quip.017"] = {
		"Don't thank me, thank the regent. Actually, no. He had nothing to do with it. Thank me.",
		"In the king's absence, I accept thanks on his behalf. Mine too, while you're at it.",
	},
	["sw.quest_complete.w19.quip.018"] = {
		"gives the purse a happy little shake, notices a street urchin taking a professional interest, and tucks it a good deal deeper.",
		"pats the newly heavy purse, catches the bright eye of a ragged child doing sums nearby, and moves it to an inside pocket.",
	},
	["sw.quest_complete.w19.quip.019"] = {
		"Done. Now for the Dwarven District, where at least some of the benches were built with me in mind.",
		"Finished. Off to find a chair my size, which in this city means the Dwarven District or the floor.",
	},
	["sw.quest_complete.w19.quip.020"] = {
		"Finished, and here comes the thunder. Excellent timing, for once in my life.",
		"Done just as the sky starts shouting. I'll take it as approval and get under a roof.",
	},
	["sw.quest_complete.w19.seal.001"] = {
		"If Stormwind could, it would press a wax seal onto a thank-you and file a copy.",
		"A thanks delivered without a seal or a witness. By this city's standards it barely counts, and I'm keeping it anyway.",
		"No wax, no ribbon, no copy for the records. For Stormwind, that was an almost reckless thank-you.",
	},
	["sw.quest_complete.w19.seal.002"] = {
		"Do I sign for this? No? Then how will anyone know it happened?",
		"No form to fill in? I'm almost disappointed. Almost.",
		"Nothing to sign, nothing to stamp? That's the least official thing I've ever done in Stormwind.",
	},
	["sw.quest_complete.w19.seal.003"] = {
		"Thanked on behalf of the kingdom, no less. It's a large thing to be thanked by, for one piece of work.",
		"In the name of Stormwind, they said, a phrase big enough to need two hands. I took it with both.",
		"The thanks came in the name of the realm, with all its weight on the words. I'll carry it carefully; it isn't the sort that folds.",
	},
	["sw.quest_complete.w19.seal.004"] = {
		"answers the formal thanks with a bow a shade too deep, and straightens a shade too quickly.",
		"meets the city's stiff courtesy with a bow of {g:his|her} own, somewhat improvised, and seems to get away with it.",
		"returns the ceremony as best {g:he|she} can: a bow begun with conviction and finished with a shrug.",
	},
	["sw.quest_complete.w19.seal.005"] = {
		"Stormwind thanks you the way it writes a letter: a greeting, a body, a closing, and a signature you can't quite read.",
		"That thanks had a salutation, three paragraphs and a sign-off. All it lacked was a seal and a courier.",
		"Even the gratitude here comes in proper form. I kept waiting for the 'yours faithfully'.",
	},
	["sw.quest_complete.w19.seal.006"] = {
		"Sealed, then. No wax, but sealed.",
		"Call it signed and stamped. My thumb will do for the stamp.",
		"There. Stamped, as far as I'm concerned.",
	},
	["sw.quest_complete.w19.seal.007"] = {
		"In Stormwind Keep there's a seal only a king may use. It has been waiting in its box a long while now. Small work like mine never needs it, and I'm glad.",
		"The great seal of the realm sits idle while its owner is missing, or so the guards whisper. Little matters like mine get by on a nod. The big ones must be piling up.",
	},
	["sw.quest_complete.w19.seal.008"] = {
		"finds a smudge of ink on one thumb, with no notion of where it came from, and rubs at it with the other.",
		"notices a fresh ink stain along the side of one hand, though nothing was signed, and frowns at it as at a pickpocket in reverse.",
		"turns a hand over to discover a thumbprint's worth of ink on it, the city's paperwork having apparently left its mark regardless.",
	},
	["sw.quest_complete.w19.seal.009"] = {
		"glances about for a quill to sign with, as if the thanks could not be complete without one, and finds that it can.",
		"half reaches for a quill nobody offers, then turns the gesture into a scratch of the jaw.",
		"looks down for a paper to sign, finds none, and lets the hand drop as though Stormwind had skipped a step.",
	},
	["sw.quest_complete.w19.seal.010"] = {
		"The handshake came with the glove still on. Courtesy here keeps a layer of leather between people, and somehow still means it.",
		"A gloved hand, offered and withdrawn in one practiced motion. Stormwind's kindness comes lined, but it does come.",
		"Kid leather, a firm grip, and the hand gone again before I'd quite taken it. Polite people here shake hands the way they sign: briskly, and for keeps.",
	},
	["sw.quest_complete.w19.seal.011"] = {
		"The honor is mine, I'm sure. There, did I say that right?",
		"Your servant, and so forth. Is that how it goes here?",
		"At your service, and the kingdom's. I've been practicing that one.",
	},
	["sw.quest_complete.w19.seal.012"] = {
		"A city this formal surely sends letters of commendation. Mine will arrive, I expect, about when I've forgotten what it was for.",
		"If there's a letter of thanks on its way, it will be on good paper under a proper seal, and it will find me years late at the wrong inn.",
	},
	["sw.quest_complete.w19.seal.013"] = {
		"has {g:his|her} hand taken in both of someone else's and held there a moment, the plainest kind of thanks the city has.",
		"is thanked with one hand clasped between two others, briefly and firmly, while Stormwind carries on around them.",
		"feels a hand closed over {g:his|her} own and pressed once, hard, in a thanks that needs no further wording.",
	},
	["sw.quest_complete.w19.seal.014"] = {
		"You're welcome. Would you like that in writing? This is Stormwind; I assume you would.",
		"You're very welcome. I can find a witness, if that's the custom.",
		"Not at all. I'd put my name to that, if anyone asked.",
	},
	["sw.quest_complete.w19.seal.015"] = {
		"'Much obliged.' Stormwind's whole manner in two words: thank you, and a quiet reminder that someone now owes someone.",
		"They said 'obliged', not 'thank you'. In this city gratitude is half courtesy and half contract.",
		"'Obliged to you.' Nicely put, and a little binding. Here even a kind word reads like a clause.",
	},
	["sw.quest_complete.w19.seal.016"] = {
		"accepts the thanks indoors, where the noise of the city arrives muffled and the coins sound louder than they ought to.",
		"is thanked between walls thick enough to hush the street, so that every word of it, and every coin, carries.",
		"takes the pay in the hush of a room, where each piece set down rings out like a small announcement.",
	},
	["sw.quest_complete.w19.seal.017"] = {
		"Tell the regent it's handled. One thing fewer on that desk of his.",
		"If word reaches the keep, say it was done properly. The regent has enough to carry.",
		"Something off Bolvar's list, then. He won't hear of it, and that's as it should be.",
	},
	["sw.quest_complete.w19.street.001"] = {
		"The auction house is right there, I've just been paid, and I know exactly how this ends.",
		"Fresh coin and the auction house a street away. Somebody should post a guard between the two, for my sake.",
		"Somehow every street I take with a full purse ends at the auction house. This city must be built on a slope.",
	},
	["sw.quest_complete.w19.street.002"] = {
		"Bank first, before I talk myself into anything. A purse locked in the vault can't be argued with.",
		"Straight to the bank. Coin in a vault keeps its opinions to itself; coin in my pocket keeps making suggestions.",
		"The bank, then. The vault has never once tempted me with anything.",
	},
	["sw.quest_complete.w19.street.003"] = {
		"stops under a signpost where the streets cross and reads every arm of it, though only one was ever going to win.",
		"pauses at a crossing to read the signpost, all of it, slowly, like the board of fare in a tavern.",
	},
	["sw.quest_complete.w19.street.004"] = {
		"Some of this goes to a trainer, and soon. Lessons are the one purchase I've never once regretted.",
		"Coin like this wants turning into something that lasts. A trainer sells the only goods nobody can lift from my pocket.",
		"Off to a trainer, then, while the purse is heavy and my pride is high. Both will be lighter within the hour.",
	},
	["sw.quest_complete.w19.street.005"] = {
		"Tempting, the tram. Ironforge is one ride away, and nobody there has thought of an errand for me yet.",
		"I could take the tram to Ironforge, just to stand somewhere nobody needs anything from me.",
		"The tram to Ironforge has never once handed me an errand. That's reason enough to ride it.",
	},
	["sw.quest_complete.w19.street.006"] = {
		"The gate is a long walk from most of this city, and I spend every step of it deciding whether to go through.",
		"I could head for the gate. By the time I've crossed the city I'll have changed my mind twice and changed it back.",
	},
	["sw.quest_complete.w19.street.007"] = {
		"turns toward the Gilded Rose with the slow, certain step of someone who has decided that the rest of the list can wait.",
		"drifts in the direction of the Gilded Rose, stops to argue with {g:himself|herself} about it, briefly, and loses.",
	},
	["sw.quest_complete.w19.street.008"] = {
		"Might as well check the mail. It's usually a note from the auction house about something I wanted and somebody else got.",
		"The post next, out of habit. Half my letters are the auction house telling me, very politely, that I was outbid.",
	},
	["sw.quest_complete.w19.street.009"] = {
		"asks a guard for the quickest way to the bank, nods along to the answer, and sets off in the wrong direction with complete confidence.",
		"gets directions from a guard, repeats them aloud to fix them in mind, and takes the first wrong turning anyway.",
	},
	["sw.quest_complete.w19.street.010"] = {
		"No errand, no address. I'll walk until the city decides where to set me down.",
		"I'll let the streets choose for a while. Stormwind has opinions about where a person should end up; I'm curious to hear them.",
		"Left at the next corner, or right. It truly doesn't matter, and that is a luxury I mean to enjoy.",
	},
	["sw.quest_complete.w19.street.011"] = {
		"Quick, somebody point me at the bank before I find a stall I like.",
		"Which way is the bank? Fast, please. There's a hat seller looking at me.",
		"Bank. Where's the bank. Don't let me stop for anything shiny on the way.",
	},
	["sw.quest_complete.w19.street.012"] = {
		"drops a copper into a beggar's cap on the way past, without slowing, like someone settling a very small account with the city.",
		"spares a coin for an old soldier begging by a doorway, and gets a salute in return, as crisp as any on the walls.",
		"presses a coin into a blind fiddler's palm in passing, and is paid back with a bar of something cheerful.",
	},
	["sw.quest_complete.w19.street.013"] = {
		"There's a bench in the Park where nobody has ever once asked me for a favor. That's where I'm going.",
		"The Park, I think. Trees don't hand out errands, and they never want to know how it went.",
	},
	["sw.quest_complete.w19.street.014"] = {
		"Anyone going toward the Trade District? I'll walk along, if you don't mind. I've had my fill of my own company.",
		"Heading my way? Good. A bit of conversation would suit me, about anything but work.",
	},
	["sw.quest_complete.w19.street.015"] = {
		"buys a twist of roasted nuts from a stall, the first thing in a good while bought for no reason but wanting it.",
		"stops at a street stall for a cone of something sugared and warm, and eats it walking, without one thought for what it cost.",
	},
	["sw.quest_complete.w19.street.016"] = {
		"A wash, a meal, a seat. In a city this size each of those comes with its own queue, and I'll stand in all three.",
		"Next comes the plain stuff: clean hands, hot food, somewhere to sit. Stormwind charges for every one, and I'll pay gladly.",
	},
	["sw.quest_complete.w19.street.017"] = {
		"tries a shortcut through a side lane and comes out, some time and several stairs later, exactly where it began.",
		"takes a short way between two houses that turns out to be a long way between four, and emerges on the same street, wiser.",
	},
	["sw.quest_complete.w19.street.018"] = {
		"Anyone know a smith in this city who'll mend my gear without a lecture on how I treat it?",
		"I need a repair, not a sermon. Is there a smith in Stormwind who sells only the first?",
	},
	["sw.quest_complete.w19.street.019"] = {
		"The gryphon master will want to know where I'm headed, and I haven't the faintest idea yet. A walk first, then the roost.",
		"I could be on a gryphon in a few minutes. I'd rather decide where to before I'm in the air deciding.",
	},
	["sw.quest_complete.w19.street.020"] = {
		"lets the crowd carry {g:him|her} along toward the Trade District, like a chip of wood finding the current in a gutter.",
		"joins the stream of people heading for the shops and goes where it goes, for once without steering.",
	},
	["sw.quest_complete.w19.street.021"] = {
		"Humans pay in silver and say thank you. In Ironforge they'd have poured an ale as well. I'll pour my own, then.",
		"Decent coin and a decent thanks. All this city lacks is the mug that ought to come with them. That I can fix.",
	},
	["sw.quest_complete.w19.street.022"] = {
		"The work and the daylight run out together. Neat, as endings go; the lamplighters are already up their ladders.",
		"Dusk, and done. Shopkeepers are closing up on both sides of the street, as if they had all been waiting for me to finish.",
	},
	["sw.quest_complete.w19.weight.001"] = {
		"Tired in the good way, the kind that comes with a reason attached.",
		"This tiredness has a receipt. That's the difference between it and the other kind.",
		"Weary, but honestly weary. I can account for every ache.",
	},
	["sw.quest_complete.w19.weight.002"] = {
		"Pride is a small warm thing. I'll keep it in a pocket for one street, then put it away before it gets ideas.",
		"A little proud of that. Just a little. Any more and I'd have to buy a bigger hat.",
	},
	["sw.quest_complete.w19.weight.003"] = {
		"I did what was asked. Whether it was right is a separate question, and in a city of nobles and favors it pays to keep the two apart.",
		"Asked, done, paid. Somewhere in that chain is a 'should I have?', and it's walking along beside me.",
		"The work was clean. The reasons behind it, I never saw. In Stormwind that's usually where the dirt is kept.",
	},
	["sw.quest_complete.w19.weight.004"] = {
		"closes {g:his|her} eyes for a moment in the middle of the street, and opens them to find the crowd has simply parted around, like water round a post.",
		"stands still with eyes shut amid the traffic of the street, a stone in a stream, while Stormwind steps patiently by on either side.",
	},
	["sw.quest_complete.w19.weight.005"] = {
		"Somewhere in Stormwind there's a chair with my name on it. I'll know it when I fall into it.",
		"I'm going to find the softest seat in this city and test it thoroughly. For the good of the realm.",
	},
	["sw.quest_complete.w19.weight.006"] = {
		"It doesn't feel like much yet. Finished things rarely do; the size of them arrives later, usually when I'm trying to sleep.",
		"Strange how small it seems now that it's over. Ask me in a week and it'll have grown.",
		"It'll be bigger in the memory than it is now. Most good things are; they need room to settle.",
	},
	["sw.quest_complete.w19.weight.007"] = {
		"kneads the back of {g:his|her} neck and stares up at a roofline for a while, at nothing in particular, the way people do when the head is still busy.",
		"tips {g:his|her} head back to ease a stiff neck and ends up studying a chimney pot with great seriousness.",
	},
	["sw.quest_complete.w19.weight.008"] = {
		"Nothing hurts much. Everything hurts a little. That's the bill for careful work, and it comes in installments.",
		"No single ache worth complaining about, just a dozen small ones taking turns. Careful work always sends its bill this way.",
	},
	["sw.quest_complete.w19.weight.009"] = {
		"I'm fine. I just need to stand very still somewhere for a bit and think about nothing.",
		"Don't mind me. I'm resting with my eyes open. It's a skill.",
	},
	["sw.quest_complete.w19.weight.010"] = {
		"Stormwind received my good work the way it receives everything: without looking up. Very much a capital.",
		"A village would make a fuss over a thing like that. A capital nods and turns the page. I find I don't mind.",
	},
	["sw.quest_complete.w19.weight.011"] = {
		"They'll have forgotten the details by next market day. I'll carry them around for years. Helping is an uneven bargain that way.",
		"For them it's over and done. For me it's one more thing I'll remember at odd moments, in odd places, for no reason at all.",
	},
	["sw.quest_complete.w19.weight.012"] = {
		"slumps against a lamppost in a thoroughly unbecoming way, and is caught at it by a passing noblewoman whose eyebrows deliver a whole lecture.",
		"sags onto a low wall with a groan just as a well-dressed couple strolls by, and receives two identical looks of disapproval.",
	},
	["sw.quest_complete.w19.weight.013"] = {
		"Nobody saw how well that went but me. That will have to be enough, and oddly, it is.",
		"Done properly, with no witnesses. I'd have known if I'd cut a corner, and I'm the hardest judge in the street.",
	},
	["sw.quest_complete.w19.weight.014"] = {
		"I'm too tired for a city this wide awake. Everyone's walking faster than I am, and every one of them is selling something.",
		"Stormwind has energy enough for ten. I'd like to borrow a little, but only to sit down with.",
		"Every shout of the Trade District lands on me like a small parcel. I'd like to stop signing for them.",
	},
	["sw.quest_complete.w19.weight.015"] = {
		"That took more out of me than I'll admit. So I won't.",
		"I'll pretend that was easy. Just don't look too closely at my hands for a minute.",
	},
	["sw.quest_complete.w19.weight.016"] = {
		"A small word to the Light on the way, for whoever asked for help. I'm no priest, but it seems a waste not to.",
		"Light keep them. That's all; I'm not one for long prayers, but a short one for the people I just helped costs nothing.",
	},
	["sw.quest_complete.w19.weight.017"] = {
		"loosens a buckle that has been biting all along, and seems to grow taller by roughly the width of the strap.",
		"lets out a belt by one hole, right there in the street, with the dignity of someone who has earned it.",
	},
]==])
